// =====================================================================
// views.js -- Page render functions for every Praxis view
//
// renderRoute() is the entry point. app.js calls it on
// DOMContentLoaded and on every 'hashchange'. It parses location.hash
// by stripping the leading '#' and splitting on '/', then dispatches
// on parts[0]:
//   ''            -> renderNotebook()
//   'notebook'    -> renderNotebook()
//   'books'       -> renderShelf()         (3.5a)
//   'book' + id   -> renderBookDetail(id)  (id from parts[1])
//   otherwise     -> renderNotebook()      (default fallback)
// The notebook-bound dispatch and the shelf-bound dispatch both
// clear state.currentBookId to null; the book-detail dispatch sets
// it to the route id. All paths call saveState() after the mutation
// so yumi-brain (which reads currentBookId) sees a consistent live
// state. The 'books' branch is distinct from the 'book' + id branch
// by parts[0] alone -- no collision with a hypothetical bookId of
// 'all' or similar reserved value.
//
// Stage 3.1: renderNotebook paints the unified Notebook surface --
// header (title + auth-aware affordance) + editor host + entry list
// (or empty-state paragraph). The unified list shows all of the
// active user's entries across both registers, newest first by
// createdAt.
//
// Stage 3.2: openJournalEditor mounts an inline textarea + Save /
// Cancel block into #notebook-editor-host. Save creates a
// notebookEntry with register 'journal', isPrivate sourced from
// the per-user Journal register default (3.4b), persists via
// saveState, and re-renders via renderNotebook.
//
// Stage 3.3: renderBookDetail paints the per-book surface -- header
// (cover if present, title, author byline if present, auth-aware
// affordance) + editor host (#book-detail-editor-host) + filtered
// entry list (this user's entries on this book, newest first), or an
// empty-state paragraph in the app literary register.
// openMarginaliaEditor mirrors openJournalEditor structurally but
// writes register 'marginalia', bookIds [bookId], and re-renders via
// renderBookDetail. renderNotebookEntry is the single register-aware
// entry renderer used by both surfaces: marginalia entries get a
// second meta line "from <title>" resolved through entry.bookIds[0]
// -> state.books; missing books fail soft as "from (unknown book)".
//
// All user-derived text goes in via textContent. innerHTML = '' is
// acceptable for clearing. No markdown rendering in 3.3.
//
// Stage 3.4b: per-entry visibility toggle on every rendered entry
// (notebook-entry-privacy + notebook-entry-privacy-toggle) plus a
// register-default settings affordance in the Notebook header
// (notebook-settings-toggle opens an inline panel at
// #notebook-settings-host). Per-entry flip is the primary
// correctable surface for principle #5; the filter that consumes
// isPrivate lives in yumi-brain.js buildContext (3.4a). New entry
// creation reads state.users[uid].registerDefaults[register]
// instead of hardcoding false. Existing entries are never
// retroactively flipped when a register default changes.
//
// Stage 3.6: principle #5's third leg -- the transparency view.
// The "What Yumi sees" affordance in the Notebook header opens an
// inline panel at #notebook-transparency-host (between settings
// host and editor host). The panel reads
// window.YumiBrain.getContextSnapshot() at mount time -- fresh on
// every open, no live updates, close clears. Five sections:
// Current book, Current arc, Recent notebook entries, conversation
// summary, recent turns. Diagnostic surface, not primary surface;
// styling differentiation deferred to the styling pass.
//
// CSS classes (all unstyled; styling pass to follow):
//   3.1: notebook-empty, notebook-empty-title, notebook-empty-body
//   3.2: notebook, notebook-title, notebook-header,
//        notebook-new-entry, notebook-signin-prompt, notebook-editor,
//        notebook-editor-body, notebook-editor-actions,
//        notebook-editor-save, notebook-editor-cancel,
//        notebook-entry-list, notebook-entry, notebook-entry-meta,
//        notebook-entry-register, notebook-entry-body
//   3.3: book-detail, book-detail-header, book-detail-title,
//        book-detail-author, book-detail-cover, book-detail-new-entry,
//        book-detail-signin-prompt, book-detail-empty-body,
//        book-detail-not-found, notebook-entry-book-meta
//   3.4b: notebook-entry-privacy, notebook-entry-privacy-toggle,
//         notebook-settings-toggle, notebook-settings-panel,
//         notebook-settings-section, notebook-settings-label,
//         notebook-settings-current, notebook-settings-toggle-link,
//         notebook-settings-explanation, notebook-settings-done
//   3.6:  notebook-transparency-toggle, transparency-panel,
//         transparency-header, transparency-title, transparency-close,
//         transparency-framing, transparency-section,
//         transparency-section-label, transparency-section-body,
//         transparency-entry, transparency-entry-body,
//         transparency-entry-meta, transparency-turn,
//         transparency-turn-role, transparency-turn-body
//   3.5a: shelf, shelf-header, shelf-title, shelf-empty-body,
//         shelf-list, shelf-book, shelf-book-title, shelf-book-author,
//         shelf-book-meta, shelf-book-status, shelf-book-genre,
//         shelf-new-book, shelf-signin-prompt, shelf-editor,
//         shelf-editor-title-input, shelf-editor-author-input,
//         shelf-editor-status, shelf-editor-status-option,
//         shelf-editor-genre-input, shelf-editor-isbn-input,
//         shelf-editor-actions, shelf-editor-save, shelf-editor-cancel
//   3.5b: shelf-book-cover, shelf-book-cover-placeholder,
//         book-detail-cover-placeholder, book-detail-isbn-row,
//         book-detail-isbn-label, book-detail-isbn-input
//   3.8:  notebook-new-arc, notebook-arc-list-block,
//         notebook-arc-list-title, notebook-arc-empty-body,
//         notebook-arc-list, notebook-arc-row, notebook-arc-title,
//         notebook-arc-description
//   3.8 2b-i: book-detail-add-to-arc, arc-picker-panel,
//         arc-picker-label, arc-picker-status, arc-picker-empty,
//         arc-picker-row, arc-picker-done
//   3.8 2b-ii: notebook-entry-add-to-arc,
//         notebook-entry-arc-picker-host
//   3.9-a: arc-detail, arc-detail-header, arc-detail-title,
//         arc-detail-description, arc-detail-delete,
//         arc-detail-empty-body, arc-detail-member-list,
//         arc-detail-missing-member, arc-detail-not-found
//   3.9-b: arc-confirm-panel, arc-confirm-copy, arc-confirm-actions,
//         arc-confirm-confirm, arc-confirm-cancel,
//         arc-confirm-stale-note, arc-confirm-stale-back
//   Editor host ids: #notebook-editor-host (3.2),
//                    #book-detail-editor-host (3.3),
//                    #shelf-editor-host (3.5a),
//                    #notebook-arc-editor-host (3.8)
//   Picker host ids: #book-detail-arc-picker-host (3.8 2b-i),
//                    .notebook-entry-arc-picker-host (3.8 2b-ii,
//                    per-card inline mount, not an id)
//   Confirm host id: #arc-detail-confirm-host (3.9-a, 3.9-b wires)
//   Settings host id:     #notebook-settings-host (3.4b)
//   Transparency host id: #notebook-transparency-host (3.6)
//
// Stage 3.5a: renderShelf paints the Books surface -- header (title
// + auth-aware add affordance: "+ Add book" if signed in,
// "Sign in to add books" otherwise) + editor host (#shelf-editor-host)
// + book list (or empty-state paragraph). The list reads from
// state.books (not state.userBooks) so book_test_1 from 3.3 console
// seeding stays visible despite never being written to userBooks --
// the pre-existing drift documented in the 3.5a brief. Filter pills
// are deferred; this sub-stage renders every record in state.books,
// newest first by addedAt. Each row is an anchor to #book/<id> so
// click-through hits the existing book-detail surface.
// renderShelfBook is the single row renderer.
//
// openShelfEditor mounts an inline title/author/status/genre/isbn
// form into #shelf-editor-host. Save (disabled until trimmed title
// is non-empty) calls genBookId, writes a complete books record
// with id, title, author, isbn (trimmed; may be ''), addedAt,
// status, genre, coverUrl (null at write time), then ensureUser
// + push to state.userBooks[uid].bookIds, persists via saveState,
// re-renders via renderShelf. Cancel re-renders the shelf without
// writing -- state.books and state.userBooks are untouched. Auth
// gate mirrors renderBookDetail header: when getCurrentUser() is
// null, the affordance becomes "Sign in to add books" and click
// routes to signInWithGoogle(), not openShelfEditor.
//
// Stage 3.5b: when isbn is non-empty after trim, the save handler
// fires fetchAndApplyCover(id, isbn, onComplete) in the background
// AFTER the synchronous write+saveState+renderShelf path completes.
// The cover arrives asynchronously and patches state.books[id]
// .coverUrl when the integrations callback fires; renderShelf is
// re-called only if the user is still on #books at that moment
// (route check, not currentBookId check -- both #books and
// #notebook clear currentBookId, so route inspection is the
// faithful signal). The fail-soft contract is enforced in
// fetchAndApplyCover: null returns, throws, empty/null coverUrl
// fields, and OL "id=0" / "/id/0-" placeholder URLs all resolve
// to state.books[id].coverUrl === null. The book record itself
// is written regardless of fetch outcome.
//
// Stage 3.5b Stage 3: fetchAndApplyCover's onComplete signature
// extends to (url, result). The save handler's callback uses
// result.title and result.author to backfill state.books[id]
// .title and .author -- but only when the user's typed form
// fields (titleTrimmed / authorTrimmed, closure-captured at save
// time) were blank. The user's typed values are authoritative;
// we only fill the gaps. Same typeof-string + length>0 guard as
// coverUrl: any missing/null/empty API value leaves the record
// field as-is. The blur handler on book detail also receives the
// (url, result) signature but ignores result -- per 3.5b Stage 3
// brief Non-Goal: ISBN edits on book detail do not backfill
// metadata, since the user's existing title and author there
// are authoritative.
//
// Stage 3.5b Stage 2: renderShelfBook prepends a cover thumbnail
// (img.shelf-book-cover) when book.coverUrl is a non-empty string,
// otherwise a placeholder div (shelf-book-cover-placeholder) so
// the row layout stays stable. renderBookDetail mirrors this on
// the full-cover element. A new ISBN row mounts between the
// book-detail header and the editor host with an addEventListener
// 'blur' handler implementing the re-fetch contract:
//   - trimmed === priorIsbn (closure-cached at render time): no-op
//   - trimmed === '': clear state.books[bookId].isbn and coverUrl,
//                     saveState, renderBookDetail. No fetch.
//   - trimmed non-empty and changed: persist new isbn, saveState,
//                     fetchAndApplyCover(bookId, trimmed, cb). cb
//                     re-renders only if the user is still on
//                     #book/<bookId> when the fetch completes.
// First onblur-driven handler in the codebase; no prior pattern
// to mirror.
//
// var/function only -- no const, let, arrow, class, or template
// literals anywhere. String concatenation only.
// =====================================================================

'use strict';

var APP_EL_ID = 'app';

// Stage 5.3 Stage 4: Bookshop.org affiliate configuration for the
// "Find this book" line that renders on arc-detail member books and
// the book-detail header. C5 spec: honest availability framing, never
// "BUY NOW", one restrained line, no store styling. The affiliate ID
// is a hardcoded constant rather than a config file because it's a
// single value with one consumer; future affiliate config (Amazon
// fallback, etc.) can earn its own file when a second value lands.
//
// When BOOKSHOP_AFFILIATE_ID is the empty string (today's value --
// Preston has not yet completed the Bookshop affiliate application,
// per README.md:26), buildBookshopUrl returns the keyword-search URL
// so the link still works and points at Bookshop, just without
// affiliate revenue. Preston edits the one constant below + bumps
// CACHE_VERSION when his ID arrives; no other code changes needed.
var BOOKSHOP_AFFILIATE_ID = '';

// Returns the Bookshop.org URL for a given ISBN, or null if the ISBN
// is missing / empty. Strips dashes and whitespace before insertion
// so a user-entered "978-0061-120060" formats correctly. Callers MUST
// check for null and skip rendering the link in that case -- a book
// with no ISBN gets no "Find this book" line (the line is honest
// availability, not a fallback search).
//
// Affiliate path:  https://bookshop.org/a/<id>/<isbn>
// Fallback path:   https://bookshop.org/search?keywords=<isbn>
//                  (live-probed at Stage 4 commit time: this URL
//                  302-redirects to Bookshop's /beta-search results
//                  page with the ISBN preserved. The plausible-looking
//                  /books?keywords=<isbn> form was probed too but
//                  302-redirects to the homepage with a dangling
//                  query, not a real search result. The /search form
//                  is the working endpoint.)
// Both surfaces are real Bookshop URLs; the fallback just lacks the
// affiliate kickback attribution.
function buildBookshopUrl(isbn) {
  if (typeof isbn !== 'string') return null;
  var normalized = isbn.replace(/[-\s]/g, '');
  if (normalized.length === 0) return null;
  if (BOOKSHOP_AFFILIATE_ID && BOOKSHOP_AFFILIATE_ID.length > 0) {
    return 'https://bookshop.org/a/' +
           encodeURIComponent(BOOKSHOP_AFFILIATE_ID) +
           '/' + encodeURIComponent(normalized);
  }
  return 'https://bookshop.org/search?keywords=' +
         encodeURIComponent(normalized);
}

// Stage 5.4 Stage 1b: arc-detail view-mode persistence. localStorage,
// global key (one preference across all arcs), default 'list'. The
// unknown-value branch in getArcViewMode coerces any corrupt /
// hand-edited ls value back to the safe default rather than letting
// it propagate into the renderArcDetail branch. setArcViewMode
// mirrors the same allow-list so a bad call site (future caller
// passing a typo) cannot poison the stored value.
function getArcViewMode() {
  var mode = ls('praxis_arc_view_mode', 'list');
  if (mode !== 'list' && mode !== 'web') {
    return 'list';
  }
  return mode;
}

function setArcViewMode(mode) {
  if (mode !== 'list' && mode !== 'web') {
    return;
  }
  sv('praxis_arc_view_mode', mode);
}

// Stage 3 (chrome-fidelity): shelf view-mode persistence. Mirrors the arc
// view-mode pattern above -- localStorage, one global preference, default
// 'covers'. The allow-list coerces any corrupt/hand-edited value back to
// the safe default in both the getter and setter.
function getShelfView() {
  var v = ls('praxis_shelf_view', 'covers');
  if (v !== 'covers' && v !== 'list') {
    return 'covers';
  }
  return v;
}

function setShelfView(v) {
  if (v !== 'covers' && v !== 'list') {
    return;
  }
  sv('praxis_shelf_view', v);
}

// Stage 1 (shelf categories): sidebar grouping persistence. Mirrors the shelf
// view-mode pattern above -- localStorage, one global preference, default
// 'lenses'. The allow-list coerces any corrupt/hand-edited value back to the
// safe default in both the getter and setter.
function getShelfGrouping() {
  var v = ls('praxis_shelf_grouping', 'lenses');
  if (v !== 'lenses' && v !== 'categories') {
    return 'lenses';
  }
  return v;
}

function setShelfGrouping(v) {
  if (v !== 'lenses' && v !== 'categories') {
    return;
  }
  sv('praxis_shelf_grouping', v);
}

// 3.10a Stage 4: guards initNavMobileToggle so the hamburger
// listener binds exactly once across the session. Module-level so
// the flag persists across renderRoute calls.
var navMobileToggleInitialized = false;

// 3.10a Stage 4: bind the mobile hamburger toggle. Called by
// renderRoute on first invocation only (guarded by
// navMobileToggleInitialized). The hamburger click toggles
// .app-nav-mobile-open on the nav; one addEventListener, no per-
// link close handlers (the panel closes when a link is tapped via
// renderRoute, which runs on every hashchange and removes the open
// class -- see the renderRoute body). The nav lives in static
// index.html so this can run any time after DOMContentLoaded;
// renderRoute is dispatched by app.js immediately after, so first-
// call binding is safe.
function initNavMobileToggle() {
  var navEl = document.querySelector('.app-nav');
  var ham = document.querySelector('.app-nav-hamburger');
  if (!navEl || !ham) return;
  ham.addEventListener('click', function() {
    if (navEl.classList.contains('app-nav-mobile-open')) {
      navEl.classList.remove('app-nav-mobile-open');
      // ON-1: release the page scroll-lock when the menu closes via re-tap.
      // (A route change also closes the menu and clears overflow in
      // renderRoute, so every close path releases the lock.)
      document.body.style.overflow = '';
    } else {
      navEl.classList.add('app-nav-mobile-open');
      // ON-1: lock page scroll so the shelf cannot scroll behind the
      // full-viewport menu overlay.
      document.body.style.overflow = 'hidden';
    }
  });
}

// HD-1 · REVEAL ON INTENT (R-POLISH B2, app-chrome rider).
// The header scrolls away with the page; ANY upward scroll intent glides it back.
// Seated normally at the top of a page. Bound exactly once per session, same
// guarded idiom as initNavMobileToggle -- the nav is static index.html markup and
// is never re-created per route, so re-binding on every renderRoute would stack
// duplicate listeners.
//
// WHY DESKTOP-ONLY: the tuck is a `transform` on .app-nav, and the canon's §2
// guardrail forbids transform/filter on any ancestor of an absolutely-positioned
// child that can overflow it (the iOS composite bug). Below 760 the nav parents
// exactly such a child -- the full-viewport mobile menu -- so the CSS scopes the
// transform to >=760. That also satisfies the brief's "<760 behaviour unchanged":
// mobile nav stays in-flow (position:relative) and never tucks. The JS is
// harmless there because the class it toggles has no effect under 760.
//
// No rAF: the two existing scroll handlers in this file are synchronous reads of
// pageYOffset (views.js shelfHeadScrollHandler, __aboutSpineScroll) and the pane
// does not fire rAF at all -- matching the house idiom keeps this measurable.
var navRevealInitialized = false;

function praxisRevealNav() {
  var navEl = document.querySelector('.app-nav');
  if (navEl) { navEl.classList.remove('nav-tucked'); }
}

function initNavReveal() {
  var navEl = document.querySelector('.app-nav');
  if (!navEl) return;
  var lastY = window.pageYOffset || 0;
  var SEAT_Y = 24;   // within this of the top, the header is always seated
  var INTENT = 6;    // px of travel before a direction counts as intent
  window.addEventListener('scroll', function () {
    var y = window.pageYOffset || 0;
    if (y <= SEAT_Y) { navEl.classList.remove('nav-tucked'); lastY = y; return; }
    var dy = y - lastY;
    if (dy > INTENT) { navEl.classList.add('nav-tucked'); lastY = y; }
    else if (dy < -INTENT) { navEl.classList.remove('nav-tucked'); lastY = y; }
  });
  // HD-1: the header must also come when CALLED, not only when scrolled to.
  // spotlight.js invokes this on the ⌘K path so search is reachable from
  // anywhere, including mid-page with the header tucked away.
  window.praxisRevealNav = praxisRevealNav;
}

function renderRoute() {
  // ME-1 (B4): the activation latch needs a mid-session heartbeat, not a boot
  // check — the qualifying moment (first book + first marginalia) happens WHILE
  // session 1 is running, and by the next boot the first-session window has
  // closed. Guarded + memoised in measure.js, so this is a comparison in the
  // common case. It derives from existing state and records nothing about it.
  if (window.PraxisMeasure) { PraxisMeasure.checkActivation(); }
  // 3.10a Stage 4: bind the hamburger toggle once on first call,
  // then close any open mobile nav panel on every route change.
  // app.js's existing hashchange listener calls renderRoute on
  // every URL change, so tapping a nav link inside the open panel
  // -> URL changes -> renderRoute fires -> classList.remove
  // closes the panel. No per-link addEventListener required.
  if (!navMobileToggleInitialized) {
    initNavMobileToggle();
    navMobileToggleInitialized = true;
  }
  // HD-1: bind the reveal-on-intent scroll listener once, same guard, same reason.
  if (!navRevealInitialized) {
    initNavReveal();
    navRevealInitialized = true;
  }
  // HD-1: a route change is a new page -- the header seats itself at the top of it.
  praxisRevealNav();
  var navOpen = document.querySelector('.app-nav');
  if (navOpen) {
    navOpen.classList.remove('app-nav-mobile-open');
  }

  // MW-1 (P1/P8): release the Shelf Manage-sheet's page scroll-lock and purge its
  // listeners on EVERY route change. Opening the mobile sheet locks body scroll +
  // binds a keydown/scroll listener; leaving #books via OS back / any external
  // hash change does NOT call renderShelf, so without this a back-nav out of an
  // open sheet would strand the next surface with overflow:hidden (and leak the
  // listeners). Global cleanup belongs in the router, next to the nav-close above;
  // when the route IS #books, renderShelf re-binds immediately after this.
  document.body.style.overflow = '';
  if (shelfManageEscapeHandler) {
    document.removeEventListener('keydown', shelfManageEscapeHandler);
    shelfManageEscapeHandler = null;
  }
  if (shelfHeadScrollHandler) {
    window.removeEventListener('scroll', shelfHeadScrollHandler);
    shelfHeadScrollHandler = null;
  }

  var rest = location.hash.replace(/^#/, '');
  var parts = rest.split('/');

  // UMBER dual-ground: tag <body> with the active route's ground so the
  // theme.css [data-ground="dark"] override resolves. Keyed off the RAW
  // hash head (parts[0]) -- NOT the collapsed activeRoute below -- because
  // the BRIGHT sub-surfaces (book, subtheory, artifact) live under DARK
  // parents (books, arcs). Dark study surfaces: home, books, arcs, arc,
  // account. Everything else (yumi-sees, artifact, and the empty / unknown ->
  // notebook default) is the bright page. (W10: #about joined the dark set.)
  // Wave 4: 'book' joins the dark-ground set so the body sits DARK behind
  // the Amber Book Detail / Book View surfaces (both have parts[0]==='book',
  // incl. #book/<id>/marks) -- the seam-proof backing for the full-bleed
  // .lum-amber-deep root, so no bright paper shows at the surface edges.
  // R-POLISH B1-FIX · PG-1 v2 (THE HOUR, REFINED) -- 'home' REJOINS the dark set.
  //
  // B1 removed 'home' here under PG-1 v1.4 ("paper by day, sky for beholding"),
  // making Home the only bright route in the app. PG-1 is amended to v2 by this
  // ship: "One twilight world; printed pages are where you work; depth is
  // meaning -- About and the galaxy are its deeper registers, every crossing
  // gradual." Home is therefore not an exception to the world; it is the first
  // room of it, and the WORK happens on vellum pages (.lit-page) laid on that
  // world -- so Home keeps its printed working surfaces AND its sky.
  //
  // With 'home' restored, every route in the app resolves data-ground="dark":
  // the world is genuinely one. B1's Home-scoped fixed ::before (the bright
  // paper vignette, components.css) retires in the same commit -- the global
  // body::before/::after ground pair is now the single ground mechanism.
  //
  // This flip re-resolves EVERY ground-sensitive token on the page at once, so it
  // is sampled before/after at 390/1280/1920 (docs/checkpoints/r-polish-b1-fix.md).
  // It does NOT touch the nav: theme.css lists .app-nav (and .yumi-bloom,
  // .yumi-panel, .spotlight-panel) as INDEPENDENT selectors on the dark remap, so
  // that chrome keeps its own world fill over any ground.
  var umberGroundDark = { home: 1, books: 1, arcs: 1, arc: 1, account: 1, book: 1, subtheory: 1, notebook: 1, profile: 1, commons: 1, reader: 1, walk: 1, search: 1, about: 1, artifact: 1, 'yumi-sees': 1 };
  document.body.setAttribute('data-ground',
    umberGroundDark[parts[0]] ? 'dark' : 'bright');

  // Stage 3.10a Stage A: toggle .app-nav-link-active on the top-nav
  // link that matches the current route. Book detail and Artifact
  // are sub-surfaces of the shelf so they keep Books highlighted.
  // Empty / unknown hashes converge on Notebook downstream, so the
  // active-link signal matches that convergence here.
  //
  // Stage 5.3 Stage 2: arc detail (#arc/<id>) is the sub-surface of
  // the Arcs page in the same way book detail is the sub-surface of
  // the shelf -- both keep Arcs highlighted. #arcs (plural, the
  // teaching page) is the canonical Arcs route. Order matters: the
  // 'arc' / 'arcs' branch must come BEFORE the books branch so a hash
  // like 'arc/abc' (parts[0] === 'arc') is caught here, not later.
  var activeRoute;
  if (parts[0] === 'arc' || parts[0] === 'arcs' || parts[0] === 'subtheory') {
    activeRoute = 'arcs';
  } else if (parts[0] === 'book' || parts[0] === 'artifact' ||
      parts[0] === 'books') {
    activeRoute = 'books';
  } else if (parts[0] === 'home') {
    // Batch 4A: Home is its own top-nav surface (landing route).
    activeRoute = 'home';
  } else if (parts[0] === 'account' || parts[0] === 'profile' ||
      parts[0] === 'commons' || parts[0] === 'reader' || parts[0] === 'walk') {
    // Stage 14.3 Stage 4: the Account page is its own top-nav surface.
    // Wave 6 (re-scoped): the own-profile surface (#profile) is reached FROM the
    // Account page (its nav link stays in index.html), so it keeps the Account
    // top-nav link highlighted -- the same sub-surface pattern as book -> books.
    // W6.5: the social surfaces (#commons discovery, #reader/<uid> other-profile,
    // #walk/<arcId> interact) are reached from the Account/own-profile umbrella,
    // so they keep the Account link lit too (no new top-nav link this wave).
    activeRoute = 'account';
  } else if (parts[0] === 'about') {
    // About page (#about): its own top-nav surface (the last text link).
    activeRoute = 'about';
  } else if (parts[0] === 'yumi-sees') {
    // 6.2c: the 'What Yumi sees' page is reached from Yumi's panel, not
    // the top nav -- this value matches no data-route so no link highlights.
    activeRoute = 'yumi-sees';
  } else if (parts[0] === 'search') {
    // W8 Lane B: the global Search page is its own surface, reached from the nav
    // pill (not a top-nav link) -- 'search' matches no data-route so no link
    // highlights (like yumi-sees), and it avoids defaulting to lighting Notebook.
    activeRoute = 'search';
  } else {
    activeRoute = 'notebook';
  }
  var links = document.querySelectorAll('.app-nav-link');
  var i;
  for (i = 0; i < links.length; i++) {
    if (links[i].getAttribute('data-route') === activeRoute) {
      links[i].classList.add('app-nav-link-active');
    } else {
      links[i].classList.remove('app-nav-link-active');
    }
  }

  // Batch 1: populate the gradient avatar's initial from the cached
  // user (getCurrentUser -> .displayName, then .email), falling back
  // to 'P' when signed out or nameless. Plain var/string-concat.
  var initialEl = document.querySelector('.app-nav-profile-initial');
  if (initialEl) {
    var navUser = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
    var navNameEl = document.querySelector('.app-nav-profile-name');
    var navAcctEl = document.querySelector('.app-nav-profile-account');
    var navProfileEl = document.querySelector('.app-nav-profile');
    // OG2: the signed-out nav must not fabricate an account. No 'P' avatar, no
    // "Your account" -- restore the honest person-silhouette glyph (the avatar's
    // original logged-out mark) and a "Sign in" label (shown in the mobile menu;
    // desktop carries it as aria-label + title). The link still routes to
    // #account, which renders a clean sign-in prompt (renderAccountPage signed-out).
    if (!navUser || !navUser.uid) {
      initialEl.innerHTML =
        '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" ' +
        'stroke="currentColor" stroke-width="1.6" aria-hidden="true">' +
        '<circle cx="12" cy="8" r="3.2"></circle>' +
        '<path d="M5.5 19c0-3.6 2.9-6 6.5-6s6.5 2.4 6.5 6"></path></svg>';
      if (navNameEl) { navNameEl.textContent = ''; }
      if (navAcctEl) { navAcctEl.textContent = 'Sign in'; }
      if (navProfileEl) {
        navProfileEl.setAttribute('aria-label', 'Sign in');
        navProfileEl.setAttribute('title', 'Sign in');
      }
    } else {
      var initial = 'P';
      if (typeof navUser.displayName === 'string' && navUser.displayName.length > 0) {
        initial = navUser.displayName.charAt(0).toUpperCase();
      } else if (typeof navUser.email === 'string' && navUser.email.length > 0) {
        initial = navUser.email.charAt(0).toUpperCase();
      }
      // textContent replaces any prior signed-out SVG child -- cycle-safe.
      initialEl.textContent = initial;

      // Canon §4-D: populate the mobile-menu profile-row name. Mirrors the
      // avatar derivation (displayName -> email) so the row matches the
      // avatar initial; the account-page display-name override is an
      // account-surface concern, not the nav's. Hidden on desktop via CSS.
      if (navNameEl) {
        var navName = 'Your account';
        if (typeof navUser.displayName === 'string' && navUser.displayName.length > 0) {
          navName = navUser.displayName;
        } else if (typeof navUser.email === 'string' && navUser.email.length > 0) {
          navName = navUser.email;
        }
        navNameEl.textContent = navName;
      }
      if (navAcctEl) { navAcctEl.textContent = 'Account'; }
      if (navProfileEl) {
        navProfileEl.setAttribute('aria-label', 'Account');
        navProfileEl.removeAttribute('title');
      }
    }
  }

  // 3.9: every route block leaves exactly one of {currentBookId,
  // currentArcId} set (or both null), never a stale pairing. Entering a
  // book leaves any arc; entering an arc leaves any book; the shelf and
  // notebook clear both. yumi-brain reads both slots ([yumi-brain.js
  // currentArc lens]) so a stale value in either is a stale-context
  // bug. The symmetric-clear pattern below is the prevention.
  // R7: the marks page (#book/<id>/marks) is RETIRED -- its material (marginalia
  // cards + grew rows) folded into book detail. Redirect to the canonical
  // #book/<id>; this block MUST still precede the #book/<id> detail block below
  // (which would otherwise swallow it). The redirect re-enters the router at
  // #book/<id> -> renderBookDetail.
  if (parts[0] === 'book' && parts[1] && parts[2] === 'marks') {
    // R7: location.replace (not hash-assign) so a stale /marks URL already in a
    // user's history is not a back-button trap (mirrors the new-subtheory route).
    location.replace('#book/' + parts[1]);
    return;
  }
  if (parts[0] === 'book' && parts[1]) {
    state.currentBookId = parts[1];
    state.currentArcId  = null;
    state.currentSubTheoryId = null;
    saveState();
    renderBookDetail(parts[1]);
    return;
  }
  if (parts[0] === 'artifact' && parts[1]) {
    // Artifact view sets currentBookId so yumi-brain's current-book
    // lens stays coherent across the workshop / finished-room boundary
    // -- the user is still engaged with this book, just on its
    // retrospective surface rather than the in-progress one.
    state.currentBookId = parts[1];
    state.currentArcId  = null;
    state.currentSubTheoryId = null;
    saveState();
    renderArtifact(parts[1]);
    return;
  }
  // R-ARC S4 (One Door): the '#arc/<id>/new-subtheory' mint-and-redirect route is
  // RETIRED — it was a parallel creation path (a second door). Arc-detail's "+ Sub-theory"
  // controls now funnel into the ONE door (notebookCreateSubTheory with a pre-selected
  // arc, the sole createSubTheory call site). The '#subtheory/<id>/build' route below
  // (the build surface for a minted draft) is unchanged.
  // 9.2: sub-theory detail / writing surface. Setting currentSubTheoryId
  // drives yumi-brain's currentSubTheory lens; currentArcId is set to
  // the parent arc so the arc lens stays coherent (the sub-theory lives
  // inside that arc), and currentBookId clears. A dangling id still sets
  // the pointer -- renderSubTheoryPage owns the not-found render.
  if (parts[0] === 'subtheory' && parts[1] && parts[2] === 'build') {
    // Wave 3 (Sub-theory Build): the create/compose surface for the freshly-
    // minted draft (new-subtheory redirects here, refresh-stable). Dark ground
    // comes from parts[0]==='subtheory' in umberGroundDark; 'arc' is untouched.
    // MUST precede the plain #subtheory/<id> branch (parts[1] truthy).
    var stbRec = state.subTheories[parts[1]];
    state.currentSubTheoryId = parts[1];
    state.currentArcId  = stbRec ? stbRec.arcId : null;
    state.currentBookId = null;
    saveState();
    renderSubTheoryBuild(parts[1]);
    return;
  }
  if (parts[0] === 'subtheory' && parts[1]) {
    var stRec = state.subTheories[parts[1]];
    state.currentSubTheoryId = parts[1];
    state.currentArcId  = stRec ? stRec.arcId : null;
    state.currentBookId = null;
    saveState();
    renderSubTheoryPage(parts[1]);
    return;
  }
  // ROOM-2 (INT-2): the note as a PLACE. Clears the lens pointers like every
  // sibling route -- entering a note is leaving any book/arc/sub-theory
  // (red-team H2: the sole non-clearing branch was a stale-lens leak).
  if (parts[0] === 'note' && parts[1]) {
    state.currentBookId = null;
    state.currentArcId = null;
    state.currentSubTheoryId = null;
    saveState();
    renderNoteSurface(parts[1]);
    return;
  }
  if (parts[0] === 'arc' && parts[1]) {
    // 3.9: arc detail. Setting currentArcId keeps yumi-brain's
    // currentArc context lens accurate; clearing currentBookId is the
    // symmetric half (entering an arc is leaving any book).
    state.currentArcId  = parts[1];
    state.currentBookId = null;
    state.currentSubTheoryId = null;
    saveState();
    renderArcDetail(parts[1]);
    return;
  }
  if (parts[0] === 'books') {
    // Shelf surface (3.5a). currentBookId clears symmetrically with
    // the notebook path so yumi-brain does not carry a stale book
    // reference into a shelf-scoped session.
    state.currentBookId = null;
    state.currentArcId  = null;
    state.currentSubTheoryId = null;
    saveState();
    renderShelf();
    return;
  }
  if (parts[0] === 'arcs') {
    // Stage 5.3 Stage 1: Arcs page (singular hash, no parameter).
    // The teaching surface; distinct from #arc/<id> (arc detail).
    // Symmetric clear of both pointer fields, mirroring the books
    // and notebook branches -- entering the Arcs page is leaving
    // both any book and any specific arc.
    state.currentBookId = null;
    state.currentArcId  = null;
    state.currentSubTheoryId = null;
    saveState();
    renderArcsPage();
    return;
  }
  // Stage 14.3 Stage 4: Account page (#account). Symmetric clear of the
  // three pointer fields, mirroring the books / arcs / notebook branches
  // -- entering the Account page is leaving any book, arc, and sub-theory.
  // Placed BEFORE the notebook fallthrough so #account is caught here, not
  // swallowed by the catch-all below.
  if (parts[0] === 'account') {
    // R9a (A1): #account is merged into the single Profile at #profile. Redirect
    // (refresh-stable, no history push -- the R7 /marks precedent, views.js:521) so
    // old links + bookmarks land on #profile; the #profile arm does the pointer
    // clear + render. renderAccountPage is retired (defined-but-unrouted; see
    // r9a-build.md "unrouted legacy renderers" debt).
    location.replace('#profile');
    return;
  }
  // About page (#about): a static orientation surface. Symmetric pointer clear
  // mirroring the account / home branches; placed BEFORE the notebook
  // fallthrough so #about is caught here, not swallowed by the catch-all.
  if (parts[0] === 'about') {
    state.currentBookId = null;
    state.currentArcId  = null;
    state.currentSubTheoryId = null;
    saveState();
    renderAbout();
    return;
  }
  // Batch 4A: Home landing surface (#home). Symmetric clear of the three
  // pointer fields, mirroring the books / arcs / account branches --
  // entering Home is leaving any book, arc, and sub-theory. Placed BEFORE
  // the notebook fallthrough so #home is caught here, not swallowed by the
  // catch-all (which is left as-is for empty / unknown hashes).
  if (parts[0] === 'home') {
    state.currentBookId = null;
    state.currentArcId  = null;
    state.currentSubTheoryId = null;
    saveState();
    renderHome();
    return;
  }
  // 6.2c: 'What Yumi sees' transparency page (#yumi-sees). Reached from
  // Yumi's panel affordance, not the top nav. Symmetric pointer clear
  // mirroring the account / home branches. Placed BEFORE the notebook
  // fallthrough so the route is caught here, not swallowed by the catch-all.
  if (parts[0] === 'yumi-sees') {
    state.currentBookId = null;
    state.currentArcId  = null;
    state.currentSubTheoryId = null;
    saveState();
    renderWhatYumiSeesPage();
    return;
  }
  // Wave 6 (re-scoped): the reader's own profile surface (#profile). Real
  // backing only (userProfiles + the user's own arcs); social counters are
  // deferred (no cross-user data model). Symmetric pointer clear mirroring the
  // account / home branches. Placed BEFORE the notebook fallthrough so #profile
  // is caught here, not swallowed by the catch-all.
  if (parts[0] === 'profile') {
    state.currentBookId = null;
    state.currentArcId  = null;
    state.currentSubTheoryId = null;
    saveState();
    // R9a (A1): the merged Profile. Fresh route entry is always owner mode --
    // "preview as visitor" is a within-page toggle, never a persisted state.
    _pfPreview = false;
    renderProfilePage();
    return;
  }
  // W6.5 social surfaces. Symmetric pointer clear like the branches above;
  // placed BEFORE the notebook fallthrough so they are caught here.
  if (parts[0] === 'commons') {
    state.currentBookId = null;
    state.currentArcId  = null;
    state.currentSubTheoryId = null;
    saveState();
    renderCommons();
    return;
  }
  if (parts[0] === 'reader' && parts[1]) {
    state.currentBookId = null;
    state.currentArcId  = null;
    state.currentSubTheoryId = null;
    saveState();
    renderOtherProfile(parts[1]);
    return;
  }
  if (parts[0] === 'walk' && parts[1]) {
    state.currentBookId = null;
    state.currentArcId  = null;
    state.currentSubTheoryId = null;
    saveState();
    renderInteract(parts[1]);
    return;
  }
  // W8 Lane B: the global Search page (#search). Reads existing state only (a
  // flatten-once index over books/arcs/sub-theories/notes); touches no write or
  // publish path. Symmetric pointer clear like the branches above; placed BEFORE
  // the notebook fallthrough so #search is caught here, not swallowed by the catch-all.
  if (parts[0] === 'search') {
    state.currentBookId = null;
    state.currentArcId  = null;
    state.currentSubTheoryId = null;
    saveState();
    renderSearch();
    return;
  }
  // Notebook (explicit), empty hash, and any unknown route all
  // converge on the unified Notebook view. currentBookId clears
  // symmetrically on the way in so yumi-brain's retrieval path
  // does not carry a stale book reference.
  state.currentBookId = null;
  state.currentArcId  = null;
  state.currentSubTheoryId = null;
  saveState();
  renderNotebook();
}

// ============================================================================
// W8 Lane B -- GLOBAL SEARCH (#search, renderSearch on .lum-amber). A flatten-
// once index over the four content kinds (books, arcs, sub-theories, notes),
// filtered in memory per keystroke. Reads existing state only (no write/publish
// path). Binds REAL signal: mockup fields with no backing (arc status/glow, note
// title, note page-ref, the "rooted/gathering/new" vocabulary) are replaced with
// real accessors or omitted -- never fabricated. Sub-theory glyphs render through
// the FIELD vocabulary via _stPickerMarkSvg (Verdict B), NOT marks.js. Yumi-cyan
// is reserved for the (seam-only) cross-cut, never the note icon.
// DEBT (logged, docs/checkpoints/w8-lane-b-search-recon.md): the per-kind haystack
// enumeration below is duplicated with spotlight.js's spotlightSearch -- consolidate
// into one shared corpus builder when spotlight is next touched.
// ============================================================================

function _searchEsc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Case-insensitive match highlight. XSS-safe: ALL text is escaped; the only
// injected tag is <mark> around the matched span(s).
function _searchHighlight(text, q) {
  var t = String(text == null ? '' : text);
  if (!q) { return _searchEsc(t); }
  var lo = t.toLowerCase(), ql = q.toLowerCase();
  var out = '', i = 0, idx;
  while ((idx = lo.indexOf(ql, i)) > -1) {
    out = out + _searchEsc(t.slice(i, idx))
      + '<mark>' + _searchEsc(t.slice(idx, idx + ql.length)) + '</mark>';
    i = idx + ql.length;
  }
  out = out + _searchEsc(t.slice(i));
  return out;
}

// Real sub-theory maturity word (the shipped sub-theory-detail band, views.js
// ~8702) -- the mockup's "rooted/gathering/new" has no backing.
// FF-7: the ONE canonical sub-theory maturity ramp (was _searchSubMaturityWord;
// the Page duplicated it inline and the Arc-Read face used a DIFFERENT ramp on the
// same score). Page + #search + Arc-Read all call this now.
function _stMaturityWord(v) {
  var m = (typeof v === 'number' && isFinite(v)) ? v : 0;
  if (m < 0.34) { return 'nascent'; }
  if (m < 0.67) { return 'developing'; }
  return 'established';
}

// Flatten all four kinds into a per-item search record ONCE (called on route
// entry). Each: { kind, title, sub, snip, crumb, hay(lowercased), route, ...glyph }.
function _searchBuildIndex() {
  var items = [];
  var user = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
  var uid = (user && user.uid) ? user.uid : null;
  var SEED = '__praxis_seed__';
  function ownVisible(rec) {
    if (!rec) { return false; }
    if (rec.userId === SEED) { return true; }
    return !!(uid && rec.userId === uid);
  }
  var k;

  // ARCS
  if (state.arcs) {
    for (k in state.arcs) {
      if (!Object.prototype.hasOwnProperty.call(state.arcs, k)) { continue; }
      var arc = state.arcs[k];
      if (!ownVisible(arc)) { continue; }
      var counts = (typeof _arcCardCounts === 'function')
        ? _arcCardCounts(k, arc) : { subTheories: 0 };
      var threadN = 0;
      if (typeof _arcDetailBuildSubTheoryData === 'function') {
        var ad = _arcDetailBuildSubTheoryData(arc);
        threadN = (ad && ad.edges) ? ad.edges.length : 0;
      }
      var arcTitle = (typeof arc.title === 'string') ? arc.title : '';
      var arcDesc = (typeof arc.description === 'string') ? arc.description : '';
      var arcSub = counts.subTheories
        + (counts.subTheories === 1 ? ' sub-theory' : ' sub-theories')
        + ' · ' + threadN + (threadN === 1 ? ' thread' : ' threads');
      items.push({
        kind: 'arc',
        title: arcTitle || 'Untitled arc',
        sub: arcSub,
        snip: '',
        crumb: 'Arc · ' + ((typeof _arcMaturityWord === 'function') ? _arcMaturityWord(k) : ''),
        hay: (arcTitle + ' ' + arcDesc + ' ' + arcSub).toLowerCase(),
        route: '#arc/' + k
      });
    }
  }

  // SUB-THEORIES
  if (state.subTheories) {
    for (k in state.subTheories) {
      if (!Object.prototype.hasOwnProperty.call(state.subTheories, k)) { continue; }
      var sub = state.subTheories[k];
      if (!ownVisible(sub)) { continue; }
      var parentArc = (sub.arcId && state.arcs) ? state.arcs[sub.arcId] : null;
      var parentTitle = (parentArc && typeof parentArc.title === 'string') ? parentArc.title : '';
      var hdr = (typeof sub.header === 'string') ? sub.header : '';
      var matV = (typeof _stComputeMaturity === 'function') ? _stComputeMaturity(sub) : 0;
      var hash = (typeof window.stHashIndices === 'function')
        ? window.stHashIndices(k) : { shapeIdx: 0, colorIdx: 0 };
      var shp = (typeof sub.markShape === 'number' && sub.markShape >= 0 && sub.markShape <= 15)
        ? sub.markShape : hash.shapeIdx;
      var clr = (typeof sub.markColor === 'number' && sub.markColor >= 0 && sub.markColor <= 15)
        ? sub.markColor : hash.colorIdx;
      var body1 = (typeof sub.bodyPublic === 'string') ? sub.bodyPublic : '';
      items.push({
        kind: 'sub',
        title: hdr || 'Untitled sub-theory',
        sub: parentTitle ? ('in ' + parentTitle) : '',
        snip: '',
        crumb: 'Sub-theory · ' + _stMaturityWord(matV),
        hay: (hdr + ' ' + body1 + ' ' + parentTitle).toLowerCase(),
        route: '#subtheory/' + k,
        subId: k, shape: shp, color: clr
      });
    }
  }

  // BOOKS -- signed-in reads the user's shelf (userBooks[uid].bookIds); signed-out
  // reads the full catalog, mirroring renderShelf (views.js ~3190).
  function pushBook(bid) {
    var book = (bid && state.books) ? state.books[bid] : null;
    if (!book) { return; }
    var bt = (typeof book.title === 'string') ? book.title : '';
    var ba = (typeof book.author === 'string') ? book.author : '';
    items.push({
      kind: 'book',
      title: bt || 'Untitled',
      sub: ba,
      snip: '',
      crumb: 'Library · ' + ((typeof statusText === 'function') ? statusText(book.status) : ''),
      hay: (bt + ' ' + ba).toLowerCase(),
      route: '#book/' + bid,
      book: book
    });
  }
  var bookIdList = (uid && state.userBooks && state.userBooks[uid] && state.userBooks[uid].bookIds)
    ? state.userBooks[uid].bookIds : null;
  if (bookIdList) {
    var bi;
    for (bi = 0; bi < bookIdList.length; bi = bi + 1) {
      var raw = bookIdList[bi];
      pushBook((typeof raw === 'string') ? raw : (raw && raw.id));
    }
  } else if (state.books) {
    for (k in state.books) {
      if (Object.prototype.hasOwnProperty.call(state.books, k)) { pushBook(k); }
    }
  }

  // NOTES -- private/own only (no seed notes).
  if (state.notebookEntries) {
    for (k in state.notebookEntries) {
      if (!Object.prototype.hasOwnProperty.call(state.notebookEntries, k)) { continue; }
      var en = state.notebookEntries[k];
      if (!en) { continue; }
      if (!(uid && en.userId === uid)) { continue; }
      var nbody = (typeof en.body === 'string') ? en.body : '';
      var srcTitle = 'in Notebook';
      if (en.bookIds && en.bookIds[0] && state.books
          && state.books[en.bookIds[0]] && state.books[en.bookIds[0]].title) {
        srcTitle = state.books[en.bookIds[0]].title;
      } else if (en.arcIds && en.arcIds[0] && state.arcs
          && state.arcs[en.arcIds[0]] && state.arcs[en.arcIds[0]].title) {
        srcTitle = state.arcs[en.arcIds[0]].title;
      }
      items.push({
        kind: 'note',
        title: (typeof _stEntryPreview === 'function') ? _stEntryPreview(en) : (nbody || 'Note'),
        sub: 'note · ' + srcTitle,
        snip: nbody,
        crumb: (typeof notebookRegisterLabel === 'function') ? notebookRegisterLabel(en.register) : 'Note',
        hay: (nbody + ' ' + srcTitle).toLowerCase(),
        route: '#note/' + en.id   // ROOM-2 (absorbs Slice 10): the deep link
      });
    }
  }

  return items;
}

// The identity glyph for a row: sub-theory = REAL field mark (_stPickerMarkSvg,
// Verdict B); book = cover (real image else typeset cloth); arc = neutral gold
// constellation glyph (no per-arc color exists); note = non-cyan document icon
// (cyan is reserved for the Yumi cross-cut seam).
function _searchGlyphEl(it, pal) {
  var g = document.createElement('span');
  if (it.kind === 'sub') {
    g.className = 'search-row-mark';
    g.innerHTML = _stPickerMarkSvg(it.subId, it.shape, it.color, pal, false);
    return g;
  }
  if (it.kind === 'book') {
    var cu = it.book && it.book.coverUrl;
    if (cu) {
      g.className = 'search-row-cover';
      var img = document.createElement('img');
      img.className = 'search-row-cover-img';
      img.setAttribute('alt', '');
      img.src = cu;
      g.appendChild(img);
    } else {
      g.className = 'search-row-cover search-row-cover-fallback';
      var ft = document.createElement('span'); ft.className = 'src-t'; ft.textContent = it.title;
      var fa = document.createElement('span'); fa.className = 'src-a'; fa.textContent = it.sub;
      g.appendChild(ft); g.appendChild(fa);
    }
    return g;
  }
  if (it.kind === 'arc') {
    g.className = 'search-row-arc';
    g.innerHTML = '<svg viewBox="0 0 34 34" aria-hidden="true">'
      + '<circle cx="17" cy="17" r="13" fill="none" stroke="currentColor" stroke-opacity=".35" stroke-width="1.4"/>'
      + '<circle cx="17" cy="17" r="4" fill="currentColor"/>'
      + '<circle cx="27" cy="12" r="2.4" fill="currentColor" fill-opacity=".7"/>'
      + '<circle cx="9" cy="23" r="2" fill="currentColor" fill-opacity=".6"/>'
      + '</svg>';
    return g;
  }
  // note
  g.className = 'search-row-note';
  g.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-opacity=".85" aria-hidden="true">'
    + '<path d="M6 3h9l4 4v14H6z"/><line x1="9" y1="9" x2="15" y2="9"/><line x1="9" y1="13" x2="15" y2="13"/>'
    + '</svg>';
  return g;
}

// One result row -> routes to its item. Text goes in via textContent or the
// escaped _searchHighlight (XSS-safe); only the glyph/highlight use innerHTML.
function _searchRowEl(it, q, pal) {
  var a = document.createElement('a');
  a.className = 'search-res';
  a.setAttribute('href', it.route);
  a.appendChild(_searchGlyphEl(it, pal));
  var body = document.createElement('div');
  body.className = 'search-res-body';
  var t = document.createElement('div');
  t.className = 'search-res-title';
  t.innerHTML = _searchHighlight(it.title, q);
  body.appendChild(t);
  if (it.sub) {
    var s = document.createElement('div');
    s.className = 'search-res-sub';
    s.innerHTML = _searchHighlight(it.sub, q);
    body.appendChild(s);
  }
  if (it.snip) {
    var sn = document.createElement('div');
    sn.className = 'search-res-snip';
    sn.innerHTML = _searchHighlight(it.snip, q);
    body.appendChild(sn);
  }
  var cr = document.createElement('div');
  cr.className = 'search-res-crumb';
  cr.textContent = it.crumb;
  body.appendChild(cr);
  a.appendChild(body);
  return a;
}

// Initial invitation (no query) or honest empty ("Nothing matches ... yet").
// When logged-out, the copy does NOT imply gathered content and a quiet sign-in
// affordance is added -- reusing the sibling pattern (.btn btn-primary "Sign in"
// -> signInWithGoogle, as in buildNotebookSignedOut / the shelf sign-in prompt);
// no new treatment (logged-out was out of the original wave scope, added as a
// consistency fix so Search matches its sibling surfaces).
function _searchEmptyEl(isInitial, q) {
  // W11 S8 Lane 1: signed-out never reaches Search (renderSearch hard-gates at
  // the top), so this is the signed-in empty only -- the loggedOut sign-in
  // branch was removed with the soft-CTA.
  var e = document.createElement('div');
  e.className = 'search-empty';
  var mark = document.createElement('div');
  mark.className = 'search-empty-mark';
  mark.setAttribute('aria-hidden', 'true');
  e.appendChild(mark);
  var text = document.createElement('div');
  text.className = 'search-empty-text';
  var sub = document.createElement('div');
  sub.className = 'search-empty-sub';
  if (isInitial) {
    text.textContent = 'Everything you’ve gathered is searchable here.';
    sub.innerHTML = 'a book title · an arc · a sub-theory · a note you wrote'
      + '<br>try a word you’ve been circling';
  } else {
    text.textContent = 'Nothing matches “' + q + '” yet.';
    sub.textContent = 'try a shorter word, or clear the filter above';
  }
  e.appendChild(text);
  e.appendChild(sub);
  return e;
}

// W8 Lane B: the "Yumi · across your results" cross-cut SEAM. The single named
// mount point where a FUTURE generative cross-result Yumi line will attach. NO-OP
// today: the gate (>=3 kinds AND >=4 hits) is computed by the caller and passed in,
// but this renders NOTHING (no LLM call, no generated text) -- the container stays
// empty (CSS :empty hides it). When Yumi's cross-cut voice ships, it mounts HERE.
function _searchYumiCrosscutSeam(container, eligible) {
  return;
}

function renderSearch() {
  var host = document.getElementById(APP_EL_ID);
  if (!host) { return; }
  host.innerHTML = '';
  // W11 S8 Lane 1 (L3): search indexes your own gathered library (own arcs/subs,
  // and notes that require a uid) -- hard-gate signed-out (mirror #notebook: in-
  // place prompt, no redirect). Replaces the prior soft-CTA (the _searchEmptyEl
  // loggedOut sign-in branch, now removed).
  var searchGateUser = getCurrentUser();
  if (!searchGateUser || !searchGateUser.uid) {
    var soWrap = document.createElement('section');
    soWrap.className = 'search lum-amber';
    soWrap.appendChild(buildSignedOutPrompt('Search is private', 'Sign in to search everything you’ve gathered — your books, arcs, sub-theories, and the notes you wrote.'));
    host.appendChild(soWrap);
    return;
  }
  var pal = (ls('praxis_constellation_palette', 'colorful') === 'muted') ? 'muted' : 'colorful';
  var index = _searchBuildIndex();
  var activeKind = 'all';
  var debTimer = null;

  var wrap = document.createElement('section');
  wrap.className = 'search lum-amber';
  var page = document.createElement('div');
  page.className = 'search-page';
  wrap.appendChild(page);

  var shell = document.createElement('div');
  shell.className = 'search-shell';
  var icon = document.createElement('span');
  icon.className = 'search-icon';
  icon.setAttribute('aria-hidden', 'true');
  icon.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8">'
    + '<circle cx="11" cy="11" r="7"></circle><line x1="21" y1="21" x2="16.5" y2="16.5"></line></svg>';
  shell.appendChild(icon);
  var input = document.createElement('input');
  input.className = 'search-input';
  input.setAttribute('type', 'text');
  input.setAttribute('autocomplete', 'off');
  input.setAttribute('spellcheck', 'false');
  input.setAttribute('aria-label', 'Search everything you have gathered');
  input.setAttribute('placeholder', 'Search everything you’ve gathered…');
  shell.appendChild(input);
  page.appendChild(shell);

  var scope = document.createElement('div');
  scope.className = 'search-scope';
  scope.textContent = 'Across books · arcs · sub-theories · notes';
  page.appendChild(scope);

  var chipsEl = document.createElement('div');
  chipsEl.className = 'search-chips';
  page.appendChild(chipsEl);

  var crosscutEl = document.createElement('div');
  crosscutEl.className = 'search-crosscut';
  page.appendChild(crosscutEl);

  var resultsEl = document.createElement('div');
  resultsEl.className = 'search-results';
  page.appendChild(resultsEl);

  var KINDS = [
    { key: 'all', label: 'All' },
    { key: 'book', label: 'Books' },
    { key: 'arc', label: 'Arcs' },
    { key: 'sub', label: 'Sub-theories' },
    { key: 'note', label: 'Notes' }
  ];
  var GROUP_ORDER = ['arc', 'sub', 'book', 'note'];
  var GROUP_LABEL = { arc: 'Arcs', sub: 'Sub-theories', book: 'Books', note: 'Notes' };

  function curQ() { return input.value.replace(/^\s+|\s+$/g, ''); }

  // Chip counts respect the query but IGNORE the active-kind filter.
  function kindCount(kind, q) {
    var n = 0, i, it, ql = q.toLowerCase();
    for (i = 0; i < index.length; i = i + 1) {
      it = index[i];
      if (kind !== 'all' && it.kind !== kind) { continue; }
      if (q && it.hay.indexOf(ql) < 0) { continue; }
      n = n + 1;
    }
    return n;
  }

  function renderChips(q) {
    chipsEl.innerHTML = '';
    var i;
    for (i = 0; i < KINDS.length; i = i + 1) {
      (function (kd) {
        var b = document.createElement('button');
        b.className = 'search-chip search-chip-' + kd.key + (activeKind === kd.key ? ' is-on' : '');
        b.setAttribute('type', 'button');
        if (kd.key !== 'all') {
          var dot = document.createElement('span');
          dot.className = 'search-chip-dot';
          dot.setAttribute('aria-hidden', 'true');
          b.appendChild(dot);
        }
        var lab = document.createElement('span');
        lab.className = 'search-chip-label';
        lab.textContent = kd.label;
        b.appendChild(lab);
        var nn = document.createElement('span');
        nn.className = 'search-chip-n';
        nn.textContent = kindCount(kd.key, q);
        b.appendChild(nn);
        b.addEventListener('click', function () { activeKind = kd.key; doRender(); });
        chipsEl.appendChild(b);
      })(KINDS[i]);
    }
  }

  function doRender() {
    var q = curQ();
    renderChips(q);
    crosscutEl.innerHTML = '';
    resultsEl.innerHTML = '';

    var hits = [], i, it, ql = q.toLowerCase();
    for (i = 0; i < index.length; i = i + 1) {
      it = index[i];
      if (activeKind !== 'all' && it.kind !== activeKind) { continue; }
      if (q && it.hay.indexOf(ql) < 0) { continue; }
      hits.push(it);
    }

    if (!q) {
      _searchYumiCrosscutSeam(crosscutEl, false);
      resultsEl.appendChild(_searchEmptyEl(true, ''));
      return;
    }
    if (!hits.length) {
      _searchYumiCrosscutSeam(crosscutEl, false);
      resultsEl.appendChild(_searchEmptyEl(false, q));
      return;
    }

    // cross-cut gate (seam only, no visible text)
    var kmap = {}, kc = 0;
    for (i = 0; i < hits.length; i = i + 1) {
      if (!kmap[hits[i].kind]) { kmap[hits[i].kind] = 1; kc = kc + 1; }
    }
    _searchYumiCrosscutSeam(crosscutEl, (kc >= 3 && hits.length >= 4));

    var gi, g, group, j;
    for (gi = 0; gi < GROUP_ORDER.length; gi = gi + 1) {
      g = GROUP_ORDER[gi];
      group = [];
      for (i = 0; i < hits.length; i = i + 1) { if (hits[i].kind === g) { group.push(hits[i]); } }
      if (!group.length) { continue; }
      var groupEl = document.createElement('div');
      groupEl.className = 'search-group';
      var head = document.createElement('div');
      head.className = 'search-group-head';
      var gl = document.createElement('span');
      gl.className = 'search-group-label';
      gl.textContent = GROUP_LABEL[g];
      var gc = document.createElement('span');
      gc.className = 'search-group-count';
      gc.textContent = group.length;
      head.appendChild(gl); head.appendChild(gc);
      groupEl.appendChild(head);
      for (j = 0; j < group.length; j = j + 1) { groupEl.appendChild(_searchRowEl(group[j], q, pal)); }
      resultsEl.appendChild(groupEl);
    }
  }

  // ~100ms debounce (notebookEntries can be large; the recon's index verdict).
  input.addEventListener('input', function () {
    if (debTimer) { clearTimeout(debTimer); }
    debTimer = setTimeout(doRender, 100);
  });

  host.appendChild(wrap);
  doRender();
  input.focus();
}

// HOME (renderHome on .lum-amber-deep) -- Amber threshold per design/"Wave 2 The
// Shell.html" MINUS the nav rail. Variants A/B draw ONLY through the locked
// renderer; reader-question / built-on / walk-with pieces omitted (no source).
var HOME_GROWING_MAX = 0.7; // 'still growing' = aggregate maturity below 'bright'

// Yumi's voice: cyan dot + Cormorant italic. Deterministic template text only.
function homeYumiLine(text) {
  var y = document.createElement('div');
  y.className = 'home-yumi';
  var dot = document.createElement('span');
  dot.className = 'home-yumi-dot';
  dot.setAttribute('aria-hidden', 'true');
  y.appendChild(dot);
  var t = document.createElement('span');
  t.className = 'home-yumi-text';
  t.textContent = text;
  y.appendChild(t);
  return y;
}

// The signed-in user's OWN arcs (renderArcsPage predicate), oldest-first, defaulted.
function homeOwnArcs() {
  var out = [];
  var u = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
  var uid = u ? u.uid : null;
  if (!uid || !state.arcs) { return out; }
  var id;
  for (id in state.arcs) {
    if (Object.prototype.hasOwnProperty.call(state.arcs, id)) {
      var rec = state.arcs[id];
      if (rec && rec.userId === uid) { out.push(rec); }
    }
  }
  out.sort(function (a, b) {
    var ca = (a && a.createdAt) ? a.createdAt : 0;
    var cb = (b && b.createdAt) ? b.createdAt : 0;
    if (ca !== cb) { return ca - cb; }
    return (a.id < b.id) ? -1 : ((a.id > b.id) ? 1 : 0);
  });
  return out;
}

// OPTION A whole-field data: ONE node per arc (id = arc.id -> id-hash emblem,
// maturity -> glow, marks:[] no dots, edges:[] unlinked).
function buildHomeFieldData(arcs) {
  var nodes = [];
  var i;
  for (i = 0; i < arcs.length; i = i + 1) {
    var a = arcs[i];
    if (!a || !a.id) { continue; }
    nodes.push({
      id: a.id,
      header: (typeof a.title === 'string') ? a.title : '',
      maturity: (typeof _arcAggregateMaturity === 'function') ? _arcAggregateMaturity(a.id) : 0,
      marks: []
    });
  }
  return { id: 'home-field', question: '', subTheories: nodes, edges: [], books: [], yumiNoticing: [] };
}

// Own arcs still growing (aggregate maturity below HOME_GROWING_MAX).
function homeGrowingCount(arcs) {
  var g = 0, i;
  for (i = 0; i < arcs.length; i = i + 1) {
    var m = (typeof _arcAggregateMaturity === 'function') ? _arcAggregateMaturity(arcs[i].id) : 0;
    if (m < HOME_GROWING_MAX) { g = g + 1; }
  }
  return g;
}

// Derived last-worked (ms): max(arc.createdAt, max member sub.updatedAt||createdAt) --
// the app's true "last touched", NOT arc.updatedAt. Orders Variant B.
function homeLastWorked(arcId, rec) {
  var newest = (rec && rec.createdAt) ? rec.createdAt : 0;
  var subs = (typeof _arcSubsOf === 'function') ? _arcSubsOf(arcId) : [];
  var i;
  for (i = 0; i < subs.length; i = i + 1) {
    var u = subs[i].updatedAt || subs[i].createdAt || 0;
    if (u > newest) { newest = u; }
  }
  return newest;
}

// Tap-to-descend: fixedArcId (seed demo) -> any tap opens it; null -> tapping a
// light opens #arc/<data-st-sub-id> (= the node's arc id).
function homeFieldNav(svg, fixedArcId) {
  if (!svg) { return; }
  svg.style.cursor = 'pointer';
  svg.addEventListener('click', function (e) {
    if (fixedArcId) { location.hash = '#arc/' + fixedArcId; return; }
    var n = e.target;
    while (n && n !== svg) {
      if (n.getAttribute && n.getAttribute('data-st-sub-id')) {
        location.hash = '#arc/' + n.getAttribute('data-st-sub-id');
        return;
      }
      n = n.parentNode;
    }
  });
}

// Variant A field: own arcs -> one-emblem-per-arc; zero -> the static seed arc demo
// (whole panel -> seed arc); none + no seed -> a quiet line. Locked renderer only.
function homeRenderField(wf, ownArcs) {
  if (!wf || typeof window.renderSubTheoryConstellation !== 'function') { return; }
  var NS = 'http://www.w3.org/2000/svg';
  if (ownArcs.length > 0) {
    var svg = document.createElementNS(NS, 'svg');
    svg.setAttribute('viewBox', '0 0 940 340');
    svg.setAttribute('xmlns', NS);
    wf.appendChild(svg);
    window.renderSubTheoryConstellation(buildHomeFieldData(ownArcs), svg, { showLegend: false, markScale: 1.15 });
    homeFieldNav(svg, null);
    return;
  }
  var seedArcId = (state.seeds && state.seeds.pedagogyOfDesire) ? state.seeds.pedagogyOfDesire.arcId : null;
  var seedArc = (seedArcId && state.arcs) ? state.arcs[seedArcId] : null;
  var seedData = (seedArc && typeof _arcDetailBuildSubTheoryData === 'function') ? _arcDetailBuildSubTheoryData(seedArc) : null;
  if (seedData && seedData.subTheories && seedData.subTheories.length) {
    var svg2 = document.createElementNS(NS, 'svg');
    svg2.setAttribute('viewBox', '0 0 940 340');
    svg2.setAttribute('xmlns', NS);
    wf.appendChild(svg2);
    window.renderSubTheoryConstellation(seedData, svg2, { showLegend: false, markScale: 1.15 });
    homeFieldNav(svg2, seedArcId);
    return;
  }
  var line = document.createElement('p');
  line.className = 'home-wfcap';
  line.textContent = 'Your arcs and the ideas between them, drawn as you read.';
  wf.appendChild(line);
}

// Alternator apply: show one variant, hide the other, mark its tab is-on.
function homeShowVariant(root, which) {
  var vs = root.querySelectorAll('.home-variant');
  var i;
  for (i = 0; i < vs.length; i = i + 1) {
    vs[i].className = (vs[i].getAttribute('data-home-variant') === which)
      ? 'home-variant' : 'home-variant home-variant-hidden';
  }
  var tabs = root.querySelectorAll('.home-alt .seg-opt');
  for (i = 0; i < tabs.length; i = i + 1) {
    tabs[i].className = (tabs[i].getAttribute('data-home-variant') === which)
      ? 'seg-opt is-on' : 'seg-opt';
  }
}

// A Variant B left-off card: per-arc mini-constellation (arc's own sub-theories via
// _arcDetailBuildSubTheoryData + the locked renderer), title, count · touched, Continue.
function homeLeftOffCard(arc) {
  var card = document.createElement('div');
  // THE HOUR: the arc card becomes a LIT PAGE -- vellum, 15px radius, the
  // Apple-tight shadow trio, and the on-card token ramp. .lit-page-lift adds the
  // MO-1 hover lift, since this row IS interactive. The legacy .lum-glass class
  // is KEPT alongside, not rewritten (canon §4-D: primitives are additive).
  card.className = 'home-arc lum-glass lit-page lit-page-lift';

  // THE HOUR: the cloth spine -- the bound edge of a printed page. The hue is
  // chosen DETERMINISTICALLY from the arc id, not at random and not by index, so
  // a given arc keeps the same spine across renders, re-orders and sessions
  // (a shuffling spine would read as a bug). Three cloths, per the reference.
  var spine = document.createElement('span');
  var spineCloths = ['lit-spine-ox', 'lit-spine-olive', 'lit-spine-teal'];
  var spineKey = String(arc && arc.id ? arc.id : '');
  var spineSum = 0;
  for (var si = 0; si < spineKey.length; si++) { spineSum += spineKey.charCodeAt(si); }
  spine.className = 'lit-spine ' + spineCloths[spineSum % 3];
  card.appendChild(spine);

  var field = document.createElement('div');
  field.className = 'home-arcfield';
  var ff = document.createElement('div');
  ff.className = 'home-arc-ff';
  field.appendChild(ff);
  card.appendChild(field);
  if (typeof window.renderSubTheoryConstellation === 'function' &&
      typeof _arcDetailBuildSubTheoryData === 'function') {
    var data = _arcDetailBuildSubTheoryData(arc);
    if (data) { data.question = ''; } // home mini-field: no center title (card heads it)
    var NS = 'http://www.w3.org/2000/svg';
    var svg = document.createElementNS(NS, 'svg');
    svg.setAttribute('viewBox', '0 0 600 360');
    svg.setAttribute('xmlns', NS);
    ff.appendChild(svg);
    window.renderSubTheoryConstellation(data, svg, { showLegend: false, markScale: 1.1 });
  }

  var body = document.createElement('div');
  body.className = 'home-arcbody';
  var top = document.createElement('div');
  top.className = 'home-arctop';
  var tt = document.createElement('span');
  tt.className = 'home-arctitle';
  tt.textContent = arc.title || 'Untitled arc';
  top.appendChild(tt);
  var mm = document.createElement('span');
  mm.className = 'home-arcmeta';
  var counts = (typeof _arcCardCounts === 'function') ? _arcCardCounts(arc.id, arc) : { subTheories: 0 };
  var metaText = counts.subTheories + (counts.subTheories === 1 ? ' sub-theory' : ' sub-theories');
  var touched = (typeof _arcTouchedWord === 'function') ? _arcTouchedWord(arc.id, arc) : '';
  if (touched) { metaText = metaText + ' · ' + touched; }
  mm.textContent = metaText;
  // THE HOUR: an ember dot marks an arc touched TODAY -- presence and attention,
  // per SEMANTIC GOLD. Display-only, derived from the same _arcTouchedWord value
  // already being rendered: no new state, no data-model change, no extra read.
  if (touched === 'touched today') { mm.className = 'home-arcmeta home-arcmeta-ember'; }
  top.appendChild(mm);
  body.appendChild(top);

  // DW-2 (>=1200 only; hidden <=1199 via CSS): surface the arc's EXISTING
  // description to fill the recomposed wide card. Felt-pass-ruled additive line.
  if (arc.description) {
    var dd = document.createElement('p');
    dd.className = 'home-arcdesc';
    dd.textContent = arc.description;
    body.appendChild(dd);
  }

  var act = document.createElement('div');
  act.className = 'home-arcact';
  var cont = document.createElement('a');
  cont.className = 'home-arcbtn home-arcbtn-primary';
  cont.href = '#arc/' + arc.id;
  cont.textContent = 'Continue →';
  act.appendChild(cont);
  body.appendChild(act);
  card.appendChild(body);
  return card;
}

// Currently-reading books: normalizeStatus(status) === 'reading' (mirrors shelfReadingCount).
function homeReadingBooks() {
  var out = [];
  if (!state.books) { return out; }
  var id;
  for (id in state.books) {
    if (Object.prototype.hasOwnProperty.call(state.books, id)) {
      var b = state.books[id];
      if (!b) { continue; }
      var st = (typeof normalizeStatus === 'function') ? normalizeStatus(b.status) : b.status;
      if (st === 'reading') { out.push(b); }
    }
  }
  return out;
}

// A still-reading spine -> the shelf. D2: adopts the Shelf's cover treatment --
// a real self-healing cover via buildSelfHealingCover (candidate-walk -> "cover
// pending" placeholder on error/none), so a coverless book can never show a
// broken image. The old text-only bar + left edge highlight (.home-mspine-edge)
// is retired -- a face-on cover has no spine edge.
function homeReadingSpine(book) {
  var s = document.createElement('a');
  s.className = 'home-mspine';
  s.href = '#books';
  if (book && book.title) { s.title = book.title; }
  s.appendChild(buildSelfHealingCover(book, 'home-mspine-cover-img', function() {
    var cover = document.createElement('div');
    cover.className = 'home-mspine-cover';
    var t = document.createElement('span');
    t.className = 'home-mspine-title';
    t.textContent = book.title || 'Untitled';
    cover.appendChild(t);
    var pend = document.createElement('span');
    pend.className = 'home-mspine-pending';
    pend.textContent = 'cover pending';
    cover.appendChild(pend);
    return cover;
  }));
  return s;
}

function renderHome() {
  var host = document.getElementById(APP_EL_ID);
  if (!host) return;
  host.innerHTML = '';

  var wrap = document.createElement('section');
  wrap.className = 'home-page lum-amber-deep';

  // OG1/OG2/OG4: an honest front door. A signed-out visitor is NOT "welcomed
  // back" onto a fabricated personal dashboard (no dead "No arcs yet / Nothing
  // open" widgets) -- they get a real introduction and a Sign-in CTA. Reuses
  // the existing buildSignedOutPrompt primitive (shared crest + signInWithGoogle);
  // no new first-run UX.
  var homeUser = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
  if (!homeUser || !homeUser.uid) {
    wrap.appendChild(buildSignedOutPrompt(
      'Welcome to Praxis',
      'A place to build theory from your reading — set books side by side into arcs, and keep your marginalia, journal, and questions, with Yumi reading along only ever as much as you allow. Sign in to begin.'));
    host.appendChild(wrap);
    return;
  }

  // DW-2 (>=1200): mark the SIGNED-IN home as composed so the two-region grid scopes
  // to it. The signed-out prompt above (a single .empty-state child) never gets the
  // class, so it keeps the base single centered column instead of landing in grid
  // column 1 beside a dead 320px rail. (fix-red-team DW-2 finding 1.)
  wrap.className = 'home-page lum-amber-deep home-composed';

  var ownArcs = homeOwnArcs();
  var haveArcs = ownArcs.length > 0;

  // welcome + alternator
  var welcome = document.createElement('div');
  welcome.className = 'home-welcome';
  // R-POLISH B1-FIX · THE HOUR: the dated kicker. It renders the REAL current
  // date -- the reference mockup's "Saturday · July 19" is sample text, never a
  // string to copy (the canon's "pull all content from live state" rule). ES3:
  // no toLocaleDateString options object, which is unreliable across the
  // browsers this app supports; the two name tables are explicit and cheap.
  var kicker = document.createElement('div');
  kicker.className = 'home-kicker';
  var kNow = new Date();
  var kDays = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  var kMonths = ['January', 'February', 'March', 'April', 'May', 'June', 'July',
    'August', 'September', 'October', 'November', 'December'];
  kicker.textContent = kDays[kNow.getDay()] + ' · ' + kMonths[kNow.getMonth()] +
    ' ' + kNow.getDate() + ' · the study is lit';
  welcome.appendChild(kicker);

  var wTitle = document.createElement('h2');
  wTitle.className = 'home-welcome-title';
  // OG1: honest greeting -- a brand-new account (no arcs AND an empty shelf) is
  // not "welcomed back." haveArcs is computed above; hasShelf here.
  // THE HOUR: the greeting splits into a lead + an italic gold accent (the
  // reference's `h1 em`). OG1's honest distinction is PRESERVED -- only the
  // typography changes, not which greeting a given account sees.
  var hasShelf = !!(state.userBooks && state.userBooks[homeUser.uid] &&
    state.userBooks[homeUser.uid].bookIds && state.userBooks[homeUser.uid].bookIds.length > 0);
  var wReturning = (haveArcs || hasShelf);
  wTitle.appendChild(document.createTextNode(wReturning ? 'Welcome back, ' : 'Welcome to '));
  var wAccent = document.createElement('em');
  wAccent.className = 'home-welcome-accent';
  wAccent.textContent = wReturning ? 'reader.' : 'Praxis.';
  wTitle.appendChild(wAccent);
  welcome.appendChild(wTitle);

  // THE HOUR: the gold hairline under the hero (reference `.herorule`).
  var hRule = document.createElement('div');
  hRule.className = 'home-herorule';
  welcome.appendChild(hRule);

  var alt = document.createElement('div');
  alt.className = 'home-alt';
  var seg = document.createElement('div');
  seg.className = 'seg';
  var segField = document.createElement('button');
  segField.type = 'button';
  segField.className = 'seg-opt';
  segField.setAttribute('data-home-variant', 'field');
  segField.textContent = 'The whole field';
  seg.appendChild(segField);
  var segLeft = document.createElement('button');
  segLeft.type = 'button';
  segLeft.className = 'seg-opt';
  segLeft.setAttribute('data-home-variant', 'left');
  segLeft.textContent = 'Where you left off';
  seg.appendChild(segLeft);
  alt.appendChild(seg);
  var altNote = document.createElement('span');
  altNote.className = 'home-altnote';
  altNote.textContent = 'Pick a view — it stays put until you flip it.';
  alt.appendChild(altNote);
  welcome.appendChild(alt);
  wrap.appendChild(welcome);

  // Variant A: the whole field (Option A, lights = arcs)
  var vField = document.createElement('div');
  vField.className = 'home-variant';
  vField.setAttribute('data-home-variant', 'field');
  vField.appendChild(homeYumiLine(haveArcs
    ? 'The whole shape of your thinking right now — no single path. Take it in, or step into any light.'
    : 'You haven’t begun an arc yet — this is what your field becomes as you read.'));
  // D3 (closes H4): the field variant gets a section label naming its purpose
  // (mirrors the left variant's "Where your thinking stands"; the field had none).
  var fieldSect = document.createElement('p');
  fieldSect.className = 'home-sectlabel';
  fieldSect.textContent = 'How your arcs connect';
  vField.appendChild(fieldSect);
  var wholefield = document.createElement('div');
  // THE HOUR: a lit page, but deliberately NOT lift-able -- it is a surface you
  // read, not a row you click.
  wholefield.className = 'home-wholefield lum-glass lit-page';
  var wf = document.createElement('div');
  wf.className = 'home-wf';
  wholefield.appendChild(wf);
  var wfcap = document.createElement('div');
  wfcap.className = 'home-wfcap';
  wfcap.textContent = haveArcs
    ? 'Choose any light to step into that thread'
    : 'An example field — begin an arc to grow your own';
  wholefield.appendChild(wfcap);
  vField.appendChild(wholefield);
  var fieldstat = document.createElement('div');
  fieldstat.className = 'home-fieldstat';
  if (haveArcs) {
    var growing = homeGrowingCount(ownArcs);
    fieldstat.textContent = ownArcs.length + (ownArcs.length === 1 ? ' arc' : ' arcs') +
      ' · ' + growing + ' still growing';
  } else {
    fieldstat.textContent = 'No arcs yet';
  }
  vField.appendChild(fieldstat);
  wrap.appendChild(vField);
  homeRenderField(wf, ownArcs);

  // Variant B: where you left off — own arcs ordered by derived last-worked (desc)
  var vLeft = document.createElement('div');
  vLeft.className = 'home-variant';
  vLeft.setAttribute('data-home-variant', 'left');
  var leftSorted = ownArcs.slice();
  leftSorted.sort(function (a, b) { return homeLastWorked(b.id, b) - homeLastWorked(a.id, a); });
  var leftLead;
  if (leftSorted.length > 0) {
    var lt = (typeof _arcTouchedWord === 'function') ? _arcTouchedWord(leftSorted[0].id, leftSorted[0]) : '';
    var since = lt ? lt.replace('touched ', '') : '';
    leftLead = since
      ? 'You last worked on ' + (leftSorted[0].title || 'a thread') + ', ' + since + ' — pick it back up?'
      : 'You left a thread mid-thought — pick it back up whenever you like.';
  } else {
    leftLead = 'Nothing in progress yet — begin an arc and it will wait for you here.';
  }
  vLeft.appendChild(homeYumiLine(leftLead));
  var sect = document.createElement('p');
  sect.className = 'home-sectlabel';
  sect.textContent = 'Where your thinking stands';
  vLeft.appendChild(sect);
  var li;
  for (li = 0; li < leftSorted.length; li = li + 1) {
    vLeft.appendChild(homeLeftOffCard(leftSorted[li]));
  }
  // DW-2 (>=1200 only; hidden <=1199 via CSS): a "start a new arc" affordance to
  // the existing arc-creation flow (#arcs). Felt-pass-ruled additive tile.
  var startTile = document.createElement('a');
  startTile.className = 'home-arc-start';
  startTile.href = '#arcs';
  var stPlus = document.createElement('span');
  stPlus.className = 'home-arc-start-plus';
  stPlus.textContent = '+';
  startTile.appendChild(stPlus);
  var stLabel = document.createElement('span');
  stLabel.textContent = 'Start a new arc — set two books side by side';
  startTile.appendChild(stLabel);
  vLeft.appendChild(startTile);
  wrap.appendChild(vLeft);

  // Glimpse: still reading (walk-with omitted). SPINE_CAP bounds the sample; count is true.
  var readingBooks = homeReadingBooks();
  var glimpses = document.createElement('div');
  glimpses.className = 'home-glimpses';
  var glimpse = document.createElement('div');
  // THE HOUR: the "Still reading" aside is a lit page (the reference's .acard).
  glimpse.className = 'home-glimpse lum-glass lit-page';
  // THE HOUR: the aside carries the teal cloth, per the reference's `.acard`.
  var glSpine = document.createElement('span');
  glSpine.className = 'lit-spine lit-spine-teal';
  glimpse.appendChild(glSpine);
  var gl = document.createElement('div');
  gl.className = 'home-gl';
  var glLabel = document.createElement('span');
  glLabel.textContent = 'Still reading';
  gl.appendChild(glLabel);
  var glLink = document.createElement('a');
  glLink.className = 'home-gl-link';
  glLink.href = '#books';
  glLink.textContent = 'Your shelf →';
  gl.appendChild(glLink);
  glimpse.appendChild(gl);
  var spines = document.createElement('div');
  spines.className = 'home-spines';
  var SPINE_CAP = 8;
  var si;
  for (si = 0; si < readingBooks.length && si < SPINE_CAP; si = si + 1) {
    spines.appendChild(homeReadingSpine(readingBooks[si]));
  }
  glimpse.appendChild(spines);
  var rstat = document.createElement('div');
  rstat.className = 'home-reading-status';
  rstat.textContent = readingBooks.length
    ? (readingBooks.length + (readingBooks.length === 1 ? ' book' : ' books') + ' open right now')
    : 'Nothing open right now';
  glimpse.appendChild(rstat);
  glimpses.appendChild(glimpse);
  wrap.appendChild(glimpses);

  host.appendChild(wrap);

  // D3: the alternator no longer auto-flips per visit. The default view is
  // mechanical -- "Where you left off" when there IS progress (own arcs), else
  // the whole field -- read off haveArcs so it can never drift from what
  // rendered. A tab tap switches the view for the session; nothing persists
  // (the old per-visit-flip key praxis_home_variant is retired).
  var homeVariant = haveArcs ? 'left' : 'field';
  segField.addEventListener('click', function () { homeShowVariant(wrap, 'field'); });
  segLeft.addEventListener('click', function () { homeShowVariant(wrap, 'left'); });
  homeShowVariant(wrap, homeVariant);
}

// N1: the active spread tab persists across re-renders (tab clicks call
// renderNotebook). Keys: 'inbox', 'journal', or a bookId. Resolved against the
// live tab model each render, falling back to the first tab if it went stale.
var notebookActiveTab = 'inbox';
// N3 gather -> sub-theory: the gathered entry set + the chosen arc + the typed
// name, persisted across re-renders (gather toggles re-render the spread).
var notebookGathered = {};
var notebookGatherArc = null;
var notebookGatherName = '';
// R6 S5 (decision #2): the just-minted sub-theory, held so the working leaf can show
// a newborn card + an "Open the workshop →" door and the author STAYS in
// the notebook (no auto-navigation). Render-layer only; nulled on a fresh gather.
var notebookNewborn = null;
// ROOM-1 D3 rider: create->Room landing flag; consumed once for the return chip.
var stbFromCreateId = null;

// ── R-ARC S2: local-first session persistence (REQ#3, the hard gate) ─────────
// Gathered cards and drafts survive beat-switch, navigate-away, and RELOAD. The
// four vars above are render-layer only, so before this a refresh silently threw
// away the gather set, the typed name, and the only door to a just-minted draft.
//
// Device-local and pre-commit by design: these are working states, not records.
// Nothing here touches Firestore -- captureNote/createSubTheory remain the only
// writers of real data, so a stale session can never forge one.
// The uid the in-memory gather set was hydrated for -- the owner both stores gate on.
var notebookSessionUid = null;

// THE TAB IS IN THE KEY, and that is load-bearing. One key per uid would make the
// tab-scope a read-only filter: every composer writes the same key, and an empty
// body writes sv(key,null), so merely visiting a second tab and backgrounding the
// page would ERASE the draft waiting in the first. Uid is a parameter, never
// re-read here -- see nbDraftFlush.
function nbDraftKey(uid, activeKey) {
  if (!uid || typeof activeKey !== 'string') { return null; }
  return 'praxis_nb_draft_' + uid + '_' + activeKey;
}

function nbDraftSave(uid, body, register, activeKey) {
  var k = nbDraftKey(uid, activeKey);
  if (!k) { return; }
  var t = (typeof body === 'string') ? body.replace(/^\s+|\s+$/g, '') : '';
  if (t === '') { sv(k, null); return; }
  sv(k, { body: body, register: register });
}

function nbDraftLoad(uid, activeKey) {
  var k = nbDraftKey(uid, activeKey);
  if (!k) { return null; }
  var d = ls(k, null);
  if (!d || typeof d.body !== 'string' || d.body === '') { return null; }
  return d;
}

function nbDraftClear(uid, activeKey) {
  var k = nbDraftKey(uid, activeKey);
  if (k) { sv(k, null); }
}

// The live composer's flush, held module-side so the page-level hooks below are
// installed ONCE. buildNotebookWriteline runs on every render, so per-composer
// document listeners would accumulate one pair per render -- a leak, and every
// stale pair would flush a detached textarea.
var nbDraftFlushFn = null;
var nbDraftHooksInstalled = false;

function nbInstallDraftHooks() {
  if (nbDraftHooksInstalled) { return; }
  nbDraftHooksInstalled = true;
  // Mobile backgrounding is the real loss case, not tab-close: iOS may never fire
  // beforeunload (which is why the repo has none), but it does fire these.
  document.addEventListener('visibilitychange', function() {
    if (document.visibilityState === 'hidden' && nbDraftFlushFn) { nbDraftFlushFn(); }
  });
  window.addEventListener('pagehide', function() {
    if (nbDraftFlushFn) { nbDraftFlushFn(); }
  });
}

// Same law as the draft store: the gather set belongs to the uid nbGatherRestore
// hydrated it for, and only that account may write it. Auth changes with NO reload
// and does not always repaint, so these call sites fire from a stale DOM under a
// new praxis_user -- and the name canvas reaches this on a 700ms debounce, with no
// click at all. Writing under whoever is signed in NOW would put A's gathered ids,
// typed name and newborn into B's key, and B's notebook would hydrate with A's work.
function nbGatherSave() {
  var u = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
  if (!u || !u.uid || u.uid !== notebookSessionUid) { return; }
  sv('praxis_nb_gather_' + notebookSessionUid, {
    gathered: notebookGathered,
    arcId:    notebookGatherArc,
    name:     notebookGatherName,
    newborn:  notebookNewborn
  });
}

// Restores ONCE per uid: re-running on every render would fight live edits, and
// latching on the uid (not a bare flag) means an account switch re-restores rather
// than carrying the previous account's set forward in memory. It is nbGatherSave's
// owner gate, NOT this latch, that keeps A's work out of B's key.
// Stale refs need no pruning here -- notebookGatheredIds() already drops ids whose
// entry is gone, and canCreate() already re-checks state.arcs[aid].
function nbGatherRestore(uid) {
  if (notebookSessionUid === uid) { return; }
  notebookSessionUid = uid;
  notebookGathered = {};
  notebookGatherArc = null;
  notebookGatherName = '';
  notebookNewborn = null;
  if (!uid) { return; }
  var k = 'praxis_nb_gather_' + uid;
  var s = ls(k, null);
  if (!s) { return; }
  if (s.gathered && typeof s.gathered === 'object') { notebookGathered = s.gathered; }
  if (typeof s.arcId === 'string') { notebookGatherArc = s.arcId; }
  if (typeof s.name === 'string') { notebookGatherName = s.name; }
  if (s.newborn && typeof s.newborn === 'object' && typeof s.newborn.id === 'string') {
    notebookNewborn = s.newborn;
    // COPY IS A CONTRACT: the card's eyebrow carries a "· just now" flourish. Across
    // a reload that is false, so a restored newborn is marked and the eyebrow tells
    // the truth instead. The door it carries is the point; the flourish is not.
    notebookNewborn.restored = true;
  }
}

// Wave 3 (the Notebook): the BOOK BAND that crowns a book's notebook -- real
// cover (coverUrl, cloth fallback) + title/author + reading status + real note
// count + computed "became sub-theories" + the inline "What Yumi sees" covenant
// panel (the exact window: marginalia + questions, never journal, never the
// book's own text). Returns null for Inbox/Journal (no book crowns those).
// Consent stays the reused header buildNotebookMasterSwitch (not duplicated).
function buildNotebookBookBand(activeKey, book, tabs, masterSwitchNode) {
  if (!book) { return null; }
  var bandWrap = document.createElement('div');
  bandWrap.className = 'nb-bookband-wrap';
  var band = document.createElement('div');
  band.className = 'nb-bookband';

  var cover = document.createElement('div');
  cover.className = 'nb-bb-cover';
  // mockup .spine (gilt edge) + .rmark (reading-status dot) crown the cover.
  var spine = document.createElement('span');
  spine.className = 'nb-bb-spine';
  spine.setAttribute('aria-hidden', 'true');
  var rmark = document.createElement('span');
  rmark.className = 'nb-bb-rmark';
  rmark.setAttribute('aria-hidden', 'true');
  // R4: ONE cover path -- the shared self-healing helper (candidate-walk +
  // broken-registry, same as Shelf/Home/Book) with a cloth title/author fallback.
  // Replaces the raw <img> so the band and the per-note chip share one cover path
  // (PRECEDENT: never a second cover path).
  cover.appendChild(buildSelfHealingCover(book, 'nb-bb-cover-img', function() {
    cover.className = 'nb-bb-cover nb-bb-cover-cloth';
    var frag = document.createDocumentFragment();
    var cct = document.createElement('div');
    cct.className = 'nb-bb-cover-title';
    cct.textContent = book.title || '';
    frag.appendChild(cct);
    var cca = document.createElement('div');
    cca.className = 'nb-bb-cover-author';
    cca.textContent = book.author || '';
    frag.appendChild(cca);
    return frag;
  }));
  cover.appendChild(spine);
  cover.appendChild(rmark);
  band.appendChild(cover);

  var meta = document.createElement('div');
  meta.className = 'nb-bb-meta';
  var bt = document.createElement('div');
  bt.className = 'nb-bb-title';
  bt.textContent = book.title || '(untitled)';
  meta.appendChild(bt);
  var ba = document.createElement('div');
  ba.className = 'nb-bb-author';
  ba.textContent = book.author || '';
  meta.appendChild(ba);

  var noteCount = 0, ti2;
  for (ti2 = 0; ti2 < tabs.length; ti2 = ti2 + 1) {
    if (tabs[ti2].key === activeKey) { noteCount = tabs[ti2].count; break; }
  }
  // computed (display-only) "became sub-theories": sub-theories whose evidence
  // resolves to this book (kind book = this id, or kind entry from this book).
  var becameCount = 0, sk;
  for (sk in state.subTheories) {
    if (!Object.prototype.hasOwnProperty.call(state.subTheories, sk)) { continue; }
    var st2 = state.subTheories[sk];
    if (!st2 || !Array.isArray(st2.evidence)) { continue; }
    var hit = false, ei2;
    for (ei2 = 0; ei2 < st2.evidence.length; ei2 = ei2 + 1) {
      var ev2 = st2.evidence[ei2];
      if (!ev2) { continue; }
      if (ev2.kind === 'book' && ev2.refId === activeKey) { hit = true; break; }
      if (ev2.kind === 'entry') {
        var en2 = state.notebookEntries && state.notebookEntries[ev2.refId];
        if (en2 && Array.isArray(en2.bookIds) && en2.bookIds.indexOf(activeKey) !== -1) { hit = true; break; }
      }
    }
    if (hit) { becameCount = becameCount + 1; }
  }
  var bstat = document.createElement('div');
  bstat.className = 'nb-bb-stat';
  var statusStr = (typeof statusText === 'function') ? statusText(book.status) : (book.status || '');
  var statLine = '';
  if (statusStr) { statLine = statusStr + ' · '; }
  statLine = statLine + noteCount + (noteCount === 1 ? ' note' : ' notes');
  if (becameCount) { statLine = statLine + ' · ' + becameCount + (becameCount === 1 ? ' became a sub-theory' : ' became sub-theories'); }
  bstat.textContent = statLine;
  meta.appendChild(bstat);
  var banklabel = document.createElement('div');
  banklabel.className = 'nb-bb-banklabel';
  banklabel.textContent = 'Your notebook for this book';
  meta.appendChild(banklabel);
  band.appendChild(meta);

  // Band consent column (mockup .bandconsent): the "Yumi reads along" master
  // switch (passed in -- same setProfile/saveProfileToFirestore covenant wiring)
  // above the inline "What Yumi sees" covenant link.
  var consent = document.createElement('div');
  consent.className = 'nb-bb-consent';
  if (masterSwitchNode) { consent.appendChild(masterSwitchNode); }
  var seesLink = document.createElement('button');
  seesLink.type = 'button';
  seesLink.className = 'nb-bb-whatsees';
  seesLink.textContent = 'What Yumi sees';
  consent.appendChild(seesLink);
  band.appendChild(consent);
  bandWrap.appendChild(band);

  var seesPanel = document.createElement('div');
  seesPanel.className = 'nb-bb-seespanel';
  seesPanel.appendChild(document.createTextNode('Yumi reads your '));
  var spb1 = document.createElement('b'); spb1.textContent = 'marginalia'; seesPanel.appendChild(spb1);
  seesPanel.appendChild(document.createTextNode(' and your '));
  var spb2 = document.createElement('b'); spb2.textContent = 'questions'; seesPanel.appendChild(spb2);
  seesPanel.appendChild(document.createTextNode(' — the notes you take with this book. She never reads your '));
  var spb3 = document.createElement('b'); spb3.textContent = 'journal'; seesPanel.appendChild(spb3);
  seesPanel.appendChild(document.createTextNode(', and never the book’s own text. A mirror held at an angle to your own thinking, nothing more.'));
  seesLink.addEventListener('click', function() {
    seesPanel.className = (seesPanel.className.indexOf(' on') !== -1) ? 'nb-bb-seespanel' : 'nb-bb-seespanel on';
  });
  bandWrap.appendChild(seesPanel);
  return bandWrap;
}

function renderNotebook() {
  var host = document.getElementById(APP_EL_ID);
  if (!host) return;
  host.innerHTML = '';

  var wrap = document.createElement('section');
  wrap.className = 'notebook lum-amber-deep';

  var user = getCurrentUser();

  // Signed out: the mock's #notebook-signedout empty-state (glyph + covenant +
  // Sign in). The head + spread are user-scoped, so render ONLY the empty-state
  // (matches the mock's signed-out behavior: head + spread hidden).
  if (!user) {
    wrap.appendChild(buildNotebookSignedOut());
    host.appendChild(wrap);
    return;
  }

  // R-ARC S2: rehydrate the gather set before anything reads it. Once per uid.
  nbGatherRestore(user.uid);

  // Intro (mock .intro): eyebrow + title + the descriptive paragraph. The master
  // "Yumi reads along" consent moves into the book band (or a slim consent row on
  // Inbox/Journal); capture/import lives in the composer's unified .nb-modes row --
  // so the intro reads clean per the mockup (no header chrome).
  var header = document.createElement('header');
  header.className = 'notebook-head';

  var titleBlock = document.createElement('div');
  titleBlock.className = 'notebook-title-block';
  var eyebrow = document.createElement('p');
  eyebrow.className = 'eyebrow';
  eyebrow.textContent = 'Structurally private';
  titleBlock.appendChild(eyebrow);
  var title = document.createElement('h1');
  title.className = 'notebook-title';
  title.textContent = 'Notebook';
  titleBlock.appendChild(title);
  var introP = document.createElement('p');
  introP.className = 'notebook-intro';
  introP.textContent = 'Each book keeps its own notebook, and the book itself crowns it — cover, your reading, what it’s grown into. Below, two leaves: catch notes on the left, gather a few on the right and a sub-theory forms. Yumi reads along quietly, only ever from what you wrote, asking rather than explaining.';
  titleBlock.appendChild(introP);
  header.appendChild(titleBlock);

  wrap.appendChild(header);

  // Transparency host -- the in-panel "What Yumi sees" (openTransparencyView)
  // mounts here when invoked. The primary transparency surface is the routed
  // #yumi-sees page (reached from Yumi's panel) + the band covenant link.
  var transparencyHost = document.createElement('div');
  transparencyHost.id = 'notebook-transparency-host';
  wrap.appendChild(transparencyHost);

  // Editor host -- inline editor mount point. Preserved.
  var editorHost = document.createElement('div');
  editorHost.id = 'notebook-editor-host';
  wrap.appendChild(editorHost);

  // One pass over the signed-in user's entries -> tab membership + counts.
  var entries = [];
  var emap = state.notebookEntries || {};
  var ekey;
  for (ekey in emap) {
    if (Object.prototype.hasOwnProperty.call(emap, ekey)) {
      var ent = emap[ekey];
      if (ent && ent.userId === user.uid) { entries.push(ent); }
    }
  }
  entries.sort(function(a, b) { return (b.createdAt || 0) - (a.createdAt || 0); });

  var tabs = buildNotebookTabModel(user, entries);
  var activeKey = notebookActiveTab;
  var foundActive = false;
  var ti;
  for (ti = 0; ti < tabs.length; ti = ti + 1) {
    if (tabs[ti].key === activeKey) { foundActive = true; break; }
  }
  if (!foundActive) {
    activeKey = tabs.length ? tabs[0].key : 'inbox';
    notebookActiveTab = activeKey;
  }

  // Tab row sits ABOVE the spread (mockup .tabs), not inside the left leaf.
  wrap.appendChild(buildNotebookTabRow(tabs, activeKey));

  // The master "Yumi reads along" consent rides in the book band (mockup); on
  // Inbox/Journal (no band) it falls back to a slim consent row above the spread,
  // so the toggle is never lost. ONE instance -- setProfile/covenant wiring intact.
  var masterSwitch = buildNotebookMasterSwitch(user);

  // The bound-leaf spread. Left leaf = "Catch a note" (composer w/ unified .nb-modes
  // row + note bank); right leaf = the working page (gathered + forming), per the mockup.
  var spread = document.createElement('div');
  spread.className = 'notebook-spread';
  // Wave 3: the real book band crowns the spread when a book tab is active.
  var bandBook = (activeKey !== 'inbox' && activeKey !== 'journal' && state.books)
    ? state.books[activeKey] : null;
  var bookBand = buildNotebookBookBand(activeKey, bandBook, tabs, bandBook ? masterSwitch : null);
  if (bookBand) {
    spread.appendChild(bookBand);
  } else {
    var consentRow = document.createElement('div');
    consentRow.className = 'nb-consent-row';
    consentRow.appendChild(masterSwitch);
    wrap.appendChild(consentRow);
  }
  var leaves = document.createElement('div');
  leaves.className = 'notebook-leaves';
  leaves.appendChild(buildNotebookLeftLeaf(activeKey, tabs, entries));
  leaves.appendChild(buildNotebookRightLeaf(user, activeKey));
  spread.appendChild(leaves);
  wrap.appendChild(spread);

  host.appendChild(wrap);
}

// Signed-out: the mock's #notebook-signedout empty-state. The em-mark is filled
// with the real shared Yumi crest (yumiGlyphNode); the button runs the live auth.
function buildNotebookSignedOut() {
  var es = document.createElement('div');
  es.className = 'empty-state';
  es.id = 'notebook-signedout';
  var mark = document.createElement('div');
  mark.className = 'em-mark';
  mark.id = 'nb-signedout-mark';
  if (typeof yumiGlyphNode === 'function') { mark.appendChild(yumiGlyphNode(56)); }
  es.appendChild(mark);
  var h2 = document.createElement('h2');
  h2.textContent = 'Your notebook is private';
  es.appendChild(h2);
  var p = document.createElement('p');
  p.textContent = 'Sign in to keep your marginalia, journal, and questions — and to let Yumi read along, only ever as much as you allow. No asymmetry, ever.';
  es.appendChild(p);
  var btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'btn btn-primary';
  btn.textContent = 'Sign in';
  btn.addEventListener('click', function() { signInWithGoogle(); });
  es.appendChild(btn);
  return es;
}

// W11 S8 Lane 1: the shared signed-out gate prompt. A parameterized twin of
// buildNotebookSignedOut (same .empty-state structure, real shared Yumi crest,
// live auth) so every hard-gated surface shows ONE in-place prompt in its own
// ground -- no new auth pattern, no new CSS, no location redirect.
function buildSignedOutPrompt(headline, copy) {
  var es = document.createElement('div');
  es.className = 'empty-state';
  var mark = document.createElement('div');
  mark.className = 'em-mark';
  if (typeof yumiGlyphNode === 'function') { mark.appendChild(yumiGlyphNode(56)); }
  es.appendChild(mark);
  var h2 = document.createElement('h2');
  h2.textContent = headline;
  es.appendChild(h2);
  var p = document.createElement('p');
  p.textContent = copy;
  es.appendChild(p);
  var btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'btn btn-primary';
  btn.textContent = 'Sign in';
  btn.addEventListener('click', function() { signInWithGoogle(); });
  es.appendChild(btn);
  return es;
}

// ===== N1 spread helpers. Display / aggregation only -- no writes. =====

// Membership predicate shared by the counts AND the left-leaf render, so a
// tab's count and its rendered entries can never disagree. Routing (locked F3):
//   journal : register === 'journal'
//   inbox   : register !== 'journal' && filed === false
//   <bookId>: register !== 'journal' && filed === true && bookId in bookIds
function notebookEntryMatchesTab(entry, tabKey) {
  if (tabKey === 'journal') { return entry.register === 'journal'; }
  if (tabKey === 'inbox') {
    return entry.register !== 'journal' && entry.filed === false;
  }
  if (entry.register === 'journal' || entry.filed !== true || !entry.bookIds) {
    return false;
  }
  var i;
  for (i = 0; i < entry.bookIds.length; i = i + 1) {
    if (entry.bookIds[i] === tabKey) { return true; }
  }
  return false;
}

// Build the ordered tab model [{key,label,count}]: Inbox, Journal, then one tab
// per book that has >=1 placed note (shelf order first, orphan books appended
// so no placed note is ever tab-less).
function buildNotebookTabModel(user, entries) {
  var model = [];
  var inboxCount = 0;
  var journalCount = 0;
  var bookCounts = {};
  var i;
  for (i = 0; i < entries.length; i = i + 1) {
    var e = entries[i];
    if (e.register === 'journal') {
      journalCount = journalCount + 1;
    } else if (e.filed === false) {
      inboxCount = inboxCount + 1;
    } else if (e.filed === true && e.bookIds) {
      var bi;
      for (bi = 0; bi < e.bookIds.length; bi = bi + 1) {
        var bid = e.bookIds[bi];
        bookCounts[bid] = (bookCounts[bid] || 0) + 1;
      }
    }
  }
  model.push({ key: 'inbox', label: 'Inbox', count: inboxCount });
  model.push({ key: 'journal', label: 'Journal', count: journalCount });

  var shelf = (state.userBooks && state.userBooks[user.uid] &&
               state.userBooks[user.uid].bookIds)
    ? state.userBooks[user.uid].bookIds : [];
  var ordered = [];
  var seen = {};
  var s;
  for (s = 0; s < shelf.length; s = s + 1) {
    if (bookCounts[shelf[s]] && !seen[shelf[s]]) {
      ordered.push(shelf[s]); seen[shelf[s]] = true;
    }
  }
  var bk;
  for (bk in bookCounts) {
    if (Object.prototype.hasOwnProperty.call(bookCounts, bk) && !seen[bk]) {
      ordered.push(bk); seen[bk] = true;
    }
  }
  var j;
  for (j = 0; j < ordered.length; j = j + 1) {
    var bookId = ordered[j];
    var title = (state.books && state.books[bookId] && state.books[bookId].title)
      ? state.books[bookId].title : '(unknown book)';
    model.push({ key: bookId, label: title, count: bookCounts[bookId] });
  }
  return model;
}

// The tab row. Each tab re-renders the notebook on click (sets the module-level
// notebookActiveTab). Closure-per-tab via appendNotebookTab (a var-in-for-loop
// would bind every handler to the last tab).
function buildNotebookTabRow(tabs, activeKey) {
  var row = document.createElement('div');
  row.className = 'nb-tabs';
  var i;
  for (i = 0; i < tabs.length; i = i + 1) {
    appendNotebookTab(row, tabs[i], activeKey);
  }
  return row;
}

function appendNotebookTab(row, tab, activeKey) {
  var el = document.createElement('button');
  el.type = 'button';
  el.className = 'nb-tab' + (tab.key === activeKey ? ' is-on' : '');
  el.appendChild(document.createTextNode(tab.label + ' '));
  var ct = document.createElement('span');
  ct.className = 'c';
  ct.textContent = String(tab.count);
  el.appendChild(ct);
  el.addEventListener('click', function() {
    notebookActiveTab = tab.key;
    renderNotebook();
  });
  row.appendChild(el);
}

// Left leaf (mockup "Catch a note"): the capture composer (which now carries the
// unified .nb-modes import row), then the tab's entries (createdAt-desc) via
// renderNotebookEntry. Book identity now lives in the band above; the tab row sits
// above the spread (both moved out of here).
function buildNotebookLeftLeaf(activeKey, tabs, entries) {
  var leaf = document.createElement('div');
  leaf.className = 'leaf leaf-left';

  var leafsub = document.createElement('p');
  leafsub.className = 'nb-leaftag';
  leafsub.textContent = 'Catch a note';
  leaf.appendChild(leafsub);

  // The capture composer (relocated from the right leaf -- behavior identical;
  // it still routes by the active tab). autogrow / photo / register / Enter-commit
  // all preserved.
  leaf.appendChild(buildNotebookWriteline(activeKey));

  // R4 (#1 unified composer): the paste/import/dictate affordances that used to
  // live here as run-in prose (.nb-capmodes) now render as labeled chips INSIDE the
  // composer's .nb-modes row (buildNotebookWriteline), beside photo/add-image. The
  // "talk it through with Yumi" mode is dropped for R4. ImportCapture is untouched.

  // R4 (#3b): the per-note book chip shows only where the book varies note-to-note
  // (Inbox + Journal). On a <book> tab the band states the book, so it is suppressed.
  var showChip = (activeKey === 'inbox' || activeKey === 'journal');
  var shown = 0;
  var i;
  for (i = 0; i < entries.length; i = i + 1) {
    if (notebookEntryMatchesTab(entries[i], activeKey)) {
      leaf.appendChild(renderNotebookEntry(entries[i], true, showChip));
      shown = shown + 1;
    }
  }
  if (shown === 0) {
    if (activeKey === 'inbox') {
      leaf.appendChild(buildNotebookInboxEmpty());
    } else {
      var empty = document.createElement('p');
      empty.className = 'notebook-empty-body';
      empty.textContent = (activeKey === 'journal')
        ? 'No journal entries yet.'
        : 'No notes on this book yet.';
      leaf.appendChild(empty);
    }
  }
  return leaf;
}

// Right leaf (mockup "The working page"): the Gathered list (each card with a ×
// remove) + an empty placeholder; once notes are gathered it grows the forming
// sub-theory (name + arc + Create). Create REUSES createSubTheory +
// addEvidenceToSubTheory (no new data path). The capture composer now lives on
// the LEFT leaf, per the mockup.
function buildNotebookRightLeaf(user, activeKey) {
  var leaf = document.createElement('div');
  leaf.className = 'leaf leaf-right';

  var ids = notebookGatheredIds();
  // R6 S5: a fresh gather supersedes the last birth card.
  // S2: persist only on a real change -- this runs on every render.
  if (ids.length > 0 && notebookNewborn) { notebookNewborn = null; nbGatherSave(); }

  var tag = document.createElement('h3');
  tag.className = 'nb-leaftag';
  tag.textContent = 'The working page · where a sub-theory forms';
  leaf.appendChild(tag);

  // R6 S5 (decision #2): after a mint the author STAYS here — a quiet newborn card
  // with an "Open the workshop →" door REPLACES the gather form; no auto-nav.
  if (notebookNewborn) {
    leaf.appendChild(buildNotebookNewbornCard(notebookNewborn));
    return leaf;
  }

  // Gathered (mockup .glab + .gathered-list): the gathered notes, each with a ×
  // remove (toggleGather), or the empty placeholder when nothing is gathered.
  var glab = document.createElement('p');
  glab.className = 'nb-glab';
  glab.textContent = 'Gathered';
  leaf.appendChild(glab);

  var glist = document.createElement('div');
  glist.className = 'nb-gathered-list';
  if (!ids.length) {
    var gempty = document.createElement('div');
    gempty.className = 'nb-gempty';
    gempty.textContent = 'Select notes on the left to gather them here…';
    glist.appendChild(gempty);
  } else {
    var gi;
    for (gi = 0; gi < ids.length; gi = gi + 1) {
      (function(eid) {
        var e = state.notebookEntries[eid];
        var g = document.createElement('div');
        g.className = 'nb-gnote';
        var gtext = document.createElement('span');
        var gb = (e && typeof e.body === 'string') ? e.body : '';
        if (gb.length > 140) { gb = gb.substring(0, 137) + '…'; }
        gtext.textContent = gb;
        g.appendChild(gtext);
        var gx = document.createElement('button');
        gx.type = 'button';
        gx.className = 'nb-gx';
        gx.setAttribute('aria-label', 'Remove from gathered');
        gx.textContent = '×';
        gx.addEventListener('click', function() { toggleGather(eid); });
        g.appendChild(gx);
        glist.appendChild(g);
      })(ids[gi]);
    }
  }
  leaf.appendChild(glist);

  if (!ids.length) {
    return leaf;
  }

  // Name block: a reserved (resting) Yumi-attribution eyebrow + the naming field
  // (the same <input> the gather path reads from via notebookGatherName).
  var nameBlock = document.createElement('div');
  nameBlock.className = 'nb-nameblock';
  var ynameTag = document.createElement('div');
  ynameTag.className = 'nb-yname-tag';
  ynameTag.textContent = 'Name this sub-theory · yours to set';
  nameBlock.appendChild(ynameTag);
  // Wave 3: the forming sub-theory's NAME field adopts the SAME shared
  // createWritingCanvas as the Page and Build (the writing trio shares one
  // substrate). onSave mirrors the trimmed name into notebookGatherName -- the
  // string the existing gather->create pipeline reads. writing-canvas.js UNCHANGED.
  var nameHost = document.createElement('div');
  nameHost.className = 'nb-working-name nb-name-canvas-host';
  nameBlock.appendChild(nameHost);
  // R6 S5 (decision #1): the leaf NAMES; the prose lives in the workshop.
  var nameHint = document.createElement('p');
  nameHint.className = 'nb-name-hint';
  nameHint.textContent = 'Name it — the writing happens in the workshop.';
  nameBlock.appendChild(nameHint);
  leaf.appendChild(nameBlock);
  var nameCanvas = createWritingCanvas(nameHost, {
    surfaceId:    'notebook-forming-name',
    placeholder:  'Name it…',
    initialValue: notebookGatherName || '',
    flags:        { focusMode: false },
    onSave: function(markdown, report) {
      notebookGatherName = (typeof markdown === 'string') ? markdown.replace(/^\s+|\s+$/g, '') : '';
      nbGatherSave();
      if (createBtn) { createBtn.disabled = !canCreate(); }
      if (report && report.setLocal) { report.setLocal(true); }
    }
  });

  // Gather bar (mock .nb-gather): "N gathered ·" + arc selection (reuses
  // buildArcPickerPanel via openGatherArcPicker) + Create. Default arc = the arc
  // shared by all gathered notes' arcIds, else the user picks one; no arcs -> guide.
  var arcId = notebookGatherArc || notebookSharedArc(ids);
  var hasArcs = notebookUserHasArcs(user);

  var gather = document.createElement('div');
  gather.className = 'nb-gather';

  var lab = document.createElement('span');
  lab.className = 'lab';
  lab.textContent = ids.length + ' gathered ·';
  gather.appendChild(lab);

  if (!hasArcs) {
    var noArc = document.createElement('span');
    noArc.className = 'lab';
    noArc.textContent = 'Create an arc first — sub-theories live inside an arc.';
    gather.appendChild(noArc);
  } else {
    var arcLabel = document.createElement('span');
    arcLabel.className = 'lab';
    if (arcId && state.arcs[arcId]) {
      arcLabel.textContent = 'Into arc: ' + (state.arcs[arcId].title || '(untitled arc)');
    } else {
      arcLabel.textContent = 'No arc chosen';
    }
    gather.appendChild(arcLabel);
    var changeLink = document.createElement('button');
    changeLink.type = 'button';
    changeLink.className = 'chip';
    changeLink.textContent = (arcId && state.arcs[arcId]) ? 'Change' : 'Choose an arc';
    changeLink.addEventListener('click', function() {
      var host = gather.querySelector('.notebook-working-arc-picker-host');
      if (!host) {
        host = document.createElement('div');
        host.className = 'notebook-working-arc-picker-host';
        gather.appendChild(host);
      }
      openGatherArcPicker(host);
    });
    gather.appendChild(changeLink);
  }

  var spacerG = document.createElement('span');
  spacerG.className = 'spacer';
  gather.appendChild(spacerG);

  var createBtn = document.createElement('button');
  createBtn.type = 'button';
  createBtn.className = 'btn btn-primary';
  createBtn.textContent = 'Create sub-theory →';
  function canCreate() {
    // FIX B: the name is OPTIONAL (createSubTheory accepts an empty header -- a
    // draft you name in the editor, like the "+ Sub-theory" flow). The arc must
    // EXIST: a gathered set may share an arcId whose arc was deleted, which
    // would enable Create but no-op in notebookCreateSubTheory's guard.
    var aid = notebookGatherArc || notebookSharedArc(ids);
    return !!(ids.length && aid && state.arcs && state.arcs[aid] && hasArcs);
  }
  createBtn.disabled = !canCreate();
  createBtn.addEventListener('click', function() { notebookCreateSubTheory(); });
  // Wave 3: the name now flows from the createWritingCanvas onSave above
  // (notebookGatherName), so the old nameInput 'input' listener is retired.
  gather.appendChild(createBtn);
  leaf.appendChild(gather);

  // Reserved (resting) Yumi COMPLICATE slot. The position is held for the later
  // generative build; here she is quiet -- a static, honest placeholder, never a
  // generated question and never a brain call.
  var complicate = document.createElement('div');
  complicate.className = 'nb-complicate';
  var cbubble = document.createElement('span');
  cbubble.className = 'nb-ybubble nb-ybubble-sm';
  cbubble.textContent = 'Y';
  complicate.appendChild(cbubble);
  var cbody = document.createElement('div');
  var ctag = document.createElement('div');
  ctag.className = 'nb-ctag';
  ctag.textContent = 'Yumi · complicates — a question, never a verdict';
  cbody.appendChild(ctag);
  var ctext = document.createElement('div');
  ctext.className = 'nb-ctext';
  ctext.textContent = 'Once Yumi’s reading along, she’ll open a question here — never a verdict.';
  cbody.appendChild(ctext);
  complicate.appendChild(cbody);
  leaf.appendChild(complicate);

  var acts = document.createElement('div');
  acts.className = 'nb-working-acts';
  var clearLink = document.createElement('a');
  clearLink.href = '#';
  clearLink.className = 'nb-working-clear';
  clearLink.textContent = 'Clear';
  clearLink.addEventListener('click', function(ev) {
    ev.preventDefault();
    notebookGathered = {};
    notebookGatherArc = null;
    notebookGatherName = '';
    nbGatherSave();
    renderNotebook();
  });
  acts.appendChild(clearLink);
  leaf.appendChild(acts);

  return leaf;
}

// R6 S5 (decision #2): the newborn card — the newborn sub-theory as a quiet
// card in the working leaf, with an "Open the workshop →" door. The author stays
// in the notebook; the door is the ONLY navigation, on click.
function buildNotebookNewbornCard(nb) {
  var card = document.createElement('div');
  card.className = 'nb-newborn-card is-shown';
  var top = document.createElement('div');
  top.className = 'nb-newborn-top';
  var mark = document.createElement('span');
  mark.className = 'nb-newborn-mark';
  var rec = state.subTheories && state.subTheories[nb.id];
  // R-ARC S3B: a just-minted basin (unnamed) shows the formless mote.
  mark.innerHTML = rec ? _stMarkOrMote(rec, 30) : '';
  top.appendChild(mark);
  // FF-7: naming decides this card's lifecycle word (title + eyebrow + snippet).
  var nbIsBasin = !!(rec && _stIsBasin(rec));
  var titleWrap = document.createElement('div');
  var title = document.createElement('div');
  title.className = 'nb-newborn-title';
  // R-ARC S3B: a basin (unnamed) shows its origin phrase, not "Untitled". Check the
  // real record FIRST -- nb.header is pre-baked with an 'Untitled…' fallback by
  // notebookCreateSubTheory, so it would mask the phrase if tested first.
  if (nbIsBasin) {
    // FF-5: provisional identity -- a basin's origin phrase reads as a QUOTED,
    // secondary phrase (the .nb-newborn-basin modifier), never title treatment,
    // so an unnamed basin never looks named.
    var nbPhrase = _stTruncPhrase(_stOriginPhrase(rec), 60);
    title.className = 'nb-newborn-title nb-newborn-basin';
    title.textContent = nbPhrase ? ('“' + nbPhrase + '”') : 'Unnamed basin';
  } else {
    title.textContent = nb.header || 'Untitled sub-theory';
  }
  titleWrap.appendChild(title);
  var eyebrow = document.createElement('div');
  eyebrow.className = 'nb-newborn-eyebrow';
  // S2: the "just now" flourish is only true in the session that bore it. A card
  // restored across a reload drops the flourish rather than lie.
  // FF-7: basin -> GATHERING, named draft -> DRAFT. "Forming" is retired.
  eyebrow.textContent = nbIsBasin
    ? (nb.restored ? 'gathering' : 'gathering · just now')
    : (nb.restored ? 'draft' : 'draft · just now');
  titleWrap.appendChild(eyebrow);
  top.appendChild(titleWrap);
  card.appendChild(top);
  var snippet = document.createElement('p');
  snippet.className = 'nb-newborn-snippet';
  // FF-7: as the eyebrow. No finished branch -- a newborn is never published.
  snippet.textContent = (nbIsBasin ? 'A gathering sub-theory in ' : 'A draft sub-theory in ')
    + (nb.arcTitle || 'your arc') + ', started from '
    + nb.count + ' marked passage' + (nb.count === 1 ? '' : 's') + '.';
  card.appendChild(snippet);
  var door = document.createElement('button');
  door.type = 'button';
  door.className = 'nb-newborn-door';
  door.textContent = 'Open the workshop →';
  door.addEventListener('click', function() {
    notebookNewborn = null;
    nbGatherSave();
    location.hash = '#subtheory/' + nb.id + '/build';
  });
  card.appendChild(door);
  var stay = document.createElement('p');
  stay.className = 'nb-newborn-stay';
  stay.textContent = 'You’re staying right here — nothing else on this page changes.';
  card.appendChild(stay);
  return card;
}

// ===== N3 gather helpers =====

function notebookRegisterLabel(reg) {
  if (reg === 'marginalia') { return 'Marginalia'; }
  if (reg === 'question') { return 'Question'; }
  return 'Journal';
}

function arrHas(arr, val) {
  var i;
  for (i = 0; i < arr.length; i = i + 1) { if (arr[i] === val) { return true; } }
  return false;
}

// The gathered entry ids that still exist (a deleted entry drops out).
function notebookGatheredIds() {
  var out = [];
  var k;
  for (k in notebookGathered) {
    if (Object.prototype.hasOwnProperty.call(notebookGathered, k) &&
        notebookGathered[k] === true &&
        state.notebookEntries && state.notebookEntries[k]) {
      out.push(k);
    }
  }
  return out;
}

function toggleGather(entryId) {
  // Covenant (Wave 3 · the Notebook): journal notes are LOCKED -- ungatherable.
  // A journal-register entry can never enter the gathered set that forms a
  // sub-theory's evidence (mirrors the spec's `if (isJournal(el)) return;`).
  var ent = state.notebookEntries && state.notebookEntries[entryId];
  if (ent && ent.register === 'journal') { return; }
  if (notebookGathered[entryId] === true) { delete notebookGathered[entryId]; }
  else { notebookGathered[entryId] = true; }
  nbGatherSave();
  renderNotebook();
}

// F6: the arc common to ALL gathered entries' arcIds (intersection), or null.
function notebookSharedArc(ids) {
  if (!ids.length) { return null; }
  var first = state.notebookEntries[ids[0]];
  var candidate = (first && first.arcIds) ? first.arcIds.slice(0) : [];
  var i, j, next;
  for (i = 1; i < ids.length; i = i + 1) {
    var e = state.notebookEntries[ids[i]];
    var eArcs = (e && e.arcIds) ? e.arcIds : [];
    next = [];
    for (j = 0; j < candidate.length; j = j + 1) {
      if (arrHas(eArcs, candidate[j])) { next.push(candidate[j]); }
    }
    candidate = next;
    if (!candidate.length) { return null; }
  }
  // FIX B: return the first shared arc that STILL EXISTS -- a deleted arc must
  // not surface as the default (it would enable Create but no-op).
  var k;
  for (k = 0; k < candidate.length; k = k + 1) {
    if (state.arcs && state.arcs[candidate[k]]) { return candidate[k]; }
  }
  return null;
}

function notebookUserHasArcs(user) {
  if (!user || !state.arcs) { return false; }
  var k;
  for (k in state.arcs) {
    if (Object.prototype.hasOwnProperty.call(state.arcs, k) && state.arcs[k] &&
        (state.arcs[k].userId === user.uid || state.arcs[k].userId === '__praxis_seed__')) {
      return true;
    }
  }
  return false;
}

function openGatherArcPicker(mountEl) {
  if (!mountEl) { return; }
  var user = getCurrentUser();
  if (!user) { return; }
  mountEl.innerHTML = '';
  mountEl.appendChild(buildArcPickerPanel({
    user: user,
    label: 'Choose an arc for this sub-theory',
    onPick: function(arcId) {
      notebookGatherArc = arcId;
      nbGatherSave();
      renderNotebook();
    },
    onDone: function() {}
  }));
}

// N3: gather -> sub-theory. REUSES createSubTheory + addEvidenceToSubTheory
// (the same path "Send to sub-theory" uses, kind 'entry', quote = body). On
// success, clears the gather and routes to the new sub-theory page.
function notebookCreateSubTheory(opts) {
  // R-ARC S4 (One Door): the SOLE createSubTheory call site. Two entry contexts funnel
  // here (S4-4). NOTEBOOK gather (opts absent): create from the gathered notes + the
  // chosen arc, land on the newborn card, stay in the notebook. ARC-DETAIL "+ Sub-theory"
  // (opts.arcId set): a pre-selected arc, no gathered notes -> an empty draft that lands
  // in the workshop (preserves the retired route's end-state). One create path, one
  // arc-resolution (a real arc, never auto-minted), one landing per context.
  opts = opts || {};
  var user = getCurrentUser();
  if (!user) { return; }
  var fromArc = (typeof opts.arcId === 'string' && opts.arcId !== '');
  var ids = fromArc ? [] : notebookGatheredIds();
  var name = fromArc ? '' : (notebookGatherName || '').replace(/^\s+|\s+$/g, '');
  var arcId = fromArc ? opts.arcId : (notebookGatherArc || notebookSharedArc(ids));
  // The arc must EXIST. The notebook entry additionally requires gathered notes; the
  // arc-detail entry mints an empty draft (name optional, given in the editor).
  if (!arcId || !state.arcs[arcId]) { return; }
  if (!fromArc && !ids.length) { return; }
  // R-ARC S3B: the basin's origin phrase = the first gathered note (arc-detail: none -> formless).
  var st = createSubTheory(arcId, fromArc ? {} : { header: name, originEntryId: ids[0] });
  if (!st) { return; }
  var i;
  for (i = 0; i < ids.length; i = i + 1) {
    var e = state.notebookEntries[ids[i]];
    var quote = (e && typeof e.body === 'string') ? e.body : '';
    addEvidenceToSubTheory(st.id, { kind: 'entry', refId: ids[i], quote: quote });
  }
  if (fromArc) {
    // Arc-detail: mint + open the workshop. location.replace keeps the transient create
    // action out of history (Back never re-mints) — exactly as the retired route did.
    saveState();
    location.replace('#subtheory/' + st.id + '/build');
    return;
  }
  var mintedArc = state.arcs[arcId];
  notebookGathered = {};
  notebookGatherArc = null;
  notebookGatherName = '';
  // ROOM-1 D3 (Preston 2026-07-17): CREATE LANDS IN THE ROOM — knowing reversal
  // of the R6-S5/S4 stay-put flow. Newborn persists as the notebook RECEIPT;
  // the workshop shows the one-gesture return chip. Mint path unchanged.
  notebookNewborn = {
    id: st.id,
    header: (name || st.header || 'Untitled sub-theory'),
    arcTitle: (mintedArc && mintedArc.title) ? mintedArc.title : '',
    count: ids.length
  };
  nbGatherSave();
  stbFromCreateId = st.id;
  location.hash = '#subtheory/' + st.id + '/build';
}

// N2: master consent switch -- interactive. Reflects profile.yumiReadsAlong
// (default true), toggles it, persists via setProfile + the /userProfiles
// mirror (saveProfileToFirestore), and re-renders. assembleContextData reads
// the same field as its single consent gate (OFF -> Yumi sees no writing).
function buildNotebookMasterSwitch(user) {
  var reads = true;
  if (typeof getProfile === 'function' && user && user.uid) {
    var prof = getProfile(user.uid);
    if (prof && prof.yumiReadsAlong === false) { reads = false; }
  }
  // Umber frame: mock .nb-switch (label span + button.nb-toggle[aria-pressed]).
  // The privacy/consent handler is preserved verbatim; a native <button> is
  // keyboard-accessible (Enter/Space), so the explicit keydown is no longer needed.
  var wrap = document.createElement('div');
  wrap.className = 'nb-switch';
  var label = document.createElement('span');
  label.textContent = 'Yumi reads along';
  wrap.appendChild(label);
  var tog = document.createElement('button');
  tog.type = 'button';
  tog.className = 'nb-toggle';
  tog.setAttribute('aria-pressed', reads ? 'true' : 'false');
  tog.setAttribute('aria-label', 'Yumi reads along: ' + (reads ? 'on' : 'off'));
  function flip() {
    if (!user || !user.uid) { return; }
    setProfile(user.uid, { yumiReadsAlong: !reads });
    if (typeof saveProfileToFirestore === 'function') {
      saveProfileToFirestore(user.uid, getProfile(user.uid), function() {});
    }
    renderNotebook();
  }
  tog.addEventListener('click', function() { flip(); });
  wrap.appendChild(tog);
  return wrap;
}

// ===== N2b notebook photo storage: device-local IndexedDB blob store =====
// Photos attach inline to a notebook entry; the entry persists only refs
// ({id, idbKey, w, h, caption}). The blobs live HERE (IndexedDB), never in
// localStorage or the /userNotebook Firestore doc -- so cross-device the refs
// sync but the blob is absent (graceful placeholder). ES3 / event-based (no
// promises) so views.js stays parse-clean.
var NB_PHOTO_DB = 'praxisNotebook';
var NB_PHOTO_STORE = 'photos';
var nbPhotoSeq = 0;

function genNotebookImageId() {
  nbPhotoSeq = nbPhotoSeq + 1;
  return 'nbimg_' + Date.now() + '_' + nbPhotoSeq;
}

function nbPhotoIdbOpen(onOk, onErr) {
  if (!window.indexedDB) { onErr(new Error('indexedDB unavailable')); return; }
  var req;
  try {
    req = window.indexedDB.open(NB_PHOTO_DB, 1);
  } catch (e) { onErr(e); return; }
  req.onupgradeneeded = function() {
    var db = req.result;
    if (!db.objectStoreNames.contains(NB_PHOTO_STORE)) {
      db.createObjectStore(NB_PHOTO_STORE);
    }
  };
  req.onsuccess = function() { onOk(req.result); };
  req.onerror = function() { onErr(req.error || new Error('idb open failed')); };
}

function nbPhotoIdbPut(key, blob, onOk, onErr) {
  nbPhotoIdbOpen(function(db) {
    var tx, st, pr;
    try {
      tx = db.transaction(NB_PHOTO_STORE, 'readwrite');
      st = tx.objectStore(NB_PHOTO_STORE);
      pr = st.put(blob, key);
    } catch (e) { onErr(e); return; }
    tx.oncomplete = function() { onOk(); };
    tx.onerror = function() { onErr(tx.error || new Error('idb put failed')); };
    pr.onerror = function() { onErr(pr.error || new Error('idb put failed')); };
  }, onErr);
}

function nbPhotoIdbGet(key, onOk, onErr) {
  nbPhotoIdbOpen(function(db) {
    var tx, st, pr;
    try {
      tx = db.transaction(NB_PHOTO_STORE, 'readonly');
      st = tx.objectStore(NB_PHOTO_STORE);
      pr = st.get(key);
    } catch (e) { onErr(e); return; }
    pr.onsuccess = function() { onOk(pr.result); };
    pr.onerror = function() { onErr(pr.error || new Error('idb get failed')); };
  }, onErr);
}

// Downscale a chosen image File on a canvas, then hand back a JPEG Blob plus its
// pixel dimensions. Mirrors the shelf-scan downscale (max edge + 0.85 JPEG) but
// yields a Blob (lean for IndexedDB) rather than base64.
function nbDownscaleImageToBlob(file, maxEdge, onOk, onErr) {
  if (!file) { onErr(new Error('no file')); return; }
  var url = URL.createObjectURL(file);
  var img = new Image();
  img.onload = function() {
    var w = img.naturalWidth || img.width;
    var h = img.naturalHeight || img.height;
    var scale = Math.min(1, maxEdge / Math.max(w, h || 1));
    var outW = Math.max(1, Math.round(w * scale));
    var outH = Math.max(1, Math.round(h * scale));
    var canvas = document.createElement('canvas');
    canvas.width = outW;
    canvas.height = outH;
    var ctx = canvas.getContext('2d');
    ctx.drawImage(img, 0, 0, outW, outH);
    URL.revokeObjectURL(url);
    if (canvas.toBlob) {
      canvas.toBlob(function(blob) {
        if (blob) { onOk(blob, outW, outH); }
        else { onErr(new Error('toBlob returned null')); }
      }, 'image/jpeg', 0.85);
    } else {
      onErr(new Error('canvas.toBlob unsupported'));
    }
  };
  img.onerror = function() {
    URL.revokeObjectURL(url);
    onErr(new Error('image decode failed'));
  };
  img.src = url;
}

// Build the at-rest inline shot for a stored image ref. Renders a sized
// placeholder synchronously (renderNotebookEntry is sync), then fills the blob
// from IndexedDB async; a missing blob (another device) keeps a graceful label.
function buildNotebookShot(ref) {
  var fig = document.createElement('figure');
  fig.className = 'notebook-shot';
  var media = document.createElement('div');
  media.className = 'notebook-shot-media notebook-shot-media-ph';
  if (ref && ref.w && ref.h) { media.style.aspectRatio = ref.w + ' / ' + ref.h; }
  var phLabel = document.createElement('span');
  phLabel.className = 'notebook-shot-ph-label';
  phLabel.textContent = 'Photo';
  media.appendChild(phLabel);
  fig.appendChild(media);
  if (ref && ref.caption) {
    var cap = document.createElement('figcaption');
    cap.className = 'notebook-shot-cap';
    cap.textContent = ref.caption;
    fig.appendChild(cap);
  }
  if (ref && ref.idbKey) {
    nbPhotoIdbGet(ref.idbKey, function(blob) {
      if (!blob) { phLabel.textContent = 'Photo not on this device'; return; }
      var objUrl = URL.createObjectURL(blob);
      var im = document.createElement('img');
      im.className = 'notebook-shot-img';
      im.alt = ref.caption || '';
      im.src = objUrl;
      media.className = 'notebook-shot-media';
      while (media.firstChild) { media.removeChild(media.firstChild); }
      media.appendChild(im);
    }, function() {
      phLabel.textContent = 'Photo unavailable';
    });
  }
  return fig;
}

// N2 upgrade: toggle the composing focus treatment on the notebook wrap. Adds /
// removes the .notebook-composing class on section.notebook ONLY -- the global
// app nav (outside the view) is never touched (design-canon A).
function setNotebookComposing(on) {
  var wrap = document.querySelector('.notebook');
  if (!wrap) { return; }
  if (on) {
    if (wrap.className.indexOf('notebook-composing') === -1) {
      wrap.className = wrap.className + ' notebook-composing';
    }
  } else {
    wrap.className = wrap.className.replace(/\s*\bnotebook-composing\b/g, '');
  }
}

// ── R-POLISH B1 · UX-3 (THE FORGIVENESS LAW) — SUBMIT DEBOUNCE ──────────────
// "All submit actions debounce -- killing the double-fire class at the root."
// The composer's commit() has TWO entry points (the Capture button's click and
// the composer's Enter keydown), so a double-click, or an Enter that lands
// beside a click, can run it twice and write two identical entries. The recon
// flagged exactly that shape: two identical marginalia moments apart.
//
// Both guards are MODULE-scoped on purpose. captureNote() re-renders the whole
// spread, which rebuilds the composer and throws away its closure -- a guard
// held inside buildNotebookWriteline would be reset by the very render it is
// meant to survive.
//   nbLastCommitAt : time gate for the SYNCHRONOUS (text-only) path.
//   nbCommitBusy   : in-flight gate for the ASYNC (staged-photo) path, where an
//                    IndexedDB put can outlive the time gate. Released on BOTH
//                    the success and the error branch, so a failed put can never
//                    wedge the composer shut (a lock you cannot release is a
//                    worse bug than the double-write it prevents).
// This ADDS a guard; it never deletes or rewrites an existing entry.
var nbLastCommitAt = 0;
var nbCommitBusy = false;
var NB_COMMIT_DEBOUNCE_MS = 700;
// Generation token for the in-flight gate (red-team finding 2). The backstop
// timeout below must only ever release the commit that ARMED it: commit #1 can
// finish legitimately at T+2s, commit #2 can start at T+3s with its own uploads
// still in flight, and #1's stale T+15s timer would then unlatch #2's gate --
// reopening the exact double-write race UX-3 exists to close, for the very
// window it is meant to protect. Each commit takes the next token; a backstop
// fires only if the token it captured is still the current one.
var nbCommitGen = 0;

// B1 · MO-1 SAVE PULSE — "every capture/save visibly answers the hand." Holds the
// id of the note just committed; renderNotebookEntry consumes it exactly once (it
// nulls the var as it applies the class), so the pulse fires on the commit render
// and never again on an unrelated re-render. Render-layer only, never persisted.
var nbJustSavedId = null;

// N2: inline capture (the writeline). A composer + register chips (the mic is
// DEFERRED to N2b; camera arrives in N2b photo capture). The selected register
// is closure-local so a chip click never loses typed text. Enter (no shift)
// commits via captureNote. Mounted at the top of the left leaf.
function buildNotebookWriteline(activeKey) {
  var line = document.createElement('div');
  line.className = 'nb-composer';

  // FIX A: auto-growing textarea (was a single-line <input>, which clipped any
  // note past the visible width / height). Grows to fit content; Enter commits,
  // Shift+Enter inserts a newline (the keydown handler below).
  var input = document.createElement('textarea');
  input.className = 'nb-ce';
  input.setAttribute('rows', '1');
  input.setAttribute('placeholder', 'Write a note…');
  function autogrowWriteline() {
    input.style.height = 'auto';
    input.style.height = input.scrollHeight + 'px';
  }
  input.addEventListener('input', autogrowWriteline);

  // Default register by context: Journal tab -> journal, else marginalia.
  var selected = (activeKey === 'journal') ? 'journal' : 'marginalia';

  // ── R-ARC S2: the draft waits where it was written (REQ#3) ────────────────
  // The composer belongs to the account that opened it. Auth can change with NO
  // reload (integrations.js: clearUserState -> sv('praxis_user', B) -> loadState),
  // and this closure outlives its own composer, so the owner is captured ONCE here
  // and every write is gated on it. Re-reading the uid at write time would let a
  // pagehide after an account switch write A's text into B's key -- which B could
  // then commit as their own words.
  var nbOwner = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
  var nbOwnerUid = (nbOwner && nbOwner.uid) ? nbOwner.uid : null;
  var nbDraft = nbOwnerUid ? nbDraftLoad(nbOwnerUid, activeKey) : null;
  if (nbDraft) {
    input.value = nbDraft.body;
    if (nbDraft.register === 'marginalia' || nbDraft.register === 'question' ||
        nbDraft.register === 'journal') {
      selected = nbDraft.register;
    }
    // autogrow reads scrollHeight, which is 0 until the composer is in the DOM.
    setTimeout(autogrowWriteline, 0);
  }
  var nbDraftTimer = null;
  function nbDraftFlush() {
    if (nbDraftTimer) { clearTimeout(nbDraftTimer); nbDraftTimer = null; }
    // The owner must still be the signed-in account, or this composer has nothing
    // to say: a stale flush from a torn-down composer must never write, and must
    // never write under someone else's uid.
    var now = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
    if (!nbOwnerUid || !now || now.uid !== nbOwnerUid) { return; }
    nbDraftSave(nbOwnerUid, input.value, selected, activeKey);
  }
  function nbDraftSchedule() {
    if (nbDraftTimer) { clearTimeout(nbDraftTimer); }
    nbDraftTimer = setTimeout(nbDraftFlush, 300);
  }
  input.addEventListener('input', nbDraftSchedule);
  input.addEventListener('blur', nbDraftFlush);
  nbDraftFlushFn = nbDraftFlush;
  nbInstallDraftHooks();

  var chips = document.createElement('div');
  chips.className = 'seg';
  var defs = [
    { r: 'marginalia', l: 'Marginalia' },
    { r: 'question', l: 'Question' },
    { r: 'journal', l: 'Journal' }
  ];
  var chipEls = {};
  function paint() {
    var r;
    for (r in chipEls) {
      if (Object.prototype.hasOwnProperty.call(chipEls, r)) {
        chipEls[r].className = 'seg-opt'
          + (r === selected ? ' is-on' : '');
      }
    }
  }
  var d;
  for (d = 0; d < defs.length; d = d + 1) {
    appendWritelineChip(chips, defs[d], chipEls, function(reg) {
      selected = reg; paint(); input.focus();
      nbDraftFlush();   // the register is part of the draft
    });
  }
  paint();

  // N2b: photo capture -- two paths (camera + library) attach inline, stored
  // device-local in IndexedDB on commit; the entry persists refs only. Staged
  // blobs are held in memory until commit, so an abandoned compose leaks nothing.
  var stagedImages = [];   // {id, blob, w, h, caption, url}

  var shotsHost = document.createElement('div');
  shotsHost.className = 'nb-shots';

  function renderStagedShot(si) {
    var fig = document.createElement('figure');
    fig.className = 'notebook-shot';
    var media = document.createElement('div');
    media.className = 'notebook-shot-media';
    if (si.w && si.h) { media.style.aspectRatio = si.w + ' / ' + si.h; }
    var im = document.createElement('img');
    im.className = 'notebook-shot-img';
    im.alt = '';
    im.src = si.url;
    media.appendChild(im);
    var rm = document.createElement('button');
    rm.type = 'button';
    rm.className = 'notebook-shot-remove';
    rm.setAttribute('aria-label', 'Remove photo');
    rm.textContent = '×';
    rm.addEventListener('click', function() {
      var k;
      for (k = 0; k < stagedImages.length; k = k + 1) {
        if (stagedImages[k] === si) { stagedImages.splice(k, 1); break; }
      }
      if (si.url) { URL.revokeObjectURL(si.url); }
      if (fig.parentNode) { fig.parentNode.removeChild(fig); }
    });
    media.appendChild(rm);
    fig.appendChild(media);
    var cap = document.createElement('input');
    cap.type = 'text';
    cap.className = 'notebook-shot-cap-input';
    cap.setAttribute('placeholder', 'Add a caption…');
    cap.addEventListener('input', function() { si.caption = cap.value; });
    fig.appendChild(cap);
    shotsHost.appendChild(fig);
  }

  function addStagedPhoto(file) {
    if (!file) { return; }
    setNotebookComposing(true);
    nbDownscaleImageToBlob(file, 1600, function(blob, w, h) {
      var si = {
        id: genNotebookImageId(), blob: blob, w: w, h: h,
        caption: '', url: URL.createObjectURL(blob)
      };
      stagedImages.push(si);
      renderStagedShot(si);
    }, function(err) {
      if (window.console) { console.warn('notebook photo decode/downscale failed', err); }
    });
  }

  var cameraInput = document.createElement('input');
  cameraInput.type = 'file';
  cameraInput.accept = 'image/*';
  cameraInput.setAttribute('capture', 'environment');
  cameraInput.className = 'notebook-capture-input';
  cameraInput.addEventListener('change', function() {
    addStagedPhoto(cameraInput.files && cameraInput.files[0]);
    cameraInput.value = '';
  });

  var libraryInput = document.createElement('input');
  libraryInput.type = 'file';
  libraryInput.accept = 'image/*';
  libraryInput.className = 'notebook-capture-input';
  libraryInput.addEventListener('change', function() {
    addStagedPhoto(libraryInput.files && libraryInput.files[0]);
    libraryInput.value = '';
  });

  // Mock .crow: the register segmented control (.seg, built above), a spacer, and
  // the Capture button. R4 (#1 unified composer): the photo chips moved OUT of the
  // crow into the labeled .nb-modes row below, alongside paste/import/dictate --
  // one coherent "bring one in" affordance.
  var crow = document.createElement('div');
  crow.className = 'crow';
  var crowSpacer = document.createElement('span');
  crowSpacer.className = 'spacer';
  var captureBtn = document.createElement('button');
  captureBtn.type = 'button';
  captureBtn.className = 'btn btn-primary';
  captureBtn.textContent = 'Capture';
  captureBtn.addEventListener('click', function() { commit(); });
  crow.appendChild(chips);
  crow.appendChild(crowSpacer);
  crow.appendChild(captureBtn);

  // R4 (#1 unified composer): one labeled "bring one in" row (.nb-modes) carrying
  // every import affordance. photo + add-image STAGE INLINE (cameraInput /
  // libraryInput .click() -- handlers byte-identical to the old .crow chips);
  // paste / import / dictate HAND OFF to the shared capture overlay
  // (window.ImportCapture.open() -- handler byte-identical to the old .nb-capmodes)
  // and carry a hand-off cue. The old "talk it through with Yumi" mode is DROPPED
  // for R4 (eval-gated; its own future round). ImportCapture.open is guarded, so
  // the paste/import/dictate trio only appears when the module is present.
  var modes = document.createElement('div');
  modes.className = 'nb-modes';
  var modesLabel = document.createElement('span');
  modesLabel.className = 'nb-modes-label';
  modesLabel.textContent = 'or bring one in';
  modes.appendChild(modesLabel);
  var modesRow = document.createElement('div');
  modesRow.className = 'nb-modes-row';
  var hasImport = window.ImportCapture && typeof window.ImportCapture.open === 'function';
  if (hasImport) {
    modesRow.appendChild(buildNotebookModeChip('paste', '☰', 'Paste', true, function() { window.ImportCapture.open(); }));
    modesRow.appendChild(buildNotebookModeChip('import', '⭳', 'Import', true, function() { window.ImportCapture.open(); }));
    modesRow.appendChild(buildNotebookModeChip('dictate', '🎤', 'Dictate', true, function() { window.ImportCapture.open(); }));
  }
  modesRow.appendChild(buildNotebookModeChip('photo', '📷', 'Photo', false, function() { cameraInput.click(); }));
  modesRow.appendChild(buildNotebookModeChip('library', '🖼', 'Add image', false, function() { libraryInput.click(); }));
  modes.appendChild(modesRow);
  var modesHint = document.createElement('p');
  modesHint.className = 'nb-modes-hint';
  modesHint.textContent = hasImport
    ? 'Photo & Add image stage right here on the page. Paste, import, and dictate open the capture window (↗) and come back with a note.'
    : 'Photo & Add image stage right here on the page.';
  modes.appendChild(modesHint);

  function commit() {
    var body = (input.value || '').replace(/^\s+|\s+$/g, '');
    if (!body && stagedImages.length === 0) { return; }
    // UX-3 debounce (see the module vars above). Placed AFTER the empty check so
    // an empty Enter never arms the gate, and BEFORE any state mutation so a
    // suppressed second fire touches nothing at all.
    var nbNow = Date.now();
    if (nbCommitBusy || (nbNow - nbLastCommitAt) < NB_COMMIT_DEBOUNCE_MS) { return; }
    nbLastCommitAt = nbNow;
    // S2 durability law: consuming the draft CLEARS it, and captureNote no-ops on a
    // signed-out caller -- so clearing without a live user would destroy the text and
    // write nothing. Confirm the write can land FIRST, and clear ONLY on the branch
    // about to call captureNote (the image path clears inside finalize, so an
    // IndexedDB abort that never reaches captureNote leaves the draft intact).
    var cUser = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
    if (!cUser || !cUser.uid) { return; }
    // Cancel the pending debounce so a stale timer cannot re-save this text against
    // the detached textarea after commit (the ghost-draft race).
    if (nbDraftTimer) { clearTimeout(nbDraftTimer); nbDraftTimer = null; }
    nbDraftFlushFn = null;
    if (stagedImages.length === 0) {
      nbDraftClear(nbOwnerUid, activeKey);
      captureNote(selected, body, activeKey, []);
      return;
    }
    // Persist each staged blob to IndexedDB, then create the note with refs.
    // refs is index-keyed so display order survives the async puts.
    var refs = new Array(stagedImages.length);
    var remaining = stagedImages.length;
    var done = false;
    function finalize() {
      if (done) { return; }
      done = true;
      var clean = [], j;
      for (j = 0; j < refs.length; j = j + 1) { if (refs[j]) { clean.push(refs[j]); } }
      var s;
      for (s = 0; s < stagedImages.length; s = s + 1) {
        if (stagedImages[s].url) { URL.revokeObjectURL(stagedImages[s].url); }
      }
      // Clear the draft only now, when captureNote is certain to run -- a hung or
      // aborted put never reaches here, so the text survives.
      nbDraftClear(nbOwnerUid, activeKey);
      nbCommitBusy = false;          // released BEFORE the re-render swaps this composer out
      captureNote(selected, body, activeKey, clean);
    }
    // UX-3: hold the in-flight gate across the async puts. Both the success and
    // the error callback decrement `remaining` and funnel into finalize(), so the
    // normal release is covered on either branch. The timeout is the backstop for
    // the one case neither covers -- an IndexedDB put that never calls back at
    // all: without it the gate would latch and the composer would be permanently
    // unable to save, which is a worse failure than the double-write it guards.
    nbCommitBusy = true;
    nbCommitGen = nbCommitGen + 1;
    (function(myGen) {
      window.setTimeout(function() {
        // Only unlatch if THIS commit still owns the gate. If a later commit has
        // since armed it (nbCommitGen moved on), that commit's own backstop is
        // the one entitled to release it -- never this stale one.
        if (nbCommitGen === myGen) { nbCommitBusy = false; }
      }, 15000);
    })(nbCommitGen);
    var i;
    for (i = 0; i < stagedImages.length; i = i + 1) {
      (function(si, idx) {
        nbPhotoIdbPut(si.id, si.blob, function() {
          refs[idx] = { id: si.id, idbKey: si.id, w: si.w, h: si.h, caption: si.caption || '' };
          remaining = remaining - 1;
          if (remaining === 0) { finalize(); }
        }, function(err) {
          if (window.console) { console.warn('notebook photo store failed', err); }
          refs[idx] = null;
          remaining = remaining - 1;
          if (remaining === 0) { finalize(); }
        });
      })(stagedImages[i], i);
    }
  }
  input.addEventListener('keydown', function(ev) {
    if (ev.key === 'Enter' && !ev.shiftKey) { ev.preventDefault(); commit(); }
  });

  // N2 upgrade: focusing the composer recedes the in-view chrome (composing);
  // when focus leaves the writeline entirely, return to resting. A chip click
  // (or a capture button / caption field, all inside `line`) keeps focus within
  // the writeline, so the deferred check leaves composing on.
  input.addEventListener('focus', function() { setNotebookComposing(true); });
  input.addEventListener('blur', function() {
    window.setTimeout(function() {
      var ae = document.activeElement;
      if (!(ae && line.contains(ae))) { setNotebookComposing(false); }
    }, 120);
  });

  // .nb-composer order: the writing measure (.ce), staged shots, the .crow
  // (register seg + Capture), then the unified .nb-modes "bring one in" row. Hidden
  // file inputs trail so .click() reaches them (they must be in the DOM).
  line.appendChild(input);
  line.appendChild(shotsHost);
  line.appendChild(crow);
  line.appendChild(modes);
  line.appendChild(cameraInput);
  line.appendChild(libraryInput);
  return line;
}

// One writeline chip, closure-scoped per register (a var-in-for-loop would bind
// every chip to the last register).
function appendWritelineChip(chips, def, chipEls, onPick) {
  var c = document.createElement('button');
  c.type = 'button';
  c.className = 'seg-opt';
  c.setAttribute('data-reg', def.r);
  c.appendChild(document.createTextNode(def.l));
  c.addEventListener('click', function() { onPick(def.r); });
  chipEls[def.r] = c;
  chips.appendChild(c);
}

// R4 (#1 unified composer): one labeled affordance chip in the composer's
// .nb-modes row. handoff=true appends the hand-off cue (paste/import/dictate open
// the shared capture overlay); handoff=false is an inline stager (photo/add-image,
// .is-inline). onClick is passed pre-bound so the wired handler is byte-identical
// to the affordance it replaces.
function buildNotebookModeChip(mode, icon, label, handoff, onClick) {
  var b = document.createElement('button');
  b.type = 'button';
  b.className = 'nb-mode' + (handoff ? '' : ' is-inline');
  b.setAttribute('data-mode', mode);
  var ic = document.createElement('span');
  ic.className = 'ic';
  ic.setAttribute('aria-hidden', 'true');
  ic.textContent = icon;
  b.appendChild(ic);
  b.appendChild(document.createTextNode(label));
  if (handoff) {
    var ho = document.createElement('span');
    ho.className = 'handoff';
    ho.setAttribute('aria-hidden', 'true');
    ho.textContent = '↗';
    b.appendChild(ho);
  }
  b.addEventListener('click', onClick);
  return b;
}

// R4 (#empty): the calm first-run / no-notes Inbox leaf that teaches the surface
// (mockup #empty state). A mark, a title, a short body, and three quiet steps.
// Journal + book tabs keep their one-line quiet empties (below).
function buildNotebookInboxEmpty() {
  var wrap = document.createElement('div');
  wrap.className = 'nb-empty';
  var mark = document.createElement('div');
  mark.className = 'nb-empty-mark';
  mark.setAttribute('aria-hidden', 'true');
  wrap.appendChild(mark);
  var title = document.createElement('div');
  title.className = 'nb-empty-title';
  title.textContent = 'Nothing in your inbox yet';
  wrap.appendChild(title);
  var body = document.createElement('p');
  body.className = 'nb-empty-body';
  body.textContent = 'Quick captures land here, awaiting a home. Write a line, paste a passage, or dictate a thought — then gather a few on the right and a sub-theory begins to form.';
  wrap.appendChild(body);
  var steps = document.createElement('div');
  steps.className = 'nb-empty-steps';
  var stepText = [
    'Catch a note — a margin, a question, a journal line.',
    'File it to the book it belongs with.',
    'Gather a few and name what they add up to.'
  ];
  var si;
  for (si = 0; si < stepText.length; si = si + 1) {
    var step = document.createElement('div');
    step.className = 'nb-empty-step';
    var n = document.createElement('span');
    n.className = 'n';
    n.textContent = String(si + 1);
    step.appendChild(n);
    var t = document.createElement('span');
    t.className = 't';
    t.textContent = stepText[si];
    step.appendChild(t);
    steps.appendChild(step);
  }
  wrap.appendChild(steps);
  return wrap;
}

// N2: create an entry from the writeline. register = chip; isPrivate = by-kind
// default (journal private; marginalia + question visible). Placement:
//   journal           -> filed true, no book (Journal tab)
//   marg/ques on book  -> filed true, bookIds = [activeKey] (that book's bank)
//   marg/ques elsewhere-> filed false, no book (Inbox, awaiting triage)
// Then "follow the note" to the tab it routed into, and re-render.
function captureNote(register, body, activeKey, images) {
  var user = getCurrentUser();
  if (!user) { return; }
  var now = Date.now();
  var id = genEntryId();
  var bookIds = [];
  var filed;
  if (register === 'journal') {
    filed = true;
  } else if (activeKey !== 'inbox' && activeKey !== 'journal') {
    filed = true; bookIds = [activeKey];
  } else {
    filed = false;
  }
  state.notebookEntries[id] = {
    id:        id,
    userId:    user.uid,
    register:  register,
    isPrivate: getRegisterDefault(register),
    body:      body,
    bookIds:   bookIds,
    arcIds:    [],
    images:    (images && images.length) ? images : [],
    filed:     filed,
    createdAt: now,
    updatedAt: now
  };
  markNotebookDirty();
  saveState();
  nbJustSavedId = id;          // B1/MO-1: the render below answers the hand
  if (register === 'journal') { notebookActiveTab = 'journal'; }
  else if (filed) { notebookActiveTab = bookIds[0]; }
  else { notebookActiveTab = 'inbox'; }
  renderNotebook();
  maybeDrawOut(id);
}

// Stage B-1/B-2: fire the Yumi-moves orchestrator on a fresh note-write. The
// orchestrator gates (consent / private / panel-open / budget) and the router
// decide the move -- DRAW OUT, COMPLICATE, or STAY QUIET; a surfaced question
// renders into the open Yumi panel via the Stage-A renderYumiMessage path.
// Fire-and-forget -- never blocks or alters the capture. panelOpen is read
// here (UI side) so the brain stays DOM-free. Hooked on the two VISIBLE-note
// seams (this writeline + book-detail marginalia); considerMove now skips
// both isPrivate AND journal-register notes.
function maybeDrawOut(entryId) {
  if (!(window.YumiBrain && YumiBrain.considerMove)) { return; }
  var entry = state.notebookEntries && state.notebookEntries[entryId];
  if (!entry) { return; }
  var panelOpen = !!(window.YumiUI && YumiUI.visiblyOpen && YumiUI.visiblyOpen());
  YumiBrain.considerMove(entry, panelOpen).then(function (r) {
    if (r && r.surface && typeof renderYumiMessage === 'function') {
      // Stage III: r carries r.web / r.theme when a web lookup informed the
      // angle; renderYumiMessage renders the grounding chip only then.
      renderYumiMessage(r.text, r);
    }
  });
  // R-ARC S9 (the raised-hand seat): a note written while the Bloom is CLOSED
  // may raise the hand -- cheap eligibility only (no proxy); the move composes
  // lazily on open. No-op when the panel is open (considerMove handles that).
  if (!panelOpen && window.YumiUI && YumiUI.maybeRaiseHand) { YumiUI.maybeRaiseHand(); }
  // yumi-intelligence Stage II: a visible note-write is also a cue to refresh
  // the reader-model profile -- "grows as you read." Fire-and-forget; self-gated
  // on consent + provenance + cooldown + its own budget (never the gate's).
  if (YumiBrain.considerProfileRefresh) { YumiBrain.considerProfileRefresh(); }
}

// Stage B-2.2: the COMPLICATE co-write. ADDITIVELY append the reader's
// reflection to the target note's body (original text preserved), stamp
// updatedAt, persist, and re-render the active route. Reuses the
// fileEntryToBook mutation pattern. Touches ONLY this one note's body --
// never other notes, never other fields, never a delete. Reversible via the
// existing Delete affordance. Returns true only when an append happened.
function integrateReflection(entryId, replyText) {
  var entry = state.notebookEntries && state.notebookEntries[entryId];
  if (!entry || typeof replyText !== 'string') { return false; }
  var add = replyText.replace(/^\s+|\s+$/g, '');
  if (add === '') { return false; }
  entry.body = (typeof entry.body === 'string' ? entry.body : '') + '\n\n' + add;
  entry.updatedAt = Date.now();
  markNotebookDirty();
  saveState();
  if (typeof renderRoute === 'function') { renderRoute(); }
  return true;
}

// R-ARC S4 (fork S4-6 FOLD): Yumi's NAME proposal, on Accept, folds INTO the one door.
// It pre-gathers the noticed notes and OFFERS the proposed name in the notebook gather
// bar, then routes to #notebook — the READER picks the arc and creates. Covenant: Yumi
// proposes, the reader acts. The offered name is editable/clearable and NEVER sticky —
// cleared, creation proceeds as an unnamed basin (never-asked-never-forbidden). No
// auto-mint, no silent create, and — by ruling — NO reader-model "named thread" write
// (that signal returns via the Wave-C raised-hand seat, not invisible threading into the
// door). Marks the thread 'named' for idempotency ONLY (so Yumi does not re-propose it).
// Returns true on a successful hand-off, else false. Inert until called (Accept only).
function notebookGatherFromThread(memberIds, proposedName) {
  var user = getCurrentUser();
  if (!user || !user.uid) { return false; }
  if (!memberIds || !memberIds.length) { return false; }
  var gathered = {};
  var any = false;
  var i;
  for (i = 0; i < memberIds.length; i = i + 1) {
    var id = memberIds[i];
    if (id && state.notebookEntries && state.notebookEntries[id]) { gathered[id] = true; any = true; }
  }
  if (!any) { return false; }
  notebookGathered = gathered;
  notebookGatherArc = null;  // the reader chooses the arc in the door
  notebookGatherName = (typeof proposedName === 'string') ? proposedName.replace(/^\s+|\s+$/g, '') : '';
  // Idempotency ONLY (no reader-model write, per the S4-6 ruling): mark the thread so
  // Yumi does not re-propose it.
  if (window.YumiBrain && YumiBrain.recordThreadNamed) { YumiBrain.recordThreadNamed(memberIds); }
  // Latch the notebook session to THIS uid BEFORE persisting. The fold usually runs
  // before the Notebook has rendered this session, so notebookSessionUid is still null;
  // without the latch, nbGatherSave's owner gate no-ops AND the Notebook's first
  // nbGatherRestore RESETS the in-memory gather + reloads an unwritten key — silently
  // dropping the whole hand-off (WS-A red-team BLOCK). Latching to the CURRENT uid keeps
  // the owner gate honest (we write this user's key) while making that restore a no-op.
  notebookSessionUid = user.uid;
  nbGatherSave();
  // Route to the one door. A same-hash set is a no-op in this SPA, so force the render
  // when already on the notebook; otherwise the hash change routes via renderRoute.
  if (location.hash === '#notebook' || location.hash === '' || location.hash === '#') {
    renderNotebook();
  } else {
    location.hash = 'notebook';
  }
  return true;
}

// N2: file an Inbox entry to a book -- set filed true + add the bookId (deduped).
function fileEntryToBook(entryId, bookId) {
  var entry = state.notebookEntries && state.notebookEntries[entryId];
  if (!entry || !bookId) { return false; }
  entry.filed = true;
  if (!entry.bookIds) { entry.bookIds = []; }
  var present = false;
  var i;
  for (i = 0; i < entry.bookIds.length; i = i + 1) {
    if (entry.bookIds[i] === bookId) { present = true; break; }
  }
  if (!present) { entry.bookIds.push(bookId); }
  entry.updatedAt = Date.now();
  markNotebookDirty();
  saveState();
  return true;
}

// N2: a book picker (mirrors buildArcPickerPanel). Lists the user's shelf
// books; onPick(bookId). Self-closing (Esc / Done).
function buildBookPickerPanel(opts) {
  var panel = document.createElement('div');
  panel.className = 'arc-picker-panel book-picker-panel';
  var labelEl = document.createElement('div');
  labelEl.className = 'arc-picker-label';
  labelEl.textContent = opts.label || 'File to a book';
  panel.appendChild(labelEl);
  function closePanel() {
    document.removeEventListener('keydown', onKeydown);
    if (panel.parentNode) { panel.parentNode.removeChild(panel); }
  }
  function onKeydown(ev) { if (ev.keyCode === 27) { closePanel(); } }
  document.addEventListener('keydown', onKeydown);
  var uid = (opts.user && opts.user.uid) ? opts.user.uid : null;
  var bookIds = (uid && state.userBooks && state.userBooks[uid] &&
                 state.userBooks[uid].bookIds) ? state.userBooks[uid].bookIds : [];
  if (!bookIds.length) {
    var empty = document.createElement('p');
    empty.className = 'arc-picker-empty';
    empty.textContent = 'No books on your shelf yet — add a book first.';
    panel.appendChild(empty);
  } else {
    var i;
    for (i = 0; i < bookIds.length; i = i + 1) {
      appendBookPickerRow(panel, bookIds[i], opts.onPick);
    }
  }
  var done = document.createElement('a');
  done.href = '#';
  done.className = 'arc-picker-done';
  done.textContent = 'Done';
  done.addEventListener('click', function(ev) { ev.preventDefault(); closePanel(); });
  panel.appendChild(done);
  return panel;
}

function appendBookPickerRow(panel, bookId, onPick) {
  var book = (state.books && state.books[bookId]) || null;
  var row = document.createElement('a');
  row.href = '#';
  row.className = 'arc-picker-row';
  row.textContent = (book && book.title) ? book.title : '(untitled book)';
  row.addEventListener('click', function(ev) {
    ev.preventDefault();
    onPick(bookId);
  });
  panel.appendChild(row);
}

function openFileToBookPicker(entryId, mountEl) {
  if (!mountEl) { return; }
  var user = getCurrentUser();
  if (!user) { return; }
  mountEl.innerHTML = '';
  mountEl.appendChild(buildBookPickerPanel({
    user: user,
    label: 'File this note to a book',
    onPick: function(bookId) {
      if (fileEntryToBook(entryId, bookId)) {
        notebookActiveTab = bookId;
        renderNotebook();
      }
    }
  }));
}

// Stage 3.7: shared editor shell. Mounts a title (optional) + body
// textarea + Save/Cancel block into the host element identified by
// opts.hostId. Three callers as of 3.7: openJournalEditor and
// openMarginaliaEditor (body-only entries into state.notebookEntries)
// and openArtifactEditor (title + body, write into state.bookArtifacts
// via ensureOneArtifact).
//
// opts shape:
//   hostId:         string         // DOM id of the mount point.
//   emptySelector:  string | null  // CSS selector for an empty-state
//                                  // element to hide on mount. null
//                                  // if none.
//   showTitleField: boolean        // render a title input above body.
//   titlePrefill:   string         // initial value when showTitleField
//                                  // is true; ignored otherwise.
//   onSave(title, body):           // both trimmed strings; only the
//                                  // gated field is guaranteed non-empty.
//   onCancel():
//
// Save-enabled gate is field-driven, not caller-driven: title-bearing
// editors enable Save when the title trims non-empty (body optional --
// the Artifact's body is genuinely optional per 3.7 brief), body-only
// editors enable Save when the body trims non-empty (existing journal /
// marginalia behavior, unchanged).
function openEditor(opts) {
  var hostEl = document.getElementById(opts.hostId);
  if (!hostEl) return;

  if (opts.emptySelector) {
    var emptyEl = document.querySelector(opts.emptySelector);
    if (emptyEl) emptyEl.style.display = 'none';
  }

  hostEl.innerHTML = '';

  var editor = document.createElement('div');
  editor.className = 'notebook-editor';

  var titleInput = null;
  if (opts.showTitleField) {
    titleInput = document.createElement('input');
    titleInput.type = 'text';
    titleInput.className = 'notebook-editor-title-input';
    titleInput.value = (typeof opts.titlePrefill === 'string')
      ? opts.titlePrefill : '';
    if (typeof opts.titlePlaceholder === 'string') {
      titleInput.setAttribute('placeholder', opts.titlePlaceholder);
    }
  }

  var bodyInput = document.createElement('textarea');
  bodyInput.className = 'notebook-editor-body';
  bodyInput.rows = 8;
  if (typeof opts.bodyPlaceholder === 'string') {
    bodyInput.setAttribute('placeholder', opts.bodyPlaceholder);
  }

  var actions = document.createElement('div');
  actions.className = 'notebook-editor-actions';

  var saveBtn = document.createElement('button');
  saveBtn.type = 'button';
  saveBtn.className = 'notebook-editor-save';
  saveBtn.textContent = 'Save';

  var cancelBtn = document.createElement('button');
  cancelBtn.type = 'button';
  cancelBtn.className = 'notebook-editor-cancel';
  cancelBtn.textContent = 'Cancel';

  function trimVal(el) {
    return el.value.replace(/^\s+|\s+$/g, '');
  }

  function refreshSaveEnabled() {
    var ok;
    if (opts.showTitleField) {
      ok = trimVal(titleInput).length > 0;
    } else {
      ok = trimVal(bodyInput).length > 0;
    }
    saveBtn.disabled = !ok;
  }
  refreshSaveEnabled();

  bodyInput.addEventListener('input', refreshSaveEnabled);
  if (titleInput) {
    titleInput.addEventListener('input', refreshSaveEnabled);
  }

  saveBtn.addEventListener('click', function() {
    var titleVal = titleInput ? trimVal(titleInput) : '';
    var bodyVal  = trimVal(bodyInput);
    if (opts.showTitleField) {
      if (titleVal.length === 0) return;
    } else {
      if (bodyVal.length === 0) return;
    }
    opts.onSave(titleVal, bodyVal);
  });

  cancelBtn.addEventListener('click', function() {
    opts.onCancel();
  });

  actions.appendChild(saveBtn);
  actions.appendChild(cancelBtn);
  if (titleInput) editor.appendChild(titleInput);
  editor.appendChild(bodyInput);
  editor.appendChild(actions);
  hostEl.appendChild(editor);

  if (titleInput) {
    titleInput.focus();
    titleInput.select();
  } else {
    bodyInput.focus();
  }
}

function openJournalEditor() {
  openEditor({
    hostId:         'notebook-editor-host',
    emptySelector:  '.notebook-empty-body',
    showTitleField: false,
    onSave: function(_titleVal, bodyVal) {
      var user = getCurrentUser();
      if (!user) return;
      var now = Date.now();
      var id  = genEntryId();
      var entry = {
        id:         id,
        userId:     user.uid,
        register:   'journal',
        isPrivate:  getRegisterDefault('journal'),
        body:       bodyVal,
        bookIds:    [],
        arcIds:     [],
        images:     [],
        filed:      true,
        createdAt:  now,
        updatedAt:  now
      };
      state.notebookEntries[id] = entry;
      markNotebookDirty();
      saveState();
      renderNotebook();
    },
    onCancel: function() {
      renderNotebook();
    }
  });
}

// Stage 3.8: arc creation editor. Thin wrapper around openEditor --
// title field is required (Save auto-disabled while empty; onSave does
// not fire on empty input), body field carries the optional
// description. onSave resolves the user via getCurrentUser, no-ops if
// absent (mirrors openJournalEditor), then calls createArc with
// (title, description, user.uid). createArc returns null only on
// empty-title (already gated by the openEditor disabled-Save
// validation, so this is belt-and-suspenders); on success the
// saveState + renderNotebook sequence matches the entry-creation path
// exactly. Cancel just re-renders, which clears the editor host as
// part of the full tree rebuild.
function openArcEditor() {
  openEditor({
    hostId:         'notebook-arc-editor-host',
    showTitleField: true,
    titlePlaceholder: 'Name this arc',
    bodyPlaceholder: 'What question or thread runs through it?',
    onSave: function(titleVal, bodyVal) {
      var user = getCurrentUser();
      if (!user) return;
      var arc = createArc(titleVal, bodyVal, user.uid);
      if (!arc) return;
      saveState();
      // R5 FIX: land on the newly created arc's field (was renderRoute, which
      // re-rendered the source page). A different hash -> the router opens it.
      location.hash = 'arc/' + arc.id;
    },
    onCancel: function() {
      renderRoute();
    }
  });
}

// Stage 5.3 Stage 2: the Arcs page. Renders the locked C2 teaching
// paragraph (design-system v2 Part C) and the C4 Create-an-arc CTA
// alongside three steps from living-doc Section 10. Worked examples
// (Stage 3) and Find-this-book (Stage 4) land in subsequent sub-
// stages. Routes from the #arcs hash via renderRoute. Distinct from
// the existing #arc/<id> arc-detail surface (renderArcDetail) -- this
// is the plural list/teaching surface that lives in the top nav.
//
// CTA wiring: the "Create an arc" button calls the existing
// openArcEditor() unchanged. openArcEditor mounts into the hostId
// 'notebook-arc-editor-host', so this page renders that div NESTED
// inside the spec-named #arcs-create-host wrapper -- the wrapper is
// the Arcs-page CSS scope; the inner div is the openArcEditor mount
// point. R5 FIX: on save openArcEditor now navigates to the newly
// created arc's field (location.hash = 'arc/<id>'); on cancel it
// re-renders the current route. (The prior note that it landed on the
// Notebook was already stale -- the code called renderRoute.)
// Canon §4-G: per-arc computed counts (display-only; no data-model change).
// books = arc.bookIds; sub-theories = sub-theories whose arcId matches;
// marginalia = attached entries (arc.entryIds) whose register is marginalia.
function _arcCardCounts(arcId, arcRec) {
  var c = { books: 0, subTheories: 0, marginalia: 0 };
  if (arcRec && arcRec.bookIds && arcRec.bookIds.length) {
    c.books = arcRec.bookIds.length;
  }
  // R5 FIX: one shared, index-backed count path (O(1) inside renderArcsPage).
  c.subTheories = _arcSubCount(arcId);
  if (arcRec && arcRec.entryIds && arcRec.entryIds.length &&
      state.notebookEntries) {
    var i;
    for (i = 0; i < arcRec.entryIds.length; i = i + 1) {
      var eid = arcRec.entryIds[i] && arcRec.entryIds[i].id;
      var entry = eid ? state.notebookEntries[eid] : null;
      if (entry && entry.register === 'marginalia') {
        c.marginalia = c.marginalia + 1;
      }
    }
  }
  return c;
}

// (Wave 7 · Surface C: the books·sub-theories·marginalia meta line _arcCardMetaText
// was replaced by _arcCardMeta2El (sub-theories · maturity · touched); removed as dead.)

// (Wave 7 · Surface C: the static single-spark _arcCardThumb was replaced by the
// per-arc _arcCardConstellation; the illustrated example uses its empty-band form.)

// ============================================================================
// Wave 7 · Surface C (Arcs -> .lum-amber): real-data helpers. Sort binds to real
// fields (createdAt / title / aggregate maturity); the mini-constellation renders
// each sub-theory's idea-light through the shared bookSubMarkHTML bridge (stored
// markShape/markColor else stHashIndices(id); never hand-rolled SVG). Published
// flag + consequence counts do NOT exist on the arc record -> their controls are
// OMITTED, not fabricated (logged as a data-model task).
// ============================================================================

// R5 FIX: an arcId -> [subs] index built ONCE per renderArcsPage so the per-card
// helpers (_arcSubsOf / _arcCardCounts / maturity / sort) stop re-scanning ALL of
// state.subTheories for every card. Non-null ONLY during a renderArcsPage pass;
// every other caller (renderArcDetail, account stats) takes the full-scan path.
var _arcSubsIndex = null;

function _buildArcSubsIndex() {
  var idx = {};
  var k;
  if (state.subTheories) {
    for (k in state.subTheories) {
      if (Object.prototype.hasOwnProperty.call(state.subTheories, k)) {
        var s = state.subTheories[k];
        if (s && s.arcId) {
          if (!idx[s.arcId]) { idx[s.arcId] = []; }
          idx[s.arcId].push(s);
        }
      }
    }
  }
  var a;
  for (a in idx) {
    if (Object.prototype.hasOwnProperty.call(idx, a)) {
      idx[a].sort(function (x, y) { return (x.createdAt || 0) - (y.createdAt || 0); });
    }
  }
  return idx;
}

// Sub-theory records of an arc, oldest-first.
function _arcSubsOf(arcId) {
  if (!arcId) { return []; }
  if (_arcSubsIndex) { return _arcSubsIndex[arcId] || []; }
  var out = [];
  var k;
  if (!state.subTheories) { return out; }
  for (k in state.subTheories) {
    if (Object.prototype.hasOwnProperty.call(state.subTheories, k) &&
        state.subTheories[k] && state.subTheories[k].arcId === arcId) {
      out.push(state.subTheories[k]);
    }
  }
  out.sort(function (a, b) { return (a.createdAt || 0) - (b.createdAt || 0); });
  return out;
}

// R5 FIX: the ONE shared sub-theory count for an arc (index-backed inside
// renderArcsPage). Replaces the ad-hoc per-helper re-scans.
function _arcSubCount(arcId) { return _arcSubsOf(arcId).length; }

// Arc-level maturity in [0,1]: mean of the real per-sub _stComputeMaturity (the
// same derivation the constellation + sub-theory detail use). Empty arc -> 0.
function _arcAggregateMaturity(arcId) {
  var subs = _arcSubsOf(arcId);
  if (!subs.length) { return 0; }
  var sum = 0, i;
  for (i = 0; i < subs.length; i = i + 1) {
    sum = sum + ((typeof _stComputeMaturity === 'function') ? _stComputeMaturity(subs[i]) : 0);
  }
  return sum / subs.length;
}

// Maturity ramp word (mock .ameta): nascent -> forming -> warming -> mature ->
// bright, derived from the real aggregate. Empty arc reads 'nascent' (was 'seed').
function _arcMaturityWord(arcId) {
  // R-ARC S3: the zero-sub-theory word was 'seed' -- forbidden as a user-facing
  // noun (F1). 'nascent' keeps this CONTENT-maturity spectrum primary (Preston's
  // ruling) without printing the banned word; the EMBER lifecycle lives in a
  // separate chip by the graduate button, not here.
  if (!_arcSubsOf(arcId).length) { return 'nascent'; }
  var m = _arcAggregateMaturity(arcId);
  if (m < 0.2) { return 'forming'; }
  if (m < 0.4) { return 'warming'; }
  if (m < 0.7) { return 'mature'; }
  return 'bright';
}

// "touched <when>": newest real activity = max(arc.createdAt, max sub.updatedAt).
function _arcTouchedWord(arcId, rec) {
  var newest = (rec && rec.createdAt) ? rec.createdAt : 0;
  var subs = _arcSubsOf(arcId);
  var i;
  for (i = 0; i < subs.length; i = i + 1) {
    var u = subs[i].updatedAt || subs[i].createdAt || 0;
    if (u > newest) { newest = u; }
  }
  if (!newest) { return ''; }
  var ago = Date.now() - newest;
  if (ago < 86400000) { return 'touched today'; }
  var d = Math.round(ago / 86400000);
  if (d < 7) { return 'touched ' + d + (d === 1 ? ' day ago' : ' days ago'); }
  if (d < 14) { return 'touched last week'; }
  if (d < 30) { return 'touched ' + Math.round(d / 7) + ' weeks ago'; }
  var mo = Math.round(d / 30);
  return 'touched ' + (mo <= 1 ? 'a month ago' : mo + ' months ago');
}

// Mono meta line (mock .ameta): "N sub-theories · <maturity> · touched <when>".
// Count is real (_arcCardCounts); maturity + touched are derived above.
function _arcCardMeta2El(arcId, rec) {
  var counts = _arcCardCounts(arcId, rec);
  var meta = document.createElement('p');
  meta.className = 'arc-card-meta';
  var parts = [];
  parts.push(counts.subTheories + (counts.subTheories === 1 ? ' sub-theory' : ' sub-theories'));
  parts.push(_arcMaturityWord(arcId));
  var touched = _arcTouchedWord(arcId, rec);
  if (touched) { parts.push(touched); }
  var line = document.createElement('span');
  line.textContent = parts.join(' · ');
  meta.appendChild(line);
  // R5 S5 (D2): a quiet "in the commons" chip on published arc cards (real field).
  // Covenant: quiet recessed meta, never a walk-count badge.
  if (rec && rec.published === true) {
    var chip = document.createElement('span');
    chip.className = 'arc-chip-commons';
    chip.textContent = 'in the commons';
    meta.appendChild(chip);
  }
  return meta;
}

// Per-arc mini-constellation thumb (mock .const). Up to 5 of the arc's sub-theory
// idea-lights via bookSubMarkHTML (the shared PraxisMarks bridge), positioned
// deterministically from each sub's id, threaded with faint curves; each light's
// size + glow scale with its real maturity. Empty arc -> a quiet dark band.
// EXEMPLAR-WASH FIX (R-POLISH B4) · the "Illustrated example" card, illustrated.
//
// The bug, root-caused rather than assumed: the Arcs-index "Arcs to learn from"
// flow card called _arcCardConstellation(null). _arcSubsOf(null) returns [] by its
// first line, so the renderer hit its own !subs.length early-exit and returned a
// bare .arc-const-empty — whose entire paint is one 11px CSS dot at .5 opacity.
// marks.js was NEVER REACHED, so this was never a jewel-token problem and no
// byte-locked file is involved. The card's own label says "Illustrated example"
// while rendering nothing: copy promising what the surface does not deliver.
//
// The fix is caller-side data, per Preston's ruling. This is a FIXED, authored
// arrangement — not random, not hashed, not user data — so the example card looks
// the same on every machine and every visit. Every field the renderer actually
// reads is supplied explicitly (verified by reading its body, not assumed):
//   id                      -> thread key + the stHashIndices fallback
//   x / y                   -> the GR-1 real-placement path (normalised, so any
//                              consistent coordinate space works; 0-100 here)
//   markShape / markColor    -> explicit, so the marks are CHOSEN, never hash-derived
//   evidence[].length        -> _stComputeMaturity, which drives BOTH mark size
//                              (cd 15-28) and opacity (0.5 + 0.5 * maturity)
//   bodyPublic              -> the OTHER half of _stComputeMaturity's raw signal
//                              (views.js:12441). Supplied as '' so the maturity
//                              of each example comes from its evidence count
//                              alone and stays exactly as authored.
// Varying the evidence counts is deliberate: it makes the example show the
// maturity ramp a real arc shows, instead of five identical dots.
function _arcIllustratedSubs() {
  // x/y trace a flowing left-to-right rise — this card is "A Pedagogy of Flow".
  var SPEC = [
    { id: 'ex-flow-1', x: 10, y: 70, shape: 0,  color: 3,  ev: 4  },
    { id: 'ex-flow-2', x: 32, y: 46, shape: 3,  color: 6,  ev: 8  },
    { id: 'ex-flow-3', x: 54, y: 58, shape: 7,  color: 9,  ev: 12 },
    { id: 'ex-flow-4', x: 74, y: 30, shape: 11, color: 4,  ev: 15 },
    { id: 'ex-flow-5', x: 92, y: 44, shape: 14, color: 7,  ev: 17 }
  ];
  var out = [];
  var i, j, ev;
  for (i = 0; i < SPEC.length; i = i + 1) {
    ev = [];
    for (j = 0; j < SPEC[i].ev; j = j + 1) { ev.push({}); }
    out.push({
      id:         SPEC[i].id,
      x:          SPEC[i].x,
      y:          SPEC[i].y,
      markShape:  SPEC[i].shape,
      markColor:  SPEC[i].color,
      evidence:   ev,
      bodyPublic: ''
    });
  }
  return out;
}
// `subsOverride` is the ONLY new behaviour here: when absent (every real call
// site) this function is byte-for-byte the same renderer it was.
function _arcCardConstellation(arcId, subsOverride) {
  var thumb = document.createElement('div');
  thumb.className = 'arc-card-thumb arc-const';
  thumb.setAttribute('aria-hidden', 'true');
  var subs = subsOverride || _arcSubsOf(arcId);
  var usable = (typeof bookSubMarkHTML === 'function' &&
                typeof PraxisMarks !== 'undefined' && PraxisMarks && PraxisMarks.render);
  if (!subs.length || !usable) {
    thumb.className = 'arc-card-thumb arc-const arc-const-empty';
    return thumb;
  }
  var n = subs.length < 5 ? subs.length : 5;
  var pos = [];
  var i, j;

  // GR-1 (R-POLISH B2) · THE LIVING MINIATURE — this thumbnail renders the arc's
  // REAL arrangement.
  //
  // Recon found the gap: this card computed a synthetic position by hashing each
  // sub-theory's id, and ignored the stored sub.x / sub.y that the user actually
  // dragged -- even though that data exists, persists (state.js setSubTheoryPosition)
  // and is read correctly by the field renderer and by Home's card. So two
  // miniatures of the SAME arc disagreed about its shape. GR-1's felt test is
  // "you recognize yours at a glance", which a hash can never satisfy.
  //
  // Stored coords are SVG USER SPACE from the field's viewBox, not percentages, so
  // they are normalised against the bounding box of THIS arc's own placed marks and
  // mapped into the thumb's 0-100 space. Normalising to the arc's own extent (not a
  // fixed viewBox constant) keeps the mapping correct whatever dimensions the field
  // was authored at, and preserves the RELATIVE arrangement -- which is the part a
  // reader recognises.
  //
  // Fallbacks are deliberate: a sub with no placement keeps the old hash slot, and
  // an arc with NO placed marks keeps the entire old layout, so never-arranged arcs
  // look exactly as they do today rather than collapsing onto a point.
  var placed = [];
  for (i = 0; i < n; i = i + 1) {
    if (typeof subs[i].x === 'number' && typeof subs[i].y === 'number') { placed.push(subs[i]); }
  }
  var minX = 0, maxX = 0, minY = 0, maxY = 0, spanX = 0, spanY = 0;
  if (placed.length) {
    minX = maxX = placed[0].x; minY = maxY = placed[0].y;
    for (i = 1; i < placed.length; i = i + 1) {
      if (placed[i].x < minX) { minX = placed[i].x; }
      if (placed[i].x > maxX) { maxX = placed[i].x; }
      if (placed[i].y < minY) { minY = placed[i].y; }
      if (placed[i].y > maxY) { maxY = placed[i].y; }
    }
    spanX = maxX - minX; spanY = maxY - minY;
  }

  for (i = 0; i < n; i = i + 1) {
    var id = subs[i].id || ('s' + i);
    var h = 0;
    for (j = 0; j < id.length; j = j + 1) { h = (h * 31 + id.charCodeAt(j)) >>> 0; }
    var fx = (h % 1000) / 1000;
    var fy = ((h >>> 10) % 1000) / 1000;
    var x, y;
    if (placed.length && typeof subs[i].x === 'number' && typeof subs[i].y === 'number') {
      // real placement -> the thumb's inset band (a single placed mark, or a
      // perfectly flat row/column, centres on its axis rather than dividing by 0)
      x = spanX > 0 ? (12 + ((subs[i].x - minX) / spanX) * 76) : 50;
      y = spanY > 0 ? (20 + ((subs[i].y - minY) / spanY) * 60) : 50;
    } else {
      x = 16 + (n === 1 ? 50 : (i * (68 / (n - 1)))) + (fx * 14 - 7);
      y = 32 + fy * 38;
    }
    if (x < 8) { x = 8; } if (x > 92) { x = 92; }
    if (y < 8) { y = 8; } if (y > 92) { y = 92; }
    var mat = (typeof _stComputeMaturity === 'function') ? _stComputeMaturity(subs[i]) : 0.5;
    pos.push({ x: x, y: y, cd: Math.round(15 + 13 * mat), mat: mat, sub: subs[i] });
  }
  var NS = 'http://www.w3.org/2000/svg';
  var svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '0 0 100 100');
  svg.setAttribute('preserveAspectRatio', 'none');
  svg.setAttribute('class', 'arc-const-threads');
  for (i = 1; i < pos.length; i = i + 1) {
    var p0 = pos[i - 1], p1 = pos[i];
    var path = document.createElementNS(NS, 'path');
    var mx = (p0.x + p1.x) / 2, my = (p0.y + p1.y) / 2 - 8;
    path.setAttribute('d', 'M ' + p0.x + ' ' + p0.y + ' Q ' + mx + ' ' + my + ' ' + p1.x + ' ' + p1.y);
    svg.appendChild(path);
  }
  thumb.appendChild(svg);
  for (i = 0; i < pos.length; i = i + 1) {
    var p = pos[i];
    var light = document.createElement('span');
    light.className = 'arc-light';
    light.style.left = p.x + '%';
    light.style.top = p.y + '%';
    light.style.opacity = String(0.5 + 0.5 * p.mat);
    light.innerHTML = bookSubMarkHTML(p.sub, p.cd);
    thumb.appendChild(light);
  }
  return thumb;
}

// Sort mode (persisted): recent | name | maturity. Bound to real fields only.
var _arcsSortMode = (typeof ls === 'function') ? ls('praxis_arcs_sort', 'recent') : 'recent';

function _arcsSortApply(arr) {
  var m = _arcsSortMode;
  arr.sort(function (a, b) {
    if (m === 'name') {
      var ta = (a.rec.title || '').toLowerCase(), tb = (b.rec.title || '').toLowerCase();
      return ta < tb ? -1 : (ta > tb ? 1 : 0);
    }
    if (m === 'maturity') {
      return _arcAggregateMaturity(b.id) - _arcAggregateMaturity(a.id);
    }
    return (b.rec.createdAt || 0) - (a.rec.createdAt || 0);
  });
  return arr;
}

// Control bar (mock .bar): the Recent/Name/Maturity segmented sort + an "N arcs"
// count. No Published-only toggle -- the arc record has no published flag (DEFERRED).
function _arcsSortBar(count) {
  var bar = document.createElement('div');
  bar.className = 'arcs-bar';
  var seg = document.createElement('div');
  seg.className = 'arcs-seg';
  var modes = [['recent', 'Recent'], ['name', 'Name'], ['maturity', 'Maturity']];
  var i;
  for (i = 0; i < modes.length; i = i + 1) {
    (function (mode, label) {
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'arcs-seg-btn' + (_arcsSortMode === mode ? ' is-on' : '');
      b.textContent = label;
      b.addEventListener('click', function () {
        if (_arcsSortMode === mode) { return; }
        _arcsSortMode = mode;
        if (typeof sv === 'function') { sv('praxis_arcs_sort', mode); }
        renderArcsPage();
      });
      seg.appendChild(b);
    })(modes[i][0], modes[i][1]);
  }
  bar.appendChild(seg);
  var cnt = document.createElement('span');
  cnt.className = 'arcs-count';
  cnt.textContent = count + (count === 1 ? ' arc' : ' arcs');
  bar.appendChild(cnt);
  return bar;
}

function renderArcsPage() {
  var host = document.getElementById(APP_EL_ID);
  if (!host) return;
  host.innerHTML = '';

  // R5 FIX: build the arcId->subs index once for this whole render (O(1) per-card
  // counts/maturity/sort); cleared before return so no other route reads it stale.
  _arcSubsIndex = _buildArcSubsIndex();

  var wrap = document.createElement('section');
  // R5 · Surface C: Universal v1.2 LIGHT skin via Option-B — the route stays in
  // umberGroundDark (body data-ground=dark), and the scoped .arcs.lum-amber-deep
  // block (components.css) re-points the globals the .arcs rules consume to the
  // shared Shelf/Home light set. (Was 'arcs lum-amber' — the dark Wave 7 skin.)
  wrap.className = 'arcs lum-amber-deep';

  // Umber port (surface 3): the mock .arcs-head -- eyebrow + title + teaching.
  // The header "+ Create an arc" button is dropped; create is reached via the
  // dashed start-tile in the grid below (openArcEditor, preserved). The arc
  // editor still mounts into #notebook-arc-editor-host.
  var header = document.createElement('div');
  header.className = 'arcs-head';

  var arcsEyebrow = document.createElement('div');
  arcsEyebrow.className = 'eyebrow';
  arcsEyebrow.textContent = 'Constellations';
  header.appendChild(arcsEyebrow);

  var title = document.createElement('h1');
  title.className = 'arcs-title';
  title.textContent = 'Arcs';
  header.appendChild(title);

  var teaching = document.createElement('p');
  teaching.className = 'arcs-teach';
  teaching.textContent =
    'An arc is a path you build through your reading — ' +
    'books from any tradition, set side by side, so they speak ' +
    'to each other.';
  header.appendChild(teaching);

  wrap.appendChild(header);

  // Editor mount point. openArcEditor mounts into #notebook-arc-editor-host;
  // it stays in the DOM (now below the header, above the grids) so the lookup
  // still resolves after the old two-column create section was removed.
  var arcEditorHost = document.createElement('div');
  arcEditorHost.id = 'notebook-arc-editor-host';
  wrap.appendChild(arcEditorHost);

  // Your arcs: the signed-in user's own arcs (userId === uid), newest
  // first. Excludes the __praxis_seed__ example (it renders in the
  // examples section below). Rendered only when the user has at least one
  // arc; with none, the teaching + examples below stand alone (the cold-
  // start view). Fixes the bug where a user's arcs were counted by the
  // account stat but had no surface on this page.
  var arcsUser = getCurrentUser();
  if (arcsUser) {
    var ownArcs = [];
    var ownArcId;
    for (ownArcId in state.arcs) {
      if (Object.prototype.hasOwnProperty.call(state.arcs, ownArcId)) {
        var ownArcRec = state.arcs[ownArcId];
        if (ownArcRec && ownArcRec.userId === arcsUser.uid) {
          ownArcs.push({ id: ownArcId, rec: ownArcRec });
        }
      }
    }
    _arcsSortApply(ownArcs);
    // Stage 3 (mockup-fidelity): render the "Your arcs" grid for any signed-in
    // user (even with zero arcs) so the dashed "Start another arc" tile always
    // has a home. The page <h1> already says "Your arcs"; the former section
    // h2 of the same text is dropped.
    var yoursHd = document.createElement('div');
    yoursHd.className = 'arcs-section-h';
    var yoursHdH2 = document.createElement('h2');
    yoursHdH2.textContent = 'Your arcs';
    yoursHd.appendChild(yoursHdH2);
    wrap.appendChild(yoursHd);

    // Control bar (mock .bar): Recent/Name/Maturity sort + "N arcs" count.
    wrap.appendChild(_arcsSortBar(ownArcs.length));

    var yoursSec = document.createElement('section');
    yoursSec.className = 'arcs-grid';
    yoursSec.id = 'arcs-yours';

    var yi;
    for (yi = 0; yi < ownArcs.length; yi++) {
      var yCard = document.createElement('a');
      yCard.className = 'arc-card arc-card-live';
      yCard.href = '#arc/' + ownArcs[yi].id;

      yCard.appendChild(_arcCardConstellation(ownArcs[yi].id));

      var yText = document.createElement('div');
      yText.className = 'arc-card-body';

      var yTitle = document.createElement('h3');
      yTitle.className = 'arc-card-title';
      yTitle.textContent = ownArcs[yi].rec.title || 'Untitled arc';
      yText.appendChild(yTitle);

      // Wave 7 C1: mockup arc tiles carry NO description — constellation + title +
      // meta carry the card. Description paragraph removed (was arc-card-desc).

      yCard.appendChild(yText);

      // Meta = real sub-theory count · derived maturity word · touched-when.
      yCard.appendChild(_arcCardMeta2El(ownArcs[yi].id, ownArcs[yi].rec));

      yoursSec.appendChild(yCard);
    }

    // Dashed "Start another arc" create tile as a grid cell (mockup line 175).
    var startTile = document.createElement('button');
    startTile.type = 'button';
    startTile.className = 'arc-card arc-card-start';
    startTile.addEventListener('click', function() {
      openArcEditor();
    });
    var startIcon = document.createElement('span');
    startIcon.className = 'arc-card-start-icon';
    startIcon.setAttribute('aria-hidden', 'true');
    startIcon.innerHTML =
      '<svg width="30" height="30" viewBox="0 0 24 24" fill="none" ' +
      'stroke="currentColor" stroke-width="1.5">' +
      '<circle cx="12" cy="12" r="10"></circle>' +
      '<path d="M12 8v8M8 12h8"></path></svg>';
    startTile.appendChild(startIcon);
    var startLabel = document.createElement('span');
    startLabel.className = 'arc-card-start-label';
    startLabel.textContent = 'Start another arc';
    startTile.appendChild(startLabel);
    yoursSec.appendChild(startTile);

    wrap.appendChild(yoursSec);
  }

  // Stage 5.3 Stage 3b: worked-example cards. Two cards in one section,
  // no parent heading -- the visual contrast (live opaque card with
  // five book covers vs. illustrated muted card with an "Illustrated
  // example" label) does the orienting work that an h2 would. Adding
  // a heading here would compete with the page <h1>Arcs</h1> for
  // attention and break the read-flow: teaching paragraph -> CTA ->
  // examples should feel like one cascading lesson, not three
  // separately-titled sections.
  //
  // The Pedagogy of Desire card reads from state.seeds.pedagogyOfDesire
  // at render time -- never hardcoded ids. Triple guard: missing seeds
  // map, missing pedagogyOfDesire entry, OR missing arc record all
  // skip the card cleanly rather than render a broken element. The
  // arc record can be legitimately absent if a signed-in user deletes
  // the seed via the arc-detail Delete button (Stage 0 design: stays
  // deleted; the page is intentionally degraded after delete).
  //
  // The Pedagogy of Flow card has NO seeded data -- it's an illustrated
  // example, deliberately not a real arc (design-system v2 Part C3:
  // "One live, one illustrated: shows the range of what an arc can
  // be without seeding two."). Rendered as <div>, not <a>, so it
  // carries no click target. The "Illustrated example" label and
  // the lighter CSS treatment carry the meaning.
  var examplesHd = document.createElement('div');
  examplesHd.className = 'arcs-section-h';
  var examplesHdH2 = document.createElement('h2');
  examplesHdH2.textContent = 'Arcs to learn from';
  examplesHd.appendChild(examplesHdH2);
  var examplesHdEy = document.createElement('span');
  examplesHdEy.className = 'eyebrow';
  examplesHdEy.textContent = 'examples';
  examplesHd.appendChild(examplesHdEy);
  wrap.appendChild(examplesHd);

  var examplesSec = document.createElement('section');
  examplesSec.className = 'arcs-grid';
  examplesSec.id = 'arcs-examples';

  var seedInfo = state.seeds && state.seeds.pedagogyOfDesire;
  var seedArc = seedInfo &&
                seedInfo.arcId &&
                state.arcs &&
                state.arcs[seedInfo.arcId];
  if (seedArc) {
    var desireCard = document.createElement('a');
    desireCard.className = 'arc-card arc-card-live';
    desireCard.href = '#arc/' + seedInfo.arcId;

    desireCard.appendChild(_arcCardConstellation(seedInfo.arcId));

    var desireText = document.createElement('div');
    desireText.className = 'arc-card-body';

    var desireTitle = document.createElement('h3');
    desireTitle.className = 'arc-card-title';
    desireTitle.textContent = seedArc.title || 'A Pedagogy of Desire';
    desireText.appendChild(desireTitle);

    // Wave 7 C1: no description on the arc tile (mockup-exact) — the seed example
    // card matches the real arc cards: constellation + title + meta.

    desireCard.appendChild(desireText);

    // Meta = real sub-theory count · derived maturity word · touched-when.
    desireCard.appendChild(_arcCardMeta2El(seedInfo.arcId, seedArc));

    examplesSec.appendChild(desireCard);
  }

  var flowCard = document.createElement('div');
  flowCard.className = 'arc-card arc-card-illustrated';

  // EXEMPLAR-WASH FIX (B4): was _arcCardConstellation(null), which rendered the
  // empty-state dot and made "Illustrated example" a promise the card broke.
  flowCard.appendChild(_arcCardConstellation(null, _arcIllustratedSubs()));

  var flowLabel = document.createElement('span');
  flowLabel.className = 'arc-card-label';
  flowLabel.textContent = 'Illustrated example';
  flowCard.appendChild(flowLabel);

  var flowText = document.createElement('div');
  flowText.className = 'arc-card-body';

  var flowTitle = document.createElement('h3');
  flowTitle.className = 'arc-card-title';
  flowTitle.textContent = 'A Pedagogy of Flow';
  flowText.appendChild(flowTitle);

  // Wave 7 C1: the illustrated example card is ON the Arcs page too, so its
  // description is removed as well — the whole page is title-only per the mockup.

  flowCard.appendChild(flowText);
  examplesSec.appendChild(flowCard);

  wrap.appendChild(examplesSec);

  // OG3: a signed-out visitor exploring the public example arcs is the best
  // conversion moment -- give it a real Sign-in CTA (the "Your arcs" block above
  // is skipped when signed out, so without this the page asks for nothing).
  if (!arcsUser) {
    wrap.appendChild(buildSignedOutPrompt(
      'Build your own arc',
      'These are examples — arcs anyone can learn from. Sign in to start your own: set books side by side and draw the threads between them.'));
  }

  _arcSubsIndex = null; // R5 FIX: release the per-render index
  host.appendChild(wrap);
}

// Theme taxonomy mirror of docs/themes.md (locked 2026-05-15).
// COUNT = 15. File order is authoritative -- DO NOT alphabetize or
// reorder. If docs/themes.md ever changes, this array changes with
// it (same number of entries, same labels, same order). The sidebar
// filter list in renderShelf reads exclusively from this array;
// docs/themes.md cannot be loaded at runtime in the browser, so this
// is the in-code mirror of that authoritative source. Stage 3.10a
// Stage 2 surfaces these as inert text rows; filter behavior is
// 3.10b.
var SHELF_THEMES = [
  'Philosophy & wisdom',
  'Critical theory & pedagogy',
  'Power & systems',
  'Political economy & society',
  'Mind & behavior',
  'History & memory',
  'Liberation',
  'Love & connection',
  'Grief & witness',
  'Joy & wonder',
  'Faith & meaning',
  'Place & belonging',
  'Nature & ecology',
  'Story & imagination',
  'Craft & practice'
];

// Stage 3.5a: the Books shelf surface. Reads from state.books and
// renders one row per record, newest first by addedAt. No filtering,
// no add-book affordance, no editor in this sub-stage -- those land
// in later 3.5a sub-stages. Each row links to #book/<id> via an
// anchor so click-through hits renderBookDetail through the router.
function renderShelf() {
  var host = document.getElementById(APP_EL_ID);
  if (!host) return;
  host.innerHTML = '';

  // 3.10b-i: purge any stale Escape handler from a previous render.
  // The fresh render replaces the sidebar; the old handler closed
  // over the now-detached old sidebar/backdrop pair. Without this,
  // an Escape press between an auto-close (filter-click re-render)
  // and the next open would no-op on the detached old sidebar and
  // leak a listener. The open/dismiss path below rebinds cleanly.
  if (shelfSidebarEscapeHandler) {
    document.removeEventListener('keydown', shelfSidebarEscapeHandler);
    shelfSidebarEscapeHandler = null;
  }

  // MW-1 (P1): purge any stale Manage-sheet Escape handler and release a page
  // scroll-lock left behind if the sheet was open when a control inside it
  // re-rendered the shelf (e.g. Covers/List, Select). The fresh render rebuilds
  // the sheet closed; this is the twin of the filter-drawer cleanup above.
  if (shelfManageEscapeHandler) {
    document.removeEventListener('keydown', shelfManageEscapeHandler);
    shelfManageEscapeHandler = null;
  }
  document.body.style.overflow = '';
  // MW-1 (P5): purge the stale sticky-title scroll listener; it closed over the
  // now-detached old head. Rebound below after the fresh head is built.
  if (shelfHeadScrollHandler) {
    window.removeEventListener('scroll', shelfHeadScrollHandler);
    shelfHeadScrollHandler = null;
  }

  var wrap = document.createElement('section');
  // Wave 1: convert the Shelf to the Amber/Lumen system. The atmosphere class
  // supplies the deep-amber "reading room" ground (lumen-amber.css:16); the
  // .shelf.lum-amber-deep block in components.css layers lumen glass/gold/cyan
  // over the theme-token base (same additive pattern as the Notebook).
  wrap.className = 'shelf lum-amber-deep' + (shelfSelecting ? ' is-selecting' : '');

  // W11 S8 Lane 1 (L3): your shelf is personal -- hard-gate signed-out (mirror
  // #notebook: in-place prompt, no redirect). Replaces the prior soft-CTA
  // (the signed-out "Sign in to add books" toolbar/empty branches, now removed).
  var shelfGateUser = getCurrentUser();
  if (!shelfGateUser || !shelfGateUser.uid) {
    wrap.appendChild(buildSignedOutPrompt('Your shelf is private', 'Sign in to build your shelf — scan a spine, search a title, or paste a whole list. Your library is yours.'));
    host.appendChild(wrap);
    return;
  }

  // Head (mock .shelf-head): "Your shelf" + a mono count line. The count is
  // display-only aggregation (books · reading · finished) filling the mock's
  // "N books · R reading · F finished" format with real data.
  var head = document.createElement('div');
  head.className = 'shelf-head';

  var title = document.createElement('h1');
  title.className = 'shelf-title';
  title.textContent = 'Your shelf';
  head.appendChild(title);

  // FIX D: the shelf renders the signed-in user's bookIds INDEX, not all of
  // state.books. state.books can hold orphan/duplicate records (added but never
  // indexed, or whose index entry was lost) that are NOT on the shelf -- reading
  // state.books showed them as duplicates with divergent read-status. Signed out
  // keeps the legacy state.books read (seed / cached demo). shelfBookIds is
  // reused by the grid assembly below.
  var shelfUserForList = getCurrentUser();
  var shelfBookIds = (shelfUserForList && state.userBooks &&
                      state.userBooks[shelfUserForList.uid] &&
                      state.userBooks[shelfUserForList.uid].bookIds)
    ? state.userBooks[shelfUserForList.uid].bookIds : null;
  var sbcMap = state.books || {};
  var shelfBookCount = 0;
  var shelfReadingCount = 0;
  var shelfFinishedCount = 0;
  var sbcId;
  var sbRec;
  var sbSt;
  if (shelfBookIds) {
    for (sbcId = 0; sbcId < shelfBookIds.length; sbcId = sbcId + 1) {
      sbRec = sbcMap[shelfBookIds[sbcId]];
      if (sbRec) {
        shelfBookCount++;
        sbSt = normalizeStatus(sbRec.status);
        if (sbSt === 'read') { shelfFinishedCount++; }
        else if (sbSt === 'reading') { shelfReadingCount++; }
      }
    }
  } else {
    for (sbcId in sbcMap) {
      if (Object.prototype.hasOwnProperty.call(sbcMap, sbcId) && sbcMap[sbcId]) {
        sbRec = sbcMap[sbcId];
        shelfBookCount++;
        sbSt = normalizeStatus(sbRec.status);
        if (sbSt === 'read') { shelfFinishedCount++; }
        else if (sbSt === 'reading') { shelfReadingCount++; }
      }
    }
  }
  var countEl = document.createElement('span');
  countEl.className = 'shelf-count';
  countEl.textContent = shelfBookCount + (shelfBookCount === 1 ? ' book' : ' books')
    + ' · ' + shelfReadingCount + ' reading · ' + shelfFinishedCount + ' finished';
  head.appendChild(countEl);

  wrap.appendChild(head);

  // MW-1 (P5): sticky-title compaction. A threshold-guarded window scroll listener
  // toggles .is-stuck on the head (CSS at <=759 steps font-size + padding; a no-op
  // at >=760 where no .is-stuck rule exists). Purged + rebound each render (above).
  shelfHeadScrollHandler = function () {
    var y = window.pageYOffset || document.documentElement.scrollTop || 0;
    if (y > 6) { head.classList.add('is-stuck'); }
    else { head.classList.remove('is-stuck'); }
  };
  window.addEventListener('scroll', shelfHeadScrollHandler);
  shelfHeadScrollHandler();   // set the initial state for an already-scrolled re-render

  // S-D1 (Wave 1): a deterministic, count-based reading line in Yumi's cyan
  // voice -- NOT generative (no model call, no interpretive "leans toward").
  // Text is filled from the real top lens once the lens tally is computed
  // below; hidden entirely when no lens has books (never fabricated).
  var shelfLean = document.createElement('div');
  shelfLean.className = 'lum-yumi shelf-yumiline';
  shelfLean.style.display = 'none';
  var shelfLeanDot = document.createElement('span');
  shelfLeanDot.className = 'dot';
  shelfLeanDot.setAttribute('aria-hidden', 'true');
  var shelfLeanP = document.createElement('p');
  shelfLean.appendChild(shelfLeanDot);
  shelfLean.appendChild(shelfLeanP);
  wrap.appendChild(shelfLean);

  // Toolbar (mock .shelf-toolbar, canon §4-E declutter): one primary "Add a
  // book" + the Covers|List segmented + a quiet "Filters" toggle + spacer +
  // quiet chips for the secondary actions + the search. All live handlers and
  // both photo paths (camera scan + barcode) are preserved -- only the visual
  // grouping changes (header child -> a single decluttered toolbar).
  var toolbar = document.createElement('div');
  toolbar.className = 'shelf-toolbar';

  var user = getCurrentUser();

  // MW-1 P1 (ON-2 REFERENCE IMPLEMENTATION): one "Manage" control at every
  // viewport. The always-visible toolbar keeps Add-a-book + Sort + Filters +
  // the filter field; the seven secondary controls (Covers|List, Select, Scan
  // shelf, Scan barcode, Bulk add, Resolve covers, Tidy library) move into this
  // Manage container -- a bottom SHEET at <=759, an anchored POPOVER >=760, ONE
  // code path (CSS differentiates by width). Those controls are appended into
  // manageBody AS THEY ARE CREATED below, so their live handlers ride with the
  // elements untouched (the W3 relocate-without-rewire lesson). Universal tokens
  // only; solid chrome, no blur (canon rail A). Focus moves in on open and
  // returns to the trigger on close; the page scroll locks while the sheet is
  // open on mobile.
  var manageWrap = document.createElement('div');
  manageWrap.className = 'shelf-manage';

  var manageBtn = document.createElement('button');
  manageBtn.type = 'button';
  manageBtn.className = 'btn btn-quiet shelf-manage-btn';
  manageBtn.setAttribute('aria-haspopup', 'true');
  manageBtn.setAttribute('aria-expanded', 'false');
  manageBtn.textContent = 'Manage';

  var manageBackdrop = document.createElement('div');
  manageBackdrop.className = 'shelf-manage-backdrop';

  var manageSheet = document.createElement('div');
  manageSheet.className = 'shelf-manage-sheet';
  manageSheet.setAttribute('role', 'dialog');
  manageSheet.setAttribute('aria-modal', 'false');
  manageSheet.setAttribute('aria-label', 'Manage shelf');

  var manageHead = document.createElement('div');
  manageHead.className = 'shelf-manage-head';
  var manageTitle = document.createElement('span');
  manageTitle.className = 'shelf-manage-title';
  manageTitle.textContent = 'Manage shelf';
  manageHead.appendChild(manageTitle);
  var manageClose = document.createElement('button');
  manageClose.type = 'button';
  manageClose.className = 'shelf-manage-close';
  manageClose.setAttribute('aria-label', 'Close');
  manageClose.textContent = '×';
  manageHead.appendChild(manageClose);
  manageSheet.appendChild(manageHead);

  var manageBody = document.createElement('div');
  manageBody.className = 'shelf-manage-body';
  manageSheet.appendChild(manageBody);

  manageWrap.appendChild(manageBtn);
  manageWrap.appendChild(manageBackdrop);
  manageWrap.appendChild(manageSheet);

  function openManageSheet() {
    manageWrap.classList.add('is-open');
    manageBtn.setAttribute('aria-expanded', 'true');
    // Lock the page scroll only for the mobile bottom sheet (the desktop
    // popover leaves the page scrollable, as popovers do). The mobile sheet is
    // effectively modal (scrim + scroll-lock + focus-in) so aria-modal tracks it.
    if (window.matchMedia('(max-width: 759px)').matches) {
      document.body.style.overflow = 'hidden';
      manageSheet.setAttribute('aria-modal', 'true');
    } else {
      manageSheet.setAttribute('aria-modal', 'false');
    }
    if (shelfManageEscapeHandler) {
      document.removeEventListener('keydown', shelfManageEscapeHandler);
    }
    shelfManageEscapeHandler = function (ev) {
      if (ev.key === 'Escape' || ev.key === 'Esc') { closeManageSheet(); }
    };
    document.addEventListener('keydown', shelfManageEscapeHandler);
    manageClose.focus();
  }
  function closeManageSheet() {
    manageWrap.classList.remove('is-open');
    manageBtn.setAttribute('aria-expanded', 'false');
    manageSheet.setAttribute('aria-modal', 'false');
    document.body.style.overflow = '';
    if (shelfManageEscapeHandler) {
      document.removeEventListener('keydown', shelfManageEscapeHandler);
      shelfManageEscapeHandler = null;
    }
    manageBtn.focus();
  }
  manageBtn.addEventListener('click', function () {
    if (manageWrap.classList.contains('is-open')) { closeManageSheet(); }
    else { openManageSheet(); }
  });
  manageBackdrop.addEventListener('click', closeManageSheet);
  manageClose.addEventListener('click', closeManageSheet);

  // Primary: signed-in "Add a book" (opens the inline editor). Signed-out never
  // reaches here -- the top-of-function hard-gate returns first (W11 S8 Lane 1).
  // .shelf-add-primary marks it for the P2 mobile thumb-zone relocation (CSS).
  var newBtn = document.createElement('button');
  newBtn.type = 'button';
  newBtn.className = 'btn btn-primary shelf-add-primary';
  newBtn.textContent = '＋ Add a book';
  newBtn.addEventListener('click', function() {
    openShelfEditor();
  });
  toolbar.appendChild(newBtn);

  // Covers | List segmented (mock .seg). LIVE handlers preserved.
  var shelfViewMode = getShelfView();
  var seg = document.createElement('div');
  seg.className = 'seg';
  seg.setAttribute('role', 'tablist');
  seg.setAttribute('aria-label', 'Shelf view');
  var segCovers = document.createElement('button');
  segCovers.type = 'button';
  segCovers.className = 'seg-opt' + (shelfViewMode === 'covers' ? ' is-on' : '');
  segCovers.setAttribute('data-shelf-view', 'covers');
  segCovers.textContent = 'Covers';
  segCovers.addEventListener('click', function() {
    setShelfView('covers');
    renderShelf();
  });
  seg.appendChild(segCovers);
  var segList = document.createElement('button');
  segList.type = 'button';
  segList.className = 'seg-opt' + (shelfViewMode === 'list' ? ' is-on' : '');
  segList.setAttribute('data-shelf-view', 'list');
  segList.textContent = 'List';
  segList.addEventListener('click', function() {
    setShelfView('list');
    renderShelf();
  });
  seg.appendChild(segList);
  manageBody.appendChild(seg);   // MW-1 P1: Covers|List lives in the Manage sheet

  // 3c (R2): Sort control (decision 4). Quiet dropdown -- date-added default +
  // reading status. Grouping is NOT duplicated here (it stays on the sidebar
  // Lenses|Categories seg). Applies via the shelfSort branch in books.sort above.
  var sortWrap = document.createElement('div');
  sortWrap.className = 'shelf-sort';
  var sortBtn = document.createElement('button');
  sortBtn.type = 'button';
  sortBtn.className = 'shelf-sort-btn';
  sortBtn.id = 'shelf-sort-btn';
  sortBtn.appendChild(document.createTextNode('Sort: '));
  var sortLabel = document.createElement('span');
  sortLabel.textContent = (shelfSort === 'status') ? 'Reading status' : 'Date added';
  sortBtn.appendChild(sortLabel);
  var sortCaret = document.createElement('span');
  sortCaret.className = 'caret';
  sortCaret.textContent = '▼';
  sortBtn.appendChild(sortCaret);
  var sortMenu = document.createElement('div');
  sortMenu.className = 'shelf-sort-menu';
  sortBtn.addEventListener('click', function (ev) {
    ev.stopPropagation();
    if (sortMenu.className.indexOf('is-open') > -1) {
      sortMenu.className = 'shelf-sort-menu';
    } else {
      sortMenu.className = 'shelf-sort-menu is-open';
      var closeOnce = function () {
        sortMenu.className = 'shelf-sort-menu';
        document.removeEventListener('click', closeOnce);
      };
      document.addEventListener('click', closeOnce);
    }
  });
  var SORT_OPTS = [ { key: 'added', label: 'Date added' }, { key: 'status', label: 'Reading status' } ];
  var soi;
  for (soi = 0; soi < SORT_OPTS.length; soi = soi + 1) {
    (function (opt) {
      var ob = document.createElement('button');
      ob.type = 'button';
      ob.className = (shelfSort === opt.key) ? 'is-on' : '';
      ob.setAttribute('data-sort', opt.key);
      ob.textContent = opt.label;
      ob.addEventListener('click', function () {
        shelfSort = opt.key;
        renderShelf();
      });
      sortMenu.appendChild(ob);
    })(SORT_OPTS[soi]);
  }
  sortWrap.appendChild(sortBtn);
  sortWrap.appendChild(sortMenu);
  toolbar.appendChild(sortWrap);

  // 3b (R2): Select toggle (decision 2). Arms bulk Select mode; its ONLY action
  // is Move to arc (the action bar below). A quiet chip; is-armed when on.
  var selectBtn = document.createElement('button');
  selectBtn.type = 'button';
  selectBtn.className = 'btn chip shelf-select-toggle' + (shelfSelecting ? ' is-armed' : '');
  selectBtn.textContent = shelfSelecting ? 'Done' : 'Select';
  selectBtn.addEventListener('click', function () {
    shelfSelecting = !shelfSelecting;
    if (!shelfSelecting) { shelfPicked = {}; }
    renderShelf();
  });
  manageBody.appendChild(selectBtn);   // MW-1 P1: Select lives in the Manage sheet

  // Filters toggle (mock .shelf-filters-btn). Desktop-hidden by CSS (the
  // sidebar is always visible there); on mobile it opens the filter drawer.
  // The handler references sidebar / backdrop / the panel fns + shelfRailOpen,
  // all assigned later in this render -- closures resolve at click time.
  var filterBtn = document.createElement('button');
  filterBtn.type = 'button';
  filterBtn.id = 'shelf-filters-btn';
  filterBtn.className = 'btn btn-quiet shelf-filters-btn';
  filterBtn.textContent = 'Filters';
  filterBtn.addEventListener('click', function() {
    if (window.matchMedia('(min-width: 760px)').matches) {
      shelfRailOpen = !shelfRailOpen;
      renderShelf();
    } else if (sidebar.classList.contains('shelf-sidebar-mobile-open')) {
      dismissShelfFilterPanel();
    } else {
      openShelfFilterPanel();
    }
  });
  toolbar.appendChild(filterBtn);

  // MW-1 P1: the Manage trigger + its sheet/popover sit right after Filters,
  // visible at every viewport. The seven secondary controls were appended into
  // manageSheet's body above/below at their creation sites.
  toolbar.appendChild(manageWrap);

  var toolbarSpacer = document.createElement('span');
  toolbarSpacer.className = 'spacer';
  toolbar.appendChild(toolbarSpacer);

  // Secondary actions -> quiet chips (signed-in only). All live handlers + both
  // photo capture paths (camera scan + barcode) preserved.
  if (user) {
    // 6.1b: shelf-photo scan (camera capture -> vision-proxy).
    var scanBtn = document.createElement('button');
    scanBtn.type = 'button';
    scanBtn.className = 'chip shelf-scan-btn';
    scanBtn.textContent = 'Scan shelf';
    scanBtn.title = 'Photograph one shelf at a time, filling the frame';
    var scanInput = document.createElement('input');
    scanInput.type = 'file';
    scanInput.accept = 'image/*';
    scanInput.setAttribute('capture', 'environment');
    scanInput.className = 'shelf-scan-input';
    scanBtn.addEventListener('click', function() {
      scanInput.click();
    });
    scanInput.addEventListener('change', function() {
      handleShelfScanFile(scanInput, scanBtn);
    });
    manageBody.appendChild(scanBtn);    // MW-1 P1: Scan shelf -> Manage sheet
    manageBody.appendChild(scanInput);

    // Phase 3: barcode / ISBN entry point (BarcodeDetector + ISBN fallback).
    var barcodeBtn = document.createElement('button');
    barcodeBtn.type = 'button';
    barcodeBtn.className = 'chip shelf-barcode-btn';
    barcodeBtn.textContent = 'Scan barcode';
    barcodeBtn.addEventListener('click', function() {
      openBarcodeScanner();
    });
    manageBody.appendChild(barcodeBtn);   // MW-1 P1: Scan barcode -> Manage sheet

    var bulkBtn = document.createElement('button');
    bulkBtn.type = 'button';
    bulkBtn.className = 'chip shelf-new-book-bulk';
    bulkBtn.textContent = 'Bulk add';
    bulkBtn.addEventListener('click', function() {
      openBulkAddEditor();
    });
    manageBody.appendChild(bulkBtn);   // MW-1 P1: Bulk add -> Manage sheet

    // 3.10d: resolve missing covers (title-imported books). Running-state label
    // + disabled read from coverResolveState (lives outside the DOM).
    var resolveBtn = document.createElement('button');
    resolveBtn.type = 'button';
    resolveBtn.className = 'chip shelf-resolve-covers-btn';
    if (coverResolveState.running) {
      resolveBtn.textContent = 'Resolving ' +
        coverResolveState.completed + ' of ' + coverResolveState.total;
      resolveBtn.disabled = true;
    } else {
      resolveBtn.textContent = 'Resolve covers';
    }
    resolveBtn.addEventListener('click', function() {
      startCoverBackfill();
    });
    manageBody.appendChild(resolveBtn);   // MW-1 P1: Resolve covers -> Manage sheet

    // Phase 6: one-time library cleanup (de-dupe + missing covers).
    var tidyBtn = document.createElement('button');
    tidyBtn.type = 'button';
    tidyBtn.className = 'chip shelf-tidy-btn';
    tidyBtn.textContent = 'Tidy library';
    tidyBtn.addEventListener('click', function() {
      openLibraryCleanup();
    });
    manageBody.appendChild(tidyBtn);   // MW-1 P1: Tidy library -> Manage sheet
  }

  // Search (mock .nav-search): a LIVE grid filter (title OR author substring).
  var searchWell = document.createElement('div');
  searchWell.className = 'nav-search shelf-search-well';
  var searchGlyph = document.createElement('span');
  searchGlyph.setAttribute('aria-hidden', 'true');
  searchGlyph.textContent = '⌕';
  searchWell.appendChild(searchGlyph);
  var searchInput = document.createElement('input');
  searchInput.id = 'shelf-search-input';
  searchInput.className = 'shelf-search-input';
  searchInput.type = 'search';
  searchInput.setAttribute('inputmode', 'search');   // MW-1 P7: non-prose field hint
  searchInput.setAttribute('placeholder', 'Filter shelf…');
  searchInput.setAttribute('aria-label', 'Filter shelf');
  searchInput.value = shelfSearchRaw;
  searchInput.addEventListener('input', onShelfSearchInput);
  searchWell.appendChild(searchInput);
  toolbar.appendChild(searchWell);

  wrap.appendChild(toolbar);

  // 6.1c: visible scan status line (empty/error messaging). Collapsed when
  // empty (:empty in CSS). Filled/cleared by showScanStatus/clearScanStatus.
  var scanStatus = document.createElement('div');
  scanStatus.className = 'shelf-scan-status';
  scanStatus.id = 'shelf-scan-status';
  wrap.appendChild(scanStatus);

  // Stage 2 (mockup-fidelity): the in-page shelf search (a LIVE GRID FILTER,
  // title OR author substring) now lives inline in the header actions cluster
  // above -- it is no longer a separate well below the header.

  // 3.10a Stage 2: two-column layout below the full-width header.
  // .shelf-layout holds .shelf-sidebar (left, 220px, transparent --
  // dissolves into the page, not a card) and .shelf-main (right,
  // flex-fills). The editor host moves inside .shelf-main so it sits
  // above the grid in the right column; getElementById lookups in
  // openShelfEditor / processBulkLines are position-independent
  // (Q1 grep 2026-05-16 confirmed zero dependencies on the previous
  // direct-child-of-.shelf position).
  //
  // SIDEBAR IS INERT IN STAGE 2. The theme + author rows render but
  // do nothing on click; filter behavior is 3.10b. No event listeners
  // are attached anywhere in this block, no checkboxes wired to
  // anything, no selected-state field on state.*.

  var booksMap = state.books || {};

  // CX-3 (orphan-safe author rail): count authors over the SAME deduped shelf set
  // the grid renders (shelfBookIds), not raw state.books -- else an orphan/
  // duplicate record inflates an author count that yields ZERO cards when clicked
  // ("rendered count == stored count" violation, books.md:179). Mirrors the
  // lenses / reading-status / category rails, which were reworked to the deduped
  // set; the author rail was the one sibling that block missed.
  var authorSrc = [];
  var asI;
  if (shelfBookIds) {
    for (asI = 0; asI < shelfBookIds.length; asI = asI + 1) {
      if (booksMap[shelfBookIds[asI]]) { authorSrc.push(booksMap[shelfBookIds[asI]]); }
    }
  } else {
    for (asI in booksMap) {
      if (Object.prototype.hasOwnProperty.call(booksMap, asI) && booksMap[asI]) { authorSrc.push(booksMap[asI]); }
    }
  }

  // Author dedupe + alphabetic sort for the sidebar's "Filter by author" section.
  var authorSeen = {};
  var authors = [];
  var abi;
  var abk;
  for (abi = 0; abi < authorSrc.length; abi = abi + 1) {
    abk = authorSrc[abi];
    if (abk && abk.author &&
        !Object.prototype.hasOwnProperty.call(authorSeen, abk.author)) {
      authorSeen[abk.author] = true;
      authors.push(abk.author);
    }
  }
  // Phase 3.1: per-value book-match tally for the author filter counts, over the
  // SAME deduped set (CX-3). Rows with zero matches still show (count 0).
  var authorCounts = {};
  var tci;
  var tcb;
  for (tci = 0; tci < authorSrc.length; tci = tci + 1) {
    tcb = authorSrc[tci];
    if (!tcb) continue;
    if (typeof tcb.author === 'string' && tcb.author.length > 0) {
      authorCounts[tcb.author] = (authorCounts[tcb.author] || 0) + 1;
    }
  }

  // Stage 4d: rank authors by book count (desc), case-insensitive
  // alpha tiebreak, and collapse the rail to the top 12 unless the
  // user expanded it (shelfAuthorRailExpanded). The toggle row at the
  // bottom of the list flips the flag and re-renders.
  authors.sort(function (a, b) {
    var ca = authorCounts[a] || 0;
    var cb = authorCounts[b] || 0;
    if (cb !== ca) { return cb - ca; }
    var la = a.toLowerCase();
    var lb = b.toLowerCase();
    if (la < lb) { return -1; }
    if (la > lb) { return 1; }
    return 0;
  });
  var totalAuthorCount = authors.length;
  var visibleAuthors = shelfAuthorRailExpanded
    ? authors
    : authors.slice(0, 12);

  // Lenses (S3): baseline lenses are the DISTINCT book.genre values actually
  // present, counted off the DEDUPED membership source -- the signed-in user's
  // bookIds index (shelfBookIds), or raw state.books when signed out. Reading
  // the deduped set means orphan/duplicate records never inflate a lens count
  // (retires the old genre-count-over-state.books inflation). lensOrder keeps
  // first-seen genres, then is re-sorted by count (desc) for a stable render.
  var lensCounts = {};
  var lensOrder = [];
  var lcArr = [];
  var lcId;
  var lcb;
  if (shelfBookIds) {
    for (lcId = 0; lcId < shelfBookIds.length; lcId = lcId + 1) {
      lcArr.push(sbcMap[shelfBookIds[lcId]]);
    }
  } else {
    for (lcId in sbcMap) {
      if (Object.prototype.hasOwnProperty.call(sbcMap, lcId)) {
        lcArr.push(sbcMap[lcId]);
      }
    }
  }
  var lcj;
  for (lcj = 0; lcj < lcArr.length; lcj = lcj + 1) {
    lcb = lcArr[lcj];
    if (lcb && typeof lcb.genre === 'string' && lcb.genre.length > 0) {
      if (!Object.prototype.hasOwnProperty.call(lensCounts, lcb.genre)) {
        lensOrder.push(lcb.genre);
      }
      lensCounts[lcb.genre] = (lensCounts[lcb.genre] || 0) + 1;
    }
  }
  lensOrder.sort(function (a, b) {
    var ca = lensCounts[a] || 0;
    var cb = lensCounts[b] || 0;
    if (cb !== ca) { return cb - ca; }
    var la = a.toLowerCase();
    var lb = b.toLowerCase();
    if (la < lb) { return -1; }
    if (la > lb) { return 1; }
    return 0;
  });

  // S-D1 (Wave 1): fill the reading line from the real top lens (deterministic,
  // count-based). lensOrder is already sorted by count desc, so [0] is the
  // most-shelved lens. Omit the line entirely when there is no lens.
  if (lensOrder.length > 0) {
    var shelfTopLens = lensOrder[0];
    var shelfTopLensN = lensCounts[shelfTopLens] || 0;
    shelfLeanP.textContent = 'Most-shelved lens: ' + shelfTopLens + ' · ' +
      shelfTopLensN + (shelfTopLensN === 1 ? ' book' : ' books');
    shelfLean.style.display = '';
  }

  // Status + Tradition rails (Umber port — mock #s-books groups 1+2). Distinct
  // canonical statuses + traditions present in the SAME deduped shelf set
  // (lcArr) the lenses are counted over, so counts are orphan-free. Values are
  // the real canon: normalizeStatus(book.status) -> reading/read/will-read, and
  // (book.traditionOverride || book.tradition) over the TRADITIONS set (the
  // 'unassigned' sentinel + empties are skipped, like the empty-genre skip).
  // No new filter idiom: the rows reuse .shelf-filter + the shared
  // onShelfFilterRowClick/Keydown + the generic toggleShelfFilter (whose for-in
  // exclusive-clear already covers the two new sections).
  var statusCounts = { reading: 0, read: 0, 'will-read': 0 };
  var srti;
  var srtb;
  for (srti = 0; srti < lcArr.length; srti = srti + 1) {
    srtb = lcArr[srti];
    if (!srtb) { continue; }
    statusCounts[normalizeStatus(srtb.status)]++;
  }

  var layout = document.createElement('div');
  // Mock: the sidebar is always visible on desktop (2-col grid) and a drawer on
  // mobile (toggled by the Filters button). shelfRailOpen is retired on desktop.
  layout.className = 'shelf-layout';

  var sidebar = document.createElement('aside');
  sidebar.className = 'shelf-side';

  // 3.10b-i: backdrop — sibling of sidebar inside .shelf-layout
  // (appended below after both are populated). Class .shelf-sidebar-
  // backdrop; default-hidden by CSS, revealed by toggling .shelf-
  // sidebar-backdrop-open in lockstep with .shelf-sidebar-mobile-open.
  var backdrop = document.createElement('div');
  backdrop.className = 'shelf-sidebar-backdrop';

  // 3.10b-i: close affordance. First child of the sidebar so source-
  // order tab focus lands on it when the panel opens — gives keyboard
  // users an immediate dismiss path. Mobile-only via CSS display
  // gate (the desktop sidebar has no panel chrome). The aria-label
  // carries semantics for screen readers; the visible glyph is ×
  // (U+00D7 multiplication sign).
  var closeBtn = document.createElement('button');
  closeBtn.type = 'button';
  closeBtn.className = 'shelf-sidebar-close';
  closeBtn.setAttribute('aria-label', 'Close filters');
  closeBtn.textContent = '×';
  sidebar.appendChild(closeBtn);

  // userThemes (manual lenses, S3): the user-created lenses, rendered in the
  // unified Lenses rail below alongside the baseline (genre) lenses. Filter
  // rows read shelfFilter.theme (a theme id); membership is
  // state.userThemes[id].bookIds (off the book record) -- counts are orphan-free.
  var utUser = getCurrentUser();
  var userThemeList = [];
  var uttk;
  if (utUser && utUser.uid && state.userThemes) {
    for (uttk in state.userThemes) {
      if (Object.prototype.hasOwnProperty.call(state.userThemes, uttk) &&
          state.userThemes[uttk] && state.userThemes[uttk].userId === utUser.uid) {
        userThemeList.push(state.userThemes[uttk]);
      }
    }
  }
  userThemeList.sort(function(a, b) {
    return (a.name || '').localeCompare(b.name || '');
  });
  // Lenses (S3): ONE rail unifying the data-driven baseline lenses (distinct
  // book.genre values present, deduped counts) and the user's hand-made lenses
  // (state.userThemes). Both render as identical .shelf-filter-row items and
  // share the existing single-select toggle: a baseline row carries
  // data-filter-section="genre", a manual row data-filter-section="theme", so
  // the same handlers + match predicate apply with NO filter-machinery change.
  var lensSection = document.createElement('div');
  lensSection.className = 'shelf-filter-group shelf-filter-group-lenses';
  var lensLabel = document.createElement('h3');
  lensLabel.className = 'shelf-filter-label';
  lensLabel.textContent = 'Lenses';
  lensSection.appendChild(lensLabel);
  var lensListEl = document.createElement('ul');
  lensListEl.className = 'shelf-filter-list shelf-filter-list-lenses';

  // (a) baseline lenses -- from book.genre, counts off the deduped set.
  var lbi;
  var lbRow;
  var lbCount;
  var lbName;
  for (lbi = 0; lbi < lensOrder.length; lbi++) {
    lbName = lensOrder[lbi];
    lbRow = document.createElement('li');
    lbRow.className = shelfFilter.genre === lbName
      ? 'shelf-filter is-on'
      : 'shelf-filter';
    lbRow.setAttribute('role', 'button');
    lbRow.setAttribute('tabindex', '0');
    lbRow.setAttribute('data-filter-section', 'genre');
    lbRow.setAttribute('data-filter-value', lbName);
    lbRow.textContent = lbName;
    lbCount = document.createElement('span');
    lbCount.className = 'n';
    lbCount.textContent = '' + (lensCounts[lbName] || 0);
    lbRow.appendChild(lbCount);
    lbRow.addEventListener('click', onShelfFilterRowClick);
    lbRow.addEventListener('keydown', onShelfFilterRowKeydown);
    lensListEl.appendChild(lbRow);
  }

  // (b) hand-made lenses -- the SAME display object; membership lives in
  // state.userThemes[id].bookIds, so the count is already orphan-free.
  var lmi;
  var lmRow;
  var lmCount;
  for (lmi = 0; lmi < userThemeList.length; lmi++) {
    lmRow = document.createElement('li');
    lmRow.className = shelfFilter.theme === userThemeList[lmi].id
      ? 'shelf-filter is-on is-manual'
      : 'shelf-filter is-manual';
    lmRow.setAttribute('role', 'button');
    lmRow.setAttribute('tabindex', '0');
    lmRow.setAttribute('data-filter-section', 'theme');
    lmRow.setAttribute('data-filter-value', userThemeList[lmi].id);
    lmRow.textContent = userThemeList[lmi].name;
    lmCount = document.createElement('span');
    lmCount.className = 'n';
    lmCount.textContent = '' + (Array.isArray(userThemeList[lmi].bookIds)
      ? userThemeList[lmi].bookIds.length : 0);
    lmRow.appendChild(lmCount);
    lmRow.addEventListener('click', onShelfFilterRowClick);
    lmRow.addEventListener('keydown', onShelfFilterRowKeydown);
    lensListEl.appendChild(lmRow);
  }

  // (c) empty hint only when there are no lenses of either kind.
  if (lensOrder.length === 0 && userThemeList.length === 0) {
    var lensEmpty = document.createElement('li');
    lensEmpty.className = 'shelf-filter is-toggle';
    lensEmpty.textContent = 'No lenses yet — ask Yumi to suggest some';
    lensListEl.appendChild(lensEmpty);
  }
  lensSection.appendChild(lensListEl);

  // (d) "Ask Yumi for more lenses" -- opens the lens panel (S4). Guarded so
  // it is inert until S4 defines window.PraxisLensPanel; its AI suggestions
  // are a feature-flagged stub (default off).
  var lensAsk = document.createElement('button');
  lensAsk.type = 'button';
  lensAsk.className = 'shelf-lens-ask';
  lensAsk.textContent = 'Ask Yumi for more lenses';
  lensAsk.addEventListener('click', function () {
    if (window.PraxisLensPanel && typeof window.PraxisLensPanel.open === 'function') {
      window.PraxisLensPanel.open();
    }
  });
  lensSection.appendChild(lensAsk);

  // Reading-status rail (mock group 1) — ABOVE Lenses. Canonical statuses in
  // STATUS_VOCAB order, count > 0 only (mirrors the present-values rule of the
  // genre/author rails). Compact labels match the shelf-head vocabulary
  // (reading/finished); the row VALUES are the real canon. Reuses .shelf-filter
  // + the shared row handlers; single-select via the generic toggleShelfFilter.
  var STATUS_RAIL_LABEL = { reading: 'Reading', read: 'Finished', 'will-read': 'Unread' };
  var statusSection = document.createElement('div');
  statusSection.className = 'shelf-filter-group';
  var statusLabel = document.createElement('h3');
  statusLabel.className = 'shelf-filter-label';
  statusLabel.textContent = 'Reading status';
  statusSection.appendChild(statusLabel);
  var statusListEl = document.createElement('ul');
  statusListEl.className = 'shelf-filter-list shelf-filter-list-status';
  var stvi;
  var stvKey;
  var stRow;
  var stCountEl;
  var statusRowCount = 0;
  // S-D4 (Wave 1): an "All" row that clears the status filter. status === null
  // IS the "all" predicate at the filter pass (statusOk below), so All just
  // nulls it; is-on when no status is picked. Count = the whole shelf.
  var stAllRow = document.createElement('li');
  stAllRow.className = shelfFilter.status ? 'shelf-filter' : 'shelf-filter is-on';
  stAllRow.setAttribute('role', 'button');
  stAllRow.setAttribute('tabindex', '0');
  stAllRow.setAttribute('data-filter-section', 'status');
  stAllRow.setAttribute('data-filter-value', '');
  stAllRow.textContent = 'All';
  var stAllCount = document.createElement('span');
  stAllCount.className = 'n';
  stAllCount.textContent = '' + shelfBookCount;
  stAllRow.appendChild(stAllCount);
  stAllRow.addEventListener('click', function () { shelfFilter.status = null; renderShelf(); });
  stAllRow.addEventListener('keydown', function (ev) {
    if (ev.key === 'Enter' || ev.key === ' ' || ev.key === 'Spacebar') {
      ev.preventDefault(); shelfFilter.status = null; renderShelf();
    }
  });
  statusListEl.appendChild(stAllRow);
  statusRowCount++;
  for (stvi = 0; stvi < STATUS_VOCAB.length; stvi = stvi + 1) {
    stvKey = STATUS_VOCAB[stvi];
    // S-D4 (Wave 1): show all four status rows always (incl. zero-count).
    statusRowCount++;
    stRow = document.createElement('li');
    stRow.className = shelfFilter.status === stvKey ? 'shelf-filter is-on' : 'shelf-filter';
    stRow.setAttribute('role', 'button');
    stRow.setAttribute('tabindex', '0');
    stRow.setAttribute('data-filter-section', 'status');
    stRow.setAttribute('data-filter-value', stvKey);
    stRow.textContent = STATUS_RAIL_LABEL[stvKey] || stvKey;
    stCountEl = document.createElement('span');
    stCountEl.className = 'n';
    stCountEl.textContent = '' + (statusCounts[stvKey] || 0);
    stRow.appendChild(stCountEl);
    stRow.addEventListener('click', onShelfFilterRowClick);
    stRow.addEventListener('keydown', onShelfFilterRowKeydown);
    statusListEl.appendChild(stRow);
  }
  statusSection.appendChild(statusListEl);
  if (statusRowCount > 0) { sidebar.appendChild(statusSection); }

  // Stage 1 (shelf categories): sidebar grouping toggle [ Lenses | Categories ],
  // modeled on the Covers|List seg. Reuses the .seg/.seg-opt/.is-on classes
  // (inherits `.shelf .seg` -- no new CSS) plus role=tablist + per-opt
  // role=tab/aria-selected. Default 'lenses' preserves the current behavior;
  // picking an opt persists via setShelfGrouping then re-renders. Placed
  // directly above the grouping section it controls (between the Reading-status
  // rail and the Lenses/Categories section).
  var shelfGrouping = getShelfGrouping();
  var groupSeg = document.createElement('div');
  groupSeg.className = 'seg';
  groupSeg.setAttribute('role', 'tablist');
  groupSeg.setAttribute('aria-label', 'Sidebar grouping');
  var groupLenses = document.createElement('button');
  groupLenses.type = 'button';
  groupLenses.className = 'seg-opt' + (shelfGrouping === 'lenses' ? ' is-on' : '');
  groupLenses.setAttribute('role', 'tab');
  groupLenses.setAttribute('aria-selected', shelfGrouping === 'lenses' ? 'true' : 'false');
  groupLenses.setAttribute('data-shelf-grouping', 'lenses');
  groupLenses.textContent = 'Lenses';
  groupLenses.addEventListener('click', function() {
    setShelfGrouping('lenses');
    renderShelf();
  });
  groupSeg.appendChild(groupLenses);
  var groupCategories = document.createElement('button');
  groupCategories.type = 'button';
  groupCategories.className = 'seg-opt' + (shelfGrouping === 'categories' ? ' is-on' : '');
  groupCategories.setAttribute('role', 'tab');
  groupCategories.setAttribute('aria-selected', shelfGrouping === 'categories' ? 'true' : 'false');
  groupCategories.setAttribute('data-shelf-grouping', 'categories');
  groupCategories.textContent = 'Categories';
  groupCategories.addEventListener('click', function() {
    setShelfGrouping('categories');
    renderShelf();
  });
  groupSeg.appendChild(groupCategories);
  sidebar.appendChild(groupSeg);

  // Stage 2C (shelf categories): grouping branch. 'lenses' appends the existing
  // Lenses rail (built above, byte-for-byte unchanged). 'categories' classifies
  // the deduped shelf set into the curated taxonomy and renders POPULATED
  // categories in taxonomy order (Uncategorized last), reusing the .shelf-filter
  // row idiom + shared handlers (same as the Reading-status rail). Classification
  // is lazy + cached: classifyBookLocal resolves cached/seed/keyword rows
  // synchronously; books it returns null for go to the Sonnet batch classifier
  // ONCE (guarded by shelfCategorizing), the result cached on each record and
  // persisted in a SINGLE batched write, then a re-render fills the rows in.
  // Non-blocking: the rest of the shelf is already built and stays usable.
  // Reading-status + Author stay in both modes.
  if (shelfGrouping === 'lenses') {
    sidebar.appendChild(lensSection);
  } else {
    var catCounts = {};
    var catPending = [];
    var cci, ccb, ccLabel;
    for (cci = 0; cci < lcArr.length; cci = cci + 1) {
      ccb = lcArr[cci];
      if (!ccb) { continue; }
      ccLabel = classifyBookLocal(ccb);
      if (ccLabel === null) { catPending.push(ccb); continue; }
      catCounts[ccLabel] = (catCounts[ccLabel] || 0) + 1;
    }

    // Lazy classify: fire once -- only when categories is the active grouping,
    // only for the unresolved books, only when signed in (the result persists to
    // the user's records), and never while a pass is already in flight.
    if (catPending.length > 0 && !shelfCategorizing && getCurrentUser()) {
      shelfCategorizing = true;
      shelfClassifyGen = shelfClassifyGen + 1;
      var ccGen = shelfClassifyGen;
      // Watchdog: classifyBooksViaLLM has no timeout/abort, so a hung fetch (or an
      // unexpected throw inside a .then handler) would never reach the callback
      // below, leaving shelfCategorizing stuck true -- spinner frozen, Re-classify
      // hidden -- until a reload. If the callback has not fired by the deadline,
      // abandon this pass: bump the generation so a late callback no-ops, clear the
      // flag, and re-render so the UI recovers (and can retry). The deadline scales
      // with the batch count and errs LONG on purpose -- tripping a slow-but-working
      // pass would churn, so the budget is generous; a genuine hang just takes a
      // little to recover.
      var ccDeadline = 20000 + Math.ceil(catPending.length / 20) * 20000;
      var ccWatchdog = setTimeout(function () {
        if (ccGen !== shelfClassifyGen) { return; }
        shelfClassifyGen = shelfClassifyGen + 1;
        shelfCategorizing = false;
        if (location.hash === '#books' && getShelfGrouping() === 'categories') {
          renderShelf();
        }
      }, ccDeadline);
      classifyBooksViaLLM(catPending, function (resultMap) {
        clearTimeout(ccWatchdog);
        if (ccGen !== shelfClassifyGen) { return; }
        var rk;
        for (rk in resultMap) {
          if (Object.prototype.hasOwnProperty.call(resultMap, rk) && state.books[rk]) {
            state.books[rk].category = resultMap[rk];
          }
        }
        markBooksDirty();
        saveState();                 // ONE batched persist for the whole pass
        shelfCategorizing = false;
        // Re-render only if the user is still on the Categories grouping, so a
        // background finish never yanks another view out from under them.
        if (location.hash === '#books' && getShelfGrouping() === 'categories') {
          renderShelf();
        }
      });
    }

    var catSection = document.createElement('div');
    catSection.className = 'shelf-filter-group shelf-filter-group-categories';
    var catLabel = document.createElement('h3');
    catLabel.className = 'shelf-filter-label';
    catLabel.textContent = 'Categories';
    catSection.appendChild(catLabel);
    var catListEl = document.createElement('ul');
    catListEl.className = 'shelf-filter-list shelf-filter-list-categories';

    // One populated row -- reuses the shared row idiom + handlers (data-filter-
    // section="category" routes through toggleShelfFilter's exclusive-clear).
    var catRowsRendered = 0;
    var appendCatRow = function (label, count) {
      var cr = document.createElement('li');
      cr.className = shelfFilter.category === label ? 'shelf-filter is-on' : 'shelf-filter';
      cr.setAttribute('role', 'button');
      cr.setAttribute('tabindex', '0');
      cr.setAttribute('data-filter-section', 'category');
      cr.setAttribute('data-filter-value', label);
      cr.textContent = label;
      var cn = document.createElement('span');
      cn.className = 'n';
      cn.textContent = '' + count;
      cr.appendChild(cn);
      cr.addEventListener('click', onShelfFilterRowClick);
      cr.addEventListener('keydown', onShelfFilterRowKeydown);
      catListEl.appendChild(cr);
      catRowsRendered = catRowsRendered + 1;
    };

    var cti, ctLabel;
    for (cti = 0; cti < SHELF_CATEGORIES.length; cti = cti + 1) {
      ctLabel = SHELF_CATEGORIES[cti];
      if ((catCounts[ctLabel] || 0) > 0) { appendCatRow(ctLabel, catCounts[ctLabel]); }
    }
    // Uncategorized always last, only when populated.
    if ((catCounts[CATEGORY_UNCATEGORIZED] || 0) > 0) {
      appendCatRow(CATEGORY_UNCATEGORIZED, catCounts[CATEGORY_UNCATEGORIZED]);
    }

    // Non-blocking loading row while a pass is in flight; else an empty hint.
    if (shelfCategorizing) {
      var catLoading = document.createElement('li');
      catLoading.className = 'shelf-filter is-toggle shelf-categories-loading';
      catLoading.textContent = 'Classifying ' + catPending.length
        + (catPending.length === 1 ? ' book…' : ' books…');
      catListEl.appendChild(catLoading);
    } else if (catRowsRendered === 0) {
      var catEmpty = document.createElement('li');
      catEmpty.className = 'shelf-filter is-toggle';
      catEmpty.textContent = 'No categories yet';
      catListEl.appendChild(catEmpty);
    }

    catSection.appendChild(catListEl);

    // Re-classify control — clears every cached category so the lazy classifier
    // re-runs over the whole shelf set, letting a classifier change (the
    // seed-drop, and future improvements) land on the already-classified
    // library. Signed-in only (it persists to the user's records) and hidden
    // while a pass is in flight (the loading row above shows instead). Mirrors
    // the Lenses rail's "Ask Yumi" button idiom.
    if (getCurrentUser() && !shelfCategorizing) {
      var catReclassify = document.createElement('button');
      catReclassify.type = 'button';
      catReclassify.className = 'shelf-lens-ask';
      catReclassify.textContent = 'Re-classify';
      catReclassify.addEventListener('click', function () {
        if (shelfCategorizing) { return; }   // never stomp an in-flight pass
        var rbid, rb;
        var rcDirty = false;
        for (rbid in state.books) {
          if (!Object.prototype.hasOwnProperty.call(state.books, rbid)) { continue; }
          rb = state.books[rbid];
          if (!rb) { continue; }
          // R7: preserve a manual category override — a pinned categoryOverride
          // is never cleared by Re-classify (it also wins in classifyBookLocal).
          if (rb.categoryOverride) { continue; }
          if (rb.category !== '') {
            rb.category = '';
            rcDirty = true;
          }
        }
        if (rcDirty) {
          markBooksDirty();
          saveState();           // ONE batched write for the whole clear
        }
        renderShelf();           // re-render -> lazy orchestration re-fires over the now-null books
      });
      catSection.appendChild(catReclassify);
    }
    sidebar.appendChild(catSection);
  }

  // S3: the former separate GENRE rail is merged into the single Lenses rail
  // above (baseline lenses are derived from the distinct book.genre values).

  // R8 (values): the Values rail — ONE new row-group in the EXISTING sidebar
  // (no new toggle, no new sidebar block). Distinct value-marks across the
  // DEDUPED shelf set (authorSrc, same source as the author/lens counts, so a
  // duplicate/orphan record never inflates a count), each counted once per book.
  // Rows reuse the shared .shelf-filter idiom + handlers; 'value' auto-joins the
  // exclusive single-select via toggleShelfFilter's generic key loop. Rendered
  // only when the shelf actually carries value-marks.
  var valueSeen = {};
  var valueList = [];
  var valueCounts = {};
  var vci, vcb, vmj, vmk, vmval, vSeenThisBook;
  for (vci = 0; vci < authorSrc.length; vci = vci + 1) {
    vcb = authorSrc[vci];
    if (!vcb || !(vcb.valueMarks instanceof Array)) { continue; }
    vSeenThisBook = {};
    for (vmj = 0; vmj < vcb.valueMarks.length; vmj = vmj + 1) {
      vmk = vcb.valueMarks[vmj];
      vmval = (vmk && typeof vmk.value === 'string') ? vmk.value : '';
      if (vmval === '' || Object.prototype.hasOwnProperty.call(vSeenThisBook, vmval)) { continue; }
      vSeenThisBook[vmval] = true;
      if (!Object.prototype.hasOwnProperty.call(valueSeen, vmval)) {
        valueSeen[vmval] = true;
        valueList.push(vmval);
      }
      valueCounts[vmval] = (valueCounts[vmval] || 0) + 1;
    }
  }
  valueList.sort(function (a, b) {
    var ca = valueCounts[a] || 0;
    var cb = valueCounts[b] || 0;
    if (cb !== ca) { return cb - ca; }
    var la = a.toLowerCase();
    var lb = b.toLowerCase();
    if (la < lb) { return -1; }
    if (la > lb) { return 1; }
    return 0;
  });
  if (valueList.length > 0) {
    var valueSection = document.createElement('div');
    valueSection.className = 'shelf-filter-group';
    var valueLabel = document.createElement('h3');
    valueLabel.className = 'shelf-filter-label';
    valueLabel.textContent = 'Values';
    valueSection.appendChild(valueLabel);
    var valueListEl = document.createElement('ul');
    valueListEl.className = 'shelf-filter-list shelf-filter-list-value';
    var vli, valueRow, valueRowCount;
    for (vli = 0; vli < valueList.length; vli = vli + 1) {
      valueRow = document.createElement('li');
      valueRow.className = shelfFilter.value === valueList[vli]
        ? 'shelf-filter is-on'
        : 'shelf-filter';
      valueRow.setAttribute('role', 'button');
      valueRow.setAttribute('tabindex', '0');
      valueRow.setAttribute('data-filter-section', 'value');
      valueRow.setAttribute('data-filter-value', valueList[vli]);
      valueRow.textContent = valueList[vli];
      valueRowCount = document.createElement('span');
      valueRowCount.className = 'n';
      valueRowCount.textContent = '' + (valueCounts[valueList[vli]] || 0);
      valueRow.appendChild(valueRowCount);
      valueRow.addEventListener('click', onShelfFilterRowClick);
      valueRow.addEventListener('keydown', onShelfFilterRowKeydown);
      valueListEl.appendChild(valueRow);
    }
    valueSection.appendChild(valueListEl);
    sidebar.appendChild(valueSection);
  }

  // Author section -- dedup'd alphabetical list from state.books.
  var authorSection = document.createElement('div');
  authorSection.className = 'shelf-filter-group';
  var authorLabel = document.createElement('h3');
  authorLabel.className = 'shelf-filter-label';
  authorLabel.textContent = 'Author';
  authorSection.appendChild(authorLabel);
  var authorListEl = document.createElement('ul');
  authorListEl.className = 'shelf-filter-list shelf-filter-list-author';
  var ai;
  var authorRow;
  for (ai = 0; ai < visibleAuthors.length; ai++) {
    authorRow = document.createElement('li');
    // 3.10b Stage 3: role, tabindex, data-* for section + value,
    // selected class on render, click + keydown handlers. The handler
    // reads the 'author' section + value directly off the activated
    // element's data-filter-section attribute.
    authorRow.className = shelfFilter.author === visibleAuthors[ai]
      ? 'shelf-filter is-on'
      : 'shelf-filter';
    authorRow.setAttribute('role', 'button');
    authorRow.setAttribute('tabindex', '0');
    authorRow.setAttribute('data-filter-section', 'author');
    authorRow.setAttribute('data-filter-value', visibleAuthors[ai]);
    authorRow.textContent = visibleAuthors[ai];
    // Phase 3.1: per-value book-match count (display only). data-filter-
    // value carries the clean author name; the count span is cosmetic.
    var authorRowCount = document.createElement('span');
    authorRowCount.className = 'n';
    authorRowCount.textContent = '' + (authorCounts[visibleAuthors[ai]] || 0);
    authorRow.appendChild(authorRowCount);
    authorRow.addEventListener('click', onShelfFilterRowClick);
    authorRow.addEventListener('keydown', onShelfFilterRowKeydown);
    authorListEl.appendChild(authorRow);
  }
  // Stage 4d: expand/collapse toggle row, rendered only when the full
  // list exceeds the collapsed cap. Quiet row -- no count, no gold
  // bar, no data-filter attributes (it is not a filter).
  if (totalAuthorCount > 12) {
    var authorToggleRow = document.createElement('li');
    authorToggleRow.className = 'shelf-filter is-toggle';
    authorToggleRow.setAttribute('role', 'button');
    authorToggleRow.setAttribute('tabindex', '0');
    authorToggleRow.textContent = shelfAuthorRailExpanded
      ? 'Show fewer'
      : 'Show all (' + totalAuthorCount + ')';
    authorToggleRow.addEventListener('click', onShelfAuthorToggleClick);
    authorToggleRow.addEventListener('keydown', onShelfAuthorToggleKeydown);
    authorListEl.appendChild(authorToggleRow);
  }
  authorSection.appendChild(authorListEl);
  sidebar.appendChild(authorSection);

  layout.appendChild(sidebar);
  // 3.10b-i: backdrop appended as a sibling of the sidebar inside
  // .shelf-layout. Order after the sidebar so the close-button focus
  // ring (Stage 1 :focus-visible) renders cleanly above the backdrop
  // dim. CSS z-index keeps the sidebar (100) above the backdrop (99).
  layout.appendChild(backdrop);

  // 3.10b-i: mobile filter panel open/close. Backdrop and sidebar
  // always toggle together via add/remove of paired classes. dismiss
  // is the single source of truth — wired to four triggers below:
  // the close × button, a click on the backdrop, an Escape keydown
  // at document scope, and the .shelf-filter-button when the panel
  // is already open. The Escape handler is parked at module scope
  // (shelfSidebarEscapeHandler) so a re-render can purge a stale
  // one; see the cleanup at the top of renderShelf.
  function openShelfFilterPanel() {
    sidebar.classList.add('shelf-sidebar-mobile-open');
    backdrop.classList.add('shelf-sidebar-backdrop-open');
    if (shelfSidebarEscapeHandler) {
      document.removeEventListener('keydown', shelfSidebarEscapeHandler);
    }
    shelfSidebarEscapeHandler = function(ev) {
      if (ev.key === 'Escape' || ev.key === 'Esc') {
        dismissShelfFilterPanel();
      }
    };
    document.addEventListener('keydown', shelfSidebarEscapeHandler);
  }

  function dismissShelfFilterPanel() {
    sidebar.classList.remove('shelf-sidebar-mobile-open');
    backdrop.classList.remove('shelf-sidebar-backdrop-open');
    if (shelfSidebarEscapeHandler) {
      document.removeEventListener('keydown', shelfSidebarEscapeHandler);
      shelfSidebarEscapeHandler = null;
    }
  }

  closeBtn.addEventListener('click', dismissShelfFilterPanel);
  backdrop.addEventListener('click', dismissShelfFilterPanel);

  // Right column: editor host above the grid/empty.
  var main = document.createElement('div');
  main.className = 'shelf-main';

  // (The Filters toggle moved into the toolbar above; its handler references
  // sidebar / backdrop / the panel fns defined here, resolved at click time.)

  // Editor host -- empty on every render; openShelfEditor mounts
  // its block here on demand. Lives above the book list so the
  // editor sits visually above existing rows.
  var editorHost = document.createElement('div');
  editorHost.id = 'shelf-editor-host';
  main.appendChild(editorHost);

  // Collect books for the grid. Read site is state.books, not
  // state.userBooks -- see 3.5a brief: userBooks is write-but-not-
  // read in 3.5a so book_test_1 (seeded into state.books in 3.3
  // console testing but never into userBooks) stays visible.
  // User-scoping the shelf is a future seam.
  var books = [];
  var bid;
  if (shelfBookIds) {
    // FIX D: signed in -> render the bookIds index (deduped, no orphans).
    for (bid = 0; bid < shelfBookIds.length; bid = bid + 1) {
      if (booksMap[shelfBookIds[bid]]) { books.push(booksMap[shelfBookIds[bid]]); }
    }
  } else {
    for (bid in booksMap) {
      if (Object.prototype.hasOwnProperty.call(booksMap, bid)) {
        if (booksMap[bid]) books.push(booksMap[bid]);
      }
    }
  }
  books.sort(function(a, b) {
    // 3c: reading-status sort when selected (reading -> will-read -> read);
    // date-added desc is the default AND the tiebreak within a status band.
    if (shelfSort === 'status') {
      var rank = { reading: 0, 'will-read': 1, read: 2 };
      var ra = rank[normalizeStatus(a.status)];
      var rb = rank[normalizeStatus(b.status)];
      if (ra === undefined) { ra = 3; }
      if (rb === undefined) { rb = 3; }
      if (ra !== rb) { return ra - rb; }
    }
    return (b.addedAt || 0) - (a.addedAt || 0);
  });

  // 3.10b Stage 3: filter pass. Sits AFTER the addedAt sort and
  // BEFORE the empty-state branch -- the empty-state branch consumes
  // the post-filter length, which is what drives the filter-empty
  // copy switch below. STRICT === only: no toLowerCase, no indexOf,
  // no normalization. An active filter excludes any book whose
  // corresponding field is empty/missing or whose value is not ===
  // the selection. A null filter for a section is a no-op for that
  // section. AND across sections: a book passes only if both
  // predicates pass.
  var filtered = [];
  var fi;
  var fb;
  var authorOk;
  var genreOk;
  var themeOk;
  var statusOk;
  var traditionOk;
  var categoryOk;
  var searchOk;
  var valueOk;
  var vfj;
  // Stage 7 (manual themes): precompute the selected user-theme's membership
  // set (book ids) once, so the per-book themeOk test is an O(1) lookup. Null
  // when no theme filter is active or the selected theme no longer exists.
  var selectedThemeBookIds = null;
  if (shelfFilter.theme !== null && state.userThemes &&
      state.userThemes[shelfFilter.theme]) {
    selectedThemeBookIds = {};
    var stbArr = state.userThemes[shelfFilter.theme].bookIds || [];
    var stbI;
    for (stbI = 0; stbI < stbArr.length; stbI++) {
      selectedThemeBookIds[stbArr[stbI]] = true;
    }
  }
  for (fi = 0; fi < books.length; fi++) {
    fb = books[fi];
    authorOk = shelfFilter.author === null ||
      (typeof fb.author === 'string' && fb.author.length > 0 &&
       fb.author === shelfFilter.author);
    // Genre rail: strict equality against book.genre (the former 'theme' slot).
    genreOk = shelfFilter.genre === null ||
      (typeof fb.genre === 'string' && fb.genre.length > 0 &&
       fb.genre === shelfFilter.genre);
    // Theme rail: the user-created overlay -- book is a member of the selected
    // theme (membership lives in state.userThemes, never on the book record).
    themeOk = shelfFilter.theme === null ||
      (selectedThemeBookIds !== null && selectedThemeBookIds[fb.id] === true);
    // Status rail: canonical-status equality (normalizeStatus collapses the
    // dual stored vocabularies the same way the head count + the 6-branch
    // matrix do, so the row count and the filtered set always agree).
    statusOk = shelfFilter.status === null ||
      (normalizeStatus(fb.status) === shelfFilter.status);
    // Tradition rail: strict equality on the resolved tradition (override wins).
    traditionOk = shelfFilter.tradition === null ||
      ((fb.traditionOverride || fb.tradition) === shelfFilter.tradition);
    // Stage 2C: category rail -- equality on the resolved category. Mirrors the
    // dormant traditionOk: a harmless always-true no-op until a category row is
    // picked. classifyBookLocal is O(1) for already-classified books (cache hit).
    categoryOk = shelfFilter.category === null ||
      (classifyBookLocal(fb) === shelfFilter.category);
    // R8 (values): value rail — the book carries the selected value (a mark on
    // its valueMarks whose .value === the slug). Membership lives on the book
    // record (like movedMe); harmless no-op until a value row is picked.
    valueOk = shelfFilter.value === null;
    if (!valueOk && (fb.valueMarks instanceof Array)) {
      for (vfj = 0; vfj < fb.valueMarks.length; vfj++) {
        if (fb.valueMarks[vfj] && fb.valueMarks[vfj].value === shelfFilter.value) { valueOk = true; break; }
      }
    }
    // Stage 4d: live search -- case-insensitive substring over title
    // OR author, AND-composed with the rail filters.
    searchOk = shelfSearchQuery === '' ||
      ((fb.title || '').toLowerCase().indexOf(shelfSearchQuery) !== -1 ||
       (fb.author || '').toLowerCase().indexOf(shelfSearchQuery) !== -1);
    if (authorOk && genreOk && themeOk && statusOk && traditionOk && categoryOk && valueOk && searchOk) {
      filtered.push(fb);
    }
  }
  books = filtered;

  // S-D2 (Wave 1): computed display-only "alight" set -- a book has grown into
  // the reader's thinking when it has >=1 marginalia entry OR >=1 sub-theory
  // derived from it (evidence {kind:'book'} OR attached marginalia). Real
  // stores only (state.notebookEntries register 'marginalia' + state.subTheories),
  // owner-filtered; one pass, no data-model change. Same predicate as
  // marginaliaForBook() + rootedSubTheories() (Book Detail), unioned.
  var shelfAlight = {};
  (function () {
    var au = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
    var auid = au ? au.uid : null;
    var entries = state.notebookEntries || {};
    var subs = state.subTheories || {};
    var ek, e, ei, s2k, s2, si, ev, sj, ent;
    for (ek in entries) {
      if (!Object.prototype.hasOwnProperty.call(entries, ek)) { continue; }
      e = entries[ek];
      if (!e || e.register !== 'marginalia') { continue; }
      if (auid && e.userId && e.userId !== auid) { continue; }
      if (!e.bookIds) { continue; }
      for (ei = 0; ei < e.bookIds.length; ei = ei + 1) { shelfAlight[e.bookIds[ei]] = true; }
    }
    for (s2k in subs) {
      if (!Object.prototype.hasOwnProperty.call(subs, s2k)) { continue; }
      s2 = subs[s2k];
      if (!s2) { continue; }
      if (auid && s2.userId && s2.userId !== auid) { continue; }
      if (s2.evidence) {
        for (si = 0; si < s2.evidence.length; si = si + 1) {
          ev = s2.evidence[si];
          if (ev && ev.kind === 'book' && ev.refId) { shelfAlight[ev.refId] = true; }
        }
      }
      if (s2.attachedMarginalia) {
        for (sj = 0; sj < s2.attachedMarginalia.length; sj = sj + 1) {
          ent = entries[s2.attachedMarginalia[sj]];
          if (ent && ent.bookIds) {
            for (ei = 0; ei < ent.bookIds.length; ei = ei + 1) { shelfAlight[ent.bookIds[ei]] = true; }
          }
        }
      }
    }
  })();

  // 3a (R2): book -> arcs map (decision 1 -- arc thread-tie, intersectional).
  // A book is in an arc when arc.bookIds carries { id: book.id } (state.js:1776).
  // Owner-filtered; one pass over state.arcs. Passed to the card helpers so the
  // spine thread is colored by the primary arc and the reveal lists them all.
  var shelfArcsByBook = {};
  (function () {
    var au = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
    var auid = au ? au.uid : null;
    var arcsMap = state.arcs || {};
    var akk, arc2, abi, mid;
    for (akk in arcsMap) {
      if (!Object.prototype.hasOwnProperty.call(arcsMap, akk)) { continue; }
      arc2 = arcsMap[akk];
      if (!arc2 || !arc2.bookIds) { continue; }
      if (auid && arc2.userId && arc2.userId !== auid) { continue; }
      for (abi = 0; abi < arc2.bookIds.length; abi = abi + 1) {
        mid = arc2.bookIds[abi] && arc2.bookIds[abi].id;
        if (!mid) { continue; }
        if (!shelfArcsByBook[mid]) { shelfArcsByBook[mid] = []; }
        shelfArcsByBook[mid].push(arc2);
      }
    }
  })();

  if (books.length === 0) {
    // 3.10a Stage 4: empty state. Structure supports both copy
    // variants (zero-books and zero-filter-results); 3.10a wired
    // only zero-books, 3.10b adds the filter-empty switch below.
    // The button is auth-conditional per Q1 resolution (2026-05-16):
    // signed-in shows Add book primary, signed-out shows the sign-in
    // prompt. Both reuse existing button classes (.shelf-new-book /
    // .shelf-signin-prompt) and existing handlers (openShelfEditor
    // / signInWithGoogle) -- zero new behavior, just reuse-wiring a
    // second button instance to a pre-existing handler. The unused
    // .shelf-empty-body class from earlier stages is discarded; no
    // rule consumed it.
    //
    // 3.10b Stage 3: copy switch. If any filter is active, the
    // empty list is the result of filtering rather than an unstocked
    // shelf; the headline + subtitle change accordingly. The auth-
    // conditional action button stays identical in BOTH branches per
    // the brief -- signed-out users still get the sign-in prompt
    // even when their filter yields zero.
    var filterActive = shelfFilter.author !== null ||
      shelfFilter.genre !== null ||
      shelfFilter.theme !== null ||
      shelfFilter.status !== null ||
      shelfFilter.tradition !== null ||
      shelfFilter.category !== null ||
      shelfFilter.value !== null ||
      shelfSearchQuery !== '';
    var empty = document.createElement('div');
    empty.className = 'empty-state';
    empty.id = 'shelf-empty';
    var emptyMark = document.createElement('div');
    emptyMark.className = 'em-mark';
    emptyMark.id = 'shelf-empty-mark';
    if (typeof yumiGlyphNode === 'function') { emptyMark.appendChild(yumiGlyphNode(56)); }
    empty.appendChild(emptyMark);
    var emptyHeadline = document.createElement('h2');
    emptyHeadline.textContent = filterActive
      ? 'Nothing on the shelf matches.'
      : 'Your shelf is open';
    empty.appendChild(emptyHeadline);
    var emptySubtitle = document.createElement('p');
    emptySubtitle.textContent = filterActive
      ? 'Clear your filters or add a new book.'
      : 'Add your first book — scan a spine, search a title, or paste a whole list. Reading starts becoming thinking the moment it has somewhere to go.';
    empty.appendChild(emptySubtitle);
    // Signed-out never reaches here (top-of-function hard-gate, W11 S8 Lane 1),
    // so the empty state always offers the signed-in "Add a book" primary.
    var emptyAddBtn = document.createElement('button');
    emptyAddBtn.type = 'button';
    emptyAddBtn.className = 'btn btn-primary';
    emptyAddBtn.textContent = '＋ Add a book';
    emptyAddBtn.addEventListener('click', function() {
      openShelfEditor();
    });
    empty.appendChild(emptyAddBtn);
    main.appendChild(empty);
  } else {
    // Stage 3: branch on the persisted shelf view. Both consume the SAME
    // post-sort/post-filter `books` array, so sort/filter/search work
    // identically in either view. 'covers' = the existing grid via
    // renderShelfBook (untouched); 'list' = compact rows via the new
    // renderShelfBookRow.
    if (getShelfView() === 'list') {
      var rows = document.createElement('div');
      rows.className = 'shelf-rows';
      var ri;
      for (ri = 0; ri < books.length; ri++) {
        rows.appendChild(renderShelfBookRow(books[ri], !!shelfAlight[books[ri].id], shelfArcsByBook[books[ri].id] || []));
      }
      main.appendChild(rows);
    } else {
      var list = document.createElement('div');
      list.className = 'shelf-grid';
      list.id = 'shelf-grid';
      var i;
      for (i = 0; i < books.length; i++) {
        list.appendChild(renderShelfBook(books[i], !!shelfAlight[books[i].id], shelfArcsByBook[books[i].id] || []));
      }
      main.appendChild(list);
    }

    // S-D2 (Wave 1): the alight legend -- static explanatory copy (not
    // generative). Shown with the grid/rows (books present), never on empty.
    var shelfRootedNote = document.createElement('p');
    shelfRootedNote.className = 'shelf-rootednote';
    var shelfRootedMark = document.createElement('span');
    shelfRootedMark.className = 'shelf-rootednote-mark';
    shelfRootedMark.setAttribute('aria-hidden', 'true');
    var shelfRootedB = document.createElement('b');
    shelfRootedB.textContent = 'Alight';
    shelfRootedNote.appendChild(shelfRootedMark);
    shelfRootedNote.appendChild(shelfRootedB);
    shelfRootedNote.appendChild(document.createTextNode(
      ' = this book has grown into your thinking — marginalia, or a sub-theory built from it. The rest are read or waiting.'));
    main.appendChild(shelfRootedNote);
  }

  layout.appendChild(main);
  wrap.appendChild(layout);

  // 3b (R2): the arc-picker host (shelfMoveToArc mounts buildArcPickerPanel here)
  // + the fixed Move-to-arc action bar -- the ONLY bulk action. The bar slides up
  // (CSS) when Select mode has >=1 pick; count restored from shelfPicked.
  var shelfArcPickerHost = document.createElement('div');
  shelfArcPickerHost.id = 'shelf-arc-picker-host';
  wrap.appendChild(shelfArcPickerHost);

  var selectBar = document.createElement('div');
  selectBar.id = 'shelf-selectbar';
  selectBar.className = 'shelf-selectbar' + (shelfPickedCount() > 0 ? ' has-pick' : '');
  var sbCount = document.createElement('span');
  sbCount.className = 'count';
  var sbCountB = document.createElement('b');
  sbCountB.id = 'shelf-pick-count';
  sbCountB.textContent = '' + shelfPickedCount();
  sbCount.appendChild(sbCountB);
  sbCount.appendChild(document.createTextNode(' selected'));
  selectBar.appendChild(sbCount);
  var sbMove = document.createElement('button');
  sbMove.type = 'button';
  sbMove.className = 'move';
  sbMove.textContent = 'Move to an arc…';
  sbMove.addEventListener('click', shelfMoveToArc);
  selectBar.appendChild(sbMove);
  var sbCancel = document.createElement('button');
  sbCancel.type = 'button';
  sbCancel.className = 'cancel';
  sbCancel.textContent = 'Cancel';
  sbCancel.addEventListener('click', function () { shelfSelecting = false; shelfPicked = {}; renderShelf(); });
  selectBar.appendChild(sbCancel);
  wrap.appendChild(selectBar);

  host.appendChild(wrap);

  // Stage 4d: the render above rebuilt the search input; when the
  // render was triggered by typing, restore focus + caret-to-end so
  // the user keeps typing uninterrupted.
  if (shelfSearchRefocus) {
    shelfSearchRefocus = false;
    var refocusInput = document.getElementById('shelf-search-input');
    if (refocusInput) {
      refocusInput.focus();
      var caretEnd = refocusInput.value.length;
      if (typeof refocusInput.setSelectionRange === 'function') {
        refocusInput.setSelectionRange(caretEnd, caretEnd);
      }
    }
  }
}

// 3a (R2): deterministic per-arc hue from the Universal field spectrum
// (--field-1..10, defined app-wide by universal-depth.css). No per-arc color
// exists in the data model, so the color is derived from a stable id-hash --
// the same "stable key -> hue" pattern PraxisMarks uses. Returns a token
// reference so the value tracks the spectrum, never a hardcoded literal.
function arcFieldHue(arcId) {
  var s = '' + (arcId || '');
  var h = 0;
  var i;
  for (i = 0; i < s.length; i = i + 1) {
    h = ((h << 5) - h + s.charCodeAt(i)) | 0;
  }
  return 'var(--field-' + (Math.abs(h) % 10 + 1) + ')';
}

// Single shelf row. Anchor element so the browser's hashchange path
// handles navigation -- no addEventListener needed.
function renderShelfBook(book, isAlight, arcs) {
  var card = document.createElement('a');
  card.className = 'shelf-book' + (isAlight ? ' is-alight' : '') + (shelfPicked[book.id] ? ' is-picked' : '');
  card.href = '#book/' + book.id;

  // 3.5b: cover thumbnail or placeholder block. The truthy check
  // correctly treats null, undefined, and '' as missing-cover.
  // 3.10a Stage 3: both branches now mount inside a shared
  // .shelf-book-cover-area wrapper so the fixed 200px cover-area
  // height applies uniformly whether the card has an image or a
  // placeholder. Wrapper is purely structural -- no behavior, no
  // event listeners. Future surfaces (Stage 4 mobile 160px, overlay
  // affordances) hang off this container.
  var coverArea = document.createElement('div');
  coverArea.className = 'shelf-book-cover-area';
  // Stage 1: self-healing cover. A broken OR null coverUrl walks any
  // coverCandidates, then falls to the graceful "cover pending" placeholder
  // (title + label) -- never a broken <img> ("?") or an empty card. The
  // placeholder label is a real <span> (not a CSS ::after) so the text is in
  // the DOM for assistive tech; the async cover fetch may still resolve, so it
  // reads as pending, not permanently absent.
  coverArea.appendChild(buildSelfHealingCover(book, 'shelf-book-cover', function() {
    var coverPlaceholder = document.createElement('div');
    coverPlaceholder.className = 'shelf-book-cover-placeholder';
    var pendingTitle = document.createElement('span');
    pendingTitle.className = 'shelf-book-cover-pending-title';
    pendingTitle.textContent = book.title || '';
    coverPlaceholder.appendChild(pendingTitle);
    var pendingLabel = document.createElement('span');
    pendingLabel.className = 'shelf-book-cover-pending';
    pendingLabel.textContent = 'cover pending';
    coverPlaceholder.appendChild(pendingLabel);
    return coverPlaceholder;
  }));

  // Tradition resolution for the spine tick below: traditionOverride
  // wins if set (user choice from the edit-book modal, 5.6 sub-step
  // 5), else the genre-derived tradition. Stage 4d removed the 5.6
  // sub-step 4 corner glyph from shelf covers (mockup parity, D4);
  // renderRegisterGlyph stays intact for other surfaces -- re-adding
  // one call site here reverses this.
  var glyphTradition = book.traditionOverride || book.tradition;

  card.appendChild(coverArea);

  // S-D2 (Wave 1): the gold root-mark on an alight cover (mirrors
  // bookAmberCover's .bk-cover-rmark). Computed display-only; the caller passes
  // isAlight from the real marginalia + sub-theory linkage.
  if (isAlight) {
    var shelfRmark = document.createElement('span');
    shelfRmark.className = 'shelf-book-rmark';
    shelfRmark.setAttribute('aria-hidden', 'true');
    coverArea.appendChild(shelfRmark);
  }

  // Phase 3.1: register tick -- left-edge accent bar colored by the
  // book's tradition. Data-driven token only: set --tick to
  // var(--register-<tradition>); CSS paints background: var(--tick).
  // 'unassigned' (and any tradition without a register token) gets NO
  // tick, mirroring renderRegisterGlyph's empty-corner signal. Uses the
  // same glyphTradition resolved above (traditionOverride || tradition).
  if (glyphTradition && glyphTradition !== 'unassigned' &&
      typeof REGISTER_SHAPE_PATHS[glyphTradition] === 'string' &&
      REGISTER_SHAPE_PATHS[glyphTradition] !== '') {
    var tick = document.createElement('span');
    tick.className = 'shelf-book-tick';
    tick.setAttribute('aria-hidden', 'true');
    tick.style.setProperty('--tick', 'var(--register-' + glyphTradition + ')');
    coverArea.appendChild(tick);
    // 3a: has-tick moves the arc thread just inside the register tick (which
    // stays at left:0). A book without a tick lets the thread hug the edge.
    card.className = card.className + ' has-tick';
  }

  // 3a (R2): arc thread-tie (decision 1/8). Colored by the primary arc; the
  // register tick above is UNTOUCHED. Tapping the thread reveals ALL arcs (the
  // card still navigates from anywhere else) -- the reveal trigger narrows from
  // the mockup's whole-card tap to the thread, because the live card is a
  // navigation link and "book open" is load-bearing.
  if (arcs && arcs.length > 0) {
    var arcThread = document.createElement('span');
    arcThread.className = 'shelf-book-arcthread';
    arcThread.setAttribute('aria-hidden', 'true');
    arcThread.style.setProperty('--arc', arcFieldHue(arcs[0].id));
    coverArea.appendChild(arcThread);
  }

  // 3b (R2): per-card select checkbox overlay (shown only in Select mode via the
  // .shelf.is-selecting gate). Picked state mirrors shelfPicked.
  var checkEl = document.createElement('span');
  checkEl.className = 'shelf-book-check';
  checkEl.setAttribute('aria-hidden', 'true');
  coverArea.appendChild(checkEl);

  var titleEl = document.createElement('h2');
  titleEl.className = 'shelf-book-title';
  titleEl.textContent = book.title || '';
  card.appendChild(titleEl);

  if (book.author) {
    var authorEl = document.createElement('p');
    authorEl.className = 'shelf-book-author';
    authorEl.textContent = book.author;
    card.appendChild(authorEl);
  }

  var meta = document.createElement('div');
  meta.className = 'shelf-book-meta';

  // 3.10a Stage 3 + Phase 1: status-modifier class hook. statusCanon is the
  // normalized canonical value (reading / read / will-read), reused for class
  // and textContent so legacy {want,reading,finished} render uniformly.
  var statusEl = document.createElement('span');
  // Phase 1: normalize legacy {want,reading,finished} -> canonical
  // {will-read,reading,read} for both the class hook and the pill text.
  var statusCanon = normalizeStatus(book.status);
  statusEl.className = 'shelf-book-status shelf-book-status-' + statusCanon;
  statusEl.textContent = statusCanon;
  meta.appendChild(statusEl);

  card.appendChild(meta);

  // 3a (R2): the tap-reveal panel -- every arc this book belongs to
  // (intersectional). Hidden until the thread is tapped (.arcs-open). The first
  // arc is the primary (matches the thread color). The card handler
  // preventDefaults clicks inside the panel so tapping a chip inspects, not navigates.
  if (arcs && arcs.length > 0) {
    var arcsBox = document.createElement('div');
    arcsBox.className = 'shelf-book-arcs';
    var aci;
    for (aci = 0; aci < arcs.length; aci = aci + 1) {
      var arcChip = document.createElement('span');
      arcChip.className = 'arc-chip' + (aci === 0 ? ' is-primary' : '');
      arcChip.style.setProperty('--arc', arcFieldHue(arcs[aci].id));
      arcChip.textContent = arcs[aci].title || 'Untitled arc';
      arcsBox.appendChild(arcChip);
    }
    card.appendChild(arcsBox);
  }

  // 3a/3b (R2): one card-level click handler routes by zone.
  //  - Select mode: any click picks/unpicks the card (never navigates).
  //  - Otherwise: a click on the arc thread reveals ALL arcs; a click inside the
  //    reveal panel inspects (no nav); anywhere else navigates (the anchor href).
  card.addEventListener('click', function (ev) {
    if (shelfSelecting) {
      ev.preventDefault();
      shelfTogglePick(card, book.id);
      return;
    }
    var cls = (ev.target && ev.target.className) ? ('' + ev.target.className) : '';
    if (cls.indexOf('shelf-book-arcthread') > -1) {
      ev.preventDefault();
      shelfToggleReveal(card);
      return;
    }
    if (cls.indexOf('arc-chip') > -1 || cls.indexOf('shelf-book-arcs') > -1) {
      ev.preventDefault();
    }
  });

  return card;
}

// Stage 3 (chrome-fidelity): compact List-view row. Whole-row anchor to
// #book/<id> (browser hashchange handles nav). Title + muted author byline,
// right-aligned status pill (OMITTED when status is falsy -- no invented
// default, unlike the covers card). NO cover thumbnail. The register tick is
// CARRIED from renderShelfBook using the SAME data-driven mechanism + the
// existing .shelf-book-tick class (no new tick CSS authored); omitted for
// unassigned / tokenless traditions, same guard as the covers card.
function renderShelfBookRow(book, isAlight, arcs) {
  var row = document.createElement('a');
  row.className = 'shelf-book-row' + (isAlight ? ' is-alight' : '') + (shelfPicked[book.id] ? ' is-picked' : '');
  row.href = '#book/' + book.id;

  // 3a (R2): arc thread-tie on the row's left spine, primary-arc color. Sits at
  // left:0 (or just inside the register tick when one is present -- has-tick).
  // No reveal panel in the compact row (the covers card carries it); the thread
  // is the at-a-glance tie. Appended first so it anchors the spine.
  if (arcs && arcs.length > 0) {
    var rowArc = document.createElement('span');
    rowArc.className = 'shelf-book-arcthread';
    rowArc.setAttribute('aria-hidden', 'true');
    rowArc.style.setProperty('--arc', arcFieldHue(arcs[0].id));
    row.appendChild(rowArc);
  }

  // S-D2 (Wave 1): the list row has no cover thumbnail, so an alight book gets a
  // small leading gold root-mark (BUILT-DIVERGES: the mockup puts it on the mini
  // cover, which the live list row does not render).
  if (isAlight) {
    var rowRmark = document.createElement('span');
    rowRmark.className = 'shelf-book-rmark shelf-book-row-rmark';
    rowRmark.setAttribute('aria-hidden', 'true');
    row.appendChild(rowRmark);
  }

  var rowTradition = book.traditionOverride || book.tradition;
  if (rowTradition && rowTradition !== 'unassigned' &&
      typeof REGISTER_SHAPE_PATHS[rowTradition] === 'string' &&
      REGISTER_SHAPE_PATHS[rowTradition] !== '') {
    var tick = document.createElement('span');
    tick.className = 'shelf-book-tick';
    tick.setAttribute('aria-hidden', 'true');
    tick.style.setProperty('--tick', 'var(--register-' + rowTradition + ')');
    row.appendChild(tick);
    row.className = row.className + ' has-tick';
  }

  var titleEl = document.createElement('span');
  titleEl.className = 'shelf-book-row-title';
  titleEl.textContent = book.title || '';
  row.appendChild(titleEl);

  if (book.author) {
    var authorEl = document.createElement('span');
    authorEl.className = 'shelf-book-row-author';
    authorEl.textContent = book.author;
    row.appendChild(authorEl);
  }

  // Reuse the covers card's status-pill classes; omit entirely when falsy.
  if (book.status) {
    var statusEl = document.createElement('span');
    var rowStatusCanon = normalizeStatus(book.status);
    statusEl.className = 'shelf-book-status shelf-book-status-' + rowStatusCanon;
    statusEl.textContent = rowStatusCanon;
    row.appendChild(statusEl);
  }

  // 3b (R2): in Select mode a row picks/unpicks instead of navigating.
  row.addEventListener('click', function (ev) {
    if (shelfSelecting) {
      ev.preventDefault();
      shelfTogglePick(row, book.id);
    }
  });

  return row;
}

// Stage 5.6 sub-step 3: renderRegisterGlyph primitive.
//
// Pure function. Returns an SVG string for the tradition's glyph
// at the requested engagement band, or empty string if the inputs
// don't resolve to a valid glyph. Empty string is a real signal —
// the §2.6 "empty space is a real signal" principle from
// docs/knowledge-arcs/knowledge-arcs-visual-system.md.
//
// Inputs:
//   tradition       - one of the 10 TRADITIONS values (see state.js).
//                     'unassigned' deliberately returns empty string.
//   engagementBand  - integer 0, 1, or 2.
//                     0 = light (0 notes), 1 = mid (1-4 notes),
//                     2 = deep (5+ notes). Out-of-range returns empty.
//
// Output:
//   SVG string for valid inputs, ready to drop into the DOM via
//   innerHTML (sub-step 4 wires the shelf integration).
//   Empty string for invalid tradition or band, OR for 'unassigned'.
//
// Reads REGISTER_SHAPE_PATHS (defined in state.js, available at top
// level via the vanilla-JS no-strict-mode pattern). CSS variables
// (--register-X-light/-mid/-deep) are referenced by name in the
// fill attribute; the browser resolves them at paint time.
//
// Pure: same inputs always produce the same output. No state reads
// beyond REGISTER_SHAPE_PATHS, no side effects, no DOM access.
function renderRegisterGlyph(tradition, engagementBand) {
  // Validate band first — cheap integer check.
  if (engagementBand !== 0 && engagementBand !== 1 && engagementBand !== 2) {
    return '';
  }
  // Validate tradition + look up path.
  if (typeof tradition !== 'string') {
    return '';
  }
  var path = REGISTER_SHAPE_PATHS[tradition];
  if (typeof path !== 'string' || path === '') {
    // Catches both unknown traditions (undefined) and 'unassigned' (''empty string).
    return '';
  }
  // Map band to CSS variable suffix.
  var bandSuffix;
  if (engagementBand === 0) {
    bandSuffix = 'light';
  } else if (engagementBand === 1) {
    bandSuffix = 'mid';
  } else {
    bandSuffix = 'deep';
  }
  var fillVar = 'var(--register-' + tradition + '-' + bandSuffix + ')';
  return '<svg viewBox="0 0 24 24" class="register-glyph" xmlns="http://www.w3.org/2000/svg">' +
    '<path d="' + path + '" fill="' + fillVar + '"></path>' +
    '</svg>';
}

// Stage 3.5b fail-soft cover fetch wrapper. Used by both the add-book
// save path (background fetch after sync save completes) and the
// book detail page ISBN re-fetch path (3.5b Stage 2). Contract:
//   - bookId   : the books map key whose coverUrl we patch
//   - isbn     : trimmed, non-empty (caller responsibility)
//   - onComplete(url, result): fires after the patch is durable.
//     url is the final coverUrl value (string or null) after the
//     placeholder filter. result is the raw fetchBookByIsbn return
//     object (or null on null-return / throw). Callers that want
//     to consume metadata fields (title, author, etc.) read them
//     off result; the helper itself only writes coverUrl. Caller
//     decides whether to re-render based on the current route --
//     the helper does NOT touch the DOM.
// Returns coverUrl === null on any of: fetchBookByIsbn returns null,
// throws (defensive -- integrations.js cannot throw to caller today
// but the guard is forward-safe), returns an object whose coverUrl
// is null or empty string, or returns an Open Library "no cover"
// placeholder URL (matched by 'id=0' or '/id/0-' substring).
// Otherwise patches state.books[bookId].coverUrl to the returned URL.
// In all cases calls saveState() before firing onComplete.
function fetchAndApplyCover(bookId, isbn, onComplete) {
  function settle(url, result) {
    if (state.books[bookId]) {
      state.books[bookId].coverUrl = url;
      markBooksDirty();
      saveState();
    }
    if (typeof onComplete === 'function') onComplete(url, result);
  }
  try {
    fetchBookByIsbn(isbn, function(result) {
      var url = null;
      if (result &&
          typeof result.coverUrl === 'string' &&
          result.coverUrl.length > 0 &&
          result.coverUrl.indexOf('id=0') === -1 &&
          result.coverUrl.indexOf('/id/0-') === -1) {
        url = result.coverUrl;
      }
      settle(url, result);
    });
  } catch (e) {
    settle(null, null);
  }
}

// 3.10d: sibling of fetchAndApplyCover for title-imported books.
// Same settle() shape, same placeholder-URL filter (the id=0 / /id/0-
// patterns are OpenLibrary-shaped and won't appear on Google Books
// URLs, but we mirror exactly so future routing changes stay safe).
// markBooksDirty() + saveState() at settle() is the Firestore
// chokepoint; no separate persistence code is added here.
function fetchAndApplyCoverByTitle(bookId, title, author, onComplete) {
  function settle(url, result) {
    if (state.books[bookId]) {
      state.books[bookId].coverUrl = url;
      markBooksDirty();
      saveState();
    }
    if (typeof onComplete === 'function') onComplete(url, result);
  }
  try {
    fetchBookByTitle(title, author, function(result) {
      var url = null;
      if (result &&
          typeof result.coverUrl === 'string' &&
          result.coverUrl.length > 0 &&
          result.coverUrl.indexOf('id=0') === -1 &&
          result.coverUrl.indexOf('/id/0-') === -1) {
        url = result.coverUrl;
      }
      settle(url, result);
    });
  } catch (e) {
    settle(null, null);
  }
}

// 3.10d: progressive missing-cover backfill state. Lives outside
// the DOM because renderShelf() rebuilds the button on every settle
// to populate covers progressively -- state in the DOM would reset
// each tick. renderShelf reads this to decide idle vs running label.
// running === true is the concurrency gate: a second click while a
// backfill is in flight is an immediate no-op (the disabled attr is
// belt-and-suspenders).
var coverResolveState = { running: false, completed: 0, total: 0 };

// 3.10b: shelf filter state. Two nullable strings -- one theme, one
// author -- enforcing single-select per section and AND across
// sections. Memory-only; no localStorage, no URL routing; closing the
// tab clears it. Same shape precedent as coverResolveState above: a
// single object var at file scope, named fields, direct read/write
// from renderShelf and the row click handlers (3.10b Stage 3).
// Theme match is STRICT EQUALITY against book.genre, which the 4b
// backfill wrote from the 5 canonical theme strings verbatim
// (112/112 coverage) -- exact match is correct by construction.
// Author values come from state.books so they match the same way.
// Stage 4c: sections are EXCLUSIVE single-select -- setting a value
// in one section clears the other (see toggleShelfFilter).
var shelfFilter = { author: null, genre: null, theme: null, status: null, tradition: null, category: null, value: null };

// Stage 2C (shelf categories): true while a lazy LLM classification pass is in
// flight, so a re-render does not fire a second pass. Memory-only, same lifetime
// as shelfFilter. Cleared in the classify callback.
var shelfCategorizing = false;
var shelfClassifyGen = 0;        // generation token — invalidates an abandoned pass's late callback

// Stage 4d: author-rail collapse + in-page search state. Memory-only,
// same lifetime contract as shelfFilter above. shelfSearchRaw keeps
// the user's exact text for the re-render's input restore;
// shelfSearchQuery is its trimmed lowercase form, the filter key.
var shelfAuthorRailExpanded = false;
var shelfSearchRaw = '';
var shelfSearchQuery = '';
var shelfSearchTimer = null;
var shelfSearchRefocus = false;

// Stage 2 (mockup-fidelity): desktop inline filter-rail collapse state.
// Memory-only, same lifetime as shelfFilter. On desktop (>=760) the
// theme+author rail is folded behind the Filter button; this flag keeps
// it expanded across re-renders (e.g. a filter-row click) so picking a
// filter does not snap the rail shut. Mobile ignores it and keeps the
// existing overlay panel (shelf-sidebar-mobile-open).
var shelfRailOpen = false;

// 3c (R2): sort order (decision 4). 'added' = date-added desc (default);
// 'status' = reading -> will-read -> read, date-added as the tiebreak. Grouping
// stays on the sidebar Lenses|Categories seg -- this control never touches it.
var shelfSort = 'added';

// 3.10b-i: module-scope reference to the document-level Escape
// listener bound when the mobile filter panel is open. Tracked here
// (not inside renderShelf's closure) so a re-render can purge a
// stale handler that closed over the previous render's detached
// sidebar. Null when no handler is bound. The open/close path in
// renderShelf rotates this slot: open() removes any prior + adds a
// fresh one, dismiss() removes and clears it.
var shelfSidebarEscapeHandler = null;
// MW-1 (P1): the Manage-sheet Escape handler, parked at module scope so a
// re-render can purge a stale one (twin of shelfSidebarEscapeHandler above).
var shelfManageEscapeHandler = null;
// MW-1 (P5): the sticky-title compaction scroll listener, parked at module scope
// so a re-render (which rebuilds the head) purges the stale one before rebinding.
var shelfHeadScrollHandler = null;

// 3b (R2): bulk Select mode -- its ONLY action is Move to arc (no archive, no
// bulk delete). shelfSelecting gates card clicks (pick instead of navigate);
// shelfPicked is the picked book-id set. Both reset on exit / after a move.
var shelfSelecting = false;
var shelfPicked = {};

function shelfToggleReveal(card) {
  if (card.className.indexOf('arcs-open') > -1) {
    card.className = card.className.replace(' arcs-open', '');
  } else {
    card.className = card.className + ' arcs-open';
  }
}

function shelfPickedCount() {
  var n = 0;
  var k;
  for (k in shelfPicked) {
    if (Object.prototype.hasOwnProperty.call(shelfPicked, k)) { n = n + 1; }
  }
  return n;
}

function shelfUpdateSelectbar() {
  var bar = document.getElementById('shelf-selectbar');
  if (!bar) { return; }
  var n = shelfPickedCount();
  var countEl = document.getElementById('shelf-pick-count');
  if (countEl) { countEl.textContent = '' + n; }
  if (n > 0) {
    if (bar.className.indexOf('has-pick') < 0) { bar.className = bar.className + ' has-pick'; }
  } else {
    bar.className = bar.className.replace(' has-pick', '');
  }
}

function shelfTogglePick(card, bookId) {
  if (shelfPicked[bookId]) {
    delete shelfPicked[bookId];
    card.className = card.className.replace(' is-picked', '');
  } else {
    shelfPicked[bookId] = true;
    card.className = card.className + ' is-picked';
  }
  shelfUpdateSelectbar();
}

// Move to arc: reuse the shared arc picker; on pick, add every picked book to
// the chosen arc via the proven addBookToArc + saveState path (state.js:1813) --
// the SAME write the book-detail "Add to an arc" uses. No data-logic change.
function shelfMoveToArc() {
  var host = document.getElementById('shelf-arc-picker-host');
  var user = getCurrentUser();
  if (!host || !user || shelfPickedCount() === 0) { return; }
  var picking = shelfPickedCount();
  host.innerHTML = '';
  host.appendChild(buildArcPickerPanel({
    user: user,
    label: 'Move ' + picking + (picking === 1 ? ' book' : ' books') + ' to an arc',
    onPick: function (arcId) {
      var bk;
      for (bk in shelfPicked) {
        if (!Object.prototype.hasOwnProperty.call(shelfPicked, bk)) { continue; }
        addBookToArc(arcId, bk);
      }
      saveState();
      shelfSelecting = false;
      shelfPicked = {};
      renderShelf();
    },
    onDone: function () {
      var h = document.getElementById('shelf-arc-picker-host');
      if (h) { h.innerHTML = ''; }
    }
  }));
  if (typeof host.scrollIntoView === 'function') {
    host.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }
}

// 9.2: module-scope Escape handler slot for the sub-theory evidence
// rail's mobile bottom sheet, mirroring shelfSidebarEscapeHandler.
// Parked here (not in renderSubTheoryPage's closure) so a re-render
// can purge a stale handler closed over a detached rail. Null when no
// handler is bound.
var subTheoryRailEscapeHandler = null;

// 3.10b Stage 3: single-select toggle. Called by both the click and
// keydown handlers on every .shelf-filter-row. If the section's
// current value === the clicked row's value, clear it (toggle off);
// else replace it (single-select replacement of any prior choice in
// that section). renderShelf is the one re-render entry point -- it
// re-reads shelfFilter to apply the selected class and the match
// predicate in a single pass.
function toggleShelfFilter(section, value) {
  if (shelfFilter[section] === value) {
    shelfFilter[section] = null;
  } else {
    // Stage 4c: exclusive select -- a new pick in one section clears
    // every other section (generic loop, no hardcoded names).
    var sk;
    for (sk in shelfFilter) {
      if (Object.prototype.hasOwnProperty.call(shelfFilter, sk) &&
          sk !== section) {
        shelfFilter[sk] = null;
      }
    }
    shelfFilter[section] = value;
  }
  renderShelf();
}

// 3.10b Stage 3: shared click handler for every .shelf-filter-row
// (theme + author). Reads section + value from the activated
// element's data-* attributes -- single source of truth, immune to
// the var-loop closure trap.
function onShelfFilterRowClick() {
  toggleShelfFilter(
    this.getAttribute('data-filter-section'),
    this.getAttribute('data-filter-value')
  );
}

// Stage 4d: author-rail expand/collapse toggle. Shared by the click
// and keydown handlers on the .shelf-filter-row-toggle row.
function onShelfAuthorToggleClick() {
  shelfAuthorRailExpanded = !shelfAuthorRailExpanded;
  renderShelf();
}

function onShelfAuthorToggleKeydown(ev) {
  if (ev.key === 'Enter' || ev.key === ' ' || ev.key === 'Spacebar') {
    ev.preventDefault();
    shelfAuthorRailExpanded = !shelfAuthorRailExpanded;
    renderShelf();
  }
}

// Stage 4d: debounced search input handler (250ms). Stores the raw
// text for the input restore (casing/spacing preserved) and the
// trimmed lowercase form for the filter predicate; empty input
// clears the filter. Plain function callback -- no arrow.
function onShelfSearchInput() {
  var raw = this.value;
  if (shelfSearchTimer !== null) {
    clearTimeout(shelfSearchTimer);
  }
  shelfSearchTimer = setTimeout(function () {
    shelfSearchTimer = null;
    shelfSearchRaw = raw;
    shelfSearchQuery = raw.toLowerCase().replace(/^\s+|\s+$/g, '');
    shelfSearchRefocus = true;
    renderShelf();
  }, 250);
}

// 3.10b Stage 3: keyboard activation for the same rows. Enter and
// Space both fire toggle, matching native <button> behavior so
// role="button" is honest. preventDefault on Space stops page
// scroll when the focused row is an <li>. Spacebar value is the
// legacy IE key name -- defensive, harmless on modern browsers.
function onShelfFilterRowKeydown(ev) {
  if (ev.key === 'Enter' || ev.key === ' ' || ev.key === 'Spacebar') {
    ev.preventDefault();
    toggleShelfFilter(
      this.getAttribute('data-filter-section'),
      this.getAttribute('data-filter-value')
    );
  }
}

function startCoverBackfill() {
  if (coverResolveState.running) return;
  var user = getCurrentUser();
  if (!user) return;
  var userBookIds = (state.userBooks &&
                     state.userBooks[user.uid] &&
                     state.userBooks[user.uid].bookIds)
    ? state.userBooks[user.uid].bookIds
    : [];
  var queue = [];
  var i;
  for (i = 0; i < userBookIds.length; i++) {
    var bid = userBookIds[i];
    var b = state.books[bid];
    if (b && b.coverUrl === null) {
      queue.push(bid);
    }
  }
  if (queue.length === 0) return;
  coverResolveState.running = true;
  coverResolveState.completed = 0;
  coverResolveState.total = queue.length;
  // Initial render so the button shows "Resolving 0 of N" disabled
  // before the first fetch resolves.
  var partsStart = location.hash.replace(/^#/, '').split('/');
  if (partsStart[0] === 'books') renderShelf();
  var qi = 0;
  function processNextCover() {
    if (qi >= queue.length) {
      // Full reset BEFORE the terminal render so the button renders
      // clean-idle and a second backfill starts from zero.
      coverResolveState.running = false;
      coverResolveState.completed = 0;
      coverResolveState.total = 0;
      var partsDone = location.hash.replace(/^#/, '').split('/');
      if (partsDone[0] === 'books') renderShelf();
      return;
    }
    var nextId = queue[qi];
    qi++;
    var book = state.books[nextId];
    var t = (book && typeof book.title === 'string') ? book.title : '';
    var a = (book && typeof book.author === 'string') ? book.author : '';
    fetchAndApplyCoverByTitle(nextId, t, a, function() {
      coverResolveState.completed = qi;
      var parts = location.hash.replace(/^#/, '').split('/');
      if (parts[0] === 'books') renderShelf();
      processNextCover();
    });
  }
  processNextCover();
}

// Inline add-book editor mounted into #shelf-editor-host. Structurally
// mirrors openMarginaliaEditor: title input + author input (optional)
// + status radio (default 'reading') + genre input (optional) + ISBN
// input + Save/Cancel. Save is disabled when BOTH title AND ISBN are
// empty after trim -- either one alone enables Save. The ISBN-only
// path is the gate that makes the 3.5b Stage 3 metadata backfill
// reachable (and the same gate 3.5c bulk import will use). On Save:
// genBookId, write a complete books record (all 1.9.0 fields plus
// coverUrl:null), ensureUser(uid) + push to userBooks[uid].bookIds,
// saveState, renderShelf. If ISBN non-empty, fire background
// fetchAndApplyCover after the sync render. Cancel re-renders the
// shelf with no writes.
function openShelfEditor() {
  var hostEl = document.getElementById('shelf-editor-host');
  if (!hostEl) return;

  hostEl.innerHTML = '';

  var editor = document.createElement('div');
  editor.className = 'shelf-editor';

  var titleInput = document.createElement('input');
  titleInput.type = 'text';
  titleInput.className = 'shelf-editor-title-input';
  titleInput.placeholder = 'Title';

  var authorInput = document.createElement('input');
  authorInput.type = 'text';
  authorInput.className = 'shelf-editor-author-input';
  authorInput.placeholder = 'Author (optional)';

  // Phase 1: canonical status radios (Currently reading / Have read / Will
  // read). Default 'reading' (manual add of a book you're starting). Writes
  // the canonical vocabulary; labels via STATUS_LABELS.
  var statusWrap = document.createElement('div');
  statusWrap.className = 'shelf-editor-status';
  var statuses = STATUS_VOCAB;
  var statusRadios = [];
  var s;
  for (s = 0; s < statuses.length; s++) {
    var label = document.createElement('label');
    label.className = 'shelf-editor-status-option';
    var radio = document.createElement('input');
    radio.type = 'radio';
    radio.name = 'shelf-editor-status';
    radio.value = statuses[s];
    if (statuses[s] === 'reading') radio.checked = true;
    statusRadios.push(radio);
    label.appendChild(radio);
    label.appendChild(document.createTextNode(' ' + STATUS_LABELS[statuses[s]]));
    statusWrap.appendChild(label);
  }

  // 3.10c Stage 4: free-text <input> swapped for a <select> populated
  // from SHELF_THEMES. First option carries value '' for "no theme
  // selected" — books with empty or legacy non-SHELF_THEMES genre
  // values land on this option without rewriting their stored
  // string. The variable name 'genreInput' is preserved so the
  // save-handler read at genreInput.value below is byte-unchanged
  // (.value contract is identical across <input> and <select>).
  // .placeholder is dropped — <select> does not honor placeholder;
  // the 'No theme' option replaces its semantics.
  var genreInput = document.createElement('select');
  genreInput.className = 'shelf-editor-genre-input';
  var emptyOpt = document.createElement('option');
  emptyOpt.value = '';
  emptyOpt.textContent = 'No theme';
  genreInput.appendChild(emptyOpt);
  var gi;
  var opt;
  for (gi = 0; gi < SHELF_THEMES.length; gi++) {
    opt = document.createElement('option');
    opt.value = SHELF_THEMES[gi];
    opt.textContent = SHELF_THEMES[gi];
    genreInput.appendChild(opt);
  }

  var isbnInput = document.createElement('input');
  isbnInput.type = 'text';
  isbnInput.className = 'shelf-editor-isbn-input';
  isbnInput.placeholder = 'ISBN (optional)';

  var actions = document.createElement('div');
  actions.className = 'shelf-editor-actions';

  var saveBtn = document.createElement('button');
  saveBtn.type = 'button';
  saveBtn.className = 'shelf-editor-save';
  saveBtn.textContent = 'Save';
  saveBtn.disabled = true;

  var cancelBtn = document.createElement('button');
  cancelBtn.type = 'button';
  cancelBtn.className = 'shelf-editor-cancel';
  cancelBtn.textContent = 'Cancel';

  // Shared toggle: Save enabled when at least one of title or ISBN
  // is non-empty after trim. Attached to both inputs so either
  // field driving non-empty enables the button. Author and genre
  // play no validation role; status always has a default selection.
  function updateSaveDisabledState() {
    var titleHas = titleInput.value.replace(/^\s+|\s+$/g, '').length > 0;
    var isbnHas  = isbnInput.value.replace(/^\s+|\s+$/g, '').length > 0;
    saveBtn.disabled = !(titleHas || isbnHas);
  }
  titleInput.addEventListener('input', updateSaveDisabledState);
  isbnInput.addEventListener('input', updateSaveDisabledState);

  saveBtn.addEventListener('click', function() {
    var titleTrimmed = titleInput.value.replace(/^\s+|\s+$/g, '');
    var isbnTrimmed  = isbnInput.value.replace(/^\s+|\s+$/g, '');
    // Defensive gate mirrors the Save-disabled toggle: bail if BOTH
    // are empty. The toggle keeps the button disabled in that state,
    // so this is belt-and-suspenders against future drift.
    if (titleTrimmed.length === 0 && isbnTrimmed.length === 0) return;
    var user = getCurrentUser();
    if (!user) return;

    var authorTrimmed = authorInput.value.replace(/^\s+|\s+$/g, '');
    var genreTrimmed  = genreInput.value.replace(/^\s+|\s+$/g, '');

    var statusValue = 'reading';
    var i;
    for (i = 0; i < statusRadios.length; i++) {
      if (statusRadios[i].checked) {
        statusValue = statusRadios[i].value;
        break;
      }
    }

    // CX-2 (data-dup): if this book is already on the shelf (shared identity key),
    // do NOT mint a duplicate. Fold: close the editor and open the copy the reader
    // already has, so the intent resolves without a second record.
    var dupExistingId = findShelfBookByIdentity(user.uid, titleTrimmed, authorTrimmed);
    if (dupExistingId) {
      renderShelf();
      location.hash = '#book/' + dupExistingId;
      return;
    }

    var now = Date.now();
    var id  = genBookId();

    state.books[id] = {
      id:       id,
      title:    titleTrimmed,
      author:   authorTrimmed,
      isbn:     isbnTrimmed,
      addedAt:  now,
      status:   statusValue,
      genre:    genreTrimmed,
      coverUrl: null
    };
    // 5.6 sub-step 1: chokepoint call — see js/state.js ensureBookFields.
    // Stamps tradition + traditionOverride on the new book so it carries
    // the 5.6 schema regardless of which write path it entered through.
    ensureBookFields(state.books[id]);

    // ensureUser is defensive against fresh accounts whose state.users
    // and state.userBooks records have not been seeded yet. After this
    // call, state.userBooks[uid].bookIds is guaranteed to be an array.
    if (typeof ensureUser === 'function') {
      ensureUser(user.uid);
    }
    state.userBooks[user.uid].bookIds.push(id);
    markBookPending(user.uid, id);  // P0: protect until Firestore-confirmed

    markBooksDirty();
    saveState();
    renderShelf();

    // 3.5b: background cover fetch. The user-visible save path is
    // already complete -- editor closed, row painted, state durable.
    // When the callback eventually fires (or fails soft), we patch
    // state.books[id].coverUrl and re-render only if the user is
    // still looking at the shelf. Route inspection rather than
    // state.currentBookId === null because #notebook also clears
    // currentBookId, and re-rendering the shelf from a notebook
    // route would clobber the Notebook surface.
    if (isbnTrimmed.length > 0) {
      fetchAndApplyCover(id, isbnTrimmed, function(url, result) {
        // 3.5b Stage 3: conditionally backfill title and author
        // from the fetch result -- only when the user's form fields
        // were blank at save time (titleTrimmed/authorTrimmed
        // closure-captured from the save handler scope). The user's
        // typed values are authoritative; we only fill the gaps.
        // Same fail-soft contract as coverUrl: typeof-string +
        // length>0 guard treats null/empty/undefined as missing
        // metadata and leaves the existing record value alone.
        if (state.books[id]) {
          var metaChanged = false;
          if (titleTrimmed === '' &&
              result &&
              typeof result.title === 'string' &&
              result.title.length > 0) {
            state.books[id].title = result.title;
            metaChanged = true;
          }
          if (authorTrimmed === '' &&
              result &&
              typeof result.author === 'string' &&
              result.author.length > 0) {
            state.books[id].author = result.author;
            metaChanged = true;
          }
          if (metaChanged) {
            markBooksDirty();
            saveState();
          }
        }
        var parts = location.hash.replace(/^#/, '').split('/');
        if (parts[0] === 'books') {
          renderShelf();
        }
      });
    } else if (titleTrimmed.length > 0) {
      // 3.10e: mirror of the ISBN background-fetch above, but on the
      // title path. Fires fetchAndApplyCoverByTitle on save; on
      // settle, conditionally backfills isbn + author when those
      // user-form fields were blank at save time. Title is never
      // backfilled -- it is the query input, and writing Google's
      // normalized echo over the user's typed title would be a
      // silent mutation. publishYear is intentionally NOT written:
      // no existing book record carries it, opportunistic property-
      // writes would produce a sparse schema, and proper adoption
      // is its own future stage.
      fetchAndApplyCoverByTitle(id, titleTrimmed, authorTrimmed, function(url, result) {
        if (state.books[id]) {
          var metaChanged = false;
          if (isbnTrimmed === '' &&
              result &&
              typeof result.isbn === 'string' &&
              result.isbn.length > 0) {
            state.books[id].isbn = result.isbn;
            metaChanged = true;
          }
          if (authorTrimmed === '' &&
              result &&
              typeof result.author === 'string' &&
              result.author.length > 0) {
            state.books[id].author = result.author;
            metaChanged = true;
          }
          if (metaChanged) {
            markBooksDirty();
            saveState();
          }
        }
        var parts = location.hash.replace(/^#/, '').split('/');
        if (parts[0] === 'books') {
          renderShelf();
        }
      });
    }
  });

  cancelBtn.addEventListener('click', function() {
    renderShelf();
  });

  actions.appendChild(saveBtn);
  actions.appendChild(cancelBtn);
  editor.appendChild(titleInput);
  editor.appendChild(authorInput);
  editor.appendChild(statusWrap);
  editor.appendChild(genreInput);
  editor.appendChild(isbnInput);
  editor.appendChild(actions);
  hostEl.appendChild(editor);

  titleInput.focus();
}

// Stage 3.5c bulk add: multi-line text editor mounted into the same
// #shelf-editor-host openShelfEditor uses. On Submit, processBulkLines
// parses + dedupes + writes per-entry, then drains a sequential ISBN
// fetch queue (sequential callback chain, per Praxis conventions).
// The save-path mirror is intentionally inlined rather than factored
// into a shared writer: at one-and-a-maybe callers (3.5d/3.5e may or
// may not want the same writer), the abstraction does not yet earn
// its keep. Extract when a second real caller arrives.
function openBulkAddEditor(prefillText) {
  var hostEl = document.getElementById('shelf-editor-host');
  if (!hostEl) return;

  hostEl.innerHTML = '';

  var editor = document.createElement('div');
  editor.className = 'shelf-bulk-editor';

  var textarea = document.createElement('textarea');
  textarea.className = 'shelf-bulk-editor-textarea';
  textarea.placeholder = 'One ISBN or title per line';
  textarea.rows = 8;
  // 6.1c: optional prefill (scan hand-off passes the extracted titles,
  // one per line). Zero-arg callers leave prefillText undefined -> empty.
  if (typeof prefillText === 'string' && prefillText.length > 0) {
    textarea.value = prefillText;
  }

  var actions = document.createElement('div');
  actions.className = 'shelf-bulk-editor-actions';

  var submitBtn = document.createElement('button');
  submitBtn.type = 'button';
  submitBtn.className = 'shelf-bulk-editor-submit';
  submitBtn.textContent = 'Submit';

  var cancelBtn = document.createElement('button');
  cancelBtn.type = 'button';
  cancelBtn.className = 'shelf-bulk-editor-cancel';
  cancelBtn.textContent = 'Cancel';

  submitBtn.addEventListener('click', function() {
    processBulkLines(textarea.value);
  });

  cancelBtn.addEventListener('click', function() {
    renderShelf();
  });

  actions.appendChild(submitBtn);
  actions.appendChild(cancelBtn);
  editor.appendChild(textarea);
  editor.appendChild(actions);
  hostEl.appendChild(editor);

  textarea.focus();
}

// 6.2a: scan review editor. Mounts inline into #shelf-editor-host (same
// idiom as openBulkAddEditor) and shows one editable row per extracted
// title, plus add/remove controls. Confirm collects the row values and
// hands the joined list to processBulkLines -- byte-for-byte the same
// write path the bulk textarea uses; this editor never writes directly.
// Reuses the .shelf-bulk-editor container chrome + the submit/cancel
// button family; only the rows/heading/remove/add carry new classes.
function openScanReviewEditor(titles) {
  var hostEl = document.getElementById('shelf-editor-host');
  if (!hostEl) return;

  hostEl.innerHTML = '';

  var editor = document.createElement('div');
  editor.className = 'shelf-bulk-editor shelf-scan-review';

  var heading = document.createElement('div');
  heading.className = 'shelf-scan-review-heading';
  heading.textContent = 'Review scanned titles';

  var rowsWrap = document.createElement('div');
  rowsWrap.className = 'shelf-scan-review-rows';

  // Build one editable row. The row element is closure-captured so the
  // remove button targets the right node regardless of add/remove order.
  // Enter inside a row input is absorbed (preventDefault) so a stray
  // keystroke never commits the list -- Confirm is the only commit path.
  function addRow(value, focusIt) {
    var row = document.createElement('div');
    row.className = 'shelf-scan-review-row';

    var input = document.createElement('input');
    input.type = 'text';
    input.className = 'shelf-scan-review-input';
    if (typeof value === 'string') {
      input.value = value;
    }
    input.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.keyCode === 13) {
        e.preventDefault();
      }
    });

    var removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.className = 'shelf-scan-review-remove';
    removeBtn.setAttribute('aria-label', 'Remove title');
    removeBtn.textContent = '×';
    removeBtn.addEventListener('click', function() {
      if (row.parentNode) {
        row.parentNode.removeChild(row);
      }
    });

    row.appendChild(input);
    row.appendChild(removeBtn);
    rowsWrap.appendChild(row);
    if (focusIt) {
      input.focus();
    }
    return input;
  }

  var i;
  for (i = 0; i < titles.length; i++) {
    var t = titles[i];
    if (typeof t !== 'string') {
      t = String(t);
    }
    addRow(t, false);
  }

  var addCtl = document.createElement('button');
  addCtl.type = 'button';
  addCtl.className = 'shelf-scan-review-add';
  addCtl.textContent = '+ Add a title';
  addCtl.addEventListener('click', function() {
    addRow('', true);
  });

  var actions = document.createElement('div');
  actions.className = 'shelf-bulk-editor-actions';

  var confirmBtn = document.createElement('button');
  confirmBtn.type = 'button';
  confirmBtn.className = 'shelf-bulk-editor-submit';
  confirmBtn.textContent = 'Confirm';
  confirmBtn.addEventListener('click', function() {
    var inputs = rowsWrap.querySelectorAll('.shelf-scan-review-input');
    var lines = [];
    var k;
    for (k = 0; k < inputs.length; k++) {
      var v = inputs[k].value.replace(/^\s+|\s+$/g, '');
      if (v.length > 0) {
        lines.push(v);
      }
    }
    // Zero non-empty rows on Confirm behaves like Cancel -- no write.
    if (lines.length === 0) {
      renderShelf();
      return;
    }
    processBulkLines(lines.join('\n'));
  });

  var cancelBtn = document.createElement('button');
  cancelBtn.type = 'button';
  cancelBtn.className = 'shelf-bulk-editor-cancel';
  cancelBtn.textContent = 'Cancel';
  cancelBtn.addEventListener('click', function() {
    renderShelf();
  });

  // Esc anywhere in the editor cancels (cheap; matches the picker idiom).
  editor.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' || e.keyCode === 27) {
      renderShelf();
    }
  });

  actions.appendChild(confirmBtn);
  actions.appendChild(cancelBtn);
  editor.appendChild(heading);
  editor.appendChild(rowsWrap);
  editor.appendChild(addCtl);
  editor.appendChild(actions);
  hostEl.appendChild(editor);
}

// Parse a pasted blob into entries, write each entry to state, then
// drain a sequential ISBN fetch queue. Per-entry write mirrors the
// openShelfEditor save path (state.books record + userBooks push +
// saveState + renderShelf). ISBN detection: strip hyphens/spaces,
// uppercase, then match either 13 digits or 9-digits-plus-(digit|X)
// for ISBN-10. Within-list dedupe on normalized ISBN only -- titles
// can legitimately repeat across editions and the user can sort
// that out. Title lines write a title-only record with isbn:''; the
// 3.5b save path already accepts title-OR-ISBN, so no schema work.
function processBulkLines(raw) {
  var user = getCurrentUser();
  if (!user) return;

  var lines = raw.split('\n');
  var entries = [];
  var seenIsbns = {};
  // CX-2 (data-dup): seed the dedup sets from the EXISTING shelf so a bulk paste
  // never re-adds a book already on the shelf (prior-add dedup, not just within-
  // paste). ISBN-form lines dedup on normalized ISBN; title-form lines dedup on
  // the shared identity key (title+author -- the same key merge uses).
  var seenTitleKey = {};
  (function () {
    var ex = (state.userBooks && state.userBooks[user.uid] && state.userBooks[user.uid].bookIds)
      ? state.userBooks[user.uid].bookIds : [];
    var xi, xb, xisbn;
    for (xi = 0; xi < ex.length; xi++) {
      xb = state.books[ex[xi]];
      if (!xb) { continue; }
      if (xb.isbn) {
        xisbn = ('' + xb.isbn).replace(/[\s-]/g, '').toUpperCase();
        if (xisbn) { seenIsbns[xisbn] = true; }
      }
      var xkey = bookIdentityKey(xb.title, xb.author);
      if (xkey !== 'ta:|') { seenTitleKey[xkey] = true; }   // empty identity is not a dup signal
    }
  })();
  var i;
  for (i = 0; i < lines.length; i++) {
    var line = lines[i].replace(/^\s+|\s+$/g, '');
    if (line.length === 0) continue;

    var normalized = line.replace(/[\s-]/g, '').toUpperCase();
    var isIsbn = false;
    if (/^[0-9]{13}$/.test(normalized)) isIsbn = true;
    else if (/^[0-9]{9}[0-9X]$/.test(normalized)) isIsbn = true;

    if (isIsbn) {
      if (seenIsbns[normalized]) continue;
      seenIsbns[normalized] = true;
      entries.push({ kind: 'isbn', value: normalized });
    } else {
      // CX-2: dedup title-form lines on the shared identity key -- against the
      // seeded shelf keys AND earlier lines in this same paste (title lines
      // previously had NO dedup at all). Author is unknown at paste time, so
      // this catches exact-title repeats + empty-author shelf copies; a title
      // line matching an already-authored shelf book is still caught later by
      // Tidy-library's post-resolution merge.
      var tkey = bookIdentityKey(line, '');
      if (tkey !== 'ta:|') {
        if (seenTitleKey[tkey]) { continue; }
        seenTitleKey[tkey] = true;
      }
      entries.push({ kind: 'title', value: line });
    }
  }

  if (entries.length === 0) {
    renderShelf();
    return;
  }

  if (typeof ensureUser === 'function') {
    ensureUser(user.uid);
  }

  // Per-entry write loop. Single saveState per entry (not batched at
  // end) so a mid-import tab close leaves localStorage consistent.
  // renderShelf is called per entry as the spec prescribes; at
  // synchronous loop pace only the final render paints, which is
  // fine -- all rows appear in one tick. Subsequent renderShelf
  // calls happen from the fetch queue as covers resolve.
  var isbnQueue = [];
  var j;
  for (j = 0; j < entries.length; j++) {
    var entry = entries[j];
    var now = Date.now();
    var id = genBookId();
    if (entry.kind === 'isbn') {
      state.books[id] = {
        id:       id,
        title:    '',
        author:   '',
        isbn:     entry.value,
        addedAt:  now,
        status:   'reading',
        genre:    '',
        coverUrl: null
      };
      ensureBookFields(state.books[id]);    // 5.6 sub-step 1 chokepoint
      isbnQueue.push({ kind: 'isbn', bookId: id, isbn: entry.value });
    } else {
      state.books[id] = {
        id:       id,
        title:    entry.value,
        author:   '',
        isbn:     '',
        addedAt:  now,
        status:   'reading',
        genre:    '',
        coverUrl: null
      };
      ensureBookFields(state.books[id]);    // 5.6 sub-step 1 chokepoint
      // 3.10e: title-form bulk lines now queue for background
      // resolution alongside ISBN-form lines. Same sequential queue,
      // discriminated by the kind field.
      isbnQueue.push({ kind: 'title', bookId: id, title: entry.value });
    }
    state.userBooks[user.uid].bookIds.push(id);
    markBookPending(user.uid, id);  // P0: protect until Firestore-confirmed
    markBooksDirty();
    saveState();
    renderShelf();
  }

  // Sequential fetch queue. Callback chain -- one fetch in flight at
  // a time, advance on settle (success or fail). 3.10e: queue now
  // carries both ISBN-form items (kind: 'isbn', resolved via
  // fetchAndApplyCover) and title-form items (kind: 'title', resolved
  // via fetchAndApplyCoverByTitle). Per-resolve metadata backfill
  // mirrors the openShelfEditor 3.5b / 3.10e paths: only patch when
  // the current record value is still blank (the user could in theory
  // have edited the row between submit and resolve; the freshness
  // check protects that). Re-render only when the user is still on
  // #books so we don't clobber other surfaces.
  var qi = 0;
  function processNext() {
    if (qi >= isbnQueue.length) return;
    var item = isbnQueue[qi];
    qi++;
    if (item.kind === 'title') {
      // 3.10e: title-form path. Author is sent as '' because bulk-
      // import title-form lines carry no author -- fetchBookByTitle
      // skips the +inauthor: qualifier when author is empty. Backfill
      // patches isbn + author when blank; title is the query input
      // and never backfilled. publishYear intentionally not written
      // (see Stage 1 single-add comment for rationale).
      fetchAndApplyCoverByTitle(item.bookId, item.title, '', function(url, result) {
        if (state.books[item.bookId]) {
          var metaChanged = false;
          if (state.books[item.bookId].isbn === '' &&
              result &&
              typeof result.isbn === 'string' &&
              result.isbn.length > 0) {
            state.books[item.bookId].isbn = result.isbn;
            metaChanged = true;
          }
          if (state.books[item.bookId].author === '' &&
              result &&
              typeof result.author === 'string' &&
              result.author.length > 0) {
            state.books[item.bookId].author = result.author;
            metaChanged = true;
          }
          if (metaChanged) {
            markBooksDirty();
            saveState();
          }
        }
        var parts = location.hash.replace(/^#/, '').split('/');
        if (parts[0] === 'books') {
          renderShelf();
        }
        processNext();
      });
      return;
    }
    fetchAndApplyCover(item.bookId, item.isbn, function(url, result) {
      if (state.books[item.bookId]) {
        var metaChanged = false;
        if (state.books[item.bookId].title === '' &&
            result &&
            typeof result.title === 'string' &&
            result.title.length > 0) {
          state.books[item.bookId].title = result.title;
          metaChanged = true;
        }
        if (state.books[item.bookId].author === '' &&
            result &&
            typeof result.author === 'string' &&
            result.author.length > 0) {
          state.books[item.bookId].author = result.author;
          metaChanged = true;
        }
        if (metaChanged) {
          markBooksDirty();
          saveState();
        }
      }
      var parts = location.hash.replace(/^#/, '').split('/');
      if (parts[0] === 'books') {
        renderShelf();
      }
      processNext();
    });
  }
  processNext();
}

// 6.1b: downscale a chosen photo on a canvas before upload. The longest
// edge is clamped to 1600px (never upscaled; aspect preserved); the
// canvas re-encodes to JPEG quality 0.85, so the output mediaType is
// always image/jpeg regardless of the input format. cb(err) on failure,
// cb(null, bareBase64, outW, outH) on success -- the data: prefix is
// stripped so the bare base64 matches vision-proxy's contract. The
// object URL is revoked on both the load and error paths.
function downscaleShelfPhoto(file, cb) {
  var url = URL.createObjectURL(file);
  var img = new Image();
  img.onload = function() {
    var w = img.naturalWidth;
    var h = img.naturalHeight;
    var scale = Math.min(1, 1600 / Math.max(w, h));
    var outW = Math.max(1, Math.round(w * scale));
    var outH = Math.max(1, Math.round(h * scale));
    var canvas = document.createElement('canvas');
    canvas.width = outW;
    canvas.height = outH;
    var ctx = canvas.getContext('2d');
    ctx.drawImage(img, 0, 0, outW, outH);
    var dataUrl = canvas.toDataURL('image/jpeg', 0.85);
    URL.revokeObjectURL(url);
    var base64 = dataUrl.replace(/^data:[^;]*;base64,/, '');
    cb(null, base64, outW, outH);
  };
  img.onerror = function() {
    URL.revokeObjectURL(url);
    cb(new Error('image decode failed'));
  };
  img.src = url;
}

// 6.1b: scan handler. Runs only once a file is actually chosen (the
// cancel path leaves the picker with no files, so the busy state never
// engages). Downscales, logs the payload size, POSTs bare base64 to
// vision-proxy, and console-logs the returned titles. Two-arg
// .then(onOk, onErr) throughout -- never .catch (ES3 parse harness).
// Phase 3: normalize a vision-proxy response into [{title,author,legibility}].
// Accepts the new {books:[{title,author,legibility}]} shape and the legacy
// {titles:[...]} string array (lifted to author '', legibility 'partial').
function scanResponseToSpecs(json) {
  var specs = [];
  if (!json) { return specs; }
  var i, b, t, s;
  if (Object.prototype.toString.call(json.books) === '[object Array]') {
    for (i = 0; i < json.books.length; i++) {
      b = json.books[i];
      if (!b || typeof b !== 'object') { continue; }
      t = (typeof b.title === 'string') ? b.title.replace(/^\s+|\s+$/g, '') : '';
      if (t.length === 0) { continue; }
      specs.push({
        title:      t,
        author:     (typeof b.author === 'string') ? b.author.replace(/^\s+|\s+$/g, '') : '',
        legibility: (b.legibility === 'clear') ? 'clear' : 'partial'
      });
    }
  } else if (Object.prototype.toString.call(json.titles) === '[object Array]') {
    for (i = 0; i < json.titles.length; i++) {
      s = json.titles[i];
      if (typeof s !== 'string') { s = String(s); }
      s = s.replace(/^\s+|\s+$/g, '');
      if (s.length === 0) { continue; }
      specs.push({ title: s, author: '', legibility: 'partial' });
    }
  }
  return specs;
}

// Phase 3: hand a resolved single-book lookup (barcode / manual) to the review
// screen. Guarded so Stage-3 inputs are verifiable before the Stage-4 screen lands.
function handoffResolvedSingle(result, source) {
  if (typeof openBookReview === 'function') {
    openBookReview([result], source);
  }
}

// Stage 5: lazy-load @zxing/library (UMD) ON DEMAND -- only when the barcode
// scanner opens on a browser WITHOUT native BarcodeDetector (iPhone Safari).
// NEVER part of the core bundle / SW precache. The external lib is exempt from
// the ES3 client rules; this loader + its call sites are ES3. Idempotent and
// queues concurrent callers; cb(true) once window.ZXing is ready, cb(false) on
// failure (the ISBN type-in fallback always remains the safety net).
var zxingLoadState = 'idle'; // idle | loading | ready | failed
var zxingLoadQueue = [];
function zxingReady() {
  return !!(window.ZXing && typeof window.ZXing.BrowserMultiFormatReader === 'function');
}
function flushZxingQueue(ok) {
  var q = zxingLoadQueue, i;
  zxingLoadQueue = [];
  for (i = 0; i < q.length; i++) { q[i](ok); }
}
function loadZxingLibrary(cb) {
  if (zxingReady()) { cb(true); return; }
  if (zxingLoadState === 'failed') { cb(false); return; }
  zxingLoadQueue.push(cb);
  if (zxingLoadState === 'loading') { return; }
  zxingLoadState = 'loading';
  var s = document.createElement('script');
  s.src = 'https://cdn.jsdelivr.net/npm/@zxing/library@0.20.0/umd/index.min.js';
  s.async = true;
  s.onload = function() {
    var ok = zxingReady();
    zxingLoadState = ok ? 'ready' : 'failed';
    flushZxingQueue(ok);
  };
  s.onerror = function() {
    zxingLoadState = 'failed';
    flushZxingQueue(false);
  };
  document.head.appendChild(s);
}

// Phase 3 / Stage 5: barcode / ISBN input (mockup C). A live camera decode runs
// via native BarcodeDetector where present (Chrome/Android) and via an
// on-demand @zxing/library decode where it is not (iPhone Safari). An ISBN
// type-in fallback is ALWAYS present. A decoded/typed ISBN runs through the
// shared resolver, then the review screen.
function openBarcodeScanner() {
  var hostEl = document.getElementById('shelf-editor-host');
  if (!hostEl) { return; }
  hostEl.innerHTML = '';

  var hasDetector = (typeof window.BarcodeDetector === 'function');
  var canCamera = !!(navigator.mediaDevices && typeof navigator.mediaDevices.getUserMedia === 'function');
  var stream = null;
  var scanning = false;
  var zxingReader = null;
  function stopCamera() {
    scanning = false;
    if (zxingReader) {
      try { zxingReader.reset(); } catch (eR) {}
      zxingReader = null;
    }
    if (stream) {
      var tracks = stream.getTracks(), ti;
      for (ti = 0; ti < tracks.length; ti++) { tracks[ti].stop(); }
      stream = null;
    }
  }

  var wrap = document.createElement('div');
  wrap.className = 'barcode-scanner';

  var heading = document.createElement('div');
  heading.className = 'barcode-scanner-heading';
  heading.textContent = 'Scan a barcode';
  wrap.appendChild(heading);
  var sub = document.createElement('p');
  sub.className = 'barcode-scanner-sub';
  sub.textContent = canCamera
    ? 'Point your camera at the back-cover barcode.'
    : 'Your browser can’t scan live — type the ISBN below.';
  wrap.appendChild(sub);

  var frame = document.createElement('div');
  frame.className = 'scan-frame';
  var view = document.createElement('div');
  view.className = 'scan-view';

  var video = document.createElement('video');
  video.className = 'scan-cam-video';
  video.setAttribute('playsinline', 'true');
  video.muted = true;
  view.appendChild(video);

  var reticle = document.createElement('div');
  reticle.className = 'reticle';
  var corners = ['tl', 'tr', 'bl', 'br'], ci;
  for (ci = 0; ci < corners.length; ci++) {
    var corner = document.createElement('span');
    corner.className = 'corner ' + corners[ci];
    reticle.appendChild(corner);
  }
  var scanline = document.createElement('span');
  scanline.className = 'scanline';
  reticle.appendChild(scanline);
  view.appendChild(reticle);

  var hint = document.createElement('div');
  hint.className = 'scan-hint';
  hint.textContent = 'point at the barcode';
  view.appendChild(hint);
  frame.appendChild(view);

  // ISBN type-in fallback (always present).
  var fb = document.createElement('div');
  fb.className = 'isbn-fallback';
  var fbLab = document.createElement('div');
  fbLab.className = 'if-lab';
  fbLab.textContent = canCamera ? 'No scanner? Type the ISBN' : 'Type the ISBN';
  fb.appendChild(fbLab);
  var fbRow = document.createElement('div');
  fbRow.className = 'if-row';
  var isbnInput = document.createElement('input');
  isbnInput.type = 'text';
  isbnInput.setAttribute('inputmode', 'numeric');
  isbnInput.setAttribute('placeholder', '978…');
  fbRow.appendChild(isbnInput);
  var findBtn = document.createElement('button');
  findBtn.type = 'button';
  findBtn.className = 'barcode-find-btn';
  findBtn.textContent = 'Find';
  fbRow.appendChild(findBtn);
  fb.appendChild(fbRow);
  frame.appendChild(fb);
  wrap.appendChild(frame);

  var status = document.createElement('div');
  status.className = 'barcode-scanner-status';
  wrap.appendChild(status);

  var cancelBtn = document.createElement('button');
  cancelBtn.type = 'button';
  cancelBtn.className = 'barcode-scanner-cancel';
  cancelBtn.textContent = 'Cancel';
  wrap.appendChild(cancelBtn);

  function lookupIsbn(rawIsbn) {
    var isbn = ('' + (rawIsbn || '')).replace(/[\s-]/g, '');
    if (isbn.length === 0) { return; }
    stopCamera();
    status.textContent = 'Looking up ' + isbn + '…';
    resolveBook({ kind: 'isbn', isbn: isbn }, function(result) {
      handoffResolvedSingle(result, 'barcode');
    });
  }

  findBtn.addEventListener('click', function() { lookupIsbn(isbnInput.value); });
  isbnInput.addEventListener('keydown', function(e) {
    if (e.key === 'Enter' || e.keyCode === 13) { e.preventDefault(); lookupIsbn(isbnInput.value); }
  });
  cancelBtn.addEventListener('click', function() { stopCamera(); renderShelf(); });
  wrap.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' || e.keyCode === 27) { stopCamera(); renderShelf(); }
  });

  hostEl.appendChild(wrap);

  // Start the live camera + decode loop only when BarcodeDetector + getUserMedia
  // are both available. Any failure (no permission, no camera) silently leaves
  // the ISBN fallback as the path -- never blocks the user.
  if (hasDetector && canCamera) {
    navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } }).then(function(s) {
      stream = s;
      video.srcObject = s;
      var playPromise = video.play();
      if (playPromise && typeof playPromise.then === 'function') { playPromise.then(function(){}, function(){}); }
      scanning = true;
      var detector = new window.BarcodeDetector({ formats: ['ean_13', 'ean_8', 'upc_a', 'upc_e'] });
      function tick() {
        if (!scanning || !stream) { return; }
        detector.detect(video).then(function(codes) {
          if (!scanning) { return; }
          if (codes && codes.length > 0 && codes[0].rawValue) {
            lookupIsbn(codes[0].rawValue);
            return;
          }
          if (typeof requestAnimationFrame === 'function') { requestAnimationFrame(tick); }
        }, function() {
          if (scanning && typeof requestAnimationFrame === 'function') { requestAnimationFrame(tick); }
        });
      }
      if (typeof requestAnimationFrame === 'function') { requestAnimationFrame(tick); }
    }, function() {
      status.textContent = 'Camera unavailable — type the ISBN above.';
    });
  } else if (canCamera) {
    // Stage 5: no native BarcodeDetector (iPhone Safari). Lazy-load zxing ONLY
    // now and decode EAN-13/ISBN from the live camera. Any failure falls back to
    // the ever-present ISBN type-in -- never blocks the user.
    status.textContent = 'Starting camera…';
    loadZxingLibrary(function(ok) {
      // Bail if the user left the scanner while the lib was loading.
      if (!video || !document.body.contains(video)) { return; }
      if (!ok || !zxingReady()) {
        status.textContent = 'Live scan unavailable — type the ISBN above.';
        return;
      }
      try {
        zxingReader = new window.ZXing.BrowserMultiFormatReader();
        scanning = true;
        status.textContent = '';
        var onZxResult = function(result) {
          if (!scanning) { return; }
          if (result && typeof result.getText === 'function') { lookupIsbn(result.getText()); }
        };
        if (typeof zxingReader.decodeFromConstraints === 'function') {
          zxingReader.decodeFromConstraints({ video: { facingMode: { ideal: 'environment' } } }, video, onZxResult);
        } else if (typeof zxingReader.decodeFromVideoDevice === 'function') {
          zxingReader.decodeFromVideoDevice(null, video, onZxResult);
        } else {
          status.textContent = 'Live scan unavailable — type the ISBN above.';
        }
      } catch (eZ) {
        status.textContent = 'Camera unavailable — type the ISBN above.';
      }
    });
  }
}

// Phase 3: manual lookup (mockup C "Add manually"). Title/author OR ISBN ->
// the shared resolver -> the review screen. Distinct from the legacy direct-add
// editor: this path verifies the book before it lands.
function openManualLookup() {
  var hostEl = document.getElementById('shelf-editor-host');
  if (!hostEl) { return; }
  hostEl.innerHTML = '';
  var wrap = document.createElement('div');
  wrap.className = 'manual-lookup';
  var heading = document.createElement('div');
  heading.className = 'manual-lookup-heading';
  heading.textContent = 'Add a book';
  wrap.appendChild(heading);

  function field(labelText, ph) {
    var f = document.createElement('label');
    f.className = 'manual-lookup-field';
    var lab = document.createElement('span');
    lab.className = 'manual-lookup-label';
    lab.textContent = labelText;
    var inp = document.createElement('input');
    inp.type = 'text';
    inp.className = 'manual-lookup-input';
    inp.setAttribute('placeholder', ph);
    f.appendChild(lab);
    f.appendChild(inp);
    wrap.appendChild(f);
    return inp;
  }
  var titleInput = field('Title', 'Book title');
  var authorInput = field('Author', 'Author (optional)');
  var isbnInput = field('or ISBN', '978… (optional)');

  var status = document.createElement('div');
  status.className = 'manual-lookup-status';
  wrap.appendChild(status);

  var actions = document.createElement('div');
  actions.className = 'manual-lookup-actions';
  var lookupBtn = document.createElement('button');
  lookupBtn.type = 'button';
  lookupBtn.className = 'manual-lookup-submit';
  lookupBtn.textContent = 'Look up';
  var cancelBtn = document.createElement('button');
  cancelBtn.type = 'button';
  cancelBtn.className = 'manual-lookup-cancel';
  cancelBtn.textContent = 'Cancel';
  actions.appendChild(lookupBtn);
  actions.appendChild(cancelBtn);
  wrap.appendChild(actions);

  function doLookup() {
    var isbn = isbnInput.value.replace(/[\s-]/g, '');
    var title = titleInput.value.replace(/^\s+|\s+$/g, '');
    var author = authorInput.value.replace(/^\s+|\s+$/g, '');
    var query;
    if (isbn.length > 0) {
      query = { kind: 'isbn', isbn: isbn };
    } else if (title.length > 0) {
      query = { kind: 'title', title: title, author: author };
    } else {
      status.textContent = 'Enter a title or an ISBN.';
      return;
    }
    status.textContent = 'Looking up…';
    resolveBook(query, function(result) { handoffResolvedSingle(result, 'manual'); });
  }
  lookupBtn.addEventListener('click', doLookup);
  cancelBtn.addEventListener('click', function() { renderShelf(); });
  wrap.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' || e.keyCode === 27) { renderShelf(); }
  });
  hostEl.appendChild(wrap);
  titleInput.focus();
}

// Stage 3: a session registry of book ids whose stored cover URL(s) all FAILED
// to load -- i.e. the shelf is showing the typographic placeholder for them.
// The cleanup pass reads this so its "missing / wrong cover" count matches what
// the shelf actually shows (a stored-but-broken coverUrl is invisible to a
// null-only check). Populated by buildSelfHealingCover as covers render.
var coverBrokenIds = {};
function isCoverBroken(id) { return !!(id && coverBrokenIds[id]); }

// Phase 6 (Stage 1): a self-healing cover element shared by the shelf card,
// the book-detail header, and the review row. Walks coverCandidates
// (OpenLibrary-by-ISBN -> Google image) on <img> onerror and, once they are
// all exhausted -- or when there are none -- shows the typographic placeholder
// built by placeholderFn. So a 404 / blank / null cover NEVER leaves a broken
// image or an empty card on any surface. imgClass is the surface's cover-image
// class; returns the <img> OR the placeholder node for the caller to append.
function buildSelfHealingCover(book, imgClass, placeholderFn) {
  var candidates = (book && book.coverCandidates && book.coverCandidates.length > 0)
    ? book.coverCandidates.slice()
    : ((book && book.coverUrl) ? [book.coverUrl] : []);
  if (candidates.length === 0) { return placeholderFn(); }
  var img = document.createElement('img');
  img.className = imgClass;
  img.alt = '';
  var ci = 0;
  img.src = candidates[ci];
  // A cover that loads is NOT broken -- clear any stale registry mark (Stage 3).
  img.addEventListener('load', function() {
    if (book && book.id) { delete coverBrokenIds[book.id]; }
  });
  img.addEventListener('error', function() {
    ci = ci + 1;
    if (ci < candidates.length) {
      img.src = candidates[ci];
    } else {
      // Stage 3: all candidates exhausted -> mark broken so cleanup counts it.
      if (book && book.id) { coverBrokenIds[book.id] = true; }
      if (img.parentNode) { img.parentNode.replaceChild(placeholderFn(), img); }
    }
  });
  return img;
}

// Phase 4: a cover element for a resolved book (review row). No-match yields a
// "?" frame; otherwise a self-healing cover (candidate-walk -> "cover pending"
// typographic placeholder) via the shared buildSelfHealingCover helper.
function makeReviewCover(book, isNoMatch) {
  var cover = document.createElement('div');
  cover.className = 'cover';
  if (isNoMatch) {
    var unk = document.createElement('div'); unk.className = 'cover-unknown';
    var q = document.createElement('span'); q.className = 'cu-q'; q.textContent = '?';
    var lab = document.createElement('span'); lab.className = 'cu-lab'; lab.textContent = 'no match';
    unk.appendChild(q); unk.appendChild(lab); cover.appendChild(unk);
    return cover;
  }
  cover.appendChild(buildSelfHealingCover(book, 'cover-img', function() {
    var pend = document.createElement('div'); pend.className = 'cover-pending';
    var pt = document.createElement('span'); pt.className = 'cp-ti'; pt.textContent = book.title || '';
    var pl = document.createElement('span'); pl.className = 'cp-lab'; pl.textContent = 'cover pending';
    pend.appendChild(pt); pend.appendChild(pl);
    return pend;
  }));
  return cover;
}

// Phase 4: the per-row read-status control (mockup .rstatus). Defaults to the
// passed value; onChange(canonicalValue) fires on select.
function makeReadStatusControl(current, onChange) {
  var box = document.createElement('div');
  box.className = 'rstatus';
  box.setAttribute('data-status', current);
  var opts = [
    { v: 'reading',   l: 'Currently reading' },
    { v: 'read',      l: 'Have read' },
    { v: 'will-read', l: 'Will read' }
  ];
  var i;
  for (i = 0; i < opts.length; i++) {
    (function(opt) {
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'rs-opt' + (opt.v === current ? ' on' : '');
      b.setAttribute('data-v', opt.v);
      b.textContent = opt.l;
      b.addEventListener('click', function() {
        var sibs = box.querySelectorAll('.rs-opt'), k;
        for (k = 0; k < sibs.length; k++) { sibs[k].classList.remove('on'); }
        b.classList.add('on');
        box.setAttribute('data-status', opt.v);
        if (typeof onChange === 'function') { onChange(opt.v); }
      });
      box.appendChild(b);
    })(opts[i]);
  }
  return box;
}

// Phase 4: the Review & Confirm screen (mockup A + B). Consumes resolved
// results from the inputs (S3) through the resolver (S2), one editable row per
// book: auto-picked match (cover/author/year/meta), a confidence flag, a
// "not this one?" edition picker, a per-row read-status control DEFAULTING to
// "Have read", a "Mark all as read" bulk, and never-drop states (no-cover
// placeholder, no-match editable manual entry). Confirm writes through the
// P0-safe path (pendingBookSync + the schema-1.20 fields).
function openBookReview(resolved, source) {
  var hostEl = document.getElementById('shelf-editor-host');
  if (!hostEl) { return; }
  var user = getCurrentUser();
  if (!user) { return; }
  hostEl.innerHTML = '';

  var rowStates = [];
  var ri;
  for (ri = 0; ri < resolved.length; ri++) {
    rowStates.push({
      result:    resolved[ri],
      book:      resolved[ri].book,
      status:    'read',
      isNoMatch: (resolved[ri].status === 'none'),
      pickerOpen: false,
      _titleInput: null,
      _authorInput: null
    });
  }

  var wrap = document.createElement('section');
  wrap.className = 'book-review';
  var eyebrow = document.createElement('div');
  eyebrow.className = 'book-review-eyebrow';
  eyebrow.textContent = (source === 'scan') ? 'Shelf scan · review' : 'Review';
  var h1 = document.createElement('h1');
  h1.className = 'book-review-title';
  h1.textContent = 'Review your books';
  var sub = document.createElement('p');
  sub.className = 'book-review-sub';
  wrap.appendChild(eyebrow); wrap.appendChild(h1); wrap.appendChild(sub);

  var bar = document.createElement('div'); bar.className = 'review-bar';
  var rbLeft = document.createElement('div'); rbLeft.className = 'rb-left';
  var rbCount = document.createElement('span'); rbCount.className = 'rb-count';
  rbLeft.appendChild(rbCount);
  var rbRight = document.createElement('div'); rbRight.className = 'rb-right';
  var markAllBtn = document.createElement('button');
  markAllBtn.type = 'button'; markAllBtn.className = 'review-mark-all'; markAllBtn.textContent = 'Mark all as read';
  var confirmBtn = document.createElement('button');
  confirmBtn.type = 'button'; confirmBtn.className = 'review-confirm';
  rbRight.appendChild(markAllBtn); rbRight.appendChild(confirmBtn);
  bar.appendChild(rbLeft); bar.appendChild(rbRight);
  wrap.appendChild(bar);

  var rowsWrap = document.createElement('div'); rowsWrap.className = 'review-rows';
  wrap.appendChild(rowsWrap);

  var cancelBtn = document.createElement('button');
  cancelBtn.type = 'button'; cancelBtn.className = 'book-review-cancel'; cancelBtn.textContent = 'Cancel';
  cancelBtn.addEventListener('click', function() { renderShelf(); });
  wrap.appendChild(cancelBtn);

  function flagOf(rs) {
    if (rs.isNoMatch) { return 'none'; }
    var weak = (rs.result.status === 'weak') ||
      (rs.result.query && rs.result.query.legibility === 'partial');
    return weak ? 'low' : 'high';
  }

  function updateBar() {
    var flagged = 0, i;
    for (i = 0; i < rowStates.length; i++) { if (flagOf(rowStates[i]) !== 'high') { flagged++; } }
    rbCount.textContent = rowStates.length + (rowStates.length === 1 ? ' book' : ' books') + ' matched'
      + (flagged > 0 ? ' · ' + flagged + ' need a look' : '');
    confirmBtn.textContent = 'Confirm & save ' + rowStates.length + ' →';
    sub.textContent = 'We matched ' + rowStates.length + (rowStates.length === 1 ? ' book' : ' books')
      + '. Confirm each, set how you read it, then save.';
  }

  function renderRow(rs) {
    var flag = flagOf(rs);
    var row = document.createElement('div');
    row.className = 'rrow' + (flag === 'low' ? ' flagged' : '') + (flag === 'none' ? ' nomatch' : '');
    var dataState = (flag === 'none') ? 'no-match' : (flag === 'low' ? 'low-confidence' : 'high-confidence');
    if (flag !== 'none' && !rs.book.coverUrl &&
        (!rs.book.coverCandidates || rs.book.coverCandidates.length === 0)) {
      dataState = 'no-cover';
    }
    row.setAttribute('data-state', dataState);

    row.appendChild(makeReviewCover(rs.book, rs.isNoMatch));

    var main = document.createElement('div'); main.className = 'rrow-main';
    if (rs.isNoMatch) {
      var scannedAs = document.createElement('div'); scannedAs.className = 'scanned-as';
      scannedAs.appendChild(document.createTextNode('scanned as '));
      var sab = document.createElement('b');
      sab.textContent = '“' + ((rs.result.query && (rs.result.query.title || rs.result.query.isbn)) || '') + '”';
      scannedAs.appendChild(sab);
      scannedAs.appendChild(document.createTextNode(' — no confident match. Edit below.'));
      main.appendChild(scannedAs);
      var manualGrid = document.createElement('div'); manualGrid.className = 'manual';
      var fT = document.createElement('div'); fT.className = 'fld fld-wide';
      var lT = document.createElement('label'); lT.textContent = 'Title'; fT.appendChild(lT);
      rs._titleInput = document.createElement('input'); rs._titleInput.type = 'text';
      rs._titleInput.value = rs.book.title || (rs.result.query && rs.result.query.title) || '';
      fT.appendChild(rs._titleInput); manualGrid.appendChild(fT);
      var fA = document.createElement('div'); fA.className = 'fld fld-wide';
      var lA = document.createElement('label'); lA.textContent = 'Author'; fA.appendChild(lA);
      rs._authorInput = document.createElement('input'); rs._authorInput.type = 'text';
      rs._authorInput.value = rs.book.author || '';
      fA.appendChild(rs._authorInput); manualGrid.appendChild(fA);
      main.appendChild(manualGrid);
    } else {
      var ti = document.createElement('div'); ti.className = 'rrow-ti'; ti.textContent = rs.book.title || '';
      main.appendChild(ti);
      if (rs.book.author) {
        var au = document.createElement('div'); au.className = 'rrow-au'; au.textContent = rs.book.author;
        main.appendChild(au);
      }
      var metaParts = [];
      if (rs.book.year) { metaParts.push(rs.book.year); }
      if (rs.book.publisher) { metaParts.push(rs.book.publisher); }
      if (rs.book.pageCount) { metaParts.push(rs.book.pageCount + ' pp'); }
      if (rs.book.isbn) { metaParts.push('ISBN ' + rs.book.isbn); }
      var meta = document.createElement('div'); meta.className = 'rrow-meta';
      meta.textContent = metaParts.join(' · ');
      main.appendChild(meta);
    }

    var flags = document.createElement('div'); flags.className = 'rrow-flags';
    var conf = document.createElement('span');
    if (flag === 'high') { conf.className = 'conf conf-high'; conf.textContent = 'match'; }
    else if (flag === 'low') { conf.className = 'conf conf-low'; conf.textContent = 'check this'; }
    else { conf.className = 'conf conf-none'; conf.textContent = 'no match'; }
    flags.appendChild(conf);
    if (!rs.isNoMatch && rs.result.alternates && rs.result.alternates.length > 0) {
      var notThis = document.createElement('button');
      notThis.type = 'button'; notThis.className = 'notthis';
      notThis.textContent = rs.pickerOpen ? 'close editions' : 'not this one?';
      notThis.addEventListener('click', function() { rs.pickerOpen = !rs.pickerOpen; rebuild(); });
      flags.appendChild(notThis);
    }
    main.appendChild(flags);

    if (rs.pickerOpen && rs.result.alternates && rs.result.alternates.length > 0) {
      var picker = document.createElement('div');
      picker.className = 'edition-picker'; picker.setAttribute('data-state', 'edition-picker');
      var epHead = document.createElement('div'); epHead.className = 'ep-head';
      var epT = document.createElement('span'); epT.className = 'ep-t'; epT.textContent = 'Choose the right edition';
      epHead.appendChild(epT); picker.appendChild(epHead);
      var epGrid = document.createElement('div'); epGrid.className = 'ep-grid';
      var allEds = [rs.result.book].concat(rs.result.alternates);
      var ei;
      for (ei = 0; ei < allEds.length; ei++) {
        (function(ed) {
          var card = document.createElement('div');
          card.className = 'edition-card' + (ed === rs.book ? ' selected' : '');
          card.setAttribute('data-edition', '');
          card.appendChild(makeReviewCover(ed, false));
          var em = document.createElement('div'); em.className = 'ec-main';
          var epub = document.createElement('div'); epub.className = 'ec-pub'; epub.textContent = ed.publisher || ed.title || '';
          var eau = document.createElement('div'); eau.className = 'ec-au'; eau.textContent = ed.author || '';
          var emeta = document.createElement('div'); emeta.className = 'ec-meta';
          var edParts = [];
          if (ed.year) { edParts.push(ed.year); }
          if (ed.pageCount) { edParts.push(ed.pageCount + ' pp'); }
          emeta.textContent = edParts.join(' · ');
          var epick = document.createElement('div'); epick.className = 'ec-pick'; epick.textContent = '✓ selected';
          em.appendChild(epub); em.appendChild(eau); em.appendChild(emeta); em.appendChild(epick);
          card.appendChild(em);
          card.addEventListener('click', function() { rs.book = ed; rs.pickerOpen = false; rebuild(); });
          epGrid.appendChild(card);
        })(allEds[ei]);
      }
      picker.appendChild(epGrid);
      main.appendChild(picker);
    }

    row.appendChild(main);

    var right = document.createElement('div'); right.className = 'rrow-right';
    right.appendChild(makeReadStatusControl(rs.status, (function(rsRef) {
      return function(v) { rsRef.status = v; };
    })(rs)));
    row.appendChild(right);

    return row;
  }

  function rebuild() {
    rowsWrap.innerHTML = '';
    var i;
    for (i = 0; i < rowStates.length; i++) { rowsWrap.appendChild(renderRow(rowStates[i])); }
    updateBar();
  }

  markAllBtn.addEventListener('click', function() {
    var i;
    for (i = 0; i < rowStates.length; i++) { rowStates[i].status = 'read'; }
    rebuild();
  });
  confirmBtn.addEventListener('click', function() { confirmReviewBooks(rowStates, user); });

  hostEl.appendChild(wrap);
  rebuild();
}

// Phase 4: write confirmed review rows to the shelf through the P0-safe path.
// One state.books record per row carrying the schema-1.20 fields; markBookPending
// protects each id until Firestore confirms (mergeRemoteBookDoc guard). Empty
// manual rows are skipped. Per-entry saveState mirrors processBulkLines' crash
// consistency.
function confirmReviewBooks(rowStates, user) {
  if (typeof ensureUser === 'function') { ensureUser(user.uid); }
  var i;
  for (i = 0; i < rowStates.length; i++) {
    var rs = rowStates[i];
    var title, author, isbn, year, pageCount, publisher, description, coverUrl, coverCandidates;
    if (rs.isNoMatch) {
      title = rs._titleInput ? rs._titleInput.value.replace(/^\s+|\s+$/g, '') : (rs.book.title || '');
      if (title.length === 0) { continue; }
      author = rs._authorInput ? rs._authorInput.value.replace(/^\s+|\s+$/g, '') : '';
      isbn = (rs.result.query && rs.result.query.isbn) || '';
      year = null; pageCount = null; publisher = ''; description = ''; coverUrl = null; coverCandidates = [];
    } else {
      title = rs.book.title || '';
      if (title.length === 0) { continue; }
      author = rs.book.author || '';
      isbn = rs.book.isbn || '';
      year = rs.book.year || null;
      pageCount = (typeof rs.book.pageCount === 'number') ? rs.book.pageCount : null;
      publisher = rs.book.publisher || '';
      description = rs.book.description || '';
      coverUrl = rs.book.coverUrl || null;
      // Stage 1: persist the FULL candidate list, not just coverUrl[0]. The
      // review row may have shown a later candidate (coverUrl[0] 404'd); the
      // shelf walks the same list so "shown == saved" after confirm + reload.
      coverCandidates = (rs.book.coverCandidates && rs.book.coverCandidates.length > 0)
        ? rs.book.coverCandidates.slice()
        : (coverUrl ? [coverUrl] : []);
    }
    var now = Date.now();
    var id = genBookId();
    state.books[id] = {
      id: id, title: title, author: author, isbn: isbn, addedAt: now,
      status: rs.status || 'read', genre: '', coverUrl: coverUrl,
      coverCandidates: coverCandidates,
      pageCount: pageCount, publisher: publisher, year: year,
      description: description, rating: null, dateRead: null
    };
    ensureBookFields(state.books[id]);
    state.userBooks[user.uid].bookIds.push(id);
    markBookPending(user.uid, id);
    markBooksDirty();
    saveState();
  }
  renderShelf();
}

// Stage 6: delete a book DURABLY. Removes it from state.books + the user's
// index, scrubs every reference (arc membership, sub-theory book-evidence,
// notebook entry bookIds, theme membership, the book artifact), then marks the
// delete pending (so a stale remote read cannot resurrect it -- see
// mergeRemoteBookDoc) and flushes through the booksDirty -> Firestore chokepoint.
// Each scrubbed collection is marked dirty so its cleanup also syncs. Returns
// true on success.
function deleteBook(uid, id) {
  if (!uid || !id || !state.books || !state.books[id]) { return false; }

  // 1. the user's book index
  if (state.userBooks && state.userBooks[uid] && state.userBooks[uid].bookIds) {
    var ub = state.userBooks[uid].bookIds, nextUb = [], ui;
    for (ui = 0; ui < ub.length; ui++) { if (ub[ui] !== id) { nextUb.push(ub[ui]); } }
    state.userBooks[uid].bookIds = nextUb;
  }

  // 2. the record itself
  delete state.books[id];

  // 3. arc membership (bookIds entries are {id,addedAt} or a bare id string)
  var arcsTouched = false;
  var am = state.arcs || {}, ak;
  for (ak in am) {
    if (am.hasOwnProperty(ak) && am[ak] && am[ak].bookIds) {
      var arr = am[ak].bookIds, kept = [], bi, hit = false;
      for (bi = 0; bi < arr.length; bi++) {
        var ent = arr[bi]; var eid = (ent && ent.id) ? ent.id : ent;
        if (eid === id) { hit = true; } else { kept.push(ent); }
      }
      if (hit) { am[ak].bookIds = kept; arcsTouched = true; }
    }
  }

  // 4. sub-theory book-evidence ({kind:'book', refId:<bookId>})
  var subsTouched = false;
  var sm = state.subTheories || {}, sk;
  for (sk in sm) {
    if (sm.hasOwnProperty(sk) && sm[sk] && sm[sk].evidence) {
      var ev = sm[sk].evidence, keptEv = [], ei, evHit = false;
      for (ei = 0; ei < ev.length; ei++) {
        if (ev[ei] && ev[ei].kind === 'book' && ev[ei].refId === id) { evHit = true; }
        else { keptEv.push(ev[ei]); }
      }
      if (evHit) { sm[sk].evidence = keptEv; subsTouched = true; }
    }
  }

  // 5. notebook entry bookIds (covers marginalia / journal / question)
  var notesTouched = false;
  var em = state.notebookEntries || {}, ek;
  for (ek in em) {
    if (em.hasOwnProperty(ek) && em[ek] && em[ek].bookIds) {
      var be = em[ek].bookIds, nb = [], bj, nHit = false;
      for (bj = 0; bj < be.length; bj++) { if (be[bj] === id) { nHit = true; } else { nb.push(be[bj]); } }
      if (nHit) { em[ek].bookIds = nb; notesTouched = true; }
    }
  }

  // 6. theme membership
  var themesTouched = false;
  var tm = state.userThemes || {}, tk;
  for (tk in tm) {
    if (tm.hasOwnProperty(tk) && tm[tk] && tm[tk].bookIds) {
      var tbb = tm[tk].bookIds, nt = [], tj, thHit = false;
      for (tj = 0; tj < tbb.length; tj++) { if (tbb[tj] === id) { thHit = true; } else { nt.push(tbb[tj]); } }
      if (thHit) { tm[tk].bookIds = nt; themesTouched = true; }
    }
  }

  // 7. the book artifact for this (uid, book)
  var artifactTouched = false;
  if (state.bookArtifacts && typeof artifactKey === 'function') {
    var artK = artifactKey(uid, id);
    if (state.bookArtifacts[artK]) { delete state.bookArtifacts[artK]; artifactTouched = true; }
  }

  // 8. durability: stop guarding it as a pending ADD; start guarding the DELETE
  if (typeof clearPendingBookSync === 'function') { clearPendingBookSync(uid, [id]); }
  if (typeof markBookDeletePending === 'function') { markBookDeletePending(uid, id); }

  // mark every collection we scrubbed so its cleanup persists to Firestore
  markBooksDirty();
  if (arcsTouched && typeof markArcsDirty === 'function') { markArcsDirty(); }
  if (notesTouched && typeof markNotebookDirty === 'function') { markNotebookDirty(); }
  if (subsTouched && typeof markSubTheoriesDirty === 'function') { markSubTheoriesDirty(); }
  if (themesTouched && typeof markThemesDirty === 'function') { markThemesDirty(); }
  if (artifactTouched && typeof markArtifactsDirty === 'function') { markArtifactsDirty(); }
  saveState();
  return true;
}

// =====================================================================
// Phase 6 -- existing-library cleanup (mockup E). Mechanism + UI.
// =====================================================================

// CX-2 (data-dup): the canonical duplicate-identity key -- normalized
// title+author (the ISBN branch was removed so a title-only copy and an
// ISBN-bearing copy of the same work still collide). ONE source, shared by
// scanLibraryForCleanup's grouping AND the add-guards below, so "duplicate"
// never means two different things.
function bookIdentityKey(title, author) {
  return 'ta:' + resolverNormalize(title || '') + '|' + resolverNormalize(author || '');
}

// Returns an existing shelf book id for this user whose identity key matches the
// candidate title/author, or null. Scans the user's deduped bookIds index (the
// real shelf), so the add-guard tests against what the shelf actually holds.
function findShelfBookByIdentity(uid, title, author) {
  var key = bookIdentityKey(title, author);
  // An empty identity (blank title AND author -- e.g. an ISBN-only add whose
  // title has not resolved yet) is NOT a duplicate signal. Never fold on it,
  // or every ISBN-only add would collapse onto a stuck empty-title record.
  if (key === 'ta:|') { return null; }
  var ids = (state.userBooks && state.userBooks[uid] && state.userBooks[uid].bookIds)
    ? state.userBooks[uid].bookIds : [];
  var i, b;
  for (i = 0; i < ids.length; i++) {
    b = state.books[ids[i]];
    if (b && bookIdentityKey(b.title, b.author) === key) { return ids[i]; }
  }
  return null;
}

// Scan one user's shelf for (a) duplicate/near-duplicate records and (b) books
// with no cover. Duplicate key = the shared bookIdentityKey (normalized
// title+author). Returns { duplicates:[[ids],...], missingCovers:[ids], total }.
function scanLibraryForCleanup(uid) {
  var out = { duplicates: [], missingCovers: [], wrongCovers: [], total: 0 };
  var ub = (state.userBooks && state.userBooks[uid] && state.userBooks[uid].bookIds)
    ? state.userBooks[uid].bookIds : [];
  var groups = {};
  var i, id, b, key;
  for (i = 0; i < ub.length; i++) {
    id = ub[i]; b = state.books[id];
    if (!b) { continue; }
    out.total = out.total + 1;
    // Stage 3: a book is "missing cover" when coverUrl is null/empty (never had
    // one), and "wrong cover" when it HAS a coverUrl that failed to load (the
    // shelf is showing the placeholder -- coverBrokenIds registry). Both feed
    // the count, so it matches the blank cards on the shelf, not just nulls.
    if (!b.coverUrl || ('' + b.coverUrl).replace(/^\s+|\s+$/g, '') === '') { out.missingCovers.push(id); }
    else if (isCoverBroken(id)) { out.wrongCovers.push(id); }
    // Group by the shared identity key (normalized title+author) so a title-only
    // copy and an ISBN-bearing copy of the same book still collide. Same key the
    // add-guard uses -- one notion of "duplicate".
    key = bookIdentityKey(b.title, b.author);
    if (!groups[key]) { groups[key] = []; }
    groups[key].push(id);
  }
  var gk;
  for (gk in groups) {
    if (!groups.hasOwnProperty(gk)) { continue; }
    // R-x: blank-identity books ('ta:|' -- e.g. distinct ISBN-only adds whose
    // titles never resolved, or titles that normalize to empty) are NOT
    // duplicates of each other; they just share an empty key. Never cluster them
    // for the destructive merge (it would delete a distinct book's identity).
    // Same "empty identity is not a dup signal" invariant the add-guards enforce.
    if (gk === 'ta:|') { continue; }
    if (groups[gk].length > 1) { out.duplicates.push(groups[gk].slice()); }
  }
  return out;
}

// Merge duplicate records into keepId: preserve the read/finished status (if any
// copy is 'read', keep is read with the earliest finishedAt), fill keep's blank
// bibliographic fields from the dropped copies, re-point marginalia + arc
// membership from dropped ids onto keepId (deduped), then drop the extras. The
// kept record's own notes/status are never discarded.
function mergeBookDuplicates(uid, keepId, dropIds) {
  var keep = state.books[keepId];
  if (!keep || !dropIds || dropIds.length === 0) { return; }
  // Data-loss invariant: the survivor is NEVER a drop. A corrupted bookIds index
  // (keepId duplicated into a dup group) would otherwise delete AND tombstone the
  // survivor from Firestore below. Filter it out of the drop list up front.
  var safeDrops = [], sdi;
  for (sdi = 0; sdi < dropIds.length; sdi++) { if (dropIds[sdi] !== keepId) { safeDrops.push(dropIds[sdi]); } }
  dropIds = safeDrops;
  if (dropIds.length === 0) { return; }
  var dropSet = {}, di, d;
  for (di = 0; di < dropIds.length; di++) { dropSet[dropIds[di]] = true; }

  var anyRead = (normalizeStatus(keep.status) === 'read');
  var earliest = (typeof keep.finishedAt === 'number') ? keep.finishedAt : null;
  for (di = 0; di < dropIds.length; di++) {
    d = state.books[dropIds[di]];
    if (!d) { continue; }
    if (normalizeStatus(d.status) === 'read') {
      anyRead = true;
      if (typeof d.finishedAt === 'number' && (earliest === null || d.finishedAt < earliest)) { earliest = d.finishedAt; }
    }
    if (!keep.coverUrl && d.coverUrl) { keep.coverUrl = d.coverUrl; }
    if (!keep.isbn && d.isbn) { keep.isbn = d.isbn; }
    if (typeof keep.pageCount !== 'number' && typeof d.pageCount === 'number') { keep.pageCount = d.pageCount; }
    if (!keep.publisher && d.publisher) { keep.publisher = d.publisher; }
    if (!keep.year && d.year) { keep.year = d.year; }
    if (!keep.description && d.description) { keep.description = d.description; }
    if (!keep.genre && d.genre) { keep.genre = d.genre; }
  }
  if (anyRead) { keep.status = 'read'; if (earliest !== null) { keep.finishedAt = earliest; } }
  ensureBookFields(keep);

  var em = state.notebookEntries || {}, ek;
  for (ek in em) {
    if (em.hasOwnProperty(ek) && em[ek] && em[ek].bookIds) {
      var nb = [], seen = {}, bi, bid;
      for (bi = 0; bi < em[ek].bookIds.length; bi++) {
        bid = em[ek].bookIds[bi];
        if (dropSet[bid]) { bid = keepId; }
        if (!seen[bid]) { seen[bid] = true; nb.push(bid); }
      }
      em[ek].bookIds = nb;
    }
  }

  var am = state.arcs || {}, ak;
  for (ak in am) {
    if (am.hasOwnProperty(ak) && am[ak] && am[ak].bookIds) {
      var nbids = [], seenA = {}, ai, entry, eid, mapped;
      for (ai = 0; ai < am[ak].bookIds.length; ai++) {
        entry = am[ak].bookIds[ai];
        eid = (entry && entry.id) ? entry.id : entry;
        mapped = dropSet[eid] ? keepId : eid;
        if (!seenA[mapped]) {
          seenA[mapped] = true;
          nbids.push((entry && entry.id) ? { id: mapped, addedAt: entry.addedAt } : mapped);
        }
      }
      am[ak].bookIds = nbids;
    }
  }

  // CX-1 parity: the collections deleteBook scrubs (views.js:7088) that merge was
  // MISSING -- REPOINT drop ids onto the survivor (preserve the user's writing;
  // merge is a re-point, not a destroy), then tombstone the dropped ids below.

  // sub-theory book-evidence: REPOINT {kind:'book', refId:drop} -> keepId IN
  // PLACE. Each evidence entry carries its own quote + annotation (distinct
  // passages), so we NEVER dedup/collapse two entries that resolve to keepId --
  // that would silently destroy a quote. deleteBook removes this evidence (the
  // book is gone); merge keeps every entry, re-pointed at the survivor.
  var subsTouched = false;
  var sm = state.subTheories || {}, sk;
  for (sk in sm) {
    if (!sm.hasOwnProperty(sk) || !sm[sk] || !sm[sk].evidence) { continue; }
    var ev = sm[sk].evidence, ei, evi;
    for (ei = 0; ei < ev.length; ei++) {
      evi = ev[ei];
      if (evi && evi.kind === 'book' && dropSet[evi.refId]) { evi.refId = keepId; subsTouched = true; }
    }
  }

  // theme membership: repoint drop -> keep, deduped.
  var themesTouched = false;
  var tm = state.userThemes || {}, tk;
  for (tk in tm) {
    if (!tm.hasOwnProperty(tk) || !tm[tk] || !tm[tk].bookIds) { continue; }
    var tbb = tm[tk].bookIds, ntb = [], seenT = {}, tj, tid, chgT = false;
    for (tj = 0; tj < tbb.length; tj++) {
      tid = tbb[tj];
      if (dropSet[tid]) { tid = keepId; chgT = true; }
      if (!seenT[tid]) { seenT[tid] = true; ntb.push(tid); }
      else { chgT = true; }
    }
    if (chgT) { tm[tk].bookIds = ntb; themesTouched = true; }
  }

  // book artifacts: repoint each drop's artifact onto keep (principle 3: one
  // artifact per user per book). If keep has none, move drop's over; if both
  // exist, keep stays canonical and drop's writing is appended under a merge
  // marker -- never silently destroyed. Then delete the orphaned drop key.
  var artifactTouched = false;
  if (state.bookArtifacts && typeof artifactKey === 'function') {
    var keepAK = artifactKey(uid, keepId);
    for (di = 0; di < dropIds.length; di++) {
      var dropAK = artifactKey(uid, dropIds[di]);
      var dropArt = state.bookArtifacts[dropAK];
      if (!dropArt) { continue; }
      var keepArt = state.bookArtifacts[keepAK];
      if (!keepArt) {
        dropArt.bookId = keepId;
        state.bookArtifacts[keepAK] = dropArt;
      } else {
        var dTitle = (typeof dropArt.title === 'string') ? dropArt.title : '';
        var dBody = (typeof dropArt.body === 'string') ? dropArt.body : '';
        var addition = '';
        if (dTitle.replace(/^\s+|\s+$/g, '') !== '') { addition = addition + dTitle + '\n'; }
        if (dBody.replace(/^\s+|\s+$/g, '') !== '') { addition = addition + dBody; }
        if (addition !== '') {
          if (typeof keepArt.body !== 'string') { keepArt.body = ''; }
          keepArt.body = keepArt.body + '\n\n— merged from a duplicate copy —\n' + addition;
        }
        if (typeof ensureArtifactFields === 'function') { ensureArtifactFields(keepArt); }
      }
      delete state.bookArtifacts[dropAK];
      artifactTouched = true;
    }
  }

  var ub = state.userBooks[uid].bookIds, newUb = [], ui;
  for (ui = 0; ui < ub.length; ui++) { if (!dropSet[ub[ui]]) { newUb.push(ub[ui]); } }
  state.userBooks[uid].bookIds = newUb;
  for (di = 0; di < dropIds.length; di++) { delete state.books[dropIds[di]]; }
  // CX-1 parity: tombstone the dropped ids exactly as deleteBook does -- stop
  // guarding them as pending ADDs, and mark them pending-DELETE so a stale/racing
  // remote read cannot RESURRECT a merged-away duplicate via mergeRemoteBookDoc's
  // remote-wins path. NEVER tombstone keepId: it is the surviving add.
  if (typeof clearPendingBookSync === 'function') { clearPendingBookSync(uid, dropIds); }
  if (typeof markBookDeletePending === 'function') {
    for (di = 0; di < dropIds.length; di++) { markBookDeletePending(uid, dropIds[di]); }
  }
  markBookPending(uid, keepId);
  markBooksDirty();
  if (typeof markArcsDirty === 'function') { markArcsDirty(); }
  if (typeof markNotebookDirty === 'function') { markNotebookDirty(); }
  if (subsTouched && typeof markSubTheoriesDirty === 'function') { markSubTheoriesDirty(); }
  if (themesTouched && typeof markThemesDirty === 'function') { markThemesDirty(); }
  if (artifactTouched && typeof markArtifactsDirty === 'function') { markArtifactsDirty(); }
  saveState();
}

// Re-resolve one book through the shared resolver and apply a found cover (and
// fill any blank bibliographic fields). callback(applied:boolean).
function reResolveCover(bookId, callback) {
  var b = state.books[bookId];
  if (!b) { if (typeof callback === 'function') { callback(false); } return; }
  var query = (b.isbn && ('' + b.isbn).replace(/[\s-]/g, '').length > 0)
    ? { kind: 'isbn', isbn: b.isbn }
    : { kind: 'title', title: b.title || '', author: b.author || '' };
  resolveBook(query, function(result) {
    var applied = false;
    if (result && result.status !== 'none' && result.book && state.books[bookId]) {
      var rb = result.book, bb = state.books[bookId];
      if (rb.coverUrl) {
        bb.coverUrl = rb.coverUrl;
        // Stage 3: refresh the candidate list too (the shelf walks it first) and
        // clear the broken mark so the re-resolved cover stops counting as wrong.
        bb.coverCandidates = (rb.coverCandidates && rb.coverCandidates.length > 0)
          ? rb.coverCandidates.slice() : [rb.coverUrl];
        delete coverBrokenIds[bookId];
        applied = true;
      }
      if (!bb.isbn && rb.isbn) { bb.isbn = rb.isbn; }
      if (!bb.year && rb.year) { bb.year = rb.year; }
      if (typeof bb.pageCount !== 'number' && typeof rb.pageCount === 'number') { bb.pageCount = rb.pageCount; }
      if (!bb.publisher && rb.publisher) { bb.publisher = rb.publisher; }
      if (!bb.description && rb.description) { bb.description = rb.description; }
      if (applied) { markBookPending(getCurrentUser() ? getCurrentUser().uid : '', bookId); markBooksDirty(); saveState(); }
    }
    if (typeof callback === 'function') { callback(applied); }
  });
}

// The one-time cleanup pass UI (mockup E): summary stats, per-item review
// (merge duplicates / resolve missing covers), and a "Resolve all" bulk.
function openLibraryCleanup() {
  var hostEl = document.getElementById('shelf-editor-host');
  if (!hostEl) { return; }
  var user = getCurrentUser();
  if (!user) { return; }
  hostEl.innerHTML = '';

  function render() {
    var report = scanLibraryForCleanup(user.uid);
    hostEl.innerHTML = '';
    var wrap = document.createElement('section');
    wrap.className = 'library-cleanup';

    var eyebrow = document.createElement('div'); eyebrow.className = 'book-review-eyebrow'; eyebrow.textContent = 'Shelf · one-time cleanup';
    var h1 = document.createElement('h1'); h1.className = 'book-review-title'; h1.textContent = 'Tidy your library';
    var sub = document.createElement('p'); sub.className = 'book-review-sub';
    sub.textContent = 'Resolve duplicates and fill in missing covers across your ' + report.total + ' books.';
    wrap.appendChild(eyebrow); wrap.appendChild(h1); wrap.appendChild(sub);

    var summary = document.createElement('div'); summary.className = 'cl-summary';
    function stat(n, label, warn) {
      var s = document.createElement('div'); s.className = 'cl-stat' + (warn && n > 0 ? ' warn' : '');
      var nn = document.createElement('div'); nn.className = 'n'; nn.textContent = '' + n;
      var ll = document.createElement('div'); ll.className = 'l'; ll.textContent = label;
      s.appendChild(nn); s.appendChild(ll); return s;
    }
    summary.appendChild(stat(report.duplicates.length, 'duplicate records to merge', true));
    summary.appendChild(stat(report.missingCovers.length + report.wrongCovers.length, 'books missing or wrong covers', true));
    summary.appendChild(stat(report.total, 'books on your shelf total', false));
    wrap.appendChild(summary);

    // Stage 3 (mockup E): the before -> after hero. Renders when there is any
    // cover work; the first such book illustrates the fix.
    var coverWork = report.missingCovers.concat(report.wrongCovers);
    if (coverWork.length > 0) {
      var heroBook = state.books[coverWork[0]] || { title: '' };
      var hero = document.createElement('div'); hero.className = 'card cl-hero';
      var baBig = document.createElement('div'); baBig.className = 'ba-big before-after';
      var beforeCol = document.createElement('div'); beforeCol.className = 'ba-col';
      var beforeLab = document.createElement('span'); beforeLab.className = 'ba-lab'; beforeLab.textContent = 'before';
      var beforeCover = document.createElement('div'); beforeCover.className = 'cover';
      var bpend = document.createElement('div'); bpend.className = 'cover-pending';
      var bpt = document.createElement('span'); bpt.className = 'cp-ti'; bpt.textContent = heroBook.title || '';
      var bpl = document.createElement('span'); bpl.className = 'cp-lab'; bpl.textContent = 'no cover';
      bpend.appendChild(bpt); bpend.appendChild(bpl); beforeCover.appendChild(bpend);
      beforeCol.appendChild(beforeLab); beforeCol.appendChild(beforeCover);
      var heroArrow = document.createElement('span'); heroArrow.className = 'ba-arrow'; heroArrow.textContent = '→';
      var afterCol = document.createElement('div'); afterCol.className = 'ba-col';
      var afterLab = document.createElement('span'); afterLab.className = 'ba-lab'; afterLab.textContent = 'after';
      var afterCover = document.createElement('div'); afterCover.className = 'cover';
      afterCover.appendChild(buildSelfHealingCover(heroBook, 'cover-img', function() {
        var hp = document.createElement('div'); hp.className = 'cover-pending';
        var hpt = document.createElement('span'); hpt.className = 'cp-ti'; hpt.textContent = heroBook.title || '';
        var hpl = document.createElement('span'); hpl.className = 'cp-lab'; hpl.textContent = 'searching…';
        hp.appendChild(hpt); hp.appendChild(hpl); return hp;
      }));
      afterCol.appendChild(afterLab); afterCol.appendChild(afterCover);
      baBig.appendChild(beforeCol); baBig.appendChild(heroArrow); baBig.appendChild(afterCol);
      var heroTx = document.createElement('div'); heroTx.className = 'cl-hero-tx';
      var heroH = document.createElement('h3'); heroH.textContent = 'We found the missing covers';
      var heroP = document.createElement('p');
      heroP.textContent = coverWork.length + ' of your books are missing or have a broken cover. ' +
        'We match each one against the catalog — review them below, or hit Resolve all.';
      heroTx.appendChild(heroH); heroTx.appendChild(heroP);
      hero.appendChild(baBig); hero.appendChild(heroTx);
      wrap.appendChild(hero);
    }

    var resolveAll = document.createElement('button');
    resolveAll.type = 'button'; resolveAll.className = 'review-confirm cl-resolve-all';
    resolveAll.textContent = 'Resolve all →';
    resolveAll.addEventListener('click', function() {
      resolveAll.disabled = true; resolveAll.textContent = 'Resolving…';
      // merge every duplicate group (keep the first), then re-resolve covers.
      var g;
      for (g = 0; g < report.duplicates.length; g++) {
        var grp = report.duplicates[g];
        mergeBookDuplicates(user.uid, grp[0], grp.slice(1));
      }
      var fresh = scanLibraryForCleanup(user.uid);
      var pending = fresh.missingCovers.concat(fresh.wrongCovers);
      var idx = 0;
      function nextCover() {
        if (idx >= pending.length) { render(); return; }
        var id = pending[idx]; idx = idx + 1;
        reResolveCover(id, function() { nextCover(); });
      }
      nextCover();
    });
    wrap.appendChild(resolveAll);

    var list = document.createElement('div'); list.className = 'cl-list';

    // duplicate items
    var di;
    for (di = 0; di < report.duplicates.length; di++) {
      (function(grp) {
        var keep = state.books[grp[0]];
        var item = document.createElement('div'); item.className = 'cl-item'; item.setAttribute('data-state', 'cleanup-duplicate');
        var kind = document.createElement('span'); kind.className = 'cl-kind dup'; kind.textContent = 'duplicate'; item.appendChild(kind);
        var mid = document.createElement('div'); mid.className = 'cl-mid';
        var ti = document.createElement('div'); ti.className = 'cl-ti'; ti.textContent = keep ? (keep.title || '') : '';
        var au = document.createElement('div'); au.className = 'cl-au'; au.textContent = keep ? (keep.author || '') : '';
        var note = document.createElement('div'); note.className = 'cl-note';
        note.textContent = grp.length + ' copies — merge keeps your notes and the read status.';
        mid.appendChild(ti); mid.appendChild(au); mid.appendChild(note); item.appendChild(mid);
        var acts = document.createElement('div'); acts.className = 'cl-actions';
        var keepBoth = document.createElement('button'); keepBoth.type = 'button'; keepBoth.className = 'review-mark-all'; keepBoth.textContent = 'Keep both';
        keepBoth.addEventListener('click', function() { /* leave as-is; re-render drops it from this pass only on merge */ });
        var mergeBtn = document.createElement('button'); mergeBtn.type = 'button'; mergeBtn.className = 'review-confirm cl-merge'; mergeBtn.textContent = 'Merge';
        mergeBtn.addEventListener('click', function() { mergeBookDuplicates(user.uid, grp[0], grp.slice(1)); render(); });
        acts.appendChild(keepBoth); acts.appendChild(mergeBtn); item.appendChild(acts);
        list.appendChild(item);
      })(report.duplicates[di]);
    }

    // Stage 3 (mockup E): cover items -- "missing cover" (Skip / Find cover)
    // and "wrong cover" (Keep / Swap), each with a before -> after. Capped at
    // 40 combined so a large library does not render thousands of rows.
    function coverItem(id, isWrong) {
      var b = state.books[id];
      if (!b) { return null; }
      var item = document.createElement('div'); item.className = 'cl-item'; item.setAttribute('data-state', 'cleanup-cover');
      var kind = document.createElement('span'); kind.className = 'cl-kind miss'; kind.textContent = isWrong ? 'wrong cover' : 'missing cover'; item.appendChild(kind);
      var mid = document.createElement('div'); mid.className = 'cl-mid cl-mid-cover';
      var ba = document.createElement('div'); ba.className = 'before-after';
      var beforeCover = document.createElement('div'); beforeCover.className = 'cover';
      var bp = document.createElement('div'); bp.className = 'cover-pending';
      var bpt2 = document.createElement('span'); bpt2.className = 'cp-ti'; bpt2.textContent = b.title || '';
      var bpl2 = document.createElement('span'); bpl2.className = 'cp-lab'; bpl2.textContent = isWrong ? 'wrong' : 'no cover';
      bp.appendChild(bpt2); bp.appendChild(bpl2); beforeCover.appendChild(bp);
      var arrow2 = document.createElement('span'); arrow2.className = 'ba-arrow'; arrow2.textContent = '→';
      var afterCover2 = document.createElement('div'); afterCover2.className = 'cover';
      afterCover2.appendChild(buildSelfHealingCover(b, 'cover-img', function() {
        var p = document.createElement('div'); p.className = 'cover-pending';
        var pt = document.createElement('span'); pt.className = 'cp-ti'; pt.textContent = b.title || '';
        var pl = document.createElement('span'); pl.className = 'cp-lab'; pl.textContent = 'searching…';
        p.appendChild(pt); p.appendChild(pl); return p;
      }));
      ba.appendChild(beforeCover); ba.appendChild(arrow2); ba.appendChild(afterCover2);
      var txt = document.createElement('div'); txt.className = 'cl-mid-text';
      var ti = document.createElement('div'); ti.className = 'cl-ti'; ti.textContent = b.title || '';
      var au = document.createElement('div'); au.className = 'cl-au'; au.textContent = b.author || '';
      var note = document.createElement('div'); note.className = 'cl-note';
      note.textContent = isWrong ? 'Saved cover won’t load — swap it for a fresh match.' : 'Imported by title alone — find a cover.';
      txt.appendChild(ti); txt.appendChild(au); txt.appendChild(note);
      mid.appendChild(ba); mid.appendChild(txt); item.appendChild(mid);
      var acts = document.createElement('div'); acts.className = 'cl-actions';
      var leftBtn = document.createElement('button'); leftBtn.type = 'button'; leftBtn.className = 'review-mark-all'; leftBtn.textContent = isWrong ? 'Keep' : 'Skip';
      var rightBtn = document.createElement('button'); rightBtn.type = 'button'; rightBtn.className = 'review-confirm cl-use-cover'; rightBtn.textContent = isWrong ? 'Swap' : 'Find cover';
      rightBtn.addEventListener('click', function() {
        rightBtn.disabled = true; rightBtn.textContent = 'Looking…';
        reResolveCover(id, function() { render(); });
      });
      acts.appendChild(leftBtn); acts.appendChild(rightBtn); item.appendChild(acts);
      return item;
    }
    var coverShown = 0, ci2;
    for (ci2 = 0; ci2 < report.missingCovers.length && coverShown < 40; ci2++) {
      var miItem = coverItem(report.missingCovers[ci2], false);
      if (miItem) { list.appendChild(miItem); coverShown = coverShown + 1; }
    }
    for (ci2 = 0; ci2 < report.wrongCovers.length && coverShown < 40; ci2++) {
      var wcItem = coverItem(report.wrongCovers[ci2], true);
      if (wcItem) { list.appendChild(wcItem); coverShown = coverShown + 1; }
    }

    wrap.appendChild(list);

    var done = document.createElement('button'); done.type = 'button'; done.className = 'book-review-cancel'; done.textContent = 'Done';
    done.addEventListener('click', function() { renderShelf(); });
    wrap.appendChild(done);

    hostEl.appendChild(wrap);
  }
  render();
}

// restore() clears the busy label and resets input.value in every
// terminal path so re-selecting the same photo re-fires the change event.
function handleShelfScanFile(input, btn) {
  if (!input.files || !input.files.length) return;
  var file = input.files[0];
  var originalLabel = btn.textContent;
  btn.disabled = true;
  btn.textContent = 'Scanning' + '…';
  clearScanStatus();
  function restore() {
    btn.disabled = false;
    btn.textContent = originalLabel;
    input.value = '';
  }
  downscaleShelfPhoto(file, function(err, base64, w, h) {
    if (err) {
      console.warn('[scan] error downscale', err);
      restore();
      showScanStatus('Scan failed — please try again.');
      return;
    }
    console.log('[scan] ' + w + 'x' + h + ' → ' +
      Math.round(base64.length / 1024) + 'KB base64');
    fetch('/.netlify/functions/vision-proxy', {
      method:  'POST',
      headers: { 'Content-Type': 'application/json', 'x-praxis-key': PRAXIS_CLIENT_KEY },
      body:    JSON.stringify({ image: base64, mediaType: 'image/jpeg' })
    }).then(function(res) {
      if (res.status === 200) {
        res.json().then(function(json) {
          restore();
          // Phase 3: vision returns {books:[{title,author,legibility}]} (legacy
          // {titles:[...]} accepted). Build a resolver query per spine, resolve
          // the batch through the shared accuracy engine, and hand the resolved
          // matches to the review screen. Never auto-writes.
          var specs = scanResponseToSpecs(json);
          if (specs.length === 0) {
            showScanStatus('No readable titles found. Try photographing one shelf at a time, filling the frame.');
            return;
          }
          var queries = [];
          var si;
          for (si = 0; si < specs.length; si++) {
            queries.push({ kind: 'title', title: specs[si].title, author: specs[si].author, legibility: specs[si].legibility });
          }
          showScanStatus('Looking up ' + queries.length + (queries.length === 1 ? ' book…' : ' books…'));
          resolveBatch(queries, function(resolved) {
            clearScanStatus();
            // openBookReview is the Stage-4 review screen; guard so the resolve
            // pipeline is independently verifiable before it lands.
            if (typeof openBookReview === 'function') {
              openBookReview(resolved, 'scan');
            }
          });
        }, function(parseErr) {
          console.warn('[scan] error parse', parseErr);
          restore();
          showScanStatus('Scan failed — please try again.');
        });
      } else {
        res.text().then(function(body) {
          console.warn('[scan] error ' + res.status, body);
          restore();
          showScanStatus('Scan failed — please try again.');
        }, function(readErr) {
          console.warn('[scan] error ' + res.status, readErr);
          restore();
          showScanStatus('Scan failed — please try again.');
        });
      }
    }, function(netErr) {
      console.warn('[scan] error network', netErr);
      restore();
      showScanStatus('Scan failed — please try again.');
    });
  });
}

// 6.1c: scan status line plumbing. One shared auto-clear timer (module-
// scoped, mirrors the _stLayersOpen idiom) so a new message replaces any
// pending clear. The element is created per-render in renderShelf with a
// stable id, so these helpers find it by id regardless of closure scope.
var _scanStatusTimer = null;
function clearScanStatus() {
  if (_scanStatusTimer) {
    clearTimeout(_scanStatusTimer);
    _scanStatusTimer = null;
  }
  var el = document.getElementById('shelf-scan-status');
  if (el) el.textContent = '';
}
function showScanStatus(msg) {
  var el = document.getElementById('shelf-scan-status');
  if (!el) return;
  if (_scanStatusTimer) {
    clearTimeout(_scanStatusTimer);
    _scanStatusTimer = null;
  }
  el.textContent = msg;
  _scanStatusTimer = setTimeout(function() {
    var e2 = document.getElementById('shelf-scan-status');
    if (e2) e2.textContent = '';
    _scanStatusTimer = null;
  }, 6000);
}

// Stage 4 (chrome-fidelity): book-detail Edit-panel collapse state. Module-
// scoped (mirrors _stLayersOpen) so it survives the in-panel re-renders that
// editing a field triggers (status / ISBN blur / tradition each re-enter
// renderBookDetail) -- otherwise the panel would snap shut mid-edit. Resets
// to collapsed on a fresh page load (reading-first view); NOT persisted to ls.
var _bookDetailEditOpen = false;

// =====================================================================
// WAVE 4 (Phase 5) -- BOOK PAIR (Amber): shared foundation.
// Book Detail (redesign-in-place, route #book/<id>) and Book View
// (net-new, route #book/<id>/marks) render in the .lum-amber-deep
// reading-room atmosphere. The helpers below are authored ONCE here so
// the two surfaces share one cover, one lens-tag row, one Yumi line, and
// one sub-theory mark renderer. Marks come from PraxisMarks (marks.js),
// never the mockup's stand-in hues. ES3 only (var/function, string
// concat); the CSS lives in components.css under the WAVE 4 block.
// =====================================================================

// The full-bleed amber surface root + centered shell. Returns both so
// callers append content into .shell. The root carries lum-amber-deep so
// it self-paints the reading-room ground; book routes are in
// umberGroundDark, so the body sits DARK behind -- no bright paper seam.
function bookAmberSurface() {
  var root = document.createElement('section');
  root.className = 'bk-surface lum-amber-deep';
  var shell = document.createElement('div');
  shell.className = 'bk-shell';
  root.appendChild(shell);
  return { root: root, shell: shell };
}

// A sub-theory's idea-mark, rendered via PraxisMarks from its stored
// { markShape, markColor } (optional 0-15 indices). When either is
// absent we derive a deterministic index from the sub-theory id via the
// app's existing scheme (window.stHashIndices -> _stIndices, FNV-1a), so
// the mark is stable-from-id. Returns an HTML string -- inline SVG with a
// per-instance gradient (no <use> shadow-boundary bug).
function bookSubMarkHTML(sub, cd) {
  if (typeof PraxisMarks === 'undefined' || !PraxisMarks.render) { return ''; }
  var sh = (sub && typeof sub.markShape === 'number') ? sub.markShape : null;
  var co = (sub && typeof sub.markColor === 'number') ? sub.markColor : null;
  if (sh === null || co === null) {
    var hx = (typeof window.stHashIndices === 'function' && sub && sub.id)
      ? window.stHashIndices(sub.id)
      : { shapeIdx: 0, colorIdx: 0 };
    if (sh === null) { sh = hx.shapeIdx; }
    if (co === null) { co = hx.colorIdx; }
  }
  if (sh < 0) { sh = 0; }
  if (sh > 15) { sh = 15; }
  if (co < 0) { co = 0; }
  if (co > 15) { co = 15; }
  var shapeId = (PraxisMarks.SHAPES[sh] && PraxisMarks.SHAPES[sh][0]) || '01';
  return PraxisMarks.render(shapeId, co, cd || 22);
}

// R-ARC S3B (the basin): FORM FOLLOWS NAMING. An unnamed draft sub-theory is a
// BASIN -- a formless mote, not a shaped mark. Named/published -> the shaped mark.
function _stIsBasin(sub) {
  if (!sub) { return false; }
  if (sub.status === 'published') { return false; }
  var h = (typeof sub.header === 'string') ? sub.header.replace(/\s+/g, '') : '';
  return h === '';
}

// The formless mote: a soft glow whose only visual property is BRIGHTNESS = mass
// (F2), mirroring the field's [0.32,0.62] luminosity clamp. Fixed size -- NO size
// variance. All values computed; no user text reaches innerHTML.
function _stMoteHTML(sub, cd) {
  var m = (typeof _stComputeMaturity === 'function') ? _stComputeMaturity(sub) : 0;
  var op = (0.32 + m * 0.30).toFixed(2);
  var d = cd || 22;
  return '<span class="st-mote" style="width:' + d + 'px;height:' + d + 'px;opacity:' + op + '"></span>';
}

// The dispatch the chrome mark sites call: mote for a basin, shaped mark otherwise.
function _stMarkOrMote(sub, cd) {
  return _stIsBasin(sub) ? _stMoteHTML(sub, cd) : bookSubMarkHTML(sub, cd);
}

// The basin's origin phrase (life 1): the body of the note it was born from, else
// its first evidence quote. Display-only; the source note is the single truth.
function _stOriginPhrase(sub) {
  if (!sub) { return ''; }
  var oe = sub.originEntryId;
  if (typeof oe === 'string' && state.notebookEntries && state.notebookEntries[oe] &&
      typeof state.notebookEntries[oe].body === 'string' && state.notebookEntries[oe].body.length) {
    return state.notebookEntries[oe].body;
  }
  if (Array.isArray(sub.evidence) && sub.evidence.length && sub.evidence[0] &&
      typeof sub.evidence[0].quote === 'string' && sub.evidence[0].quote.length) {
    return sub.evidence[0].quote;
  }
  return '';
}

// R-ARC S3B-POLISH (FF-9b): collapse to one line + truncate at a WORD boundary
// (was raw .substring, which cut mid-word at 5 sites). Falls back to a hard cut
// only if the last space is too near the start.
function _stTruncPhrase(s, n) {
  if (typeof s !== 'string') { return ''; }
  s = s.split('\n')[0].replace(/\s+/g, ' ').replace(/^\s+|\s+$/g, '');
  if (s.length <= n) { return s; }
  var cut = s.substring(0, n);
  var sp = cut.lastIndexOf(' ');
  if (sp > n * 0.6) { cut = cut.substring(0, sp); }
  return cut + '…';
}

// A mark's fill colour (the lighter palette stop), for a small tinted
// glint (e.g. the "became ->" dot). Mirrors bookSubMarkHTML's index
// derivation so the glint matches the mark.
function bookSubMarkFill(sub) {
  var co = (sub && typeof sub.markColor === 'number') ? sub.markColor : null;
  if (co === null) {
    var hx = (typeof window.stHashIndices === 'function' && sub && sub.id)
      ? window.stHashIndices(sub.id) : { colorIdx: 0 };
    co = hx.colorIdx;
  }
  if (co < 0) { co = 0; }
  if (co > 15) { co = 15; }
  var c = (typeof PraxisMarks !== 'undefined' && PraxisMarks.COLORS && PraxisMarks.COLORS[co])
    ? PraxisMarks.COLORS[co] : ['', '#ffce4a', '#cf9c2a'];
  return c[1];
}

// A drop-in span holding a sub-theory mark at the given diameter.
function bookSubMarkNode(sub, cd) {
  var slot = document.createElement('span');
  slot.className = 'bk-mark';
  slot.innerHTML = bookSubMarkHTML(sub, cd);
  return slot;
}

// The Amber book cover: cloth/spine/glow frame holding the REAL cover
// image when present (self-healing candidate-walk), falling back to a
// typeset cloth (title + author). When alight (the book has rooted
// sub-theories) it gets the gold root-mark dot + the alight glow.
function bookAmberCover(book, alight) {
  var cover = document.createElement('div');
  cover.className = 'bk-cover' + (alight ? ' bk-cover-alight' : '');
  var spine = document.createElement('span');
  spine.className = 'bk-cover-spine';
  spine.setAttribute('aria-hidden', 'true');
  cover.appendChild(spine);
  if (alight) {
    var rmark = document.createElement('span');
    rmark.className = 'bk-cover-rmark';
    rmark.setAttribute('aria-hidden', 'true');
    cover.appendChild(rmark);
  }
  cover.appendChild(buildSelfHealingCover(book, 'bk-cover-img', function() {
    var cloth = document.createElement('div');
    cloth.className = 'bk-cover-cloth';
    var ct = document.createElement('div');
    ct.className = 'bk-cover-ct';
    ct.textContent = (book && book.title) ? book.title : '';
    var ca = document.createElement('div');
    ca.className = 'bk-cover-ca';
    ca.textContent = (book && book.author) ? book.author : '';
    cloth.appendChild(ct);
    cloth.appendChild(ca);
    return cloth;
  }));
  return cover;
}

// The lens/category tag row: genre + tradition as lens tags (gold dot),
// category as a category tag (square dot). Read-only descriptors pulled
// from the live book record. Returns null when the book carries none.
function bookLensTags(book) {
  var tags = [];
  if (book && book.genre && ('' + book.genre).replace(/^\s+|\s+$/g, '') !== '') {
    tags.push({ label: book.genre, cat: false });
  }
  var trad = book ? (book.traditionOverride || book.tradition) : null;
  if (trad && trad !== 'unassigned') {
    var tlab = (typeof TRADITION_LABELS !== 'undefined' && TRADITION_LABELS[trad])
      ? TRADITION_LABELS[trad] : trad;
    tags.push({ label: tlab, cat: false });
  }
  if (book && book.category && ('' + book.category).replace(/^\s+|\s+$/g, '') !== '') {
    tags.push({ label: book.category, cat: true });
  }
  if (tags.length === 0) { return null; }
  var row = document.createElement('div');
  row.className = 'bk-tags';
  var i;
  for (i = 0; i < tags.length; i++) {
    var tag = document.createElement('span');
    tag.className = 'bk-ltag' + (tags[i].cat ? ' bk-ltag-cat' : '');
    var dot = document.createElement('span');
    dot.className = 'bk-ltag-dot';
    dot.setAttribute('aria-hidden', 'true');
    tag.appendChild(dot);
    tag.appendChild(document.createTextNode(tags[i].label));
    row.appendChild(tag);
  }
  return row;
}

// The Yumi whisper line (cyan dot + Cormorant italic) via the .lum-yumi
// primitive. Text is set with textContent; callers pass copy true to the
// computed counts -- never a fabricated data claim. Yumi is --lum-cyan.
function bookYumiLine(text) {
  var y = document.createElement('div');
  y.className = 'lum-yumi';
  var dot = document.createElement('span');
  dot.className = 'dot';
  dot.setAttribute('aria-hidden', 'true');
  var p = document.createElement('p');
  p.textContent = text || '';
  y.appendChild(dot);
  y.appendChild(p);
  return y;
}

// Display-only aggregation: the sub-theories ROOTED in this book -- those
// whose evidence cites the book ({kind:'book', refId:bookId}) or whose
// attached marginalia belong to it. Owner-filtered, oldest first. No
// data-model change (canon §2 allows computed display-only aggregation).
function rootedSubTheories(bookId) {
  var out = [];
  var map = state.subTheories || {};
  var user = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
  var uid = user ? user.uid : null;
  var k;
  for (k in map) {
    if (!Object.prototype.hasOwnProperty.call(map, k)) { continue; }
    var st = map[k];
    if (!st) { continue; }
    if (uid && st.userId && st.userId !== uid) { continue; }
    var rooted = false;
    if (st.evidence && st.evidence.length) {
      var i;
      for (i = 0; i < st.evidence.length; i++) {
        var ev = st.evidence[i];
        if (ev && ev.kind === 'book' && ev.refId === bookId) { rooted = true; break; }
      }
    }
    if (!rooted && st.attachedMarginalia && st.attachedMarginalia.length) {
      var j;
      for (j = 0; j < st.attachedMarginalia.length; j++) {
        var ent = state.notebookEntries && state.notebookEntries[st.attachedMarginalia[j]];
        if (ent && ent.bookIds && ent.bookIds.indexOf(bookId) !== -1) { rooted = true; break; }
      }
    }
    if (rooted) { out.push(st); }
  }
  out.sort(function(a, b) {
    var ax = (typeof a.createdAt === 'number') ? a.createdAt : 0;
    var bx = (typeof b.createdAt === 'number') ? b.createdAt : 0;
    if (ax !== bx) { return ax - bx; }
    return ('' + (a.header || '')).localeCompare('' + (b.header || ''));
  });
  return out;
}

// All marginalia (notebook entries, register 'marginalia') for a book,
// owner-filtered, oldest first.
function marginaliaForBook(bookId) {
  var out = [];
  var map = state.notebookEntries || {};
  var user = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
  var uid = user ? user.uid : null;
  var k;
  for (k in map) {
    if (!Object.prototype.hasOwnProperty.call(map, k)) { continue; }
    var e = map[k];
    if (!e || e.register !== 'marginalia') { continue; }
    // W12 S10: seed-owned marginalia (the Pedagogy of Desire worked example)
    // always surfaces -- signed-in AND signed-out -- mirroring the sentinel
    // open-check. Real marginalia still filters to the viewer exactly as before.
    if (e.userId !== '__praxis_seed__' && uid && e.userId && e.userId !== uid) { continue; }
    if (!e.bookIds || e.bookIds.indexOf(bookId) === -1) { continue; }
    out.push(e);
  }
  out.sort(function(a, b) {
    var ax = (typeof a.createdAt === 'number') ? a.createdAt : 0;
    var bx = (typeof b.createdAt === 'number') ? b.createdAt : 0;
    return ax - bx;
  });
  return out;
}

// The sub-theory a marginalia entry "became", by reverse lookup: a
// sub-theory whose attachedMarginalia (or evidence {kind:'entry'})
// references this entry id. Returns the sub-theory or null. No forward
// "became" field is stored; this is the honest computed link.
function marginaliaBecame(entryId) {
  var map = state.subTheories || {};
  var k;
  for (k in map) {
    if (!Object.prototype.hasOwnProperty.call(map, k)) { continue; }
    var st = map[k];
    if (!st) { continue; }
    if (st.attachedMarginalia && st.attachedMarginalia.indexOf(entryId) !== -1) { return st; }
    if (st.evidence && st.evidence.length) {
      var i;
      for (i = 0; i < st.evidence.length; i++) {
        var ev = st.evidence[i];
        if (ev && ev.kind === 'entry' && ev.refId === entryId) { return st; }
      }
    }
  }
  return null;
}

// The arc title a sub-theory lives in, for the "in <arc>" context line.
function subTheoryArcName(sub) {
  if (!sub || !sub.arcId) { return ''; }
  var arc = state.arcs && state.arcs[sub.arcId];
  if (!arc) { return ''; }
  return ('' + (arc.title || arc.name || '')).replace(/^\s+|\s+$/g, '');
}

// One "What you marked" card. The store holds only the note body (no
// distinct passage quote, no page/location), so we render the REAL note
// and NEVER fabricate a quote or page -- the gold left-accent carries the
// "marked" signature, and loc shows only the real date (or bare
// "marked"). The "became ->" link resolves when this note is computed to
// have become a sub-theory (reverse lookup), tinted to that mark's fill.
function buildMargCard(marg, bookId, user) {
  var card = document.createElement('div');
  card.className = 'bk-marg lum-glass';
  var annot = document.createElement('div');
  annot.className = 'bk-annot';
  // DWF-1: the decorative glyph was GONE -- never wired, but it promised editing.
  // MARG-EDIT (R-POLISH B3): it is back, and it is wired -- the promise DWF-1
  // removed rather than kept is now kept. See the pencil at the foot of this
  // function; it opens this entry in the marginalia canvas, pre-filled.
  var atext = document.createElement('span');
  atext.className = 'bk-atext';
  atext.textContent = marg.body || '';
  annot.appendChild(atext);
  card.appendChild(annot);
  var meta = document.createElement('div');
  meta.className = 'bk-margmeta';
  var became = marginaliaBecame(marg.id);
  // R7 FIX (woven-state dot): a filled field-hue dot when this mark was woven into
  // a sub-theory, a hollow ring when it has not been (R6 pull-system vocabulary).
  var metaL = document.createElement('span');
  metaL.className = 'bk-margmeta-l';
  var stateDot = document.createElement('span');
  stateDot.className = 'bk-marg-dot ' + (became ? 'woven' : 'unwoven');
  stateDot.setAttribute('aria-hidden', 'true');
  if (became) { stateDot.style.setProperty('--dot', bookSubMarkFill(became)); }
  metaL.appendChild(stateDot);
  var loc = document.createElement('span');
  loc.className = 'bk-loc';
  var when = '';
  if (typeof marg.createdAt === 'number') {
    try { when = new Date(marg.createdAt).toLocaleDateString(); } catch (eW) { when = ''; }
  }
  loc.textContent = when ? ('marked · ' + when) : 'marked';
  metaL.appendChild(loc);
  // MARG-EDIT (R-POLISH B3) · THE PENCIL, WIRED. Sits in the meta row beside the
  // state dot and the date -- NOT in `.bk-annot`, which is the prose column and
  // carries the <=72ch measure this surface protects.
  // OWNER-ONLY: `user` is null on the signed-out book detail (W12 S10 renders
  // seed-owned marks to visitors), so a reader never sees an edit affordance for
  // marks that are not theirs. `openMarginaliaEditor` re-checks ownership anyway.
  // ALWAYS RENDERED, not hover-revealed: a hover-only affordance is unreachable
  // on touch, and this surface already ships a mobile tier.
  if (user && bookId && marg.userId === user.uid) {
    var pen = document.createElement('button');
    pen.type = 'button';
    pen.className = 'bk-margedit';
    pen.textContent = '✎';
    pen.setAttribute('aria-label', 'Edit this marginalia');
    pen.title = 'Edit this marginalia';
    pen.addEventListener('click', function() { openMarginaliaEditor(bookId, marg.id); });
    metaL.appendChild(pen);
  }
  meta.appendChild(metaL);
  if (became) {
    var link = document.createElement('button');
    link.type = 'button';
    link.className = 'bk-becamelink';
    var gl = document.createElement('span');
    gl.className = 'bk-gl';
    gl.setAttribute('aria-hidden', 'true');
    gl.style.background = bookSubMarkFill(became);
    link.appendChild(gl);
    link.appendChild(document.createTextNode('became “' + (became.header || 'a sub-theory') + '” →'));
    link.addEventListener('click', function() { location.hash = 'subtheory/' + became.id; });
    meta.appendChild(link);
  } else {
    var uw = document.createElement('span');
    uw.className = 'bk-unwoven-note';
    uw.textContent = 'not yet woven';
    meta.appendChild(uw);
  }
  card.appendChild(meta);
  return card;
}

// One "What it grew into" row: the rooted sub-theory's real PraxisMark
// (cd 22) + title + the arc it lives in (+ draft badge) + Open ->. The
// whole row navigates to the sub-theory's Page.
function buildGrewRow(sub) {
  var row = document.createElement('div');
  row.className = 'bk-grew lum-glass';
  var gli = document.createElement('span');
  gli.className = 'bk-gli';
  gli.appendChild(bookSubMarkNode(sub, 22));
  row.appendChild(gli);
  var body = document.createElement('div');
  body.className = 'bk-gbody';
  var t = document.createElement('div');
  t.className = 'bk-grew-t';
  t.textContent = sub.header || 'Untitled sub-theory';
  body.appendChild(t);
  var inLine = document.createElement('div');
  inLine.className = 'bk-grew-in';
  var arcName = subTheoryArcName(sub);
  if (arcName) {
    inLine.appendChild(document.createTextNode('in '));
    var b = document.createElement('b');
    b.textContent = arcName;
    inLine.appendChild(b);
  }
  if (sub.status === 'draft') {
    if (arcName) { inLine.appendChild(document.createTextNode(' ')); }
    var draft = document.createElement('span');
    draft.className = 'bk-draft';
    draft.textContent = arcName ? 'draft' : 'private draft';
    inLine.appendChild(draft);
  }
  body.appendChild(inLine);
  row.appendChild(body);
  var open = document.createElement('button');
  open.type = 'button';
  open.className = 'bk-gopen';
  open.textContent = 'Open →';
  row.appendChild(open);
  row.addEventListener('click', function() { location.hash = 'subtheory/' + sub.id; });
  return row;
}

// R7 (book detail): the arcs holding a book (arc.bookIds carries {id, addedAt}
// since 3.8; legacy string ids tolerated), owner-filtered, title-sorted. Display-
// only aggregation -- no data-model change.
function arcsHoldingBook(bookId) {
  var out = [];
  var map = state.arcs || {};
  var user = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
  var uid = user ? user.uid : null;
  var k;
  for (k in map) {
    if (!Object.prototype.hasOwnProperty.call(map, k)) { continue; }
    var arc = map[k];
    if (!arc) { continue; }
    if (uid && arc.userId && arc.userId !== uid) { continue; }
    if (!(arc.bookIds instanceof Array)) { continue; }
    var i, hit = false;
    for (i = 0; i < arc.bookIds.length; i++) {
      var ref = arc.bookIds[i];
      var rid = (ref && typeof ref === 'object') ? ref.id : ref;
      if (rid === bookId) { hit = true; break; }
    }
    if (hit) {
      if (!arc.id) { arc.id = k; }
      out.push(arc);
    }
  }
  out.sort(function(a, b) {
    return ('' + (a.title || a.name || '')).localeCompare('' + (b.title || b.name || ''));
  });
  return out;
}

// R7: a deterministic 0-9 field-spectrum index from an arc id (FNV-1a), so an
// arc's chip hue is stable-from-id (Shelf R2 precedent). Maps to --bk-field-1..10.
function bookArcHueIndex(arcId) {
  var s = '' + (arcId || '');
  var h = 2166136261;
  var i;
  for (i = 0; i < s.length; i++) {
    h = h ^ s.charCodeAt(i);
    h = (h * 16777619) >>> 0;
  }
  return h % 10;
}

// R7 (F4): the hero arc-chip row -- one link per arc holding the book, its dot
// tinted by the field-spectrum hue derived from the arc id. Returns null when the
// book is in no arc.
function buildBookArcChips(bookId) {
  var arcs = arcsHoldingBook(bookId);
  if (arcs.length === 0) { return null; }
  var row = document.createElement('div');
  row.className = 'bk-arcchips';
  var lab = document.createElement('span');
  lab.className = 'bk-arcchips-label';
  lab.textContent = 'In arcs';
  row.appendChild(lab);
  var ci;
  for (ci = 0; ci < arcs.length; ci++) {
    (function(arc) {
      var chip = document.createElement('a');
      chip.className = 'bk-arcchip';
      chip.href = '#arc/' + arc.id;
      chip.style.setProperty('--arc', 'var(--bk-field-' + (bookArcHueIndex(arc.id) + 1) + ')');
      chip.textContent = '' + (arc.title || arc.name || 'Untitled arc');
      row.appendChild(chip);
    })(arcs[ci]);
  }
  return row;
}

// R7: the Book View / marks page (#book/<id>/marks) is RETIRED -- its material
// (marginalia cards + grew rows) now LEADS book detail (renderBookDetail). This
// function is kept as a thin redirect for its export / any direct caller; the old
// bk-sec render path is gone, and the router redirects the /marks hash to the
// canonical #book/<id>.
function renderBookView(bookId) {
  // R7: location.replace (not hash-assign) -- no history push, so the retired
  // /marks route is not a back-button trap for its export / any direct caller.
  location.replace('#book/' + bookId);
}

// Wave 4: "+ Add to a lens" inline panel open-state (module-level, like
// _bookDetailEditOpen: survives an in-panel re-render, resets on load).
var _bdLensOpen = false;

// ---- Book Detail Amber sub-builders (Detail-only; the cover/tag/yumi/
// mark/aggregation primitives are the shared WAVE 4 helpers above). ----

